-- ============================================================
-- Alman4b (2/2): Günə-özəl push bildirişlərinin DE tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc'::uuid, 'Pyjama-Protest 👕', 'Dein Kind will sich nicht anziehen und rennt durch die Wohnung? Mach aus dem Kampf ein Spiel: Mal sehen, wer sich schneller anzieht! Ein kleiner Wettbewerb ist oft das beste Mittel gegen Trotz.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'Das kleine Diktiergerät läuft 🎙️', 'Dein Kind wiederholt sofort selbst das beiläufigste Wort, das du sagst? Es ist dein lebendiger Spiegel. In diesem Alter wächst der Wortschatz explosionsartig – halte die neuen Wörter im Entwicklungs-Tracker fest.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'Schneller Nachschub 🛒', 'Die schlaflosen Nächte machen dich unkonzentriert? Du vergisst ständig, was du einkaufen wolltest. Trag alles sofort in die Einkaufsliste ein und lass deinen Partner die Verantwortung für den Einkauf vollständig übernehmen.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'Papas Märchentheater 📖', 'Deine Stimmbänder sind müde davon, den ganzen Tag Nein zu sagen. Übergib die Märchenstunde heute Abend an Papa. Lass ihn seine Stimme verstellen und lustige Geschichten erzählen, während du dich ausruhst.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'Die neue Leinwand des kleinen Künstlers 🖍️', 'Das Papier ist aufgebraucht und jetzt möchte dein Kind die Wand oder die Tür bemalen? Es kritzelt nicht einfach nur, sondern entdeckt mit seiner Feinmotorik die Welt. Gib ihm einen großen Karton und lege damit einen klaren Rahmen fest.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'Die Stille spüren 🤫', 'Das Chaos zu Hause ist endlich vorbei und dein Kind schläft. Öffne den Geräuschpegelmesser, sieh dir an, wie still es im Raum ist, und versinke 15 Minuten lang in dieser Ruhe – ganz ohne auf einen Bildschirm zu schauen.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'Gemeinsam schaffen wir das 🥂', 'Wenn euer Kind eingeschlafen ist, setzt euch einander gegenüber. Statt über das Kind zu sprechen, lächelt euch an und sagt: „Wir haben auch diesen Tag überlebt.“ Spürt dabei, was für ein gutes Team ihr seid.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'Raus an die frische Luft ⛅', 'Die vier Wände fallen dir auf den Kopf. Schau im Wetter- und Kleidungs-Tool nach der tatsächlichen Temperatur und lauft ohne lange nachzudenken in den Park. Frische Luft kann selbst den heftigsten Wutanfall schnell entschärfen.'),
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498', 'Der 20-Minuten-Schuh 👟', 'Dein Kind möchte seine Schuhe selbst anziehen und ihr kommt deshalb später aus dem Haus? Verliere nicht die Geduld.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'Die Sätze werden länger 🗣️', 'Dein Kind verbindet inzwischen Wörter und bildet interessante Sätze, die ganz seiner eigenen Logik folgen. Lass dir diese Momente nicht entgehen und halte die süßen Dialoge mit dem Baby-Fotoshooting als Video fest.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'Spiele im Dunkeln 🐰', 'Hat dein Kind Angst, wenn das Licht ausgeht? Verdunkelt das Zimmer vollständig und macht mit einer Taschenlampe Schattenspiele an der Wand. So verwandelt ihr die Angst in Spaß und helft eurem Kind, sich mit der Dunkelheit anzufreunden.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'Wachstumsschub bei Größe und Gewicht 📏', 'Sind die Hosen schon wieder zu kurz? Dein Kind wächst rasant! Trage die aktuellen Maße in den Wachstumstracker ein und betrachte stolz die ansteigende Wachstumskurve – die Belohnung für deine schlaflosen Nächte.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'Nächtliches Aufwachen ohne erkennbaren Grund 😭', 'Dein Kind ist mitten in der Nacht schreiend aufgewacht. Keine Panik. Prüfe mit dem Tool zur Schreianalyse, ob Wachstumsschmerzen oder ein Nachtschreck dahinterstecken, und nimm dein Kind geduldig in den Arm.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'Eiskalter Kaffee ☕', 'Den Kaffee einzuschenken und erst 3 Stunden später zu trinken, ist das offizielle ungeschriebene Gesetz des Mutterseins. Mach es heute anders: Lass dein Kind eine Weile allein mit seinen Spielsachen spielen und trink deinen Kaffee innerhalb von 10 Minuten, solange er noch heiß ist!'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'Die schönste Last 🫂', 'Den ganzen Tag hat dein Baby dich in den Wahnsinn getrieben und wegen jeder Kleinigkeit geweint. Doch dann kuschelt sich dieser warme, kleine Körper abends beim Einschlafen an deine Brust und du riechst seinen Duft ... Genau das ist das schönste Gefühl der Welt.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'Ein Ort für Mamas ☕', 'Hast du es satt, jeden Tag in denselben Park zu gehen? Entdecke unter den mama-freundlichen Orten ein ruhiges, außergewöhnliches Café, in dem auch Kinder entspannt spielen können, und gönn dir heute etwas Schönes.'),
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80', 'Form- und Raumverständnis 🧩', 'Dein Kind versucht beharrlich, Puzzleteile und verschiedene Formen in die passenden Öffnungen zu stecken. Greif nicht ein, auch wenn es Fehler macht. Denn genau durch Ausprobieren lernt es, Probleme zu lösen.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'Natürliches weißes Rauschen 🤫', 'In der ersten halben Stunde nach dem Einschlafen ist das Gehirn besonders aktiv. Prüfe die Lautstärke im Zimmer mit einem Schallpegelmesser. Manchmal kann schon das sanfte Geräusch von Regen dein Baby in einen tiefen Schlaf begleiten.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'Sei stolz auf dich 🎈', 'Schlaflose Nächte, hektische Tage ... Aber du hast es geschafft. Sag dir heute selbst: Gut gemacht – dafür, dass du dein Kind liebevoll großziehst, ohne laut zu werden!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'Ohne Liste einkaufen? Niemals! 🛒', 'Du verlässt dich beim Einkaufen auf dein Gedächtnis und kommst ausgerechnet ohne das Wichtigste nach Hause. Mach Schluss damit. Gewöhne dir an, alles, was zu Hause fehlt, sofort auf die Einkaufsliste zu setzen.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'Lass deinen Gefühlen freien Lauf 📝', 'Du fühlst dich unverstanden? Niemand sieht, wie erschöpft du bist? Das Stimmungstagebuch ist dein bester Vertrauter. Schreib all deinen Stress, deinen Schmerz und deine Einsamkeit hinein – du wirst merken, wie erleichtert du dich danach fühlst.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'Der Gemüse-Streit geht weiter 🥦', 'Hat dein Kind schon wieder das winzige Stück Karotte in der Suppe entdeckt und wollte nicht weiteressen? Mach die Portionen kleiner und variiere die Formen. Kreativität ist die stärkste Geheimwaffe einer Mama.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'Stolz auf euer Team 🥂', 'Ihr habt einen anstrengenden Tag gemeistert. Wenn euer Kind eingeschlafen ist, macht euch gemeinsam eine Tasse Tee und motiviert euch gegenseitig mit den Worten: „Wir machen das wirklich großartig.“'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'Wechselhaftes Wetter ⛅', 'Lass dich beim Spazierengehen nicht vom Wetter täuschen, damit dein Kind nicht friert. Verlass dich nicht nur auf den Blick aus dem Fenster, sondern finde mit dem Wetter- und Kleidungsassistenten das passende Outfit für draußen.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'Mutige Sprünge 🧗‍♂️', 'Dein Kind springt vom Sofa auf die Kissen. Dabei testet es die Schwerkraft und seinen Mut. Statt es zu verbieten, richte im Zimmer einen sicheren Bereich zum Springen ein.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'Nimm die schlaflose Nacht gelassen 😭', 'Dein Kind ist mitten in der Nacht aufgewacht und möchte nicht mehr schlafen. Werde nicht ärgerlich. Finde heraus, woran es liegt, streichle es sanft und gib ihm einfach das Gefühl, dass du da bist.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'Geduld beim Wutanfall 🛒', 'Dein Kind schreit im Supermarkt, weil du ihm das gewünschte Spielzeug nicht gekauft hast. Ignoriere die Blicke der vermeintlich perfekten Eltern um dich herum. Stelle ruhig Blickkontakt her, erkläre deine Entscheidung und bleib konsequent.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', 'Willkommen im 31. Monat!  🎉', 'Dein Kind befindet sich jetzt in einer der intellektuell spannendsten und zugleich turbulentesten Phasen seiner Kindheit. Jeder Satz und jede Frage ist für dich eine große Entdeckung.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'Stress beim Essen 🥣', 'Dein Kind isst zwei Löffel, sagt, dass es satt ist, und läuft davon? Zwinge es nicht zum Weiteressen. Eine gesunde Beziehung zum Essen zu entwickeln, ist wichtiger, als den Teller leer zu essen.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'Ein Moment, der die Zeit anhält 📸', 'Wenn dein Kind gerade ganz vertieft im Zimmer spielt, öffne sofort das Baby-Fotoshooting. Halte das veränderte, schon so groß gewordene Gesicht und die leuchtenden Augen ganz ohne Filter als Erinnerung für die Zukunft fest.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'Schon wieder Trennungsangst? 🥺', 'Selbst wenn du nur zur Toilette gehst, wartet dein Baby weinend hinter der Tür auf dich. Trennungsangst kann manchmal zurückkehren. Sprich immer wieder mit deinem Baby und sage ihm auch aus einem anderen Zimmer, dass du da bist und zurückkommst.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'Energie muss raus 🌳', 'In den eigenen vier Wänden wird dein Baby schnell gereizt. Setz es in den Kinderwagen oder nimm es an die Hand und geht an die frische Luft. Die Ruhe der Natur tut sowohl deinem Baby als auch deiner Psyche richtig gut.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'An die Dunkelheit gewöhnen 🌙', 'Damit dein Baby schneller einschläft, schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin wird in einer ruhigen und dunklen Umgebung besonders schnell ausgeschüttet.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', 'Die „Was ist das?“-Phase ☝️', 'Zeigt dein Baby mit dem Finger auf alles und fragt nach dem Namen? Es möchte, dass du ihm die Welt erklärst. Das ist ein großer Entwicklungssprung in der Kommunikation! Benenne geduldig jeden Gegenstand, auf den es zeigt.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'Freude am Klatschen 👏', 'Klatscht dein Baby stolz für sich selbst, wenn ihm etwas gelingt? Es wünscht sich Anerkennung! Feiere auch du diesen kleinen Erfolg mit großer Freude und motiviere dein Baby.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'Hast du eine Frage? 🤖', 'Machst du dir nach dem Alter von 2.5 Jahren Sorgen um die Größen- und Gewichtskurve deines Kindes? Statt beängstigende Artikel im Internet zu lesen, erhältst du bei Anacan AI präzise und wissenschaftlich fundierte Informationen.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'Papas lustige Geräusche 🤡', 'Wenn nichts von dem hilft, was du versuchst, retten Papas lustige Geräusche die Situation. Überlass ihm bei abendlichen Krisen sofort das Feld und lächle entspannt aus der Ferne.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'Die Melodie des Abends 🛀', 'Nach einem ganzen Tag voller Bewegung seid ihr beide erschöpft. Ein warmes Bad und eine sanfte, ruhige Melodie im Hintergrund helfen dem Nervensystem deines Babys, vollkommen zur Ruhe zu kommen.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', 'Ich hab dich gefunden! Überraschung 🙈', 'Die Regeln beim Versteckspiel haben sich geändert. Jetzt versteckt sich dein Kind und kommt dann mit einem lauten „Hier bin ich!“ hervor. Lass es seine eigenen Spielregeln erfinden und lacht gemeinsam aus vollem Herzen.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'Abendliche Ruhe 🛀', 'Wenn dein Kind an einem Abend besonders trotzig und gereizt ist, lass es in warmem Wasser baden. Schon das Spielen mit dem Wasser und seine wohltuende Wirkung können die ganze negative Energie fortspülen.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'Fröhliches Summen 🎶', 'Beim Spielen singt dein Kind vor sich hin und erfindet dabei unverständliche Wörter. Das ist ein Zeichen dafür, dass sich sowohl seine Sprache als auch sein Gehör weiterentwickeln. Trage diesen neuen Meilenstein unbedingt im Entwicklungs-Tracker ein.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'Papas Vorlesestunde 📖', 'Sorgen wir heute Abend für eine andere Atmosphäre im Zimmer. Überlass das Vorlesen Papas tiefer, beruhigender Stimme und genieße währenddessen ein wenig wohltuende Stille.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'Selbsthilfegruppe für Mütter 💬', 'Stehst du vor einer schwierigen Entscheidung? (Kita, Töpfchen, Schlaf). Die Ratschläge erfahrener Mütter in der Anacan-Community bieten oft die alltagstauglichsten Lösungen, die in keinem Buch zu finden sind.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'Lass das Chaos liegen 🌪️', 'Bist du es leid, jeden Abend dieselben Spielsachen in die Kiste zu räumen? Dann räum heute einfach nicht auf! Dein Zuhause ist kein Museum, sondern ein lebendiger Ort, an dem ein kleiner Entdecker heranwächst.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'Gezieltes Werfen und Fangen ⚾', 'Dein Kind lässt den großen Ball, den du ihm zuwirfst, nicht mehr einfach vorbeifliegen, sondern versucht, ihn zu fangen. Seine Hand-Auge-Koordination entwickelt sich jetzt rasant. Veranstaltet im Flur kleine Ballspiele, bei denen ihr euch den Ball gegenseitig zuwerft.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'Ohne Märchen schlafen wir nicht ein 🪄', 'Schalte das Licht im Zimmer vollständig aus. Wähle bei den Smart-Märchen einen ruhigen, wortlosen Hintergrund mit Naturgeräuschen (Wind, Wald), um deinem Kind das Einschlafen zu erleichtern.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'Bilder bekommen Bedeutung 📖', 'Wenn dein Kind Tiere oder Kinder im Buch sieht, tippt es darauf und fragt: „Was macht das?“ Seine visuelle Wahrnehmung ist erstaunlich. Erzähle ihm ausführliche Geschichten über die Figuren.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'Zeit für Mama 🥑', 'Iss dein Mittagessen im hektischen Alltag nicht im Stehen. Wähle einen gesunden, energiereichen Snack und stelle deine eigene Ernährung in den Vordergrund, indem du dich wenigstens 10 Minuten auf dem Sofa ausruhst.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'Flüstergespräche 🌙', 'Schalte das Licht im Zimmer vollständig aus. Lege dich neben dein Kind und erzähle ihm ganz leise und flüsternd, was im Laufe des Tages passiert ist. Flüstern ist eine der besten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'Eisen und Kraft 🥩', 'Ist dein Kind blass oder wird es schnell müde? Serviere zum Fleisch einen Salat mit Zitrone oder Tomaten, damit das Eisen besser aufgenommen werden kann.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'Die Macht der Listen 🛒', 'Vergisst du beim Einkaufen immer etwas? In der App wartet eine Einkaufsliste auf dich. Trage dort alles ein, was ihr braucht, damit dein Partner es auf dem Heimweg von der Arbeit gezielt besorgen kann.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'Schreib deine Gefühle auf 📝', 'Du fühlst dich unverstanden? Niemand sieht, wie erschöpft du bist? Ein Stimmungstagebuch ist der beste Vertraute. Schreib all deinen Stress, deinen Schmerz und deine Einsamkeit hinein – du wirst sehen, wie schnell du dich innerlich erleichtert fühlst.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'Das gehört mir 🧸', 'Dein Kind möchte sein Spielzeug nicht mit einem Besucherkind teilen? Das ist kein Egoismus, sondern der Schutz seiner persönlichen Grenzen. Bring ihm das Teilen nicht durch Zwang bei, sondern indem du es ihm vorlebst.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'Freies Spielen 🧸', 'Du musst dein Kind nicht jede Minute unterhalten oder dir ständig Spiele für es ausdenken. Langeweile ist für Kinder der Beginn von Kreativität. Lass dein Kind im Zimmer selbstständig etwas entdecken.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'Wenn Mama müde ist 🛑', 'Du bist nicht aus Stahl. Wenn dir heute die Kraft zum Kochen fehlt, mach einfach Nudeln oder bestell etwas. Eine perfekte Mutter zu sein bedeutet nicht, alles allein schaffen zu müssen.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'Verstopfungsalarm 💩', 'Tobt dein Kind viel herum, vergisst aber, Wasser zu trinken? Achte auf den Stuhlgang im Töpfchen. Nimm unbedingt ballaststoffreiche Haferflocken und Pflaumen in den Speiseplan auf.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'Die endlose Show im Bett 🛌', 'Springt und tobt dein Kind im Bett herum, statt zu schlafen? Starte den Schlaftimer und setze liebevoll klare Grenzen. Verwandle das Zimmer mit Waldrauschen aus der Funktion „Weißes Rauschen“ in eine ruhige Schlafzone.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'Kalzium-Schutzschild 🦴', 'Trinkt dein Kind keine Milch? Kalzium ist für starke Knochen unverzichtbar. Erfasse heute mit dem Ernährungstracker, wie viel Käse, Joghurt oder Brokkoli dein Kind gegessen hat, und gleiche mögliche Defizite aus.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'Kissenburg 🏰', 'Verwandle das Zimmer heute Abend in einen Spielplatz. Baut aus Sofakissen eine kleine Burg und kriecht gemeinsam hinein. Es wird ein bisschen chaotisch, aber das fröhliche Lachen ist es auf jeden Fall wert.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'Ich will allein essen! 🥄', 'Nimmt dein Kind den Löffel und bekleckert alles? Starte den Ernährungstimer. Schau nicht auf das verschüttete Essen, sondern sei stolz auf die Selbstständigkeit und das Selbstvertrauen, die dein Kind dabei gewinnt.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'Morgenlaune ☁️', 'Weint dein Kind gleich nach dem Aufwachen über alles und ist mit nichts zufrieden? Vielleicht steckt es gerade mitten in einem Wachstumsschub. Rette den Tag, indem du es ausgiebig kuschelst und ihm Geborgenheit schenkst.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'Papas Nachtschicht 👨‍🍼', 'Die Erschöpfung am Tag reicht dir völlig. Überlass am Abend Papa die Vorbereitung aufs Schlafengehen und das Anziehen des Schlafanzugs – und schau einfach nur zu.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'Kleckern ausdrücklich erlaubt 🏖️', 'Dein Kind möchte mit Matsch oder Wasser spielen? Lass es ruhig schmutzig werden! Leicht zu reinigendes Zubehör für diese Aktivitäten, die die sensorische Entwicklung fördern, findest du unter den Empfohlenen Produkten.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'Geräusche herausfiltern 🤫', 'Beim Einschlafen ist dein Kind besonders geräuschempfindlich. Um Geräusche von draußen zu überdecken, kannst du im Zimmer leise ein Gerät mit weißem Rauschen (White Noise) oder Naturklänge laufen lassen.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'Schau nach unten: Was entdeckt dein Kind? 👣', 'Dein Kind genießt es jetzt, barfuß zu laufen und den Teppich oder die Fliesen im Zimmer unter seinen Füßen zu spüren. Die Stimulation der Nerven in den Fußsohlen ist für sein Gleichgewicht und seine motorische Entwicklung sehr wichtig.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'Einfach nur kuscheln 🫂', 'Heute braucht es weder Spiele noch Bücher oder Geschichten. Drück dein Kind heute Abend einfach an deine Brust, atme seinen Duft ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'Erfahrungen austauschen 💬', 'Macht es dir Angst, dass dein Kind bei allem widerspricht? Suche im Internet nicht nach beängstigenden Artikeln. Profitiere lieber von den Erfahrungen anderer Mütter in der Anacan-Community.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'Rennen mit einem Ziel 🐢', 'Gehen allein reicht deinem Kind nicht mehr: Es rennt schnell los und versteckt sich vor dir. Räume gefährliche Hindernisse im Zimmer weg und mach mit ganz viel Energie bei diesem Fangspiel mit.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'Papas Vorlesezeit 📖', 'Gönn deiner Stimme heute Abend eine Pause. Lass Papa die Lieblingsbücher deines Kindes mit verschiedenen Stimmen und auf lustige Weise vorlesen.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'Jetzt kommt das klare Nein 🛑', 'Dein Kind weicht zurück und sagt entschieden Nein, wenn es jemand küssen möchte? Respektiere seine körperlichen Grenzen. Dass es sich gegen Berührungen ohne seine Zustimmung wehrt, ist für sein späteres Selbstvertrauen sehr wichtig.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'Wörter nachplappern 🗣️', 'Wiederholt dein Kind jedes neue Wort, das du sagst, sofort wie ein Papagei? Sein Wortschatz wächst. Achte besonders darauf, welche Wörter du in seiner Nähe verwendest und welche Emotionen du zeigst – es ahmt alles nach.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'Gemüse verstecken 🥦', 'Hat dein Kind schon wieder das winzige Stück Karotte in der Suppe entdeckt und weigert sich nun zu essen? Gemüse zu pürieren und mithilfe des Ernährungsplans in Frikadellen zu verstecken, ist einer der ältesten und hilfreichsten Mama-Tricks.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'Überraschungswetter ⛅', 'Lass dich beim Spaziergang nicht vom Wetter täuschen, damit dein Kind nicht friert. Entscheide nicht nur nach einem Blick aus dem Fenster: Nutze den Wetter- und Kleidungsassistenten, um das passende Outfit für die Bedingungen draußen zusammenzustellen, bevor ihr das Haus verlasst.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'Nächtlicher Sturm 😭', 'Ist dein Kind mitten in der Nacht scheinbar grundlos weinend aufgewacht? Sind es Blähungen oder doch nur Nachtschreck? Nimm es ruhig in den Arm und begleite es mit sanfter Stimme und viel Geborgenheit zurück in den Schlaf.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'Trennungsangst 🥺', 'Sogar wenn du nur zur Toilette gehst, wartet dein Kind weinend hinter der Tür auf dich. Trennungsangst kann zeitweise besonders stark sein. Sprich immer wieder mit ihm und sage ihm, dass du da bist und gleich zurückkommst.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'Auf der Suche nach neuen Freunden 👫', 'Versucht dein Kind im Park, zu Gleichaltrigen zu laufen und auf sie zuzugehen? Die soziale Entdeckungsreise hat offiziell begonnen! Bleib in sicherer Nähe und beobachte stolz diese ersten Kontaktversuche.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'Pyjama-Ringkampf 👕', 'Wird das Anziehen am Abend zum großen Kampf? Überlass deinem Kind die Wahl: Möchtest du den roten oder den blauen Pyjama? Mit diesem kleinen Trick hat es das Gefühl, selbst entscheiden zu dürfen.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'Ruhezeit ☕', 'Wenn dein Kind keinen Mittagsschlaf mehr macht, legt wenigstens 1 Stunde Ruhezeit (Quiet Time) fest. Es kann in seinem Bett Bücher anschauen, während du deinen Tee trinkst und den Kopf frei bekommst.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'Das Monster im Dunkeln 🌌', 'Hat dein Baby Angst vor den Schatten, wenn du das Licht ausschaltest? Je lebhafter die Fantasie wird, desto realer wirken auch die Ängste. Spiele bei den Weißen Geräuschen Gebärmutterklänge ab und schenke ihm so das vertraute Gefühl von Geborgenheit, das es braucht.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'Plötzliche Tränen 😭', 'Weint dein Baby scheinbar grundlos, sobald es die Augen öffnet? Sprich mit unserem Anacan AI-Experten und erfahre, wie du dein von seinen Gefühlen überwältigtes Kleines ruhig und gelassen beruhigen kannst.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'Zeit für frische Luft 🌳', 'Fällt euch beiden zu Hause die Decke auf den Kopf? Finde unter den mama-freundlichen Orten einen Park in eurer Nähe, bevor die Stimmung kippt. Frische Luft ist die beste Medizin für euch beide.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'Ich helfe dir! 🧹', 'Versucht dein Kind, dir den Mopp oder Staubwedel aus der Hand zu nehmen, wenn du putzt? Es fühlt sich schon ganz groß. Gib ihm ein kleines Tuch und lass es mithelfen – so kann es sich spielerisch weiterentwickeln.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'Die Energie muss raus 🌳', 'Vier Wände machen dein Kind unruhig und gereizt. Setze es in den Kinderwagen oder nimm es an die Hand und geht an die frische Luft. Die Ruhe der Natur tut sowohl deinem Baby als auch deiner seelischen Gesundheit richtig gut.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'An die Dunkelheit gewöhnen 🌙', 'Damit dein Baby schneller einschläft, schalte alle zusätzlichen Lichtquellen im Zimmer aus – insbesondere Tablet-Bildschirme. Melatonin wird nur in einer dunklen Umgebung ausgeschüttet.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'Nimm die schlaflose Nacht gelassen 😭', 'Dein Baby ist mitten in der Nacht aufgewacht und möchte nicht mehr schlafen. Werde nicht ärgerlich. Finde die Ursache heraus – etwa Schmerzen, Blähungen oder Angst – und halte es geduldig im Arm, bis es wieder einschläft.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'Hartnäckige Flecken 👗', 'Bist du es leid, dass die Kleidung ständig Flecken bekommt? Ärgere dich nicht darüber. Dein Kind entdeckt gerade verschiedene Lebensmittel. Verwende Silikonlätzchen und genieße einfach diese bunten, klebrigen Momente.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'Der Freund im Spiegel 👀', 'Setz dein Baby vor den Spiegel. Beobachte, wie es sein Spiegelbild erstaunt betrachtet und verschiedene Gesichtsausdrücke ausprobiert. Das ist eine wunderbare Aktivität, um seine Selbstwahrnehmung zu fördern.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'Mit Musik in den Schlaf 🛀', 'Ist eure Abendroutine anstrengend geworden? Lass während eines warmen Bades im Hintergrund beruhigende Musik laufen. Die Harmonie von Wasser und Melodie entspannt selbst das hartnäckigste Kind.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'Der Kampf ums Zähneputzen 🦷', 'Dein Kind lässt die Zahnbürste nicht an seinen Mund? Mach daraus keinen Zwang, sondern ein Spiel. Lass es zuerst deine Zähne putzen, danach bist du an der Reihe.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'Essensverweigerung 🥣', 'Dein Kind isst zwei Löffel, sagt, es sei satt, und läuft weg? Zwing es nicht. Ein gesundes Verhältnis zum Essen ist wichtiger, als es zum Essen zu drängen. Biete häufiger kleine Portionen an.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'Hormonsturm 🩸', 'Hast du plötzlich Heißhunger auf Süßes und bist gereizt? Schau in den Perioden-Tracker. Vielleicht ist es PMS. Mach dir keine Vorwürfe und unterstütze deinen Körper mit einem magnesiumreichen Snack mit Datteln aus den Gesunden Rezepten.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'Morgendliche Krisen ohne erkennbaren Grund 🛑', 'Dein Kind schreit und weint über alles, sobald es die Augen öffnet? Sprich direkt mit unserem Anacan AI-Experten und erfahre, wie du dein von seinen Gefühlen überwältigtes Kleines ruhig beruhigen kannst.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'Lass dein Kind die Geschichte beenden 📖', 'Lass heute Abend beim Vorlesen die Sätze unvollständig und dein Kind sie beenden! Frag Anacan AI nach dialogorientierten Methoden, die diese erstaunliche Sprachentwicklung unterstützen.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'Schmutzigwerden ausdrücklich erlaubt 🏖️', 'Dein Kind möchte mit Matsch oder Wasser spielen? Lass es ruhig schmutzig werden! Leicht zu reinigendes Zubehör für diese Aktivitäten zur Förderung der sensorischen Entwicklung findest du unter Empfohlene Produkte.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'Lass mich dir helfen 🧽', 'Zieht dein Kind dir beim Staubwischen das Tuch aus der Hand? Es möchte sich groß fühlen. Gib ihm ein kleines, feuchtes Tuch. Wahrscheinlich macht es mehr Schmutz, als es beseitigt, aber dafür ist es mächtig stolz auf sich.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'Die Akustik zu Hause 🤫', 'Dein Kind ist nur mit Mühe zum Mittagsschlaf eingeschlafen. Jetzt kann dich selbst das kleinste Geräusch im Haus verrückt machen. Aktiviere sofort den Schallpegelmesser, schließe die Fenster und genieße diese vollkommene Stille.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'Der Kampf ums Schuheanziehen 👟', 'Dein Kind hat den rechten Schuh am linken Fuß an und will ihn auf keinen Fall ausziehen? Lass ihn einfach so. Ästhetik oder Korrektheit sind gerade nicht wichtiger als sein Gefühl von Selbstbestimmung.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'Sich mit der Dunkelheit anfreunden 🌙', 'Schalte das Licht im Zimmer vollständig aus. Lege dich zu deinem Kind und erzähle ihm ganz leise und flüsternd, was ihr tagsüber erlebt habt. Flüstern ist eine der natürlichsten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'Kleiner Künstler 🎨', 'Malt dein Kind mit einem Stift Kreise an die Wand oder auf Papier? Das ist ein großer Entwicklungssprung in der Feinmotorik.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'Beginnt die Kita-Suche? 🏫', 'Geht dir mit Blick auf den 3. Geburtstag der Gedanke an die Kita durch den Kopf? Wenn du es leid bist, allein darüber nachzudenken, tritt der Anacan-Community bei und frage andere Mütter nach ihren Erfahrungen und Empfehlungen.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'Eine fantasievolle Teestunde ☕', 'Reicht dir dein Kind eine leere Tasse und sagt: Trink Tee? Symbolisches Spielen ist ein Meisterwerk der kindlichen Entwicklung. Genieße den imaginären Tee in Zimmertemperatur mit größtem Vergnügen.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'Die Kleidung ist voller Flecken 🎨', 'Ist der Schlafanzug voller Essensreste und die Kleidung mit Farbe bekleckert? Kinder müssen nicht sauber groß werden – sie dürfen beim Entdecken schmutzig werden. Verwende Silikonlätzchen und überlasse den Rest der Waschmaschine.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'Schlafrhythmus analysieren ⏱️', 'Dauert das Einschlafen am Abend 1 Stunde? Schau dir die Grafik im Schlaf-Timer an. Vielleicht ist es längst an der Zeit, den Mittagsschlaf zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'Gemeinsam aufräumen 🧹', 'Muss die Wohnung aufgeräumt werden? Lass dein Kind beim Fegen mit einem Tuch mitwischen und dir helfen. Lies in den Blogs, wie ihr das Aufräumen gemeinsam in ein lustiges Spiel verwandeln könnt.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'Nächtliche Schreie 🤖', 'Wacht dein Kind mitten in der Nacht schreiend auf und erkennt dich nicht? Das könnte ein Nachtschreck sein. Frag Anacan AI gleich, wie du richtig damit umgehst und warum du dein Kind dabei nicht wecken solltest.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', 'Das „Warum?“ hört nie auf 🤔', 'Dein Kind möchte die Welt verstehen und für alles eine logische Erklärung finden. Erfahre von Anacan AI, wie du geduldig und ohne genervt zu sein auf seine endlosen Fragen antworten kannst. Deine Geduld prägt seine Zukunft.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'Das Recht auf heißen Kaffee ☕', 'Das Zimmer ist unordentlich? Lass es einfach so. Nimm dir 10 Minuten für dich und trink deinen Kaffee endlich heiß. Du musst nicht perfekt sein.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'Heimlich genaschte Schokolade 🍫', 'Bist du in die Küche gegangen und hast heimlich im Stehen etwas Süßes genascht? Mach dir keine Vorwürfe. Um den Trubel des Tages durchzustehen, darf Mamas Blutzucker ruhig mal steigen.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'Die Bühne gehört Papa 🎭', 'Dein Satz „Iss dein Essen auf“ zieht nicht mehr. Jetzt ist Papa dran. Wenn er den Löffel in ein Flugzeug verwandelt, verschwindet die Sturheit wie durch ein Wunder. Lehn dich zurück und schau zu.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'Krise wegen der falschen Löffelfarbe 🥄', 'Die Welt geht unter, weil du das Essen mit dem gelben statt mit dem grünen Löffel serviert hast? Atme tief durch. Versuch jetzt nicht, darin Logik zu finden – dein Kind testet nur, ob es die Welt kontrollieren kann. Tausch einfach den Löffel aus und lächle.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15 Minuten Auszeit 🛀', 'Du bist ins Bad gegangen, hast die Tür abgeschlossen und schaust einfach nur aufs Handy? Ja, das ist eine der beliebtesten Methoden für Mamas, um kurz zu entkommen und sich zu erholen. Genieße diese Ruhe, ohne dich vor irgendjemandem rechtfertigen zu müssen.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', 'Ein klares „Küss mich nicht!“ 🛑', 'Dreht dein Kind den Kopf weg und schiebt die Person von sich, wenn ein Verwandter es küssen möchte? Missachte seine körperlichen Grenzen nicht! Dass es sich gegen unerwünschte Berührungen wehrt, ist eine wichtige Voraussetzung für seine gesunde Zukunft.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'Wenn der Nachtschreck kommt 😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert auf niemanden? Das ist ein Nachtschreck. Schüttle es nicht und versuche nicht, es zu wecken. Bleib einfach bei ihm und vermittle ihm Geborgenheit.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'Eine Auszeit in der Natur muss sein 🌳', 'Ist das Chaos zu Hause heute unerträglich geworden? Sieh sofort im Tool Wetter und Kleidung nach, zieht euch passend an und macht euch auf den Weg zum nächsten Park. Frische Luft ist das beste Beruhigungsmittel für dein Kind.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'Die neue Version der Wörter 🗣️', 'Sagt dein Kind „Wassa“ statt Wasser oder „loß“ statt groß? Es klingt so süß, dass es schwerfällt, nicht zu lachen. Wiederhole das Wort trotzdem jedes Mal freundlich in der richtigen Form, damit sich sein Gehirn die korrekte Aussprache einprägt.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'Lass dein Kind das Ende des Märchens schreiben 🪄', 'Ihr habt beide genug von den klassischen Büchern? Lass dein Kind bei den interaktiven Märchen diesmal selbst entscheiden, wie die Geschichte endet. Frage: „Was glaubst du, wer hat dem Helden geholfen?“ So regst du seine Fantasie an.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'Wenn deine Energie aufgebraucht ist 🔋', 'Du hast heute für nichts mehr Kraft? Bereite dir nach einem unserer gesunden Rezepte in 5 Minuten einen Smoothie aus dem Mixer zu, der reich an Eisen und Vitaminen ist, und trink ihn einfach zwischendurch. Achte gut auf dich.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'Die Einkaufsliste ist deine Rettung 🛒', 'Du hast dich auf dein Gedächtnis verlassen, bist einkaufen gegangen und ohne Windeln zurückgekommen? So etwas passiert. Gewöhne dir an, alles, was du brauchst, in die Einkaufsliste einzutragen. Lass dich von der App daran erinnern.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'Überraschende Paarzeit 🥂', 'Das Kind ist unerwartet früh eingeschlafen! Nutzt diesen seltenen Moment nicht zum Putzen. Setzt euch einander gegenüber, schaltet den Fernseher aus und fragt euch einfach, wie euer Tag war.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'Puzzle-Technik 🧩', 'Dein Kind versucht hartnäckig, die Formen in die passenden Öffnungen zu stecken. Hilf nicht sofort, auch wenn es Fehler macht oder frustriert ist. Genau durch dieses Ausprobieren entwickelt es seine Problemlösungsfähigkeiten.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'Parkabenteuer mit Papa 👨‍👧', 'Muttersein ist kein 24/7-Dienst! Überlass den heutigen Ausflug Papa. Lass die beiden gemeinsam im Matsch spielen, während du dich auf dem Sofa ausstreckst und die Ruhe genießt.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'Wachstumsschub bei Größe und Gewicht 📏', 'Sind die Hosenbeine schon wieder zu kurz? Dein Kind wächst jeden Tag direkt vor deinen Augen! Trage die aktuellen Maße in den Entwicklungs-Tracker ein und betrachte voller Stolz die Wachstumskurve – das Ergebnis all deiner schlaflosen Nächte.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'Das Wunder klassischer Musik 🎶', 'Am späten Nachmittag ist ohne ersichtlichen Grund schlechte Laune aufgekommen. Schalte den Fernseher aus, dimme das Licht und lass ganz leise klassische Musik im Raum spielen. Das harmonische Zusammenspiel von Wasser und Musik wird die Atmosphäre verändern.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'Geheimagenten in der Suppe 🥦', 'Boykottiert dein Kind alles, was grün ist? Keine Sorge. Gemüse zu pürieren und mithilfe des Ernährungsplans in Frikadellen oder Soßen zu verstecken, ist einer der ältesten und nützlichsten Mama-Tricks.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'Erfundene Lieder 🎤', 'Während dein Kind seine Spielsachen ordnet, singt es mit Wörtern, die es in keiner Sprache gibt. Dabei entwickeln sich sein Wortschatz und sein Rhythmusgefühl gleichzeitig. Trage diesen neuen musikalischen Meilenstein unbedingt in den Entwicklungs-Tracker ein.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'Der hartnäckige Pyjama 👕', 'Ist das Anziehen zu einem großen Kampf geworden? Überlass deinem Kind die Wahl: Möchtest du den roten oder den blauen Pyjama? Dieser kleine Trick gibt ihm das Gefühl, selbst entschieden zu haben, und beendet den Machtkampf.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'Trennungsangst 🥺', 'Selbst wenn du das Zimmer nur für ein paar Sekunden verlässt, weint dein Kind dir hinterher. Trennungsangst kann manchmal wiederkehren. Gib ihm auch aus der Ferne Sicherheit, indem du dich jedes Mal bemerkbar machst und sagst: „Ich bin hier, ich bin in der Küche und komme gleich.“'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'Der Druck, perfekt zu sein 🛑', 'Andere Kinder können schon die Farben aufzählen, aber deins möchte nicht? Hör sofort auf, zu vergleichen! Jedes Kind entwickelt sich in seinem eigenen Tempo. Dein Kind geht seinen eigenen Weg – und das ist völlig normal.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'Papas Geheimtaktik 👨‍🍼', 'Die Müdigkeit vom Tag ist schon genug für dich. Überlass am Abend Papa spielerisch die Vorbereitung aufs Schlafengehen und das Zähneputzen, während du dich zurückziehst und in Ruhe deinen Tee genießt.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'Fragen zur kindlichen Entwicklung 🤖', 'Die Größen- und Gewichtskurve deines 32 Monate alten Kindes macht dir plötzlich Sorgen? Suche in Internetforen nicht nach beängstigenden Krankheiten, sondern erfahre von Anacan AI präzise, wissenschaftlich fundierte Fakten.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'Eine natürliche Schlafumgebung 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die Zeit, in der das Gehirn besonders empfindlich ist. Schalte im Zimmer ein Gerät mit sanftem weißem Rauschen ein, zum Beispiel Regengeräuschen, um Geräusche von draußen zu überdecken.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'Ich erklär’s dir! ☝️', 'Dein Kind zeigt mit dem Finger auf alles und stellt eine Frage nach der anderen. Es möchte, dass du ihm die Welt benennst. Das ist ein großer Sprung in der sprachlichen Entwicklung! Auch wenn du müde wirst, wiederhole geduldig die Namen der Gegenstände.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'Einfach nur kuscheln 🫂', 'Es braucht kein Spiel, kein Buch und keine Geschichte. Drück dein Kind heute Abend einfach an deine Brust, atme seinen wunderbaren Duft ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'Gemeinsam aufräumen 🧹', 'Die Wohnung muss aufgeräumt werden? Lass dein Kind beim Fegen ebenfalls mit einem Tuch wischen und dir helfen. Lies in den Blogs, wie du das Putzen zu Teamarbeit und einem gemeinsamen Vergnügen machen kannst.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'Ich bin so müde 🔋', 'Alle erwarten Energie von dir, aber dein Akku ist leer. Koche heute nichts, sondern bestell etwas. Eine perfekte Mutter zu sein bedeutet nicht, alles allein schaffen zu müssen. Erlaube dir, eine Pause zu machen.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'Vom Kreis zur Form 🎨', 'Malt dein Kind mit einem Stift Kreise an die Wand oder auf Papier? Dieser kleine Unfug ist in Wirklichkeit ein großer Entwicklungssprung seiner motorischen Fähigkeiten.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'Harmonie des Wassers 🛀', 'Nach einem ganzen Tag voller Herumtoben seid ihr beide erschöpft. Lass während eines warmen Bades im Hintergrund beruhigende Naturgeräusche laufen. Die Harmonie des Wassers bereitet selbst das hartnäckigste Kind auf den Schlaf vor.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'Wutanfall im Supermarkt 🛒', 'Dein Kind schreit an der Kasse nach Süßigkeiten? Ignoriere die missbilligenden Blicke der anderen. Stelle ruhig Blickkontakt her, erkläre die Regel und bleib konsequent.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'Gerät der Rhythmus durcheinander? ⏱️', 'Dauert das Einschlafen am Abend länger als 1 Stunde? Sieh dir den Zeitplan im Schlaf-Timer an. Vielleicht ist es längst an der Zeit, den Mittagsschlaf deutlich zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'Tiere nachahmen 🐶', 'Macht dein Kind nicht nur Tierlaute, sondern krabbelt auch wie ein Hund und schmiegt sich an wie eine Katze? Körpersprache und Fantasie kommen hier zusammen. Mach voller Energie mit und spielt gemeinsam auf dem Teppich.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'Mittagsschlaf-Krise 🥱', 'Dein Kind möchte nicht ins Bett und weint? Mit etwa 3 Jahren beginnen manche Kinder, den Mittagsschlaf auszulassen. Statt darum zu kämpfen, könnt ihr eine Ruhezeit einführen und vereinbaren, dass es im Bett einfach leise mit seinen Spielsachen spielt.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'Möchte dein Kind nicht einschlafen und hat Angst vor der Dunkelheit?', 'Verdunkle das Zimmer vollständig und forme mit deinen Händen Vogel- oder Hundeschatten an der Wand. Verwandle die Angst in ein Spiel und hilf deinem Kind so, sich mit der Dunkelheit anzufreunden.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'Wer macht den Haushalt? 🌪️', 'Bleibt etwas liegen? Dann lass es liegen. Bitte deinen Partner, heute die Hausarbeit zu übernehmen. Ruh dich aus – du bist der wichtigste Mensch in diesem Zuhause und brauchst neue Energie.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'Unterstützung im Team 🥂', 'Ihr habt einen anstrengenden Tag hinter euch. Wenn euer Kind eingeschlafen ist, trinkt gemeinsam eine Tasse Tee und motiviert euch gegenseitig mit den Worten: „Wir machen das wirklich großartig!“'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'Bilder bekommen eine Bedeutung 📖', 'Dein Kind berührt die Figuren im Buch und fragt: „Was macht das?“ Seine visuelle Wahrnehmung ist erstaunlich. Denkt euch gemeinsam ein neues, völlig frei erfundenes Ende für das Buch aus, das ihr gerade lest.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'Putzfimmel 🌪️', 'Du hast das ganze Haus geputzt, aber 10 Minuten später sieht wieder alles wie nach einer Explosion aus? Ergib dich heute einfach dem Chaos. Setz dich aufs Sofa und steh erst wieder auf, wenn du deinen Kaffee ausgetrunken hast.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'Papas diplomatische Lösung 👨‍👧', 'Der Satz „Iss bitte auf“ wirkt nicht mehr? Dann übergib an Papa. Sobald er den Löffel in ein fliegendes Raumschiff verwandelt, löst sich der Widerstand wie durch ein Wunder in Luft auf. Lehn dich zurück und genieße die Show.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'Der kleine Morgenanwalt im Einsatz 💼', '„Ich ziehe nicht dieses Hemd an, sondern das andere!“ Im Zimmer steht kein kleines Kind mehr, sondern ein kleiner Anwalt, der professionell mit dir verhandelt. Diskutiere nicht, sondern biete ihm einfach 2 Möglichkeiten an und gib ihm so das Gefühl, selbst entschieden zu haben.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'Erfolg auf dem Töpfchen 🚽', 'Dein Kind merkt, dass es muss, und läuft selbst zum Töpfchen? Das ist ein großer Erfolg!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'Heute erfindet dein Kind die Geschichte 📖', 'Leg das Buch heute Abend beiseite. Lass dein Kind die Geschichte erzählen! Frag Anacan AI nach Gesprächsimpulsen, die diese wunderbare Entwicklung der Fantasie fördern.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'Signale beim Essen 🥣', 'Dein Kind sagt nach zwei Löffeln, dass es satt ist, und läuft vom Stuhl weg? Zwinge es nicht weiterzuessen. Ein gesundes Verhältnis zum Essen zu entwickeln, ist viel wichtiger, als den Teller immer leer zu essen. Wenn es Hunger hat, wird es von selbst danach verlangen.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'Bildergeschichten 📖', 'Wenn dein Kind Tiere oder Kinder im Buch sieht, zeigt es darauf und fragt: „Was macht das?“ Seine visuelle Wahrnehmung ist erstaunlich. Erfindet gemeinsam fantasievolle und lustige Geschichten über die Figuren.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'Ändert sich der Schlafrhythmus? 😭', 'Dein Kind wacht mitten in der Nacht auf und möchte nicht mehr schlafen? Werde nicht wütend. Versuche herauszufinden, woran es liegt, streichle es und vermittle ihm einfach, dass du da bist. Warte geduldig, bis es wieder einschläft.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'Überraschendes Wetter ⛅', 'Lass dich beim Spaziergang nicht vom Wetter täuschen und achte darauf, dass dein Kind nicht friert. Entscheide nicht nur nach einem Blick aus dem Fenster: Mit dem Wetter- und Kleidungsassistenten findest du das passende Outfit für den Wind draußen und kannst entspannt das Haus verlassen.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'Die Vorteile des freien Spielens 🧸', 'Du musst dein Kind nicht jede Minute unterhalten oder dir ständig Spiele für es ausdenken. Langeweile ist für Kinder der erste Schritt zur Kreativität. Lass es im Zimmer selbstständig etwas entdecken.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'Vergessenes auf der Einkaufsliste 🛒', 'Vergisst du beim Einkaufen ausgerechnet immer das Wichtigste? Die Einkaufsliste wartet in der App auf dich. Trage dort ein, was ihr braucht, damit dein Partner auf dem Heimweg von der Arbeit alles gezielt besorgen kann.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'Kommunikation durch Körpersprache 🗣️', 'Wenn du fragst: „Wollen wir gehen?“, hebt dein Kind die Arme. Wenn es etwas nicht möchte, schüttelt es energisch den Kopf. Sein Sprachverständnis hat sich unglaublich entwickelt! Antworte ihm häufig mit bestätigenden Sätzen.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'Mit Musik sanft in den Schlaf 🎶', 'Versuche, scheinbar grundlose Gefühlsausbrüche am späten Nachmittag mit sanfter klassischer Musik zu beruhigen. Dieser einfache, aber wirkungsvolle Trick wirkt zu Hause oft Wunder und bringt wohltuende Ruhe ins Zimmer.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'Schlafstreik angekündigt 🥱', 'Dein Kind will nicht ins Bett und wehrt sich dagegen? Manche Kinder verzichten in dieser Phase auf ihren Mittagsschlaf. Statt darum zu kämpfen, könnt ihr eine Ruhezeit einführen, in der es im Bett einfach leise mit seinen Spielsachen spielt.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'Das Rätsel des Nachtschrecks 😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert auf niemanden? Lass die Schreianalyse den Laut auswerten. Wenn es sich um einen Nachtschreck handelt, versuche nicht, dein Kind zu wecken. Bleib einfach bei ihm und gib ihm Sicherheit.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'Krisen beim wählerischen Essen 🍝', 'Heute lehnt dein Kind das Essen ab, das es gestern noch geliebt hat? Mach den Esstisch nicht zum Schlachtfeld. Prüfe mit dem Ernährungstracker die wöchentliche Ausgewogenheit und entdecke unter Gesunde Rezepte abwechslungsreiche, spielerische Ideen zum Anrichten.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'Der Arzt für den verletzten Teddybären 🩺', 'Streichelt dein Kind sein Spielzeug, wenn es herunterfällt, und sagt: „Nicht weinen“? Dann entwickelt es gerade ein erstaunliches Einfühlungsvermögen! Halte diese wertvolle Phase seiner Persönlichkeitsentwicklung gleich im Entwicklungstracker fest.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'Einladung an das Melatonin 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen und Bildschirme mit blauem Licht im Zimmer aus. Das Schlafhormon Melatonin wird in einer dunklen, technikfreien Umgebung besonders schnell ausgeschüttet.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'Sandkasten-Diplomatie 🧸', 'Dein Kind will im Park niemandem seinen Eimer geben? Das ist kein Egoismus, sondern einfach die Entdeckung des persönlichen Besitzgefühls. Schlage ihm, ohne es zu beschämen, ein Abwechseln vor und löse so die diplomatische Krise.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'Blickkontakt ist Pflicht 🥂', 'Dein Kind ist unerwartet früh eingeschlafen! Verschwende diesen seltenen Moment nicht mit Putzen. Setzt euch zu zweit gegenüber, schaltet den Fernseher aus, schaut euch einfach in die Augen und fragt einander, wie der Tag war.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'Ein lebendiges Diktiergerät 🎙️', 'Wiederholt dein Kind selbst das beiläufigste Wort, das dir herausrutscht, sofort wie ein Papagei? Es ist dein lebendiger Spiegel. Achte in seiner Nähe besonders auf deine Worte und Gefühle – es ahmt alles nach.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'Protest gegen Grün 🥦', 'Wirft dein Kind das Grünzeug vom Teller? Mach den Esstisch nicht zum Schlachtfeld. Entdecke unter den gesunden Rezepten selbst gemachte Muffins mit verstecktem Gemüse und deckt euren Vitaminbedarf ganz nebenbei.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'Der Zauber des Flüsterns 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und flüstere ihm ganz leise ins Ohr, was ihr tagsüber erlebt habt. Flüstern ist eine der natürlichsten und beruhigendsten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'Brokkoli-Detektiv 🥦', 'Entdeckt dein Kind jedes grüne Gemüse auf dem Teller und schiebt es beiseite? Dann ist Tarnkunst gefragt. Entdecke unter den gesunden Rezepten raffinierte Ideen, bei denen du Gemüse pürierst und in leckeren Bratlingen versteckst.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'Das erste Konzert deines kleinen Komponisten 🎤', 'Reiht dein Kind seine Spielsachen auf und singt dabei in einem ganz besonderen Rhythmus Wörter, die in keinem Wörterbuch stehen? Unterbrich diesen geistigen Entwicklungsschub nicht, sondern halte das Lied im Entwicklungstracker als seine erste eigene Komposition fest.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'Fluchtplan in die Natur ⛅', 'Die eigenen vier Wände machen euch beide gereizt. Sieh im Wetter- und Kleidungshelfer nach, zieht euch passend an und macht euch sofort auf den Weg in den Park. Frische Luft entschärft selbst heftige Kleinkindkrisen im Nu.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'Goldene Stille 🤫', 'Das Chaos zu Hause ist endlich vorbei und dein Kind schläft tief und fest. Öffne den Schallpegelmesser, sieh dir die Lautstärke im Zimmer in Dezibel an und genieße diese goldene Stille 15 Minuten lang – ganz ohne auf einen Bildschirm zu schauen.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'Avantgarde-Mode 👗', 'Hat dein Kind die Hose über den Kopf gezogen und stolziert selbstbewusst durchs Zimmer? Greif nicht ein. Diese lustigen Experimente gehören zu seiner Suche nach Freiheit und Individualität. Ja, es sieht ungewöhnlich aus, aber diese Momente sind einfach herrlich.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'Gedächtnislücke im Supermarkt 🛒', 'Bist du im Vertrauen auf dein Gedächtnis einkaufen gegangen und ohne den wichtigsten Artikel zurückgekommen? Gewöhne dir an, alles, was ihr braucht, in die Einkaufsliste der App einzutragen – lass dich von deinem digitalen Gedächtnis retten.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'Unsichtbare Gäste 👻', 'Dein Kind schaut auf eine leere Stelle auf dem Sofa, erzählt etwas und schenkt sogar seinem unsichtbaren Freund Tee ein? Die Phase der Fantasiefreunde läuft auf Hochtouren! Es schreibt jetzt die Drehbücher für seine eigene Welt. Lehn dich zurück und genieße die Vorstellung mit einem Lächeln.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'Die reinigende Kraft des Wassers 🛀', 'Nach einem Tag voller Trubel liegen bei euch beiden die Nerven blank. Ein warmes Bad dient nicht nur der Körperpflege: Nutzt auch die fast magische Kraft des Wassers, das Anspannung löst und die negative Energie des Tages fortspült.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'Papas Küchendienst 👨‍🍳', 'Muttersein ist kein Marathon, den du allein bewältigen musst. Lass Papa am Wochenende das Mittagessen zubereiten und dein Kind füttern, während du dich auf dem Sofa ausstreckst und eine wohlverdiente Pause genießt.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'Geht es nur mir so? 💬', 'Bist du völlig erschöpft und hast das Gefühl, dass dich niemand versteht? Schreib gleich in die Anacan Community. Dort geben dir die „Mir geht es genauso wie dir“-Nachrichten Tausender Mütter, die ebenfalls unter Schlafmangel leiden, neue Kraft.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'Dein Kind schreibt das Drehbuch 🪄', 'Ihr habt beide genug von den klassischen Büchern? Lass dein Kind bei interaktiven Märchen diesmal selbst entscheiden, wie die Geschichte endet. Frag vor dem Schlafengehen: „Wer hat dem Helden deiner Meinung nach geholfen?“ So regst du seine Fantasie an.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'Mamas Energiereserve 🥗', 'Du hast dir drei verschiedene Menüs ausgedacht, damit dein Kind satt wird – und selbst nur schnell im Stehen etwas gegessen? Such dir unter den gesunden Rezepten einen vitaminreichen Salat aus, der in 10 Minuten fertig ist, und tu auch dir selbst etwas Gutes.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'Papas Grimassentheater 🤡', 'Wenn selbst deine Grimassen nicht mehr helfen, retten Papas seltsame Geräusche sofort die Situation. Überlass ihm bei abendlichen Krisen das Ruder und genieße von der Seitenlinie aus das fröhliche Gelächter.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'Kleine Haushaltshilfe 🧽', 'Zieht dein Kind dir beim Staubwischen das Tuch aus der Hand? Es möchte sich groß und als Teil des Teams fühlen. Gib ihm ein feuchtes Tuch. Es wird wahrscheinlich mehr Schmutz verteilen als beseitigen, aber dafür mächtig stolz auf sich sein.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'Trau nicht dem Blick aus dem Fenster ⛅', 'Lass dich vor einem Spaziergang nicht vom Blick aus dem Fenster täuschen. Mit dem Wetter- und Kleidungsassistenten findest du das passende Outfit für die tatsächliche Temperatur und den Wind draußen und kannst ganz entspannt losgehen.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'Dein Einkaufsretter 🛒', 'Vergisst du beim Einkaufen auch immer ausgerechnet das Wichtigste? Deine Einkaufsliste wartet in der App auf dich. Trag dort ein, was ihr braucht, damit dein Partner auf dem Heimweg von der Arbeit alles gezielt besorgen kann.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'Wasser als Therapie 🛀', 'Nach einem turbulenten Tag seid ihr beide völlig erschöpft. Lass während eines warmen Bades im Hintergrund beruhigende Naturgeräusche laufen. Die Harmonie des Wassers stimmt selbst das hartnäckigste Kind auf den Schlaf ein.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'Ein entschiedenes Nein! 🛑', 'Geht dein Kind auf Abstand und sagt entschieden Nein, wenn jemand es küssen möchte? Respektiere seine körperlichen Grenzen. Sich gegen unerwünschte Berührungen wehren zu dürfen, ist für eine gesunde psychische Entwicklung unerlässlich.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'Papas Stimme 📖', 'Gönn deiner Stimme heute Abend eine Pause. Lass Papa die Lieblingsbücher eures Kindes mit verschiedenen Stimmen, fantasievoll und lustig vorlesen.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'Mein Eigentum 🧸', 'Will dein Kind sein Spielzeug nicht mit einem Besucherkind teilen? Das ist kein Egoismus, sondern bedeutet, dass es seine persönlichen Grenzen schützt. Bring ihm das Teilen nicht durch Zwang bei, sondern indem du es ihm vorlebst.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'Heute darf Chaos sein 🌪️', 'Hast du es satt, jeden Tag dieselben Spielsachen in die Kiste zu räumen? Dann lass es heute einfach sein! Dein Zuhause ist kein Museum, sondern ein Ort voller Leben. Konzentriere dich nicht auf die Unordnung, sondern auf die Freude deines Kindes am Entdecken.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'Jetzt ist Papa dran 👨‍🍼', 'Die Müdigkeit vom Tag reicht völlig aus. Überlass Papa am Abend die Vorbereitung aufs Schlafengehen, das Zähneputzen und das Anziehen des Schlafanzugs – und genieße in Ruhe eine Tasse Tee.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'Mama, schau mich an! 👀', 'Kommt dein Kind zu dir und dreht dein Gesicht zu sich, wenn du aufs Handy schaust oder mit etwas anderem beschäftigt bist? Es möchte deine ungeteilte Aufmerksamkeit. Stelle Blickkontakt her und zeige ihm, dass du zuhörst und es dir wichtig ist.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'Aus Sätzen werden Geschichten 🗣️', 'Verbindet dein Kind schon Wörter miteinander und erzählt lustige Fantasiegeschichten? Sein Wortschatz wächst jetzt explosionsartig!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'Die Akustik im Zimmer 🤫', 'Beim Einschlafen reagiert dein Kind besonders empfindlich auf Geräusche. Überprüfe mit dem Schallpegelmesser die Geräuschkulisse und schalte im Zimmer ein Gerät mit sanftem weißem Rauschen (White Noise) ein, um Geräusche von draußen zu überdecken.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'Kleiner Ingenieur 🤔', '„Was passiert, wenn ich das werfe?“ „Wofür ist dieser Knopf da?“ Dein Kind führt ständig kleine physikalische Experimente durch. So lernt es! Überprüfe die Sicherheit deines Zuhauses noch einmal aus seiner Augenhöhe.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'Der geheime Mütter-Club 💬', 'Stehst du vor einer schwierigen Entscheidung? Zum Beispiel bei der Wahl der Kita? Die Tipps erfahrener Mütter in der Anacan-Community bieten praxiserprobte, alltagstaugliche Lösungen, die in keinem Buch stehen.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'Die Realität des kalten Kaffees ☕', 'Den Kaffee aufzubrühen und ihn 3 Stunden später eiskalt zu trinken, ist ein ungeschriebenes Gesetz des Mutterseins. Mach es heute einmal anders! Lass dein Kind kurz allein mit seinen Spielsachen spielen und genieße deinen Kaffee innerhalb von 10 Minuten, solange er noch heiß ist. Du hast es verdient.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'Mamas heimlicher Sturm 🩸', 'Plötzliche Müdigkeit und grundloses Bedürfnis zu weinen? Öffne den Perioden-Tracker. Vielleicht bist du gerade in der PMS-Phase. Mach dir keine Vorwürfe, bereite mit den gesunden Rezepten einen magnesiumreichen Snack zu und höre auf deinen Körper.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'Digitaler Kinderarzt 🤖', 'Die Größen- und Gewichtskurve deines 33 Monate alten Kindes hat dich plötzlich beunruhigt? Suche nicht in Internetforen nach beängstigenden Krankheiten, sondern erfahre von Anacan AI präzise, sofortige und wissenschaftlich fundierte Fakten.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'Mozart-Effekt 🎶', 'Am späten Nachmittag beginnt plötzlich grundlose Gereiztheit. Schalte den Fernseher aus, dimme das Licht und lass ganz leise klassische Musik im Zimmer laufen. Die Harmonie von Wasser und Musik wird die Atmosphäre auf magische Weise verändern.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'Flugversuche 🧗‍♂️', 'Dein Kind wirft sich vom Sofa auf die Kissen? Es testet die Schwerkraft und seinen Mut. Statt es zu verbieten, richte im Zimmer eine sichere Sprungzone ein, damit es sich austoben kann.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'Der Code des nächtlichen Weinens 😭', 'Weinanfälle, deren Ursache du nicht herausfinden kannst, sind zermürbend. Hör auf zu raten und nutze das Tool zur Weinanalyse, um die verborgene Botschaft hinter den Lauten – etwa Schmerzen oder Müdigkeit – zu verstehen und dein Kind zu beruhigen.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'Meister der Tarnung 🥦', 'Dein Kind schiebt das Gemüse in der Suppe beiseite, als würde es mit einem Mikroskop danach suchen? Entdecke bei den gesunden Rezepten Soßen, die Gemüse unsichtbar machen. Kreativität ist die größte Geheimwaffe einer Mutter.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'Zahnbürstenkrieg 🦷', 'Dein Kind lässt die Zahnbürste nicht an seinen Mund und will alles selbst machen? Mach daraus keinen Zwang, sondern ein Spiel. Lass es zuerst deine Zähne putzen, danach bist du an der Reihe.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'Mamas Energiekick 🥑', 'Iss dein Mittagessen im hektischen Alltag nicht im Stehen. Wähle einen energiereichen Snack aus gesunden Rezepten und stelle deine eigene Ernährung in den Mittelpunkt – und sei es nur, indem du dich 10 Minuten aufs Sofa legst.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'Fangspiel-Marathon 🏃‍♂️', 'Laufen allein reicht deinem Kind nicht mehr: Wenn du es rufst, rennt es schnell davon und versteckt sich. Räume gefährliche Hindernisse im Zimmer weg und mach bei diesem fröhlichen Fangspiel mit.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'Entdecke die Psychologie 📱', 'Bist du es leid, dass dein Kind zu allem Nein sagt? Lies die psychologischen Blogbeiträge in der App und erfahre, welche tieferen Gründe hinter diesem Entwicklungssturm in seinem Gehirn stecken.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'Die Kraft der Dunkelheit 🌙', 'Schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Eine dunkle, technikfreie Umgebung unterstützt die Ausschüttung von Melatonin.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'Einfach nur kuscheln 🫂', 'Heute braucht es weder ein Spiel noch ein Buch oder eine Geschichte. Drück dein Kind heute Abend einfach an deine Brust, atme seinen wunderbaren Duft ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', 'Die „Was ist das?“-Maschine ☝️', 'Zeigt dein Kind mit dem Finger auf alles und fragt, wie es heißt? Es möchte, dass du ihm die Welt benennst. Das ist ein großer Sprung in seiner sprachlichen Entwicklung! Auch wenn du müde wirst, wiederhole geduldig die Namen der Gegenstände.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'Du bist auch nur ein Mensch 🛑', 'Heute lief nichts nach Plan? Gib dir nicht die Schuld. Du bist eine echte Mama und keine gefilterte Illusion aus den sozialen Medien. Dein Kind braucht einfach nur dich.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'Regie bei der Arbeit 🎭', 'Erzählt dein Kind beim Betrachten der Figuren in einem Bilderbuch völlig frei erfundene Geschichten? Seine Fantasie ist auf dem Höhepunkt! Hör dir diese außergewöhnlichen Geschichten stolz an, ohne es zu unterbrechen.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'Warmer Tee und Ruhe 🍵', 'Vergiss den Haushalt – alles kann warten. Bereite dir nach einem unserer gesunden Rezepte einen Melissentee zu und genieße es, einfach einmal Zeit nur für dich zu haben.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'Parktherapie 🌳', 'Die eigenen vier Wände fallen dir auf den Kopf. Auch wenn es draußen kühl ist: Zieh dein Kind warm an und geht für 20 Minuten in den Park. Lass es Blätter und Steine entdecken – die frische Luft versorgt sein Gehirn mit Sauerstoff.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'Kunst auf dem Teller 🥦', 'Dein Kind möchte das Essen nicht essen? Manchmal liegt das Problem nicht am Geschmack, sondern am Aussehen. Gestalte mit buntem Gemüse lustige Gesichter, um seinen Appetit anzuregen und das Essen in ein Spiel zu verwandeln.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'Fröhliches Lachen 🤡', 'Wenn deine Späße nicht helfen, retten Papas seltsame Geräusche die Situation. Überlass ihm bei abendlichen Krisen sofort das Feld und lächle entspannt aus der Ferne.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'Wildnis zu Hause 🐶', 'Macht dein Kind nicht nur Tiergeräusche, sondern krabbelt auch wie ein Hund und rollt sich wie eine Katze zusammen? Körpersprache und Fantasie verbinden sich hier auf faszinierende Weise. Mach bei diesem Spiel mit und tobt gemeinsam über den Teppich.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'Barfuß unterwegs 👣', 'Dein Kind liebt es, barfuß zu laufen und unterschiedliche Oberflächen zu spüren. Die Stimulation der Nerven in den Fußsohlen ist für seine neurologische Entwicklung besonders wertvoll. Lass es daher ruhig ohne Socken laufen.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'Digitale Merkliste 🛒', 'Vergisst du beim Einkaufen immer etwas? Deine Einkaufsliste wartet in der App auf dich. Trag dort alles ein, was ihr braucht, damit dein Partner es auf dem Heimweg von der Arbeit gezielt besorgen kann.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'Klangvolle Fantasie 🪄', 'Erfinde heute Abend in den intelligenten Märchen ein ganz besonderes Abenteuer für dein Kind: die Geschichte eines mutigen Kaninchens, das keine Angst vor dem Staubsauger hat. Mit Geschichten lassen sich Ängste ganz leicht spielerisch bewältigen.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'Unverletzter Stolz 🛑', '„Ich mache das selbst!“ – dein Kind lehnt jede Hilfe ab. Auch wenn es die Schuhe verkehrt herum anzieht, greif nicht ein. Ein unversehrtes Selbstwertgefühl ist wichtiger als ein etwas ramponierter Schuh.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'Schluss mit den Zweifeln 🤖', 'Plötzliche Veränderungen im Verhalten deines Kindes machen dir Sorgen? Suche in Internetforen nicht nach beängstigenden Krankheiten. Mit Anacan AI erhältst du sofort präzise und wissenschaftlich fundierte Informationen.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'Schlafwächter 🤫', 'In der ersten halben Stunde nach dem Einschlafen ist das Gehirn besonders aktiv. Prüfe mit dem Schallpegelmesser die Lautstärke im Zimmer. Manchmal kann schon das sanfte Geräusch von Regen dein Kind in einen tiefen Schlaf begleiten.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', 'Nur noch 5 Tage bis zum 1000. Tag! 🎈', 'Der Countdown ist fast vorbei! Ihr steht kurz davor, eine große und unvergessliche Reise von genau 1000 Tagen zu vollenden. Lächelt und beginnt schon jetzt mit den Vorbereitungen für das Jubiläum und fröhlichen Motto-Ideen!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'Stille Bücherstunde 🥱', 'Dein Kind will nicht ins Bett und wehrt sich dagegen? Manche Kinder verzichten in diesem Alter bereits auf den Mittagsschlaf. Statt darum zu kämpfen, könnt ihr eine Ruhezeit einführen und vereinbaren, dass es im Bett einfach nur Bücher anschaut.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'Eine kleine Stolz-Notiz 📝', 'Auf diesem langen Weg voller Höhen und Tiefen ist deine Liebe zu deinem Baby deine größte Kraft. Öffne dein Stimmungstagebuch und schreibe deinem Baby einen kleinen, liebevollen Brief, auf den es später stolz sein kann.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'Kleine Hilfe 🧸', 'Wenn du sagst: „Bring bitte die Schuhe“, läuft dein Baby dann tatsächlich los und holt sie? Wortschatz und Sprachverständnis entwickeln sich gerade rasant! Beziehe dein Baby in kleine Aufgaben im Haushalt ein und stärke so sein Selbstvertrauen.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'Ihr seid ein echtes Team 🌟', 'Jeder selbstbewusste Schritt ist das Ergebnis der gemeinsamen Arbeit von dir und deinem Partner oder deiner Partnerin.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'Chaotisches Zuhause, entspannte Mama 🌪', 'Die Wäsche türmt sich und die Spülmaschine ist voll? Lass es einfach liegen. Bitte deinen Partner oder deine Partnerin, heute die Hausarbeit zu übernehmen. Ruh dich aus – du bist die wichtigste Stütze dieser Familie.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'Anatomieunterricht 👀', 'Zeigt dein Baby mit dem Finger auf seine Schultern, wenn du fragst: „Wo sind deine Schultern?“ Seine geistige Auffassungsgabe entwickelt sich gerade rasant! Setzt das Spiel mit schwierigeren Körperteilen fort und erweitert so seinen Wortschatz.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'Die Kraft des Wassers 🛀', 'Nach einem ganzen Tag voller Herumtoben seid ihr beide erschöpft. Lass während eines warmen Bades im Hintergrund beruhigende Naturgeräusche laufen. Die harmonische Wirkung des Wassers bereitet selbst das hartnäckigste Kind auf den Schlaf vor.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'Mamas Essen schmeckt besser 🥣', 'Schiebt dein Baby seinen eigenen Teller weg und möchte unbedingt von deinem Essen probieren? Kinder vertrauen der Auswahl ihrer Eltern meist mehr. Wähle unter den gesunden Rezepten Gerichte aus, die ihr beide gemeinsam essen könnt.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'Die richtige Spaziergangstaktik ⛅', 'Lass dich vor dem Spaziergang nicht vom Wetter täuschen, damit dein Baby nicht friert. Entscheide nicht nur nach einem Blick aus dem Fenster: Mit dem Wetter- und Kleidungsassistenten findest du das passende Outfit für den Wind draußen und kannst ganz entspannt losgehen.'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'Tagebuch-Bilanz 📝', 'Öffne das Stimmungstagebuch, nachdem dein Kind eingeschlafen ist. Was hat dich heute am meisten erschöpft, was hat dich zum Lachen gebracht? Lass deinen Gefühlen freien Lauf und schreib dir alles von der Seele.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'Die Realität nach dem Triumph 🚀', 'Nach dem gestrigen Jubiläum sind wir heute Morgen wieder zwischen verstreutem Spielzeug und lauter „Ich will nicht!“ aufgewacht! Das Leben geht weiter. Atme tief durch – du bist die großartigste Managerin dieses Chaos.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'Krise beim Mittagsschlaf 🥱', 'Dein Kind will nicht ins Bett und weint? Mit etwa 3 Jahren beginnen manche Kinder, den Mittagsschlaf auszulassen. Statt darum zu kämpfen, könnt ihr eine Ruhezeit einführen und vereinbaren, dass es im Bett einfach ein Buch anschaut.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'Flucht aus dem Bett 🛌', 'Versucht dein Kind, aus seinem Gitterbett zu klettern? Überprüfe das Zimmer noch einmal auf mögliche Gefahren. Bald könnte es Zeit für den Wechsel in ein Kinderbett sein.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', 'Die „Wie?“-Fragen beginnen 🤔', 'Die „Warum?“-Fragen werden nun von „Wie funktioniert das?“ abgelöst. Dein Kind versucht, Zusammenhänge und Mechanismen zu verstehen. Hab Geduld und gib ihm kurze, logische Erklärungen.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'Eine Pause für Mama ☕', 'Stürz dich nicht sofort auf die Hausarbeit, wenn dein Kind allein spielt. Die Unordnung läuft dir nicht davon, deine Energie kann jedoch zur Neige gehen. Setz dich hin und genieße deinen Kaffee, solange er noch warm ist.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'Fantasievolle Szenarien 🧸', 'Erzählt dein Kind seinem Teddybären eine Geschichte oder trinkt es Tee aus einer leeren Tasse? Symbolspiele sind ein wahres Meisterwerk der Entwicklung. Unterbrich es nicht, sondern beobachte diesen kleinen Regisseur aus der Ferne.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'Bedürfnis nach Ruhe 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Miss den Geräuschpegel im Raum mit einem Schallpegelmesser und passe die Lautstärke des Fernsehers im Nebenzimmer entsprechend an.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'Melatoninfabrik 🌙', 'Damit dein Baby schneller einschläft, schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin wird nur in einer dunklen, technikfreien Umgebung rasch ausgeschüttet.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'Gute Manieren 👋', 'Wenn jemand zur Tür hinausgeht, winkt dein Kind von sich aus zum Abschied! So entwickeln sich soziale Intelligenz und Empathie. Bestärke es immer wieder in diesen höflichen Gesten.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'Gemeinsam aufräumen 🧹', 'Die Wohnung muss aufgeräumt werden? Wenn du das Zimmer fegst, lass dein Kind mit einem Tuch mitwischen und dir helfen. Lies in den Blogs, wie ihr das Putzen zu Teamarbeit und Spaß machen könnt.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'Gerät der Rhythmus durcheinander? ⏱️', 'Dauert das Einschlafen am Abend sehr lange? Sieh dir den Zeitplan im Schlaf-Timer an. Vielleicht ist es längst an der Zeit, den Mittagsschlaf deutlich zu verkürzen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', 'Der „Ich bin schon groß!“-Trotz 🛑', 'Dein Kind will bei allem mitmachen und hält dadurch alles auf? Gib ihm in diesem lustigen Kampf um Selbstständigkeit kleine Wahlmöglichkeiten.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', 'Das Wunder von 1000 Tagen! 👑', 'HERZLICHEN GLÜCKWUNSCH! Seit genau 1000 Tagen gehst du nun diesen turbulenten, anstrengenden, aber wertvollsten Weg der Welt! Feiere diesen besonderen Erfolgstag gebührend und teile ihn voller Stolz in der Anacan-Community!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'Der Siegestanz eures Teams 🥂', 'Feiere heute Abend gemeinsam mit deinem Partner oder deiner Partnerin all die Erschöpfung, Tränen und Freude dieser 1000 Tage. Stellt eine Kerze auf den Tisch und stoßt voller Freude auf euren unerschütterlichen Erfolg als Team an!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'Du hast es geschafft! 📈', 'Was für einen weiten Weg dein Kind zurückgelegt hat! Die zerbrechliche Unsicherheit der ersten Tage ist inzwischen einem riesigen Vertrauen gewichen. Du hast diese 1000 Tage voller Stolz gemeistert! Du bist wirklich großartig!'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'Kontakte im Park 🌳', 'Spielt dein Kind lieber für sich neben anderen Kindern, statt mit ihnen zusammen? Parallelspiel ist in diesem Alter völlig normal. Wenn Wetter und Kleidung passen, könnt ihr in den Park gehen.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'Schneller Kinderarzt 🤖', 'Gibt es beim Töpfchentraining Rückschritte? Mach dir keinen Stress – frag Anacan AI nach Lösungen, die euch bei diesem psychologischen Prozess helfen können.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d'::uuid, 'Die „Meins!“-Phase 🛑', 'Will dein Kind alles für sich beanspruchen? Das Verständnis fürs Teilen ist noch nicht vollständig entwickelt. Zwing es nicht dazu, sondern führt nach und nach die Regel „Wir wechseln uns ab“ ein.'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'Magische Einschlafkulisse 🪄', 'Fällt deinem Kind das Einschlafen schwer? Erstellt bei den intelligenten Märchen eine individuelle Geschichte und verwandelt neue Gewohnheiten in ein spannendes Abenteuer.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'Die Ästhetik-Krise beim Essen 🥦', 'Isst dein Kind die Brotrinde oder eine Gurkenscheibe nicht, weil sie „hässlich“ aussieht? Wählerisches Essverhalten kann ungewöhnliche Formen annehmen. Entdecke im Ernährungsplan die cleversten Möglichkeiten, Gemüse zu pürieren und unauffällig ins Essen zu mischen.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'Das Morgenkonzert beginnt 🎤', 'Singt dein Kind gleich nach dem Aufwachen irgendetwas in höchster Lautstärke? Um 7 Uhr morgens ist seine Energie bereits vollständig aufgeladen. Reib dir die Augen und genieße lächelnd die Show dieses kleinen Popstars.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'Überschwemmung im Badezimmer 🛀', 'Beim Spielen mit Wasser geht es weniger ums Sauberwerden als darum, das Badezimmer in einen Wasserpark zu verwandeln. Lass das Wasser ruhig spritzen. Warmes Wasser und Spaß lassen all den über den Tag angesammelten Trotz einfach davonschwimmen.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', 'Die „Nur noch eine“-Falle 📖', 'Dein Kind will nicht ins Bett und versucht, mit „Nur noch eine Geschichte!“ Zeit zu schinden. Lass die klassischen Bücher heute liegen. Erstellt bei den intelligenten Märchen eine kurze Einschlafgeschichte mit selbst erfundenen Figuren und bringt das Abendritual entspannt zu Ende.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'Morgengymnastik 🤸‍♂️', 'Du bist noch nicht einmal wach, da hüpft dein Kind schon auf dir im Bett herum. Der lauteste, aber auch süßeste Wecker der Welt! Starte lachend und mit seiner unbändigen Energie in den Tag.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'Einkaufschaos ohne Liste 🛒', 'Du warst einkaufen und bist ausgerechnet ohne das Wichtigste zurückgekommen? So ist das Gedächtnis als Mama. Verlass dich nicht auf deinen Kopf, sondern gewöhne dir an, jeden noch so kleinen Bedarf sofort auf die Einkaufsliste zu setzen.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'Tee bei Kerzenschein 🕯️', 'Dein Kind schläft. Mach das Licht aus und zünde eine Kerze auf dem Tisch an. Nicht für die Romantik, sondern einfach, um deine vom ganzen Tag überreizten Nerven und Augen zu beruhigen.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'Künstliche Intelligenz, echte Hilfe 🤖', 'Was steckt psychologisch dahinter, wenn dein Kind bei allem trotzt? Suche im Internet nicht nach beängstigenden Artikeln. Bitte Anacan AI um eine kurze, wissenschaftlich fundierte Erklärung zu den Krisen bei 33 Monate alten Kindern.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'Verschobener Schlafrhythmus ⏱️', 'Dauert das Einschlafen am Abend länger als 1 Stunde? Sieh dir die Übersicht im Schlaf-Timer an. Vielleicht ist es längst an der Zeit, den Mittagsschlaf deutlich zu verkürzen und die abendliche Schlafenszeit vorzuverlegen.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'Drama beim Haarekämmen 🪮', 'Schreit dein Kind beim Kämmen oder bei jeder Berührung der Haare, als wäre es die schlimmste Folter der Welt? Beende den Kampf. Gib ihm zuerst den Kamm und lass es deine Haare kämmen. Danach bist du an der Reihe.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'Eisenspeicher 🥩', 'Ist dein Kind blass oder hat es wenig Appetit? Überprüfe die Eisenaufnahme im Ernährungstracker. Gib zu Fleisch unbedingt einen Salat mit Zitrone dazu, um die Eisenaufnahme durch Vitamin C zu verbessern.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'Spielzeug teilen lernen 🧸', 'Sprich vor dem Parkbesuch mit deinem Kind darüber: Heute geben wir unsere Spielsachen abwechselnd weiter. Ja, wahrscheinlich wird es sie trotzdem nicht teilen, aber es muss diese abstrakte Regel immer wieder hören.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'Geheime Schokopause 🍫', 'Mama, die du heimlich im Stehen hinter der Küchenschranktür etwas Süßes naschst – wir sehen dich! Mach dir keine Vorwürfe. Du hast dir diesen Zuckerschub wirklich verdient, um den ganzen Lärm auszuhalten.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'Der kleine Diktator zu Hause 👑', 'Nicht da, setz dich hierhin! Das mache ich, nicht du! Dein Kind möchte zu Hause das Sagen haben. Brich seinen Willen nicht, sondern sorge für Ausgleich, indem du sagst: Du setzt dich hierhin und ich dorthin.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'Eine Massage von Papa 💆‍♂️', 'Heute warst du viel auf den Beinen, und vom ständigen Hinterherlaufen tut dir der Rücken weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind schläft. Du bist die Säule eures Zuhauses – und auch Säulen brauchen eine Pause.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'Nicht eingreifen 🧦', 'Die Ferse der Socke sitzt oben auf dem Fuß, aber dein Kind hat sie ganz allein angezogen und läuft herum wie der stolzeste Mensch der Welt. Greif auf keinen Fall ein. Das Gefühl von Selbstständigkeit ist wichtiger als eine richtig sitzende Socke.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'In der Community durchatmen 💬', 'Bist du völlig erschöpft und fühlst dich wie die ungeduldigste Mutter der Welt? Öffne sofort die Anacan-Community. Zu lesen, dass andere Mütter die gleichen Krisen erleben, kann eine große seelische Unterstützung sein.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'Das Wolkenrätsel ⛅', 'Fällt dir zu Hause die Decke auf den Kopf? Macht euch dem Wetter entsprechend fertig und geht in den Park. Setzt euch einfach hin und überlegt, woran euch die Wolken am Himmel erinnern. Dieses ruhige Spiel entspannt und fördert zugleich das Gehirn.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'Das Chaos zu Hause ist endlich vorbei.', 'Mach Lofi-Musik an, um die Geräusche von draußen auszublenden und zur Ruhe zu kommen.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'Die ersten kleinen Schwindeleien? 🤥', 'Ich habe das Wasser nicht verschüttet, das war mein Teddybär. Achtung! Die Fantasie deines Kindes ist inzwischen so weit entwickelt, dass es sich Ereignisse zu seinen Gunsten ausdenken kann. Beschuldige es nicht, zu lügen. Lächle und sag einfach: Sag deinem Teddybären, dass er es nicht noch einmal tun soll.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'Papas Einschlaftaktik 👨‍🍼', 'Will dein Kind abends keinen Schlafanzug anziehen und läuft davon? Dann ist Papa dran. Wenn er das Anziehen in einen Ringkampf oder ein lustiges Spiel verwandelt, trägt das Kind plötzlich seinen Schlafanzug, ohne es überhaupt zu merken.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'Natur-Rätsel 🍁', 'Macht aus dem Spaziergang im Park ein Spiel: Komm, wir suchen das größte gelbe Blatt! Die Natur ist für dein Kind die größte und interaktivste Schule.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'Faszination Waschmaschine 🧺', 'Sitzt dein Kind vor der Waschmaschine und beobachtet konzentriert die Wäsche, die sich darin dreht? Das ist eine völlig kostenlose und beruhigende Beschäftigung. Stör es nicht dabei und nutze die Gelegenheit, um dich ebenfalls auszuruhen.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'Geständnisse im Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Statt durch die sozialen Medien zu scrollen, öffne das Stimmungstagebuch und schreibe dir alles von der Seele, was dich heute wahnsinnig gemacht hat. Digitale Therapie kann wirklich helfen.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'Zeit für Melatonin 🌙', 'Verzichte mindestens 1 Stunde vor dem Schlafengehen vollständig auf Blaulichtquellen wie Fernseher und Tablet, damit das Schlafhormon seine Wirkung entfalten kann. Dunkelheit und Ruhe sind die beste Einschlafhilfe.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'Das Ich bin Mama!-Spiel 🎭', 'Droht dein Kind seiner Puppe mit dem Finger und schimpft dabei in genau deinem Tonfall? Da läuft eine kleine Version von dir durchs Zimmer. Dich selbst von außen zu sehen, ist nicht nur lustig, sondern auch ein Hinweis darauf, bewusster auf dein eigenes Verhalten zu achten.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'Wenn der Mittagsschlaf verweigert wird 🥱', 'Will dein Kind nicht ins Bett, obwohl ihm vor Müdigkeit schon die Augen zufallen? Gegen 3 Jahre ist dieser Widerstand ganz typisch. Zwing es nicht, sondern dimme das Licht im Zimmer und erkläre die stille Bilderbuchzeit.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'Die Farbe des morgendlichen Trotzes 🔴', 'Dein Kind wollte sein Essen auf dem grünen Teller, doch sobald du ihn bringst, weint es und behauptet, es hätte Rot gesagt. Hör auf, nach Logik zu suchen. Fülle das Essen einfach auf den roten Teller um und schone deine Nerven.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'Operation „Verstecktes Gemüse“ 🥦', 'Schiebt dein Kind das Gemüse in der Suppe beiseite, als würde es mit einem Mikroskop danach suchen? Unter den gesunden Rezepten findest du Soßenrezepte, mit denen sich Gemüse unsichtbar machen lässt. Kreativität ist die stärkste Geheimwaffe einer Mutter.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'Schau nach unten – was entdeckt dein Kind? 👣', 'Dein Kind liebt es besonders, barfuß zu laufen und verschiedene Oberflächen zu ertasten. Die Stimulation der Nerven an den Fußsohlen ist wichtig für sein Gleichgewicht. Lass es daher ruhig ohne Socken laufen.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'Beschützer der Nacht 🧸', 'Hat dein Kind Angst vor der Dunkelheit? Stell seine liebsten Teddys und Spielsachen rund um das Bett und sag: „Sie werden dich bis zum Morgen beschützen.“ Dieses sichtbare Gefühl von Sicherheit wirkt wunderbar.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'Die beruhigende Kraft der Stille 🤫', 'Miss nach einem lauten Tag mit einem Schallpegelmesser, wie still das Zimmer ist, sobald dein Kind schläft. Schon der Anblick der Werte, die sich null nähern, kann auf das Gehirn einer Mutter wie eine Therapie wirken.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'Das morgendliche „Nein!“ 🛑', 'Noch bevor dein Kind die Augen geöffnet hat, antwortet es auf jeden Vorschlag mit „Nein!“. Kurz vor dem dritten Geburtstag solltest du keine Fragen stellen, sondern direkt zum nächsten Schritt übergehen. Sag statt „Wollen wir Hände und Gesicht waschen?“ lieber: „Jetzt ist Zeit zum Hände- und Gesichtwaschen!“'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'Nimm dir auch Zeit für dich 🥑', 'Der Alltagsstress hat dich erschöpft. Statt nur schnell im Stehen etwas zu naschen, stell dir aus den gesunden Rezepten einen sättigenden, vitaminreichen Teller zusammen und genieße ihn in Ruhe. Du brauchst diese Energie unbedingt.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'Flüstergespräch 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und erzähl ihm ganz leise und flüsternd, was im Laufe des Tages passiert ist. Flüstern ist eine der besten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'Erfahrungen austauschen 💬', 'Macht es dir Angst, dass dein Kind bei allem seinen Willen durchsetzen möchte? Suche im Internet nicht nach beängstigenden Artikeln. Nutze lieber die Erfahrungen anderer Mütter in der Anacan-Community und lächle darüber.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'Nächtlicher Sturm 😭', 'Ist dein Baby mitten in der Nacht scheinbar grundlos weinend aufgewacht? Sind es Blähungen oder Nachtschreck? Hör auf zu rätseln: Finde mit der Weinanalyse die Ursache heraus und beruhige dein Baby mit einer liebevollen Umarmung.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'Töpfchenunfälle 🚽', 'Beim Töpfchentraining ist schon wieder Pipi auf dem Teppich gelandet? Atme tief durch. Wenn du schimpfst, kann das zu Rückschritten führen. Lass dich von etwas, das sich wegwischen lässt, nicht aus der Ruhe bringen – es gehört einfach zum Lernprozess dazu.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'Der kleine Anwalt im Park 🗣️', '„Nur noch ein bisschen, nur 5 Minuten!“, sagt dein Kind und versucht, mehr Spielzeit auszuhandeln. Es hat noch kein Zeitgefühl, ist aber schon ein echtes Verhandlungstalent. Stelle einen Timer und erinnere spielerisch an eure Abmachung, ohne daraus einen Streit zu machen.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'Wachstumsschub 📏', 'Sind die Hosen plötzlich zu kurz? Dein Kind wächst rasant! Trage die aktuellen Maße in den Entwicklungstracker ein und bestaune stolz, was aus all deinen schlaflosen Nächten geworden ist.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'Zeit für euch als Paar 🥂', 'Das Kind schläft. Legt jetzt die Handys und die Hausarbeit beiseite. Sprecht mindestens 20 Minuten miteinander – über etwas anderes als das Kind und Rechnungen.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'Die magische Welt der Märchen 🪄', 'Probiert heute Abend bei den smarten Märchen etwas ganz Neues aus: die Geschichte von der kleinen Wolke, die den Himmel entdeckt. Passe deine Stimme an den Rhythmus des Märchens an und begleite dein Kind sanft in den Schlaf.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', 'Der „Schau mich an!“-Klaps 👀', 'Während du auf dein Handy schaust, kommt dein Kind zu dir, schlägt dir gegen die Hand oder nimmt dir das Gerät weg. Und damit hat es völlig recht. In diesem Moment möchte es deine sofortige und ungeteilte Aufmerksamkeit. Stelle Blickkontakt her und zeige ihm, dass du zuhörst.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'Hartnäckige Flecken, grenzenloses Entdecken 🎨', 'Ist der Schlafanzug voller Essensreste und die Kleidung mit Farbe bekleckert? Kinder müssen nicht sauber aufwachsen – beim Entdecken dürfen sie schmutzig werden. Das Chaos ist die Handschrift ihrer Kreativität. Mach dir keinen Stress.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'Professioneller Tänzer 🎶', 'Sobald dein Kind einen Rhythmus hört – ob in der Werbung oder von einer Autohupe –, beginnt es zu tanzen. Sieh das Leben so fröhlich wie dein Kind! Mach mit und tanzt ein paar Minuten lang ausgelassen durchs Zimmer.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'Papas Geheimtaktik 👨‍🍼', 'Die Müdigkeit des Tages reicht dir völlig. Überlass am Abend Papa mit seinen spielerischen Tricks das Zubettgehen und Zähneputzen, während du dich in Ruhe zurücklehnst und entspannst.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'Gefaltete und wieder verstreute Kleidung 👗', 'Du faltest mühsam die Kleidung zusammen, und dein Kind kommt und wirft im Nu alles durcheinander. Statt dich zu ärgern, mach ein Spiel daraus: Mal sehen, wer dieses T-Shirt weiter werfen kann!'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'Ich will allein essen! 🥄', 'Dein Kind nimmt den Löffel und bekleckert alles? Starte den Ernährungstimer. Freu dich nicht über das verschüttete Essen, sondern über die Selbstständigkeit, die dein Kind dabei gewinnt.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'Barfuß auf Entdeckungstour 👣', 'Dein Kind will keine Socken anziehen, läuft weg und versteckt sich? Lass es eine Weile barfuß den Boden, den Teppich und die kalten Fliesen spüren. Die Stimulation der Nervenenden an den Fußsohlen ist für die Entwicklung seines Gleichgewichtssinns besonders wertvoll.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin wird nur in einer dunklen, technikfreien Umgebung ausgeschüttet.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'Auf Entdeckungstour in der Natur 🍁', 'Zieht euch dem Wetter entsprechend an und geht nach draußen. Spielt im Park ein Suchspiel und findet verschiedene Steine und bunte Blätter. Die Natur ist in diesem Alter das größte und interaktivste Spielzeug für dein Kind.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'Beim Einkaufen etwas vergessen? 🛒', 'Du hast dich auf dein Gedächtnis verlassen und beim Einkaufen ausgerechnet das Wichtigste vergessen? Gewöhn dir an, alles, was du brauchst, sofort in die Einkaufsliste einzutragen. Lass dich von der App daran erinnern.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'Kleine Küchenhilfe am Morgen 🧑‍🍳', 'Dein Kind möchte beim Zubereiten des Frühstücks helfen. Dabei wird Mehl verschüttet, Wasser verteilt und die Küche im Chaos versinken ... Doch durch diese kleinen Übungen entwickelt es seine Feinmotorik. Hab Geduld.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'Papas Zaubershow 🤡', 'Wenn deine Tricks nicht mehr helfen, retten Papas seltsame Geräusche sofort die Situation. Überlass ihm bei abendlichen Krisen das Ruder und genieße von der Seitenlinie aus das fröhliche Gelächter.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'Ein warmes Bad als Therapie 🛀', 'Nach einem Tag voller Herumrennen seid ihr beide erschöpft. Lass während eines lauwarmen Bades im Hintergrund beruhigende Naturgeräusche laufen. Die Harmonie des Wassers bereitet selbst das hartnäckigste Kind auf den Schlaf vor.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'Ich will selbst einschenken! 💧', 'Dein Kind will das Wasser unbedingt selbst ins Glas gießen. Halte Tücher bereit und bremse seine Selbstständigkeit nicht aus. Es wird etwas verschütten, aber nach ein paar Versuchen wirst du staunen, wie vorsichtig es das Glas füllt.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'Gefühl der Erschöpfung 🔋', 'Fühlst du dich nicht gut genug? Denkst du, dass du nicht alles schaffst? Schau dir die Beiträge in der Community an: Du bist nicht allein und keineswegs unzulänglich. Du bist die ganze Welt deines Kindes.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'Ungewöhnliche Grammatik 🗣️', 'Dein Kind macht völlig neue, ganz eigene grammatikalische Entdeckungen und sagt Dinge wie „Ich habe Hunger gehabtet“ oder „Er ging und ist gekommen“. Korrigiere es nicht streng, sondern antworte einfach, indem du den Satz in der richtigen Form wiederholst.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Tipp von Anacan AI 🤖', 'Hast du Fragen dazu, wie dein Kind im Park mit anderen Kindern Kontakte knüpft? Verlier dich nicht stundenlang im Internet. Frag Anacan AI und erhalte sofort einen kinderärztlich geprüften, entwicklungsgerechten Rat.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'Hinweis zum Nachtschreck 😭', 'Wenn dein Kind plötzlich weint oder mit geschlossenen Augen schreit, überprüfe es mit der Weinanalyse. Handelt es sich um einen Nachtschreck, versuche nicht, es zu wecken. Bleib einfach bei ihm und vermittle ihm ruhig ein Gefühl von Sicherheit.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'Die Zeit vergeht wie im Flug!', 'Blick zurück und sieh, wie viel du gelernt hast. Dein kleiner Verhandlungskünstler kann inzwischen bei jedem Thema mit dir feilschen. Sei stolz auf dein Kind und auf dich selbst.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'Die Hauptfigur im Märchen 🪄', 'Ihr habt beide genug von den klassischen Kinderbüchern. In fantasievollen Geschichten kannst du dein Kind als Astronaut zu den Sternen fliegen oder in die Tiefen des Meeres tauchen lassen. Lasst eurer Fantasie vor dem Schlafengehen freien Lauf.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'Eine Ruhezeit ist ein Muss ☕', 'Wenn dein Kind den Mittagsschlaf partout verweigert, zwinge es nicht dazu. Führe stattdessen eine 30-minütige Ruhezeit (quiet time) ein. Es kann allein mit Büchern im Bett bleiben, während du im Zimmer eine Verschnaufpause einlegst.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Statt durch soziale Medien zu scrollen, öffne das Stimmungstagebuch und halte für später den lustigsten Moment des Tages fest, bei dem dein Kind dich am meisten zum Lachen gebracht hat.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'Mission: verstecktes Gemüse 🥦', 'Dein Kind fischt das Gemüse aus der Suppe und lässt es liegen? Mach keinen Kampf daraus. Entdecke im Ernährungsplan kreative und raffinierte Möglichkeiten, Gemüse zu pürieren und in Soßen zu verstecken.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', 'Das beharrliche „Mama, schau mich an!“ 👀', 'Dein Kind kommt zu dir und schlägt dir das Handy aus der Hand, wenn du darauf schaust oder etwas erledigst? Sein Wunsch nach deiner ungeteilten Aufmerksamkeit ist völlig verständlich. Schon 5 Minuten bewusste gemeinsame Zeit mit Blickkontakt können dein Kind beruhigen.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'Das Fangspiel durchs Zimmer 🏃‍♂️', 'Wenn du deinem Kind den Schlafanzug oder ein Oberteil anziehen möchtest, läuft es lachend aus dem Zimmer. Werde nicht ärgerlich, sondern mach ein Spiel daraus. Beim Fangenspielen geht das Anziehen leichter.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'Wetterhinweis ⛅', 'Lass dich vor dem Spaziergang nicht vom Blick aus dem Fenster täuschen. Mit dem Wetter- und Kleidungsassistenten findest du die passende Kleidung für die tatsächliche Temperatur und den Wind draußen, bevor ihr das Haus verlasst.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'Teamsieg 🥂', 'Ihr habt einen weiteren anstrengenden Tag geschafft. Setzt euch gegenüber und stoßt mit einer Tasse Tee an: Wir sind wirklich ein legendäres Team und machen das großartig!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'Das Dilemma mit dem Teilen 🧸', 'Will dein Kind sein Spielzeug niemandem geben? Das ist kein Egoismus, sondern Teil seiner Entwicklung. Erfahre von Anacan AI, warum es mit fast 3 Jahren noch nicht ums Teilen, sondern ums Abwechseln beim Spielen geht.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'Dreirad 🚴‍♂️', 'Versucht dein Kind, in die Pedale zu treten und loszufahren? Seine Beinmuskulatur und Koordination erreichen eine neue Entwicklungsstufe! Ermutige es, an sicheren Orten zu üben.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'Vitamine für Mama 🥑', 'Du tust alles, damit dein Kind satt wird. Aber was ist mit dir? Wähle im Bereich mit gesunden Rezepten ein leichtes, eisen- und kalziumreiches Mittagessen aus.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'Papas Nachtschicht 👨‍🍼', 'Bewältige das nächtliche Aufwachen nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig aufzuteilen.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'Taschen voller Schätze 🍁', 'Ihr kommt aus dem Park zurück und in der Tasche deines Kindes findest du 3 Steine, 1 vertrocknetes Blatt und einen Stock? Für dein Kind sind das wertvolle Schätze. Versuche einfach, sie unauffällig verschwinden zu lassen, bevor sie im ganzen Haus verteilt werden.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'Such nicht nach Logik 👑', 'Verlangt dein Kind zum Frühstück Eis oder die Linsensuppe von gestern? Im Haus gibt es einen neuen Diktator. Lenke es schnell ab, indem du ihm eine Auswahl gibst (zum Beispiel: Möchtest du einen Apfel oder eine Banane?).'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'Körper-Tattoos 🖍️', 'Ein paar Sekunden Stille können manchmal gefährlich sein. Du kommst ins Zimmer und siehst, dass dein Kind seine Arme mit Filzstiften tätowiert hat? Atme tief durch. So entwickelt sich die Feinmotorik – und die Farbe lässt sich von der Haut wieder abwaschen.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'Papa übernimmt 👨‍👧', 'Am späten Nachmittag ist deine Energie aufgebraucht? Sag einfach: „Ich bin für heute raus“, und übergib das Kind seinem Papa. Das Zimmer aufzuräumen, das die beiden gemeinsam verwüstet haben, ist leichter, als allein mit dem Kind zu kämpfen.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'Ballaststoffbedarf 💩', 'Dein Kind rennt viel herum, vergisst aber, Wasser zu trinken. Beobachte den Stuhlgang beim Töpfchentraining. Besteht Verstopfungsgefahr, ergänze den Speiseplan um Haferflocken und Pflaumen.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'Der Schatten als Feind 👻', 'Dein Kind fängt draußen oder im Zimmer plötzlich an zu weinen? Vielleicht liegt es daran, dass sein Schatten ihm folgt! Gegen Ende des dritten Lebensjahres nimmt die Fantasie manchmal seltsame Formen an. Nimm dein Kind in den Arm und stelle ihm den Schatten mit einem Lächeln vor.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'Der Lebensmittelchirurg 🥦', 'Dein Kind isst nicht, sondern sortiert nur mit chirurgischer Präzision kleine Reiskörner oder grüne Kräuter aus dem Essen. Öffne den Ernährungsplan und entdecke Möglichkeiten, Gemüse als Püree anzubieten.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'Allem Gute Nacht sagen 🧸', 'Vor dem Schlafengehen möchte dein Kind dem Spielzeugauto, dem Stuhl und sogar der Türklinke Gute Nacht sagen. Das ist eines seiner neuen Einschlafrituale – dränge es nicht zur Eile.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'Erfundene Geschäftstelefonate 🍌', 'Dein Kind hält eine Banane oder die Fernbedienung ans Ohr und führt in einer Fantasiesprache ein ernstes Telefongespräch? Es ahmt deine Körpersprache ganz genau nach. Nimm es auf Video auf und bewahre die Aufnahme für später auf – du wirst noch viel darüber lachen.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'Gerät der Rhythmus durcheinander? ⏱️', 'Dauert das Einschlafen am Abend länger als 1 Stunde? Sieh dir die Übersicht im Schlaf-Timer an. Vielleicht ist es an der Zeit, den Mittagsschlaf ganz wegzulassen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'Ab in den Ruhemodus 🤫', 'Wenn dein Kind einschläft, reagiert es besonders empfindlich. Sorge für eine ruhige Umgebung.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'Papas Einschlafduett 📖', 'Sorgt heute Abend für eine besondere Atmosphäre im Zimmer. Statt ein Buch vorzulesen, kann Papa gemeinsam mit eurem Kind leise ein rhythmisches Lied singen und es so sanft in den Schlaf begleiten.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'Mama, stärke dich 🥑', 'Iss dein Mittagessen im hektischen Alltag nicht im Stehen. Setz dich hin, bereite dir einen besonderen Salat mit viel Eisen und Kalzium zu und genieße ihn in Ruhe. Deine Energie ist der Motor dieses Zuhauses.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'Erste Schritte zur Freundschaft 👫', 'Hat dein Kind im Park zum ersten Mal von sich aus sein Spielzeug mit einem anderen Kind geteilt? Das ist ein großer Entwicklungsschritt! Die egozentrische Phase lässt nach und Empathie entwickelt sich. Freu dich mit ihm und lobe es begeistert.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', '10 Minuten bei Kerzenschein 🕯️', 'Dein Kind schläft und das Chaos zu Hause ist vorbei. Schalte das Licht aus und schau einfach 10 Minuten lang in die Dunkelheit oder in eine Kerzenflamme. Lass dabei deinen Kopf und deine Gedanken vollkommen zur Ruhe kommen.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'Trost in der Community 💬', 'Bedrückt dich der Gedanke: „Ich werde nie wieder die Alte sein“? Teile dieses vorübergehende, aber sehr belastende Gefühl mit den Müttern in der Anacan-Community und hol dir Unterstützung.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'Widerspenstige Zöpfe 🪮', 'Dein Kind lässt sich partout nicht die Haare zusammenbinden oder kämmen? Beende den Machtkampf. Stell dich mit ihm vor den Spiegel und kämme zuerst dein eigenes Haar so, wie dein Kind es möchte. Danach ist dein Kind an der Reihe.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'Der Kampf um den Mittagsschlaf 🥱', 'Wenn dein Kind nicht schlafen möchte, zwinge es nicht dazu. Statt immer wieder zu versuchen, es hinzulegen, und dabei die Nerven zu verlieren, kannst du eine ruhige Auszeit im Zimmer einführen, in der es still mit seinen Spielsachen spielt.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'Zahnbürstenkrieg 🪥', 'Macht dein Kind den Mund fest zu, sobald es die Zahnbürste sieht? Mach die Zahnpflege nicht zum Kampf. Schau dir unter „Empfohlene Produkte“ musikalische Zahnbürsten an und verwandle diese mühsame Routine in ein lustiges Spiel.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', '„Meine Beine funktionieren nicht“-Trotz 🛑', 'Setzt sich dein Kind auf dem Rückweg vom Park plötzlich auf den Boden, behauptet, seine Beine würden nicht mehr funktionieren, und will getragen werden? Das ist keine Müdigkeit, sondern ein kleines Machtspiel. Frag: „Mal sehen, ob du bis nach Hause wie ein Hase hüpfen kannst!“ – und mach ein Spiel daraus.'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'Töpfchen-Versteckspiel 🚽', 'Versteckt sich dein Kind hinter dem Vorhang oder neben dem Sofa, wenn es mal muss? Dann ist jetzt der perfekte Zeitpunkt, im Bereich „Blogs“ nachzulesen, wie du Schritt für Schritt und wissenschaftlich fundiert mit dem Töpfchentraining beginnen kannst.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'Frust im Tagebuch ablassen 📝', 'Hat jemand zu dir gesagt: „Du bist doch zu Hause – wovon bist du müde?“ Öffne sofort dein Stimmungstagebuch und tippe deinen ganzen Ärger in den Bildschirm. Es ist besser, deine wahren Gefühle aufzuschreiben, als ein Lächeln vorzutäuschen.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'Papas Märchen-Show 📖', 'Heute Abend gehört die Stimme im Kinderzimmer nicht dir, sondern Papa. Lass ihn die Geschichte vorlesen und mit tiefen und hohen Stimmen für die Figuren für Lacher sorgen. Du lehnst dich zurück und lauschst einfach dem fröhlichen Lachen.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'Mamas geheime Schokolade 🍫', 'Liebe Mama, die du dir schnell ein Stück Schokolade in den Mund steckst und es hastig kaust, sobald dein Kind sich umdreht: Diese Glukose steht dir von Herzen zu. Du musst schließlich deine Akkus aufladen, um den ganzen Tag mit dieser Energie mithalten zu können.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'Ein ungewöhnlicher bester Freund 🥄', 'Obwohl so viele teure Spielsachen herumliegen, hat dein Kind in der Küche einen Silikonspatel entdeckt, trägt ihn den ganzen Tag mit sich herum und bringt ihn sogar ins Bett? Das kindliche Gehirn ist unglaublich. Halte es nicht davon ab – lass es seinen Spatel lieben.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'Schatzsuche in der Natur ⛅', 'Die eigenen vier Wände haben deinen Kopf ganz benebelt. Schau auf das Wetter, wähle die passende Kleidung aus und geh nach draußen. Macht euch einfach auf die Mission, ein gelbes Blatt zu finden – so kann dein Kind Energie loswerden und du kannst gleichzeitig durchatmen.'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'Schrumpelfinger in der Badewanne 🛀', 'Mit Wasser zu spielen macht so viel Spaß, dass dein Kind trotz schrumpeliger Finger nicht aus der Badewanne kommen möchte. Kündige das Ende 5 Minuten vorher an und stelle einen Timer. Die Regel „Wenn es klingelt, steigen wir aus der Wanne“ funktioniert meistens gut.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'Der Kampf ums Haarefrisieren 🪮', 'Dein Kind wacht morgens auf und seine Haare stehen in alle Richtungen ab, als hätte es einen Stromschlag bekommen. Sobald es die Bürste sieht, rennt es davon. Statt die Haare zu kämmen, kannst du sie mit angefeuchteten Händen glatt streichen und so den Kampf beenden.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'Was die künstliche Intelligenz sagt 🤖', 'Dein Kind hat eine seltsame Angewohnheit entwickelt, zum Beispiel Nägelkauen, und die Artikel im Internet haben dir Angst gemacht? Stopp. Frage Anacan AI nach möglichen, kinderärztlich fundierten Ursachen und beruhige dich.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'Der Doktor ist für dich da 🩺', 'Dein Kind nimmt sein Spielzeugstethoskop, legt es auf deine Brust und fordert dich auf, tief einzuatmen. Du bist krank und dein Kind ist der Chefarzt. Spiel mit, leg dich hin, schließe während der Behandlung die Augen und ruhe dich aus – wenn auch nur für 5 Minuten.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'Plötzlicher Energieschub 🏃‍♂️', 'Dein Kind klettert zu Hause förmlich die Wände hoch. Prüfe das Wetter, zieh ihm passende Kleidung an und geht unbedingt nach draußen. 30 Minuten Bewegung an der frischen Luft sind die beste Voraussetzung für einen guten Schlaf am Abend.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'Die Magie des Flüsterns 🌙', 'Schalte alle Lichter im Zimmer aus. Leg dich neben dein Kind und erzähle ihm ganz leise und flüsternd, was im Laufe des Tages passiert ist. Flüstern ist eine besonders natürliche und beruhigende Methode, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'An die Dunkelheit gewöhnen 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Die Ausschüttung des Hormons Melatonin wird vor allem in einer ruhigen und dunklen Umgebung gefördert.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'Mamas Ladezeit 🔋', 'Dein Kind puzzelt allein und ist seit 10 Minuten still. Du möchtest diesen Moment nutzen, um die Wohnung aufzuräumen. Nein! Leg dich aufs Sofa. Auch dein Akku muss aufgeladen werden, damit du bis zum Abend durchhältst.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'Verbotene Wörter 🤐', 'Wiederholt dein Kind lachend ein Schimpfwort, das es irgendwo gehört hat, und wartet auf deine Reaktion? Deine stärkste Waffe ist, nicht darauf zu reagieren. Lach nicht, ärgere dich nicht – ignoriere es einfach. Es wird das Wort wieder vergessen.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'Goldene Stille nach Maß 🤫', 'Endlich ist dein Kind eingeschlafen! Aktiviere den Schallpegelmesser und beobachte auf dem Bildschirm den Geräuschpegel im Zimmer (0-10 Dezibel). Diese Zahlen zu sehen, ist die beste Massage für das Gehirn einer müden Mama.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'Der hartnäckige Pyjama 👗', 'Dein Kind will den schmutzigen und fleckigen Pyjama, den es seit dem Morgen trägt, einfach nicht ausziehen? Mit 3 Jahren spielt Ästhetik keine Rolle. Solange ihm nicht kalt ist, lass es ruhig noch ein paar Stunden so herumlaufen.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'Ich im magischen Märchen 🪄', 'Die klassischen Bücher kennst du schon auswendig. Öffne die intelligenten Märchen, mache dein Kind zur Hauptfigur und sein Zimmer zum Ort, den es zu erobern gilt. So gestaltest du ein außergewöhnliches Einschlafritual.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'Kleiner Zeichentrickkritiker 📺', 'Dein Kind erzählt dir in seiner eigenen Grammatik von dem Zeichentrickfilm, den es gesehen hat, und erklärt ganz ernst, wer wohin gegangen ist. Hör aufmerksam und mit staunendem Gesicht zu. Lass es sich wie der klügste Mensch der Welt fühlen.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'Wach vor Sonnenaufgang 🌅', 'Dein Kind ist um 6 Uhr schon auf den Beinen, während du völlig erschöpft bist? Frag Anacan AI, wie du diesen Rhythmus anpassen kannst. Denk daran: Der Schlafmangel hält nicht ewig an. Auch diese Phase geht vorüber.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'Der Paar-Champagner 🥂', 'Das Kind schläft. Auch wenn ihr keinen Champagner habt, gießt euch heißen Tee in Gläser und stoßt mit den Worten „Auch diesen schwierigen Tag haben wir gut überstanden“ an. Du bist eine großartige Partnerin.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'Überraschung auf der Liste 🛒', 'Du öffnest vor dem Einkauf die Einkaufsliste und siehst, wie dein Kind von hinten auf den Handybildschirm tippt und Schokolade hinzufügt. Ja, Kinder kennen sich mit Technik besser aus als wir!'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'Einschlafen mit Naturgeräuschen 🪄', 'Klassische Musik hilft nicht? Schließe bei den intelligenten Märchen die Geschichte und wechsle zu einer Geräuschkulisse mit Regen- oder Waldgeräuschen. Gleichmäßige Naturgeräusche lassen dein Kind wie durch Zauberhand einschlafen.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'Seufzen wie die Großen 😔', 'Dein Kind sitzt auf dem Sofa, atmet plötzlich wie ein Erwachsener tief ein und seufzt. Es ahmt dich einfach verblüffend gut nach! Beobachte seine dramatische Mimik einfach lächelnd aus der Ferne.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'Küchenkatastrophen 🧑‍🍳', 'Beim Kochen will dein Kind unbedingt am Herd helfen und das Salz hineinschütten. Lässt du es zu, ist das Essen ruiniert, lässt du es nicht zu, fließen die Tränen. Gib ihm eine leere Schüssel und etwas Wasser und sage: „Koch du deine eigene Suppe.“'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'Die Liste im Blick behalten 🛒', 'Hast du alles, was du für den Jubiläumstag brauchst, zur Einkaufsliste hinzugefügt? Vergewissere dich, dass auch Luftballons und kleine Überraschungen daraufstehen. Schicke deinem Partner über die App eine letzte Erinnerung.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'Lichtwächter 🤫', 'In der ersten halben Stunde nach dem Einschlafen ist das Gehirn besonders aktiv. Überprüfe das Zimmer mit dem Geräuschpegelmesser. Dämpfe die Geräusche von draußen und schaffe eine vollkommen ruhige und dunkle Umgebung.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'Regisseur der Geschichte 🪄', 'Öffne die intelligenten Märchen und lass dein Kind heute Abend die Handlung bestimmen. Frage: „Wohin soll die Hauptfigur jetzt gehen?“ Lass es ein herrlich absurdes Ende erfinden und dabei selbst einschlafen.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'Tränen ohne Logik 🐶', 'Dein Kind hat 15 Minuten lang bitterlich geweint, weil der Hund auf der Straße es nicht angesehen hat? Suche nicht nach Logik. Für dein Kind ist das wirklich sehr traurig. Bestätige sein Gefühl, indem du sagst: „Ich weiß, du wolltest, dass der Hund dich ansieht.“'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'Das Chaos zu Hause akzeptieren 🌪️', 'Das ganze Zimmer ist voller Spielzeug? Nicht die Ordnung zählt, sondern die ausgelassenen Momente, die ihr miteinander verbringt. Das Spielzeug ist morgen auch noch da – überanstrenge dich nicht. Manchmal ist es die beste Erholung, sich dem Chaos einfach hinzugeben.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'Rückschritt beim Toilettentraining? 🚽', 'Dein Kind konnte schon aufs Töpfchen gehen, doch jetzt passieren wieder Missgeschicke? Das ist ein ganz normaler Rückschritt. Setze es nicht unter Druck und frage Anacan AI, wie ihr diese psychische Hürde ohne Drama überwinden könnt.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'Inspiration aus den Blogbeiträgen 📱', 'Welche Entwicklungssprünge macht ein Kind mit fast 35 Monaten? Was sollte es bereits können? Sieh dir die Entwicklungsbeiträge in der App an und freue dich darüber, wie weit dein Kind schon ist.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'Vorbereitung auf den großen Tag 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig zum morgigen großen Meilenstein gratulieren und einander mit einer kleinen Schultermassage verwöhnen. Damit ihr genug Energie für den Jubiläumstag habt, solltet ihr euch beide gut ausruhen.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'Toben im Schlafzimmer 🏃‍♂️', 'Springt dein Kind auf dem Sofa herum, statt zu schlafen? Und findet es immer neue Gründe, noch etwas Wasser zu verlangen? Starte den Schlaftimer und bleibe konsequent bei euren Grenzen.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'Papa ist mit Spielen dran 👨‍👧', 'Muttersein sollte kein endloser Marathon sein. Lass dein Kind heute mit Papa im Park seine Energie austoben, während du die Ruhe auf dem Sofa genießt.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'Wintermützen im Sommer 🧢', 'Möchte dein Kind unbedingt etwas anziehen, das überhaupt nicht zum Wetter passt? Gib ihm in seinem Streben nach Selbstständigkeit kleine Wahlmöglichkeiten.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'Die endlose Fragemaschine 🤔', 'Zermürben dich die ständigen Fragen „Warum?“ und „Wie?“? Frage Anacan AI, wie du seine Entdeckerfreude mit logischen Antworten fördern kannst, ohne die Geduld zu verlieren. Deine Geduld unterstützt seine Entwicklung.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'Tagebuch der Stille 📝', 'Der kleine Wirbelsturm zu Hause ist endlich eingeschlafen. Nimm jetzt dein Handy und schreibe dir im Stimmungstagebuch einen Dankesbrief dafür, dass du den heutigen Tag überstanden hast. Du schaffst das.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'Fantasiegrammatik 🗣️', 'Dein Kind erfindet seltsame und lustige Zeitformen wie „Ich gingte“ oder „Er ist gekommt“. Sein Wortschatz entwickelt sich weiter! Lach nicht darüber und korrigiere es nicht direkt, sondern wiederhole den Satz einfach in der richtigen Form.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'Zuflucht im Stimmungstagebuch 📝', 'Niemand merkt, wie erschöpft du bist? Das Stimmungstagebuch in der App ist da, um dir zuzuhören. Schreib dort all die kleinen Dinge auf, die dich heute wahnsinnig gemacht haben, und befrei deinen Kopf.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'Essensexperimente 🥣', 'Bis gestern hat dein Kind noch alles gegessen, heute spuckt es alles wieder aus. Wenn es keine Zahnprobleme hat, testet es wahrscheinlich nur seine Grenzen. Probier bei den gesunden Rezepten die leckeren, bunten Bratlinge aus, in denen Gemüse versteckt ist.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', 'Die 5-Minuten-Illusion ⏱️', 'Dein Kind sagt: „Nur noch 5 Minuten schauen“, hat aber noch kein richtiges Zeitgefühl. Stell den Timer auf deinem Handy und erklär ihm, dass die Zeit vorbei ist, sobald das Signal ertönt. So ist die Technik schuld – und nicht du.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'Reiten auf Papas Rücken 🐴', 'Dein Kind hat noch zu viel Energie und will nicht ins Bett? Auf Papas Rücken durch die Wohnung zu reiten und dabei Lachanfälle zu bekommen, ist die schnellste und lustigste Art, die restliche Energie loszuwerden. Jetzt ist Papa am Zug.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'Mamas Bedürfnis nach Ruhe 🩸', 'Reizt dich gerade jedes Geräusch? Schau in deinen Perioden-Tracker. Dein Körper braucht Erholung. Bereite dir mit den gesunden Rezepten einen magnesiumreichen Snack zu und nimm dir Zeit für dich.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'Scheinbar grundloses Weinen 😭', 'Dein Kind beginnt sofort nach dem Aufwachen scheinbar grundlos zu weinen? Das ist keine Laune, sondern emotionale Überforderung. Sprich mit unserem Anacan AI-Experten darüber und finde heraus, wie du in solchen Krisenmomenten reagieren kannst.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'Papas Küchendienst 👨‍🍳', 'Heute ist Papa dafür zuständig, das Mittagessen zuzubereiten und das Kind zu füttern! Nutze diese Zeit nur für dich: Leg dich hin oder ruh dich einfach aus.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', '„Ich mach das selbst!“-Phase 🛑', 'Dein Kind möchte seine Schnürsenkel selbst binden und das kostet dich 10 Minuten? Hetze es nicht, sondern gib ihm Zeit. Ausprobieren und Fehler machen bilden die Grundlage für seine spätere Problemlösungskompetenz.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'Kaffee und Meditation ☕', 'Dein Kind hat das Zimmer auf den Kopf gestellt? Lass das Aufräumen erst einmal sein. Während es sich selbst beschäftigt, kannst du dich aufs Sofa setzen, deinen heißen Kaffee trinken und 10 Minuten lang einfach nur an die Wand schauen, um den Kopf freizubekommen.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'Berufe nachahmen 🩺', 'Dein Kind verarztet seinen Teddybären oder repariert Spielzeugautos? Rollenspiele haben jetzt Hochkonjunktur.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'Schattenspiele 🐰', 'Dein Kind möchte nicht einschlafen? Verdunkle das Zimmer vollständig und veranstalte mit deinen Händen ein Schattentheater an der Wand. So lässt sich die Angst vor der Dunkelheit besonders spielerisch überwinden.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', '„Nicht weinen!“ 🫂', 'Dein Kind sieht im Park ein anderes Kind weinen, geht zu ihm und streichelt es? Seine Empathie ist jetzt ganz offiziell im Einsatz! Beobachte diesen wunderbaren Moment des Mitgefühls voller Stolz.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'Zeit für ein großes Bett? 🛏️', 'Dein Kind versucht, aus seinem Gitterbett zu klettern? Vielleicht überlegst du bereits, ob ein Wechsel ansteht. Frage Anacan AI nach den Sicherheitsregeln und dem besten Zeitpunkt für den Umstieg auf ein Kinderbett.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'Papas Vorlesestunde 📖', 'Gönne deiner Stimme heute Abend eine Pause. Lass Papa die Lieblingsbücher eures Kindes mit unterschiedlichen Stimmen vorlesen.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'Es setzt persönliche Grenzen ✋', 'Dein Kind weicht zurück oder sagt Nein, wenn es jemand küssen möchte? Respektiere seine körperlichen Grenzen und bestehe darauf, dass andere das ebenfalls tun. Genau hier beginnt Selbstvertrauen.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'Papa übernimmt 👨‍🍼', 'Du musst nicht alles selbst machen. Überlass heute Abend das Zähneputzen und Anziehen des Schlafanzugs ganz dem Papa und schau einfach zu.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'Die Kraft von Mamas Stimme 🎶', 'Verwende heute Abend keine Hilfsmittel. Drück dein Kind einfach an deine Brust und flüstere ihm sein liebstes Schlaflied ins Ohr. Deine Stimme ist sein sicherster Hafen.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'Schnelle kinderärztliche Unterstützung 🤖', 'Macht dir die Größen- und Gewichtskurve deines Kindes im Alter von fast 3 Jahren Sorgen? Suche nicht stundenlang im Internet, sondern ruf mit Anacan AI sofort genaue, kinderärztlich bestätigte Normwerte ab.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'Kennt seinen Namen und sein Alter 🎂', 'Versucht dein Kind mit den Fingern zu zeigen, wie alt es ist, wenn du es fragst? Seine Selbstwahrnehmung ist hervorragend. Halte diesen kognitiven Entwicklungssprung im Entwicklungstracker fest.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'Regisseur vor dem Spiegel 🎭', 'Steht dein Kind vor dem Spiegel, schneidet verschiedene Grimassen und spricht mit sich selbst? Es probiert unterschiedliche Rollen aus. Beobachte es heimlich und genieße diese lustigen Momente.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'Zeit für neue Energie 🍲', 'Das ständige Herumrennen hat dich erschöpft. Wähle im Bereich „Gesunde Rezepte“ ein abwechslungsreiches, eisen- und proteinreiches Mittagessen aus, das dir und deinem Kind schmeckt.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'Tagesrückblick 📝', 'Öffnet gemeinsam das Stimmungstagebuch, sobald euer Kind eingeschlafen ist. Schreibt auf, was euer Kind heute am lustigsten gemacht hat, und lasst den Stress mit einem gemeinsamen Lächeln hinter euch.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'Mit Musik sanft in den Schlaf 🛀', 'Ist die Abendroutine schwierig geworden? Lass während eines warmen Bades im Hintergrund beruhigende klassische Musik laufen. Die Harmonie von Wasser und Musik entspannt selbst das hartnäckigste Kind.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'Der Zauber intelligenter Märchen 🪄', 'Du hast genug von klassischen Märchen? Gib den intelligenten Märchen ein besonderes Thema: die Abenteuer eines magischen Dinosauriers, der gern Gemüse isst.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'Kleidungsdiplomatie 👗', 'Dein Kind möchte mitten im Winter eine Sommerhose anziehen? Öffne einfach das Wetter- und Kleidungs-Tool und erkläre ihm anhand der Bilder auf dem Bildschirm verständlich, dass es draußen kalt ist.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'Der Wert der Stille 🤫', 'Endlich ist dein Kind eingeschlafen. Jetzt bringt dich selbst das leiseste Geräusch im Haus aus der Ruhe. Stelle mit dem Geräuschmesser einen Grenzwert für das Zimmer ein und lass im Hintergrund durchgehend weißes Rauschen laufen.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'Wir fangen an zu zählen 🔢', 'Versucht dein Kind beim Treppensteigen oder Aufräumen seiner Spielsachen eins, zwei, drei zu sagen? Damit wird der Grundstein für mathematisches Denken gelegt. Zählt gemeinsam die Gegenstände im Zimmer laut.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'Burnout-Syndrom 🔋', 'Möchtest du wegen allem losschreien? Du leidest möglicherweise unter Burnout. Geh in die Anacan-Community und schreibe: Ich bin so müde. Du wirst sehen, dass sich im selben Moment Tausende Frauen mit dir verbunden fühlen.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'Mittagsschlaf verweigert 🥱', 'Dein Kind will auf keinen Fall Mittagsschlaf machen und wehrt sich dagegen? Im Alter von etwa 3 Jahren brauchen manche Kinder keinen Mittagsschlaf mehr. Versuche, ihn durch eine Ruhezeit ohne Schlaf (sleep-free quiet time) zu ersetzen.'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'Erinnerungen werden wach 🧠', 'Bildet dein Kind Sätze über Vergangenes wie „Gestern waren wir bei Oma“? Sein Zeitverständnis und sein Langzeitgedächtnis entwickeln sich. Höre seinen Erinnerungen interessiert zu und stelle Fragen dazu.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'Schreit und weint dein Kind nachts mit geschlossenen Augen?', 'Versuche nicht, es zu wecken. Lass das Geräusch von der Weinanalyse prüfen, um sicherzugehen, dass es sich nur um einen Nachtschreck handelt, und bleib ruhig bei deinem Kind.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'Der „Ich hab dich gefunden!“-Spaß 🙈', 'Verstecken ist jetzt das Lieblingsspiel deines Babys. Es versteckt sich hinter dem Vorhang und wartet darauf, dass du es findest. Durch solche Spiele festigt sich in diesem Alter das Verständnis der Objektpermanenz.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'Wutanfälle meistern 🛑', 'Sind dir die Wutanfälle im Geschäft oder im Park peinlich? Denk daran: Entscheidend ist nicht, was die anderen denken, sondern was dein Kind in diesem Moment fühlt. Nimm es ruhig in den Arm.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'Bitte deinen Partner um Hilfe 🛒', 'Du hast keine Zeit zum Einkaufen? Öffne die Einkaufsliste, trage alles ein, was zu Hause fehlt, und schicke sie mit nur einem Klick an deinen Partner. Aufgaben zu teilen ist ein Muss.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'Stille Lesezeit 📖', 'Heute Abend soll im Zimmer nur das Rascheln der Buchseiten zu hören sein. Legt euch beide ins Bett: Dein Kind schaut sein Bilderbuch an, während du die Ruhe genießt und dich erholst.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'Gefährliche Sprünge 🧗‍♂️', 'Versucht dein Kind, von der Sofalehne auf den Boden zu springen? Es vertraut sehr auf seine motorischen Fähigkeiten. Statt es zu verbieten, leg weiche Kissen auf den Boden und schaffe so einen sicheren Bereich zum Springen.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'Grenzen austesten ⚠️', 'Tut dein Kind genau das, was du verboten hast, und schaut dir dabei direkt in die Augen? Es will dich nicht wütend machen, sondern herausfinden, wie konsequent deine Grenzen sind. Bleib bei deinen Regeln.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'Lass das Chaos liegen 🌪️', 'Bist du es leid, jeden Tag dieselben Spielsachen aufzuräumen? Dann lass es heute einfach sein! Ein unordentliches Zuhause ist nicht das Ende der Welt – deine psychische Überlastung sollte dagegen ernst genommen werden.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'Heute im cleveren Märchen 🪄', 'Gib dem cleveren Märchen ein besonderes Thema: ein magisches Bärchen, das gern seine Spielsachen aufräumt. Vielleicht hilft euch diese Geschichte morgen beim Aufräumen!'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'Ein Schwall Selbstständigkeit 🥛', 'Dein Kind möchte Wasser oder Milch unbedingt selbst ins Glas gießen – und das Ergebnis? Überall sind Pfützen. Atme tief durch. Dieses Chaos ist der Preis dafür, dass sich seine Hand-Augen-Koordination und sein Selbstvertrauen entwickeln. Gib ihm auch ein Tuch und wischt alles ganz in Ruhe gemeinsam auf.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'Lärm-Detox 🎧', 'Mama, Mama, Mama! Hallt das schon in deinem Kopf wider? Gönn dir eine kleine Auszeit. Beschäftige dein Kind 15 Minuten lang mit etwas Sicherem und trink deinen Kaffee in völliger Stille. Auch deine Akkus müssen wieder aufgeladen werden.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'Keine Kämpfe mehr beim Baden 🛁', 'Dein Kind will nicht in die Badewanne und wälzt sich protestierend auf dem Boden? Sag statt Komm, ich wasche dich lieber: Komm, wir baden deine Lieblingsautos (oder Puppen). Wenn aus einem Muss ein Spiel wird, können Kinder kaum widerstehen.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'Schuhdrama zu Hause 👟', 'Dein Kind weint, weil es seine Straßenschuhe unbedingt auch zu Hause tragen und auf keinen Fall ausziehen möchte? Das ist keinen Kampf wert. Wisch die Sohlen mit einem feuchten Tuch ab und lass es ein paar Stunden lang stolz damit durchs Zimmer laufen. Manche Kämpfe bewusst zu verlieren, ist in Wahrheit der größte Sieg einer Mutter.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'Jetzt ist Papa dran 👨‍🍼', 'Du bist müde davon, den ganzen Tag Nein zu sagen und Regeln aufzustellen. Überlass heute Abend den Kampf ums Anziehen des Pyjamas und Zähneputzen Papa. Mach die Zimmertür zu, schreib einfach deine heutigen Gefühle in dein Stimmungstagebuch und nimm dir ganz bewusst Zeit für dich.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'Aufmunterung in der Community 💬', 'Haben dich die Trotzanfälle deines Kindes heute wirklich ausgelaugt? Öffne gleich die Anacan Community und lies die ähnlichen oder sogar noch lustigeren Geschichten anderer Mütter über kleine Dramen zu Hause. Zu wissen, dass ihr alle Ähnliches erlebt und du nicht allein bist, ist die beste seelische Unterstützung.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'Auf der Suche nach neuen Freunden 👫', 'Versucht dein Kind im Park, mit Gleichaltrigen herumzulaufen und bei ihren Spielen mitzumachen? Jetzt beginnt das soziale Miteinander ganz offiziell! Ermutige dein Kind und zeig ihm, wie es andere Kinder begrüßen kann.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'Naturtherapie für Mama 🌳', 'Fällt dir zu Hause die Decke auf den Kopf? Schnapp dir dein Kind und geht in den nächsten Park. Frische Luft ist nicht nur für dein Kind, sondern auch für deine strapazierten Nerven die beste Erholung.'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'Papas Rituale 👨‍🍼', 'Kinder haben oft ganz eigene Rituale mit ihrem Papa. Überlass ihm heute Abend das Zubettbringen nach seinen lustigen Regeln und genieße draußen in aller Ruhe deinen Tee.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'Die Welt der Farben entdecken 🎨', 'Sortiert dein Kind Farben richtig und sagt dabei: „Das ist rot, das ist blau“? Das ist ein großer Fortschritt in der kognitiven Entwicklung! Halte diesen Meilenstein stolz im Entwicklungstracker fest.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'Gemeinsam in der Küche 🧑‍🍳', 'Möchte dein Kind dir bei allem helfen? Wählt ein einfaches Kuchenrezept aus den gesunden Rezepten aus und lass es beim Einfüllen von Mehl oder Wasser helfen. Auch wenn es dabei schmutzig wird: Spaß ist garantiert.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'Der nächtliche Geräuschpegel 🤫', 'Hindern die Geräusche von draußen dein Kind daran, tief einzuschlafen? Analysiere die Lautstärke im Zimmer mit dem Schallpegelmesser.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'Kleiner Künstler am Werk 🖍️', 'Wände und Türen werden manchmal zur Leinwand deines Kindes. Statt dich zu ärgern, leg ein großes Stück Pappe auf den Boden und sag: „Das hier gehört dir.“ Lenke seinen Gestaltungsdrang in die richtige Richtung.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'Eine Flut von Fragen 🤖', 'Hast du unzählige Fragen zum Verhalten deines fast dreijährigen Kindes? Anacan AI ist dein digitaler Kinderarzt und Psychologe, rund um die Uhr für dich da. Schreib einfach und erhalte sofort eine Antwort.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'Lass deinen Gefühlen freien Lauf 📝', 'Fühlst du dich sehr allein und unverstanden? Das ist ein ganz natürliches Gefühl. Schreib im Stimmungstagebuch offen und ehrlich auf, wie du dich fühlst.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'Das eigene Ich entdecken 👑', '„Ich!“ und „Meins!“ sind die Lieblingswörter deines Kindes. Jetzt ist die egozentrische Phase besonders ausgeprägt. Begegne seiner wachsenden Eigenständigkeit mit Respekt – sie ist ein wichtiger Entwicklungsschritt.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'Kleiner Philosoph 🤔', 'Hat dein Kind gerade noch die Augen geschlossen und dann plötzlich den Kopf gehoben und eine philosophische Frage gestellt wie: „Mama, wo geht die Sonne schlafen?“ Sein Gehirn verarbeitet die Welt sogar noch beim Einschlafen. Antworte kurz und märchenhaft, ohne zu sehr ins Detail zu gehen.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'Magische Wünsche 🪄', 'Hat dein Kind heute Morgen gleich nach dem Aufwachen lautstark verlangt, dass du den aufgeschnittenen Apfel wieder ganz machst? Ja, mit fast 3 Jahren fordert seine Logik die Gesetze der Physik heraus.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'Tiere nachahmen 🐶', 'Macht dein Kind nicht nur Tierlaute, sondern krabbelt auch wie ein Hund und schmiegt sich an wie eine Katze? Körpersprache und Fantasie kommen jetzt zusammen. Mach bei diesem Spiel auf dem Teppich mit.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'Wählerisches Essen 2.0 🥣', 'Lehnt dein Kind heute die Suppe ab, die es gestern noch geliebt hat? Übe keinen Zwang aus. In der Rubrik mit gesunden Rezepten findest du abwechslungsreiche Alternativen, in denen sich Gemüse verstecken lässt.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'Magische Gute-Nacht-Geschichte 🪄', 'Erfinde in den smarten Märchen die Geschichte eines mutigen kleinen Helden, der bald 3 Jahre alt wird. So vermittelst du deinem Kind das Gefühl, dass es wächst und stärker wird.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'Ich suche dich! 👀', 'Fängt dein Kind wieder an zu weinen, sobald du das Zimmer verlässt? Trennungsangst kann manchmal zurückkehren. Gib ihm aus der Ferne mit deiner Stimme Sicherheit – du musst aber nicht ständig in seinem Blickfeld bleiben.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'Lass dein Kind das Märchen beenden 📖', 'Lass heute Abend beim Vorlesen die Sätze unvollendet und dein Kind sie zu Ende erzählen! Frage Anacan AI nach Möglichkeiten, wie du mit solchen Dialogen seine erstaunliche Fantasieentwicklung unterstützen kannst.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'Eine Liste ist unverzichtbar 🛒', 'Damit ihr nichts vergesst, was ihr für den Geburtstag braucht! Zerbrich dir nicht den Kopf: Trage alles sofort in die Einkaufsliste ein und synchronisiere sie mit deinem Partner.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'Wechselhaftes Wetter ⛅', 'Ihr möchtet spazieren gehen, aber das Wetter draußen ist trügerisch? Nutzt das Wetter- und Kleidungs-Tool, um das passende Outfit zu finden, das euer Baby schützt, ohne es ins Schwitzen zu bringen.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'Stolz auf euer Team 🥂', 'Ihr habt eine schwierige Woche hinter euch. Setzt euch einander gegenüber und motiviert euch gegenseitig mit den Worten: „Wir machen das wirklich gut mit unserem Kind.“'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'Erzählt Geschichten in ganzen Sätzen 🗣️', 'Schaut sich dein Kind ein Bilderbuch an und erfindet dazu eigene Sätze und Geschichten? Fantasie und Sprachvermögen blühen gleichzeitig auf! Hör aufmerksam zu und schenke ihm viel Anerkennung.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'Mamas halten zusammen 💬', 'Bringt dich das Töpfchentraining zur Verzweiflung? Dann schau gleich in der Anacan-Community vorbei. Die Erfolgs- und Misserfolgsgeschichten anderer Mütter werden dir neue Kraft geben.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'Angst vor der Dunkelheit 🌙', 'Hat dein Kind Angst vor dem dunklen Zimmer? Stell ein kleines Nachtlicht neben das Bett, aber achte darauf, dass der Raum für die Melatoninausschüttung noch dunkel genug bleibt.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'Möchte seine Kleidung selbst aussuchen 👗', 'Öffnet dein Kind den Kleiderschrank und möchte Farben und Kleidungsstücke aus verschiedenen Jahreszeiten wild miteinander kombinieren? Unterstütze seine Selbstständigkeit, aber biete ihm nur 2 Möglichkeiten an, damit du den Überblick behältst.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'Kaffee-Energieschub ☕', 'Der Mittagsschlaf fällt inzwischen aus und du kommst den ganzen Tag nicht zur Ruhe? Beschäftige dein Kind 15 Minuten lang mit einer sicheren Aktivität und gönn dir in dieser Zeit unbedingt deinen Kaffee-Energieschub.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'Schwere Last, starker Wille 🛒', 'Möchte dein Kind auf dem Rückweg vom Spaziergang unbedingt den schwersten Gegenstand oder die schwerste Tasche selbst tragen? Auch wenn es die Last keinen Zentimeter bewegen kann, lehnt es deine Hilfe entschieden ab. Lass es ruhig eine Weile versuchen und seine Kräfte erproben.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'Gespräch mit einer unsichtbaren Ameise 🐜', 'Beugt sich dein Kind auf dem Balkon oder im Park zu einer Ameise auf dem Boden hinunter und erzählt ihr ganz ernst etwas? Hier sind Fantasie und Mitgefühl gleichzeitig am Werk. Halte diesen wundervollen Moment gleich mit dem Baby-Fotoshooting fest und bewahre ihn in der schönsten Ecke deines Archivs auf.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'Papas Flugmodus ✈️', 'Dein Kind wird zu Hause seine Energie nicht los und weigert sich, ins Bett zu gehen? Bitte Papa um Hilfe. Wenn er das Kind hochhebt und wie ein Flugzeug durch die Luft fliegen lässt, erfüllt lautes Lachen den Raum und die ganze angestaute körperliche Anspannung löst sich innerhalb von Sekunden.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'Die Freiheit, sich auf dem Boden zu wälzen 🌪️', 'Hat sich dein Kind mitten im Supermarkt auf den Boden geworfen? Versuch nicht, es hochzuheben oder dich vor den Umstehenden zu rechtfertigen. Atme tief durch. In der Anacan Community wirst du sehen, dass Tausende Mütter denselben peinlichen, aber ganz natürlichen Moment erleben.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', 'Der „Schau mich nicht an!“-Trotz 🙈', 'Du hast dein Kind angesehen und angelächelt – und nun weint es und ruft: „Schau mich nicht an!“ Der Gipfel absurder Logik! Dreh dein Gesicht zur Seite und warte, bis diese lustige Laune vorübergeht. Manchmal wissen Kinder selbst nicht, was sie wollen.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'Der Zauber der Lichter 🌙', 'Hat dein Kind plötzlich Angst vor der Dunkelheit? Verdunkle das Zimmer vollständig und lass mit einer kleinen Taschenlampe Lichtspiele an der Decke entstehen. So wird aus der gefürchteten Dunkelheit ein Vergnügen und eine kleine Entdeckungsreise vor dem Schlafengehen.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'Große Pyjamaliebe 👗', 'Dein Kind ist morgens aufgewacht und weigert sich hartnäckig, den fleckigen Pyjama auszuziehen. Wenn ihr nicht aus dem Haus müsst, erspar dir den Kampf. Manchmal ist das seelische Wohlbefinden der Mutter viel wichtiger als ein ordentlich aussehendes Kind.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'Schätze aus der Hosentasche 🍁', 'Ihr kommt aus dem Park zurück und aus der Tasche deines Kindes kommen 3 Steine, 1 trockenes Blatt und ein Stöckchen zum Vorschein. Für dich ist es Abfall, für dein Kind ein Schatz. Richtet eine Sammelbox ein, damit es seine Fundstücke dort aufbewahren kann, statt sie im ganzen Haus zu verteilen.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'Seelischen Ballast loslassen 📝', 'Sitzt jemand bei dir zu Hause und merkt trotzdem nicht, wie erschöpft du bist? Dein Stimmungstagebuch ist dein stillster Vertrauter. Schreib heute jedes Detail hinein, das dich wahnsinnig gemacht hat, und spüre, wie dein Kopf leichter wird.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'Ich laufe allein! 🚶‍♂️', 'Dein Kind weigert sich auf der Straße entschieden, deine Hand zu halten, und erklärt seine Unabhängigkeit. Lass ihm diese Freiheit an sicheren Orten. Behalte es gut im Auge und lass es die Welt auf eigenen Füßen entdecken.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'Kleiner Küchenchef 🧑‍🍳', 'Stellt dein Kind sofort einen Stuhl neben dich und mischt sich ein, sobald du Teig ausrollst? Gib ihm ein kleines Stück Teig. Danach wird zwar überall Mehl sein, aber sein ernster, geschäftiger Gesichtsausdruck ist das Aufräumen allemal wert.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'Schwierige bildschirmfreie Auszeit 📺', 'Du hast dein Kind heute wegen all deiner Aufgaben länger als sonst Zeichentrickfilme schauen lassen und hast nun ein schlechtes Gewissen? Mach dir keine Vorwürfe. Du kannst nicht jeden Tag eine perfekte Mutter sein. Manchmal bewahrt dich der digitale Babysitter vor einem Nervenzusammenbruch.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'Ein lebendiges Diktiergerät 🎙️', 'Heute Morgen sagt dein Kind zu seinem Spielzeug genau das eine Wort, das dir gestern im Gespräch mit deinem Partner herausgerutscht ist! Sein Wortschatz wächst rasant, und es ahmt dich vollständig nach. Vergiss nicht, dass du sein Vorbild bist.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'Der Flüstertrick 🤫', 'Dein Kind ist im Bett so aktiv, dass es einfach nicht einschläft. Statt lauter zu werden, senke deine Stimme plötzlich und sprich ganz leise. Wenn sich dein Kind konzentriert, um dich zu verstehen, schaltet sein Gehirn automatisch in den Schlafmodus.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'Zeit für frische Luft ⛅', 'Die vier Wände machen dich ganz benommen, und zu Hause jagt ein Wutanfall den nächsten. Schau auf das Wetter, wähle die passende Kleidung und geht nach draußen. Einfach loszurennen hilft deinem Kind, überschüssige Energie abzubauen, und lässt auch dich wieder aufatmen.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'Dein Kind bestimmt die Geschichte 🪄', 'Ihr habt beide genug von den klassischen Kinderbüchern. Denkt euch eine fantasievolle Geschichte aus, in der dein Kind die Hauptfigur und sein Zimmer der Ort ist, der gerettet werden muss. So entsteht ein außergewöhnliches, ruhiges und entspanntes Einschlafritual.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'Avantgardistische Kunst 🖍️', 'Ein paar Sekunden Stille haben nichts Gutes verheißen. Du kommst ins Zimmer und siehst, dass dein Kind sich mit Filzstiften Tattoos auf die Arme oder den Bauch gemalt hat. Atme tief durch. Seine Feinmotorik entwickelt sich – und die Farbe lässt sich von der Haut wieder abwaschen.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'Das Drama mit der Sockennaht 🧦', 'Heute Morgen begann der Tag mit einer großen Krise: Die Naht in der Socke berührt den Zeh! Gegen Ende des dritten Lebensjahres erreicht die emotionale Sensibilität ihren Höhepunkt. Suche nicht nach Logik, zieh die Socke einfach auf links an und beobachte, wie diese absurde Krise innerhalb von 10 Sekunden vorbei ist.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'Auf Pfützenjagd 🌧️', 'Ihr seid nach dem Regen nach draußen gegangen und dein Kind ist direkt in eine schlammige Pfütze gesprungen? Die Kleidung ist schmutzig, aber schau dir dieses Leuchten der Entdeckerfreude in seinen Augen an. Behalte das Wetter im Blick und plane Gummistiefel und passende Kleidung ein – lass dein Kind einfach Kind sein.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'Gute Nacht, ihr Spielsachen 🧸', 'Es ist Schlafenszeit, aber dein Kind verabschiedet sich einzeln von jedem Auto und jedem Teddybären im Zimmer. Das ist ein Meisterwerk der Kunst, das Zubettgehen hinauszuzögern. Stell einen Timer und führt die Regel ein: In 3 Minuten sagen wir allen gleichzeitig Gute Nacht.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'Der ungewöhnlichste Gegenstand 🥄', 'Es gibt so viele teure Spielsachen, aber dein Kind hat in der Küche eine Schöpfkelle gefunden, trägt sie den ganzen Abend herum und bringt sie sogar ins Bett. Die kindliche Vorliebe für bestimmte Gegenstände ist manchmal unerklärlich. Halte es nicht davon ab – lass es seine Schöpfkelle liebhaben.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'Der Chirurg in der Suppe 🥣', 'Dein Kind isst nicht, sondern sortiert mit chirurgischer Präzision jedes kleine Zwiebelstückchen und jedes Reiskorn aus. Vielleicht ist es Zeit, das Gemüse zu pürieren und unsichtbar zu machen. Schau dir bei den gesunden Rezepten die kreativsten Rezepte anderer Mütter mit gut verstecktem Gemüse an.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'Ich mache den Schrank auf! 🚪', 'Du hast morgens die Schranktür geöffnet, woraufhin dein Kind weinend verlangt hat, dass du sie wieder schließt, damit es sie selbst öffnen kann? Ja, es möchte unbedingt die Kontrolle haben. Begegne diesen unschuldigen „Ich mache das!“-Versuchen mit einem Lächeln – dein Kind erprobt gerade seinen eigenen Willen.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'Stille in Zahlen 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich im Haus ausbreitet, kaum glauben. Aktiviere den Schallpegelmesser und beobachte die Anzeige von 0-10 desibel, während du spürst, wie dein Kopf langsam zur Ruhe kommt und neue Energie tankt.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', 'Der Schlag: „Du bist eine schlechte Mama!“ 💔', 'Dein Kind hat zu dir „Du bist gemein!“ gesagt, weil du ihm nicht die gewünschte Süßigkeit gegeben hast? Lass dir das nicht zu Herzen gehen. Es kann seine Gefühle noch nicht mit den richtigen Worten ausdrücken und möchte eigentlich sagen: „Ich bin sehr wütend.“ Stell Blickkontakt her und nimm sein Gefühl ernst.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'Wasser, überall Wasser! 💧', 'Das Wasser wollte dein Kind unbedingt selbst ins Glas gießen. Natürlich ging etwas daneben und alles wurde nass. Aber schau dir diese kleinen Hände an, die nach dem Lappen greifen und versuchen, alles sauber zu machen. Dein Kind lernt durch Fehler, Verantwortung zu übernehmen – werde nicht ärgerlich.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'Papa ist dran 👨‍👧', 'Muttersein sollte kein endloser Marathon sein. Lass Papa heute den Ausflug in den Park übernehmen, während du auf dem Sofa die Ruhe genießt.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'Massage im Team 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren und so den Stress des Tages lösen. Ihr seid nicht nur Eltern, sondern auch die größte Stütze für euer Zuhause und füreinander.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'Ich bin müde … 🔋', 'Alle erwarten Energie von dir, aber dein Akku ist leer. Koche heute nichts, sondern bestellt etwas oder macht einfach die schnellsten Nudeln. Eine Superheldin zu sein bedeutet nicht, alles allein machen zu müssen.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'Frieden in der Badewanne 🛀', 'Der ganze Tag war voller „Ich will nicht!“. Ein warmes Bad dient nicht nur der Körperpflege, sondern hilft auch dem angespannten Nervensystem deines Kindes, sich zu beruhigen. Lauscht dem Wasser – die Atmosphäre im Raum wird sich sofort verändern.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'Ganz allein die Treppe hinauf 🧗', 'Versucht dein Kind, ohne Hilfe die Treppe hinaufzusteigen? Seine motorischen Fähigkeiten sind gerade auf dem Höhepunkt! Beobachte es aus der Nähe, ohne einzugreifen. Halte diesen Moment der Selbstständigkeit mit einem Baby-Fotoshooting für immer fest.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'Die magische Anziehungskraft des Kartons 📦', 'Du hast deinem Kind ein teures Spielzeug gekauft, das Geräusche macht, aber seit 1 Stunde spielt es lieber mit der Verpackung. Das kindliche Gehirn liebt keine vorgegebenen Strukturen, sondern einfache Gegenstände, die Raum für Fantasie lassen. Schau zu und lerne.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'Natürliches weißes Rauschen 🤫', 'Beim Einschlafen reagiert dein Kind besonders empfindlich auf Geräusche. Aktiviere im Raum das Hintergrundgeräusch des Geräuschpegelmessers, um Geräusche von draußen zu überdecken und eine dauerhaft ruhige Atmosphäre zu schaffen.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'Vorgetäuschtes Weinen 🎭', 'Tut dein Kind so, als würde es weinen, indem es die Stimme zittern lässt, ohne dabei Tränen zu vergießen – nur um seinen Willen zu bekommen? Es lernt gerade, dich zu manipulieren. Versuch, nicht zu lachen, aber gib auch nicht nach. Setze klare Grenzen.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'Ein überraschendes „Ich liebe dich“ 💖', 'Hat dein Kind mitten im Spielen plötzlich zu dir geschaut und gesagt: „Ich hab dich sooo lieb“? Dafür haben sich all die schlaflosen Nächte und die Erschöpfung gelohnt! Genieße den tiefen, einzigartigen Frieden, den dieser Moment dir schenkt.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'Papas verrückter Tanz 🕺', 'Mit dem Wutanfall am späten Nachmittag wird manchmal nur Papa fertig. Dreht die Musik ganz laut auf und lasst die beiden gemeinsam durchs Zimmer springen und tanzen. Du kannst diese fröhliche Energie von außen beobachten – voller Stolz.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', '10 Minuten nur für dich ☕', 'Während dein Kind in den Zeichentrickfilm vertieft ist, lauf nicht gleich los, um die Spülmaschine einzuräumen! Leg dich aufs Sofa. Trink deinen Kaffee endlich, solange er noch heiß ist, und sei 10 Minuten lang nicht nur Mama, sondern einfach du selbst.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'Die Schokoladenüberraschung im Supermarkt 🛒', 'Bevor ihr zum Supermarkt aufbrecht, öffnest du die Einkaufsliste – und plötzlich kommt dein Kind von hinten, tippt auf den Bildschirm und kritzelt etwas hinein. Ja, es ahmt sogar dein digitales Leben nach!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'Der Charme erfundener Grammatik 🗣️', 'Dein Kind erfindet seltsame, aber unglaublich süße Zeitformen wie „Ich bin gegangt“ oder „Er ist gekommt“. Sein Wortschatz entwickelt sich rasant! Halte diese ganz eigene Sprache im Entwicklungstracker als schöne Erinnerung fest.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'Was ist unter dem Bett? 👻', 'Glaubt dein Kind, dass im Dunkeln Monster lauern? Füll einfach eine Sprühflasche mit Wasser und versprüh es als „Monsterspray“ im Zimmer, um dein Kind zu beruhigen. Bekämpfe Fantasie mit Fantasie.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'Um 5 Uhr morgens beginnt die Party! ⏰', 'Die Sonne ist noch nicht aufgegangen, doch dein Kind springt schon im Bett herum und startet in den Tag. Während du noch verschlafen bist, ist es bereit, die Welt zu erobern. Mach mit und lass dich von dieser wilden Energie ebenfalls wachrütteln.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'Auf der Suche nach einer Kita? 🏫', 'Je näher der 3. Geburtstag rückt, desto öfter denkst du über eine Kita nach, kannst dich aber nicht entscheiden? Wenn du es leid bist, allein darüber nachzugrübeln, tritt der Anacan-Community bei und lies von den echten Kita-Erfahrungen anderer Mütter.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'Gefühle festhalten 📝', 'Hat dir jemand gesagt: „Du bist doch zu Hause, wovon bist du denn müde?“ Öffne sofort dein Stimmungstagebuch und tippe deinen ganzen Ärger in den Bildschirm. Deine echten Gefühle aufzuschreiben, ist heilsamer, als ein Lächeln vorzutäuschen.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'Der Gemüse-Streik geht weiter 🥦', 'Hat dein Kind wieder das winzige Möhrenstück in der Suppe entdeckt und sich geweigert, weiterzuessen? Gemüse zu pürieren und mithilfe des Ernährungsplans in Frikadellen zu verstecken, ist einer der ältesten und nützlichsten Mama-Tricks. Probier es aus!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'Der kleine Arzt untersucht dich 🩺', 'Dein Kind nimmt sein Spielzeugstethoskop, legt es auf deine Brust und sagt: „Tief einatmen!“ Du bist krank und dein Kind ist der Chefarzt. Spiel mit, leg dich hin und schließe während der Behandlung für wenigstens 5 Minuten die Augen, um dich auszuruhen.'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'Bitte ganz leise 🌙', 'Endlich ist dein Kind eingeschlafen. Jetzt lässt dich selbst das leiseste Geräusch im Haus zusammenzucken. Dimme das Licht, schalte den Fernseher aus und genieße in der Dunkelheit diese seltene, herrliche Stille.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('19419b9a-b627-43ae-9610-e43b875264b1'::uuid, 'Zielstrebig unterwegs 🐢', 'Gehen allein reicht nicht mehr: Dein Kind läuft schnell davon, versteckt sich vor dir und lugt hinter Türen hervor. Räume Hindernisse aus dem Weg und mach bei diesem Fangspiel mit der Energie eines großen Kindes mit.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen und Bildschirme mit blauem Licht im Zimmer aus. Das Schlafhormon Melatonin wird in einer dunklen, technikfreien Umgebung besonders gut ausgeschüttet.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'Künstliche Intelligenz, echte Antwort 🤖', 'Dein Kind hat eine ungewöhnliche Angewohnheit entwickelt, zum Beispiel Nägelkauen, und die Internetforen haben dir Angst gemacht? Stopp. Frag Anacan AI nach der tatsächlichen, kinderärztlich bestätigten Ursache und beruhige dich.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'Dich selbst zu vergessen ist verboten! 🥗', 'Du hast dir 3 verschiedene Menüs überlegt, um dein Kind satt zu bekommen – aber bist selbst wieder hungrig geblieben? Wähle aus den gesunden Rezepten ein Mittagessen, das in 10 Minuten zubereitet und reich an Eisen und Kalzium ist, und tu dir selbst etwas Gutes.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'Plötzlicher Wutanfall 💥', 'Dein Kind wurde beim Spielen plötzlich wütend und warf seine Spielsachen herum? Es kann seine Gefühle noch nicht kontrollieren. Statt zu schimpfen, zeige Verständnis und sage: „Ich sehe, dass du wütend bist. Komm, wir atmen gemeinsam tief durch.“'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'Ein Hoch auf euch als Paar 🥂', 'Das Kind schläft. Auch wenn ihr keinen Champagner habt, gießt euch warmen Tee in die Gläser und stoßt mit deinem Partner an: „Auch diesen schwierigen Tag haben wir gut überstanden.“ Ihr seid die stärksten Anführer eurer Familie.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', 'Nur noch 5 Tage bis zum 3. Geburtstag! 🚀', 'Unglaublich! Nur noch 5 Tage bis zum großen 3. Geburtstag. Du hast diesen kleinen Menschen großgezogen, der zu Hause seine eigenen Regeln aufstellt. Bestelle jetzt die Torte bei Anacan und beginne mit den Vorbereitungen.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'Papas Flugmodus ✈️', 'Dein Kind konnte seine Energie zu Hause nicht loswerden und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind hochhebt und mit ihm Flugzeug spielt, erfüllt lautes Lachen das Zimmer und der körperliche Stress verschwindet innerhalb von Sekunden.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'Mamas Auszeit ☕', 'Du bist es leid, ständig in Kindersprache zu sprechen. Finde unter den mama-freundlichen Orten ein Café mit Spielecke, genieße deinen Kaffee, tausche dich mit anderen Müttern aus und atme einmal durch.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'Freiheit im Park 🌳', 'Vier Wände machen dein Kind aggressiv. Geh mit ihm in den Park: Lass es sich im Sand schmutzig machen, beim Rennen hinfallen und Steine sammeln. Diese Freiheit in der Natur ist die beste Entwicklungsförderung für sein Gehirn.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'Melatonin-Fabrik 🌙', 'Schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Melatonin wird nur in einer ruhigen, abgedunkelten und bildschirmfreien Umgebung schnell ausgeschüttet.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'Die Fantasiegäste sind da ☕', 'Spricht dein Kind allein im Zimmer mit unsichtbaren Freunden und schenkt ihnen Tee ein? Seine Fantasie ist auf dem Höhepunkt! Beobachte dieses großartige kleine Drehbuch-Talent stolz aus der Ferne – dein Kind erschafft gerade ein ganzes Universum.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'Ich erkläre es dir! ☝️', 'Dein Kind erklärt dir mit sehr ernster und kluger Miene etwas, das du längst weißt. So überprüft es sein Wissen. Auch wenn du dich beherrschen musst, um nicht zu lachen, solltest du ihm ganz ernsthaft zuhören.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'Ein Geständnis im Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Anstatt durch das Leben anderer in den sozialen Medien zu scrollen, öffne das Stimmungstagebuch und halte den lustigsten Moment deines Kindes von heute für die Zukunft fest. Digitale Therapie wirkt.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'Aufstand gegen den Mittagsschlaf 🥱', 'Dein Kind will auf keinen Fall ins Bett? Kurz vor dem 3. Geburtstag ist dieser Widerstand ganz typisch. Zwinge es nicht und bringe es nicht zum Weinen. Dimme das Licht im Zimmer, erkläre eine ruhige Bilderbuchzeit und passe so eure Routine an.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'Schon wieder Trennungsangst? 🥺', 'Dein Kind weint dir hinterher, selbst wenn du das Zimmer nur für eine Sekunde verlässt. Um den 3. Geburtstag herum kann die Trennungsangst manchmal zurückkehren. Gib ihm aus der Entfernung Sicherheit, indem du dich immer wieder meldest und sagst: „Ich bin hier, ich bin in der Küche und komme gleich.“'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'Die Bestätigung der Stille 🤫', 'Miss nach einem lauten Tag, wenn dein Kind eingeschlafen ist, mit dem Schallpegelmesser die Ruhe im Zimmer. Allein zu sehen, wie sich die Zahlen null nähern, wirkt auf das Gehirn einer Mutter wie die beste visuelle Massage.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'Der Druck, perfekt sein zu müssen 🛑', 'Andere Kinder können schon die Farben aufzählen, aber deins möchte es nicht? Hör sofort auf zu vergleichen! Jedes Kind hat sein eigenes Entwicklungstempo. Dein Kind entwickelt sich in seinem eigenen Rhythmus – und das ist völlig normal.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'Vorbereitung auf den großen Tag 💆‍♂️', 'Wenn dein Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren, um gemeinsam den Stress des Tages abzubauen. Für den morgigen 3. Geburtstag und all den Trubel müsst ihr beide unbedingt voller Energie sein!'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'Selbsthilfegruppe für Mütter 💬', 'Du hast einen schwierigen Tag und alles wächst dir über den Kopf? Die Ratschläge der erfahrenen Mütter in der Anacan-Community sind lebensnahe Lösungen, die in keinem Buch stehen. Lass dich dort inspirieren.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', 'Der 3. Geburtstag steht bevor! 🎂', 'Morgen ist der große Tag! Seit dem Tag, an dem du die ersten Tritte in deinem Bauch gespürt hast, habt ihr einen langen Weg zurückgelegt. Schau dein Kind heute ganz lange an, wähle die Kleidung aus und schaffe auf deinem Handy Platz für das morgige Baby-Fotoshooting.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'Feiere mit deinem Partner 🥂', 'Feiere heute Abend gemeinsam mit deinem Partner die Erschöpfung, die Tränen und die Freude dieser 3 Jahre. Stellt eine Kerze auf den Tisch und stoßt lächelnd und voller Freude auf euren Erfolg als unschlagbares Team an!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'Wunderbare 3 Jahre! 👑🎉', 'Herzlichen Glückwunsch! Dein Kind ist jetzt 3 Jahre alt! Seit genau 1095 Tagen geht ihr gemeinsam diesen turbulenten und anstrengenden, aber zugleich schönsten Weg der Welt! Feiert diesen besonderen Tag gebührend und teilt eure Freude mit allen!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'Du bist großartig! 📈', 'Was für einen langen Weg dein Kind schon zurückgelegt hat! Die verletzliche Unsicherheit der ersten Tage ist inzwischen einem großen Vertrauen und viel Erfahrung gewichen. Du hast diese 3 Jahre mit großem Stolz gemeistert! Du bist wirklich eine großartige Mama!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'Zurück im Alltag nach der Feier 🚀', 'Nach der großen Geburtstagsfeier gestern bist du heute Morgen wieder zwischen verstreutem Spielzeug und „Ich will mich nicht anziehen!“ aufgewacht. Das Leben ist in seinen gewohnten Rhythmus zurückgekehrt. Atme tief durch – du bist die beste Managerin dieses Chaos.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'Dein Kind bestimmt die Geschichte 🪄', 'Ihr habt beide genug von den klassischen Kinderbüchern. Öffnet die intelligenten Märchen und macht dein Kind zur Hauptfigur und sein Zimmer zu dem Ort, der gerettet werden muss. So schafft ihr eine außergewöhnliche, ruhige und entspannte Einschlafroutine.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', 'Die „Ich kann das allein!“-Phase 🛑', 'Dein Kind möchte seine Schnürsenkel selbst binden und dafür gehen 10 Minuten drauf? Hetze es nicht, sondern gib ihm Zeit. Durch Ausprobieren und Fehler entwickelt es die Grundlage für seine späteren Problemlösungsfähigkeiten.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'Das Chaos zu Hause annehmen 🌪️', 'Überall im Zimmer liegt Spielzeug herum? Nicht die Sauberkeit zählt, sondern diese ausgelassenen Momente, die ihr miteinander verbringt. Das Spielzeug wird morgen noch da sein – mach dich nicht fertig. Manchmal ist es die beste Erholung, das Chaos einfach zu akzeptieren.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'Papas Geheimtaktik 👨‍🍼', 'Die Erschöpfung des Tages reicht dir völlig. Überlass Papa am Abend spielerisch das Zubettgehen und Zähneputzen, während du dich zurückziehst und die Ruhe genießt.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'Ein ungewöhnlicher bester Freund 🥄', 'Obwohl es so viele teure Spielsachen hat, holt es sich einen Silikonspatel aus der Küche, trägt ihn den ganzen Tag mit sich herum und bringt ihn sogar ins Bett? Das kindliche Gehirn ist unglaublich. Halte es nicht davon ab – lass es seinen Spatel lieb haben.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'Mit Flüstern in den Schlaf 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und flüstere ihm ganz leise ins Ohr, was ihr im Laufe des Tages erlebt habt. Flüstern ist eine der natürlichsten und wirkungsvollsten Methoden, um das Gehirn auf den Schlaf einzustimmen und störende Geräusche auszublenden.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'Die Überraschung auf der Liste 🛒', 'Bevor du zum Supermarkt gehst, öffnest du die Einkaufsliste – und plötzlich kommt dein Kind von hinten, tippt auf den Bildschirm und fügt Schokolade hinzu. Ja, mit Technik kennen sie sich besser aus als du!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'Zerstören mit Absicht 🧱', 'Mit großer Mühe baut dein Kind einen Turm und reißt ihn dann lachend mit einem einzigen Schlag ein. Dabei lernt es etwas über Physik und Ursache und Wirkung. Ärgere dich nicht: Jeder eingestürzte Turm schafft neue neuronale Verbindungen in seinem Gehirn.'),
  ('aa798243-c44e-4178-957c-647030916048', 'Wetterhinweis ⛅', 'Lass dich vor einem Spaziergang nicht vom Blick aus dem Fenster täuschen. Mit dem Wetter- und Kleidungsassistenten findest du das passende Outfit für die tatsächliche Außentemperatur und den Wind – so könnt ihr entspannt und gut ausgerüstet losgehen.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'Kleiner Zeichentrickkritiker 📺', 'Dein Kind erzählt dir mit seiner ganz eigenen Grammatik von der Zeichentrickserie und erklärt dir ernsthaft, wer wohin gegangen ist. Hör aufmerksam und mit gespieltem Staunen zu. Lass es sich wie der klügste Mensch der Welt fühlen.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'Die Kraft der Dunkelheit 🌙', 'Schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Melatonin wird nur in einer dunklen, technikfreien Umgebung zügig ausgeschüttet.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'Wählerische Feinschmecker 🥦', 'Heute lehnt dein Kind das Essen ab, das es gestern noch geliebt hat? Diese Launen beim Essen sind mit 3 Jahren ganz normal. Probiere gesunde Rezepte aus, die mit farbenfrohen und abwechslungsreichen Präsentationen Spaß am Essen machen.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'Die Fantasie hebt ab 🚀', 'Dein Kind spielt nicht mehr einfach nur, sondern erfindet ganze Geschichten! Ein Pappkarton verwandelt sich im Handumdrehen in ein Raumschiff. Halte diesen kognitiven Entwicklungssprung stolz im Entwicklungstracker fest und spiele mit.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'Tagesrückblick 🌙', 'Dimme vor dem Schlafengehen das Licht und sprecht darüber, worüber ihr heute am meisten gelacht habt. Diese kleinen Gespräche vor dem Einschlafen fördern die Ausdrucksfähigkeit deines Kindes.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'Der unsichtbare Verfolger 👻', 'Dein Kind hat Angst vor seinem Schatten an der Wand und fängt an zu weinen? Der Kampf gegen Schatten ist ein besonders amüsanter Klassiker mit 3 Jahren. Schalte das Licht aus, nimm eine Taschenlampe und lass die Schatten tanzen. So wird aus der Angst ein unterhaltsames Einschlafritual.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'Ein Zelt aus dem Wäscheberg ⛺', 'Dein Kind hat den frisch gefalteten Stapel sauberer Wäsche auseinandergerissen und daraus ein Zelt gebaut? Bevor du dich ärgerst, wirf einen Blick hinein. Die Fantasiewelt darin und die Freude deines Kindes sind wertvoller als die Mühe, die du dir beim Falten gemacht hast.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'Etiketten-Drama 🏷️', 'Es kratzt am Hals! Das kleine Etikett hinten im Shirt ist heute Morgen der größte Feind. Mit 3 Jahren erreicht die sensorische Empfindlichkeit ihren Höhepunkt. Diskutiere nicht, schneide das Etikett einfach ab und gib dem Tag die Chance, friedlich zu beginnen.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'Sinkende Schiffe in der Badewanne 🛀', 'Ihr wolltet im Badezimmer mit Wasser spielen, und nun versucht dein Kind, schwimmende Spielsachen unter Wasser zu drücken. Es entdeckt die Physik! Lass das Wasser ruhig herumspritzen – seine Energie nimmt auch den über den Tag angestauten Widerstand deines Kindes mit sich.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'Paarzeit 🥂', 'Das Kind schläft. Legt jetzt die Handys und die Hausarbeit beiseite. Setzt euch einander gegenüber und unterhaltet euch einfach 20 Minuten lang über etwas anderes als Rechnungen und das Kind. Ihr seid schließlich auch ein Paar!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'Schätze aus der Hosentasche 🪨', 'Beim Waschen seiner Hose kamen 3 unterschiedlich große Steine und eine Kastanienschale aus der Tasche? Für dein Kind ist das die wertvollste Sammlung der Welt. Statt alles wegzuwerfen, sammle die Fundstücke in einer kleinen Schachtel und macht daraus eine Schatzkiste.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme aus. Melatonin (das Schlafhormon) wird besonders gut in einer dunklen Umgebung ohne digitale Geräte ausgeschüttet.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'Gefühl der Erschöpfung 🔋', 'Möchtest du gerade alles und jeden anschreien? Geht dir jeder Lärm durch Mark und Bein? Das ist ein deutliches Zeichen von Überlastung. Bring dein Kind sofort an einen sicheren Ort (oder übergib es seinem Papa), geh in ein anderes Zimmer und schreibe im Stimmungstagebuch ungefiltert all deinen Stress auf.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'Aufwachen mit Musik 🎶', 'Die Sonne ist noch nicht ganz aufgegangen, aber dein Kind hüpft schon im Bett und gibt rhythmische Laute von sich. Der lauteste, aber zugleich süßeste Wecker der Welt! Starte mit einem Lächeln über diese grenzenlose Energie in den Tag.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'Gefühle festhalten 📝', 'Öffne das Stimmungstagebuch, nachdem dein Kind eingeschlafen ist. Halte für später den lustigsten, absurdesten Moment des Tages fest, der dich am meisten zum Lachen gebracht hat. Wenn du ihn Jahre später liest, wirst du Tränen in den Augen haben.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'Das Experiment mit der Ruhezeit 🥱', 'Dein Kind möchte keinen Mittagsschlaf machen, obwohl ihm die Augen schon zufallen? Dieser Widerstand ist mit 3 Jahren ganz typisch. Zwinge es nicht, sondern dimme das Licht im Zimmer, rufe eine stille Bilderbuchzeit aus und führt so eine neue Routine ein.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'Papas Geheimwaffe 🤡', 'Wenn deine Tricks nicht mehr funktionieren, retten Papas seltsame Geräusche und lustige Grimassen sofort die Situation. Spiele ihm bei abendlichen Krisen direkt den Ball zu, lehne dich entspannt zurück und schau zu.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'Ein unsichtbares Haustier 🐕', 'Streichelt dein Kind einen Hund oder eine Katze, die gar nicht im Zimmer sind, und gibt ihnen einen Namen? Seine Fantasie kennt inzwischen keine räumlichen Grenzen mehr. Stell eine unsichtbare Wasserschale in eine Zimmerecke und mach bei dieser süßen Illusion einfach mit.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'Ein Festmahl aus der Eiswürfelform 🧊', 'Dein Kind will dieses Gemüse partout nicht essen? Dann verändere die Präsentation komplett. Verteile gesunde Snacks auf die kleinen Fächer einer Eiswürfelform (ice cube tray). Eine ungewöhnliche Darbietung macht immer Appetit.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'Papas Flugmodus ✈️', 'Dein Kind rennt durchs Haus und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind hochhebt und mit ihm Flugzeug spielt, erfüllt schallendes Lachen das Zimmer – und die ganze angestaute körperliche Energie löst sich innerhalb von Sekunden in Schweiß auf.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'Regie führen um 6 Uhr morgens 🎬', 'Du schläfst noch, doch dein Kind steht schon über dir: „Du bist der Bär, ich bin der Hase!“ Spiel halb schlafend deine Rolle in diesem absurden Theater und gib dabei knurrende Laute von dir. Muttersein verlangt manchmal schauspielerische Höchstleistungen.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'Die Community als Vertraute 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären. Öffne einfach die Anacan Community und lies nur mit. Zu sehen, dass andere Mütter genauso erschöpft sind, gibt dir das Gefühl: „Ich bin nicht allein.“ Und manchmal ist genau das die beste Therapie.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'Der digitale Genuss der Stille 🤫', 'Endlich ist dein Kind eingeschlafen! Die Stille im Haus ist so tief, dass sie fast in den Ohren dröhnt. Aktiviere den Schallpegelmesser und beobachte die Anzeige von 0-10 Dezibel auf dem Bildschirm – so kannst du förmlich sehen, wie sich dein Gehirn langsam erholt.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', '„Ich schiebe!“ im Supermarkt 🛒', 'Dein Kind will den Einkaufswagen unbedingt selbst schieben – und prompt rammt ihr die Regale. Damit du seinen Willen nicht brichst, schiebt den Wagen einfach gemeinsam. Und damit du nichts vergisst, lass die Einkaufsliste in der App geöffnet.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'Unvollständige Sätze ergänzen 🗣️', 'Dein Kind hat ein Wort vergessen, gestikuliert mit den Händen und wartet darauf, dass du es errätst? Beobachte seine Erleichterung, wenn du fragst: „Ach, du meinst den Ball?“ Sein Wortschatz wächst – sein Gehirn arbeitet nur schneller als seine Zunge.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'Hör auf deinen Körper 🩸', 'Bist du ohne erkennbaren Grund erschöpft und könntest ständig weinen? Öffne den Perioden-Tracker. Dein Körper sendet dir Signale. Tu dir etwas Gutes und wähle aus den gesunden Rezepten einen magnesiumreichen Snack.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'Wählerischer Appetit 🍝', 'Isst dein Kind nur seine 2-3 Lieblingsgerichte? Keine Sorge. Prüfe mit dem Ernährungstracker die wöchentliche Ausgewogenheit und vermeide Druck am Esstisch.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'Dein Kind bestimmt das Ende der Geschichte 🪄', 'Ihr habt beide genug von den klassischen Kinderbüchern. Öffne die interaktiven Märchen und lass dein Kind heute Abend die Handlung bestimmen. Frag: „Wohin soll das Auto jetzt fahren?“ Dann kann es mit seinem selbst erfundenen, herrlich verrückten Ende einschlafen.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'Der Mythos von der perfekten Mutter 🛑', 'Die Kinder in den sozialen Medien sagen schon Gedichte auf, während dein Kind noch Wörter vertauscht? Hör sofort auf, zu vergleichen! Jedes Kind hat sein ganz eigenes Entwicklungstempo. Dein Kind ist genau richtig, so wie es ist.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'Die Schuhanzieh-Olympiade 👟', 'Dein Kind hat den rechten Schuh am linken Fuß angezogen und will ihn auf keinen Fall ausziehen? Lass ihn einfach dort. Das Gefühl von Selbstständigkeit und der Stolz „Ich hab’s geschafft!“ sind wichtiger, als die Schuhe richtig anzuziehen. Damit wird auch eine Grundlage für das spätere Lösen von Problemen gelegt.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'Das Drama um den unsichtbaren Müll 🗑️', 'Dein Kind sucht weinend nach diesem unnützen Papierschnipsel, den es selbst weggelegt und den du in den Müll geworfen hast! Genau so funktioniert die Logik eines 3-jährigen Kindes. Da du ihn nicht zurückholen kannst, lenke dein Kind sofort mit etwas Interessanterem ab.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'Mamas Ladezeit 🔋', 'Dein Kind puzzelt allein und ist seit 10 Minuten still. Du möchtest diesen Moment nutzen, um aufzuräumen. Nein! Leg dich aufs Sofa. Auch dein Akku muss aufgeladen werden, damit du dieses Tempo bis zum Abend durchhältst.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'An die Dunkelheit gewöhnen 🌙', 'Wird dein Kind unruhig, wenn im Schlafzimmer das Licht ausgeht? Stell in eine Ecke des Zimmers ein kleines Nachtlicht mit warmem Licht (gelb oder orange). Der Rest des Zimmers sollte für einen tiefen Schlaf vollständig dunkel bleiben.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'Der morgendliche Diktator ist im Einsatz 👑', 'Setz dich nicht dorthin, da soll mein Teddybär sitzen! Beim Frühstück bestimmt er über den ganzen Tisch. Brich seinen Willen nicht abrupt, sondern wahre die Balance, indem du sagst: „Gut, dein Teddybär sitzt dort und ich sitze hier.“'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'Raus in die Natur ⛅', 'Die eigenen vier Wände machen sowohl dein Kind als auch dich gereizt. Schau im Wetter- und Kleidungsratgeber nach und macht euch gleich auf den Weg in den Park. Draußen herumzulaufen und sich frei zu bewegen, kann selbst die heftigsten Trotzanfälle im Nu beenden.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'Entspannte Momente am Abend 🛀', 'Der ganze Tag war voller „Ich will nicht!“. Ein warmes Bad dient nicht nur der Hygiene, sondern hilft auch, das angespannte Nervensystem deines Kindes zu beruhigen. Das Plätschern und die Wärme des Wassers lassen die ganze Anspannung und Trotzreaktion dahinschmelzen.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'Beim Einkaufen etwas vergessen 🛒', 'Du hast dich auf dein Gedächtnis verlassen und beim Einkaufen die Windeln vergessen? Das kann passieren. Gewöhne dir an, alles, was du brauchst, sofort auf die Einkaufsliste zu setzen. So wird die App zu deinem digitalen Gedächtnis.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'Mama, schau mich an! 👀', 'Wenn du auf dein Handy schaust oder etwas erledigst, schlägt dein Kind dir gegen die Hand oder stellt sich vor dich. Sein Wunsch ist völlig verständlich: Es möchte deine ungeteilte Aufmerksamkeit. Schon 5 Minuten gemeinsames Spielen mit ununterbrochenem Blickkontakt können es beruhigen.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'Die wohltuende Stille 🤫', 'Miss nach einem lauten Tag mit dem Schallpegelmesser, wie still es im Zimmer ist, sobald dein Kind schläft. Zu sehen, wie sich die Werte null nähern, wirkt wie eine wohltuende Massage für dein müdes Mama-Gehirn.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'Wie schnell die Zeit vergeht!', 'Dein Kind ist schon eine eigenständige Persönlichkeit mit eigenen Entscheidungen. Sein starker Charakter wird dich später sehr stolz machen. Diese Tage kommen nicht zurück – nimm es liebevoll in den Arm.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'Der Gemüsechirurg 🥦', 'Sortiert dein Kind das Gemüse aus der Suppe, als würde es mit einem Mikroskop danach suchen? Kämpfe nicht dagegen an. Entdecke in den gesunden Rezepten kreative und leckere Möglichkeiten, Gemüse zu pürieren und in Soßen zu verstecken.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'Natur-Detox ist ein Muss 🌳', 'Hinter vier Wänden kann sich seine Energie in Aggressivität verwandeln. Geh deshalb bei jedem Wetter mit deinem Kind nach draußen – natürlich passend ausgerüstet und angezogen. Die Erde zu berühren und Blätter zu sammeln, beruhigt sein Nervensystem sofort.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'Die magische Kraft des Flüsterns 🌙', 'Deine Stimmbänder sind vom Vorlesen müde. Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und flüstere ihm ganz leise ins Ohr, was ihr im Laufe des Tages erlebt habt. Flüstern ist eine der beruhigendsten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'Ein erstaunliches Wesen 🎈', 'Auf diesem langen Weg gibt es so vieles, worüber du staunen kannst. Zum Beispiel, wenn dein Kind ein Wort, das es erst gestern gelernt hat, heute in einem philosophischen Satz verwendet! Diese Tage kommen nicht wieder.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'Die heimliche Schokoladenpause 🍫', 'Liebe Mama, die du dich hinter dem Küchenschrank versteckst, um heimlich Schokolade zu essen: Diese Glukose steht dir zu. Mach dir keine Vorwürfe! Um mit dieser wilden Energie mitzuhalten, musst auch du deine Akkus aufladen. Atme durch und kau einfach weiter.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'Dein Kind im intelligenten Märchen 🪄', 'Gib der Hauptfigur in den intelligenten Märchen heute Abend einfach den Namen deines Kindes. Erzähle zum Beispiel, dass die Figur im Märchen ihre Zähne nicht geputzt und es später bereut hat. So kannst du deinem Kind wichtige Werte ganz nebenbei vermitteln.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'Der Toilettenpapier-Ingenieur 🧻', 'Ein paar Minuten Stille ... Und als du das Zimmer betrittst, siehst du, dass das gesamte Toilettenpapier abgerollt und im Haus verteilt wurde! Statt dich zu ärgern, sammelt die Papierbahnen ein und baut gemeinsam einen Schneemann daraus. Begegne dem Chaos mit Kreativität.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'Du bist das Kind, ich bin die Mama 👩‍👧', 'Der Rollentausch beginnt! Dein Kind gibt dir Anweisungen wie: „Komm her, iss dein Essen!“ Lass dich mit Freude auf seine ersten Führungserfahrungen ein und spiele widerspruchslos die Rolle seines Kindes.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'Künstliche Intelligenz, echte Lösung 🤖', 'Warum beginnt ein 3-jähriges Kind plötzlich, an den Nägeln zu kauen? Vergiss die beängstigenden, traumatisierenden Artikel im Internet. Frag Anacan AI, ob es sich vielleicht nur um eine vorübergehende Stressreaktion handelt, und erhalte eine wissenschaftlich fundierte Antwort.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'Papas Massagestunde 💆‍♂️', 'Heute warst du lange auf den Beinen, und vom ständigen Hinterherlaufen tut dir der Rücken weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind eingeschlafen ist. Du bist die tragende Säule der Familie – und auch Säulen müssen sich unbedingt erholen.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'Einladung in die Dunkelheit 🌙', 'Damit dein Kind schneller einschläft, schalte alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. In einer dunklen, technikfreien Umgebung wird Melatonin schneller ausgeschüttet und erleichtert so das Einschlafen.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'Gedanken über die Kita 🏫', 'Hast du das Gefühl, dass dein Kind inzwischen mehr soziale Kontakte braucht? Ist jetzt der richtige Zeitpunkt für die Kita? Tritt der Anacan Community bei und lies die echten Eingewöhnungserfahrungen anderer Mütter, um dir die Entscheidung zu erleichtern.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'Ich helfe dir! 🧽', 'Will dein Kind beim Abwaschen unbedingt einen Stuhl neben dich stellen und mit dem Wasser spielen? Eigentlich möchte es nicht helfen, sondern mitten im Geschehen sein. Gib ihm eine kleine Plastikschüssel, die es ebenfalls einseifen darf.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'Geflüsterte Geschichten 🪄', 'Schalte das Licht im Zimmer vollständig aus. Lege dich neben dein Kind und flüstere ihm ganz leise eine kurze Handlung aus den Smarten Geschichten ins Ohr. Flüstern ist eine der natürlichsten und beruhigendsten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'Ein lebendiges Diktiergerät 🎙️', 'Den emotionalen oder seltsamen Satz, den du gestern am Telefon zu deiner Freundin gesagt hast, sagt dein Kind heute zu seinem Spielzeug! Sein Wortschatz wächst rasant, und es ahmt dich nach. Deshalb solltest du jetzt doppelt auf deine Worte achten.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'Sei es dir wert 🥗', 'Du hast Eier auf 4 verschiedene Arten zubereitet, damit dein Kind etwas isst – aber was hast du gegessen? Belohne dich mit einem besonderen, eisen- und kalziumreichen Teller aus unseren gesunden Rezepten, der in nur 5 Minuten fertig ist.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'Hilfe durch weißes Rauschen 🤫', 'Beim Einschlafen ist dein Kind besonders geräuschempfindlich. Aktiviere das Hintergrundgeräusch des Schallpegelmessers, um Geräusche von draußen zu überdecken und eine dauerhaft ruhige Atmosphäre im Zimmer zu schaffen.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'Kleidung voller Flecken 🎨', 'Ist der Schlafanzug voller Essensreste und die Kleidung mit Farbe bekleckert? Kinder müssen nicht sauber aufwachsen – sie dürfen beim Entdecken schmutzig werden. Verwende Silikonlätzchen und überlass den Rest der Waschmaschine.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'Auf Möbel klettern 🧗‍♂️', 'Versucht dein Kind, sich am Sofa oder Sessel hochzuziehen? Dabei entwickeln sich Gleichgewicht und Muskelkraft. Sorge für seine Sicherheit, aber halte diesen kleinen Kletterer nicht davon ab, die Gesetze der Physik zu entdecken.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'Austausch unter Müttern 💬', 'Erschöpft dich der Gedanke, dass sich dein Kind niemals beruhigen wird? Tritt der Anacan-Community bei. Dort wirst du sehen, dass jedes Kind auf dem Weg zum 3. Geburtstag durch solche stürmischen Krisen geht – und kannst erst einmal tief durchatmen.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'Eins, zwei, drei … zehn! 🔢', 'Versucht dein Kind, seine Finger oder Spielsachen zu zählen? Sein mathematisches Verständnis erwacht. Verpasse nicht diese kleinen Versuche, die sich in unglaublichem Tempo weiterentwickeln.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'Papas Nachtschicht 👨‍🍼', 'Übernimm das nächtliche Aufwachen und Einschlafbegleiten nicht ganz allein. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen. Heute Nacht ist er komplett fürs Einschlafbegleiten zuständig.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'Eine ruhige Stunde ausprobieren 🥱', 'Will dein Kind keinen Mittagsschlaf machen und weint? Zwinge es nicht. Dimme das Licht im Zimmer und führe eine ruhige Bilderbuchstunde ein. So entsteht eine neue Routine, die euch beide entspannt.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'Fantasien im Dunkeln 🌌', 'Verwandeln sich die Gegenstände im Zimmer in Monster, sobald das Licht ausgeht? Spiele bei den Weißen Geräuschen den Klang aus dem Mutterleib ab und schenke deinem Kind damit wieder dieses ursprüngliche, vollkommene Gefühl von Geborgenheit.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'Auf der Suche nach Logik 🧩', 'Einfache Spielsachen interessieren dein Kind nicht mehr und es denkt sich komplexere Spiele aus. Entdecke im Bereich „Empfohlene Produkte“ Spiele, die es geistig noch stärker fordern und das logische Denken fördern.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'Der Zauber des warmen Wassers 🛀', 'Der ganze Tag war voller „Ich will nicht!“. Ein warmes Bad dient nicht nur der Körperpflege, sondern hilft auch, das überreizte Nervensystem deines Babys wieder zur Ruhe zu bringen. Das Rauschen und die Wärme des Wassers werden all die Anspannung und Widerspenstigkeit einfach wegspülen.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'Naturrätsel 🍁', 'Die eintönige Atmosphäre zu Hause macht euch beide unruhig. Geht in den Park und macht euch auf die Suche nach dem Stein mit der ungewöhnlichsten Form. Die Natur ist für dein Baby das größte Forschungslabor und lässt all seine Anspannung verfliegen.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'Tiere nachahmen 🐶', 'Dein Baby macht nicht nur Tierlaute, sondern krabbelt auch wie ein Hund und schnurrt wie eine Katze? Körpersprache und Fantasie verbinden sich auf erstaunliche Weise. Mach bei diesem Spiel auf dem Teppich mit und lass dabei auch deinen eigenen Stress los.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'Offline-Zeit für Mama ☕', 'Wenn dein Kind ganz in sein Spiel vertieft ist, lauf nicht sofort los, um die Wohnung aufzuräumen. Gieß dir eine Tasse heißen Tee ein, leg das Handy beiseite und sitz einfach 15 Minuten da, ohne an irgendetwas zu denken.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'Zeit für euch als Paar 🥂', 'Das Kind schläft. Lass jetzt die Hausarbeit liegen. Sprich mindestens 20 Minuten mit deinem Partner oder deiner Partnerin über etwas anderes als das Kind und eure Ausgaben. Ihr seid schließlich auch ein Paar!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', 'Die „Was ist das?“-Maschine ☝️', 'Dein Kind zeigt mit dem Finger auf alles und fragt, wie es heißt? Es möchte, dass du ihm die Welt benennst. Das ist ein großer Sprung in seiner sprachlichen Entwicklung! Auch wenn du müde wirst, wiederhole die Namen der Gegenstände weiterhin geduldig.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'Die Fernbedienung im Kühlschrank 📺', 'Du kannst die Fernbedienung nicht finden? Schau im Kühlschrank oder im Schuhschrank nach. Dein Kind entdeckt die Welt, indem es Gegenstände nach seiner ganz eigenen Logik einsortiert. Statt dich zu ärgern, nimm dieses absurde Detektivspiel mit Humor.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'Die Suche nach der unsichtbaren Wunde 🩹', 'Kaum ist dein Kind wach, entdeckt es eine unsichtbare Wunde an seinem Körper und verlangt aufgeregt, dass du ein Pflaster daraufklebst. Dahinter stecken keine körperlichen Schmerzen, sondern einfach das Bedürfnis nach Aufmerksamkeit und Zuwendung. Diskutiere nicht: Kleb das kleine Pflaster auf, gib einen Kuss darauf und schon ist euer Tag gerettet.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'Plötzlicher Hunger 🥱', 'Kaum liegt dein Kind im Bett, ruft es: „Mama, ich habe Hunger!“ und will in die Küche laufen. Ein Meistertrick, um das Einschlafen hinauszuzögern! Plane für den Abend einen kleinen, schlaffördernden Snack ein, zum Beispiel eine Banane, und nimm dieser Ausrede schon im Voraus den Wind aus den Segeln.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'Wenn die Stille verdächtig wird 🤫', 'Dein Kind sitzt allein im Zimmer und schaut sich Bilder an, während im Haus tiefe Stille herrscht. Doch genau diese Ruhe macht dich misstrauisch, und du rechnest jeden Moment mit einer Katastrophe. Entspann dich. Manchmal möchten Kinder einfach allein sein. Lehn dich zurück und genieße diesen seltenen Offline-Moment.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'Lautes Denken 💭', 'Dein Kind liegt im Bett und erzählt sich selbst laut, was es im Laufe des Tages erlebt hat. So verarbeitet es Informationen und Erinnerungen. Öffne den Entwicklungstracker und halte stolz fest, wie rasant sich seine Fähigkeit zum freien Erzählen entwickelt hat.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'Die Linien auf dem Teppich 📏', 'Dein Kind versucht, über den Teppich zu laufen, ohne auf die Linien zu treten, und verlangt von dir dasselbe. Hier wirken Grobmotorik, Aufmerksamkeit und Koordination perfekt zusammen. Spiel einfach mit und springt ein paar Schritte lang gemeinsam über dieselben Linien.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'Eine Atempause für Mama 🌬️', 'Das Chaos zu Hause dröhnt dir schon in den Ohren. Prüfe das Wetter, zieh euch warm an und geht einfach für 15 Minuten nach draußen. Dein Kind kann Steine vom Boden sammeln, während du die kalte, frische Luft auf deinem Gesicht spürst und ganz tief einatmest.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'Dinosauriersprache 🦖', 'Heute Morgen ist dein Kind kein Mensch, sondern ein Dinosaurier und beantwortet all deine Fragen nur mit lautem Brüllen. Rollenspiele sind wunderbar für die Persönlichkeitsentwicklung. Sei auch du für einen Moment keine Mama, sondern ein anderer Dinosaurier, und antworte ihm in seiner eigenen Sprache.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'Erschöpfung eingestehen 📝', 'Hast du das Gefühl, dass dich niemand versteht und all deine Mühe unbemerkt bleibt? Dann lass das aufgesetzte Lächeln einmal beiseite. Schreib heute in dein Stimmungstagebuch, wie erschöpft du wirklich bist. Jedes Wort, das du auf dem Bildschirm festhältst, wird dir eine schwere Last von den Schultern nehmen.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'KI und Sorgen 🤖', 'Hat dich plötzlich beunruhigt, dass dein Kind manche Laute noch nicht aussprechen kann? Schließe die unseriösen und beängstigenden Internetforen. Frag Anacan AI nach den Normen der Sprachentwicklung im Alter von etwa 3 Jahren und erhalte eine wissenschaftlich fundierte, beruhigende Antwort.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'Papas magische Arme 🫂', 'Vom vielen Herumtragen tun dir schon die Arme weh, aber dein Baby möchte immer noch auf den Arm. Ruf Papa! Durch die Luft zu fliegen in Papas Armen erfüllt das Bedürfnis deines Kindes nach Aufmerksamkeit und gönnt deinen Armen und deinem Rücken die dringend benötigte Pause.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'Die Logik hinter der Frage 🧐', 'Warum können Fische nicht laufen? Schon früh am Morgen erwacht sein Gehirn mit philosophischen Fragen. Auch wenn seine Fragen dich manchmal ratlos machen, versuche immer wieder, sie geduldig zu beantworten. Deine Stimme ist für dein Kind der sicherste und schönste Weg, das Universum zu verstehen.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'Chaos mit der Einkaufsliste 🛒', 'Du stehst im Supermarkt an der Kasse und stellst fest, dass du schon wieder das Wichtigste vergessen hast. Dein Kopf ist ohnehin mit tausend Dingen gleichzeitig beschäftigt. Gewöhne dir deshalb an, alles sofort in die Einkaufsliste der App einzutragen, sobald du merkst, dass du es brauchst. Mach dir das Leben leichter.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'Stolz auf verkehrt herum angezogene Kleidung 🧦', 'Die Ferse der Socke sitzt oben auf dem Fuß, aber dein Kind läuft stolz herum, weil es sie selbst angezogen hat. Greif bloß nicht ein. Dieses Gefühl von „Ich habe es geschafft!“ ist als psychologische Grundlage millionenfach wertvoller als Ästhetik oder korrekt angezogene Kleidung.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'Geflüsterte Geschichten 🌙', 'Du hast heute so viel gesprochen, dass dir Stimme und Atem ausgehen. Schalte das Licht aus, leg dich neben dein Kind und flüstere ihm einfach ins Ohr, was ihr im Laufe des Tages erlebt habt. Das Flüstern bündelt seine Aufmerksamkeit und bereitet sein Gehirn auf beinahe hypnotische Weise auf einen tiefen Schlaf vor.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'Konzert in der Küche 🥄', 'Dein Kind holt Töpfe und Holzlöffel hervor und veranstaltet mitten in der Küche ein lautstarkes Konzert. Auch wenn du davon Kopfschmerzen bekommst: So entwickelt es sein Rhythmusgefühl und seine motorischen Fähigkeiten. Ruf ihm ein „Bravo!“ zu und hoffe, dass das Konzert bald vorbei ist.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'Das Maß der goldenen Stille 🤫', 'Das Chaos zu Hause ist endlich vorbei und dein Kind ist eingeschlafen. Lauf jetzt bloß nicht zum Abwasch! Öffne den Schallpegelmesser, betrachte die vollkommene Stille im Zimmer (0-10 Dezibel) und beobachte 15 Minuten lang, wie dein Gehirn zur Ruhe kommt.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'Das Drama um die geschälte Banane 🍌', 'Um 8 Uhr morgens bricht im Zimmer eine Revolution aus, weil du die Banane anstelle deines Kindes geschält hast? Die goldene Regel in diesem Alter lautet: Es will alles selbst entscheiden. Du kannst die Schale nicht wieder an die Banane kleben – lenke seine Aufmerksamkeit sofort auf etwas anderes Absurdes und entschärfe so die Krise.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'Zirkus im Bett 🎪', 'Sobald es Zeit zum Schlafen ist, verwandelt sich das Bett plötzlich in eine Zirkusmanege. Dein Kind hüpft, krabbelt und schreit. Dimme das Licht, ohne die Stimme zu erheben. Es lässt gerade die letzten Energiereserven heraus. Lass diesen Sturm mit einer sehr ruhigen Geschichte aus den smarten Märchen allmählich abklingen.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'Der heiß umkämpfte Türgriff 🚪', '„Ich mache die Tür auf!“, ruft dein Kind und rennt vor dir los. Wenn du sie bereits geöffnet hast, verlangt es weinend, dass du sie wieder schließt, damit es sie selbst öffnen kann. In diesem Alter ist das Gefühl von Kontrolle besonders wichtig. Lass dein Kind die Tür öffnen – solche kleinen Erfolge stärken sein noch empfindliches Selbstvertrauen.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'Gemeinsam sind wir stärker 💬', 'Heute hat dein Kind sich so sehr gegen alles gewehrt, dass du dich wie eine schlechte Mutter fühlst. Schau gleich in der Anacan Community vorbei. Wenn du von den heutigen kleinen Rebellionen der Kinder anderer Mütter liest, wirst du merken, dass du nicht allein bist – und dass du in Wahrheit großartige Arbeit leistest.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'Das rätselhafte Hin und Her 🤔', 'Dein Kind kommt zu dir und sagt völlig widersprüchliche Dinge wie: „Gib mir Wasser, aber gib es mir nicht.“ In seinem Kopf bestehen zwei gegensätzliche Wünsche gleichzeitig. Suche nicht nach zu viel Logik. Stell das Wasser einfach auf den Tisch und überlass die Entscheidung seinem inneren Konflikt.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'Versuche mit Hammer und Schrauben 🛠️', 'Mit jedem harten Spielzeug, das dein Kind in die Hände bekommt, klopft es auf die Möbel und „repariert“ sie. Auch wenn dir die Geräusche durch Mark und Bein gehen, ist das eine Entdeckungsreise, bei der es Ursache und Wirkung kennenlernt. Gib ihm einen leeren Karton und einen Holzlöffel, damit es seine lauten Reparaturarbeiten dort fortsetzen kann.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'Kein Müll, sondern Kunst 🎨', 'Mitten im Zimmer hat dein Kind aus kleinen Papierschnipseln und abgeschnittenen Fäden ein großes Kunstwerk geschaffen – und du darfst es auf keinen Fall wegwerfen. Lass deinen Ordnungsdrang für einen Moment los. Respektiere das kreative Chaos; aufräumen kannst du auch morgen noch.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'Schallpegel-Therapie 🤫', 'Der endlose Lärm zu Hause ist endlich verstummt. Dein Kind schläft. Öffne den Schallpegelmesser und beobachte, wie die Zahlen auf dem Bildschirm bis auf 0 Dezibel sinken. Spüre, wie die sichtbare absolute Stille im Raum dein Gehirn sanft massiert.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'Theater vor dem Spiegel 🎭', 'Schon früh am Morgen steht dein Kind vor dem Spiegel und übt verschiedene Gesichtsausdrücke: Weinen, Lachen und Staunen. Es lernt, seine Gefühle auszudrücken und zu beobachten, wie sich dabei sein Gesicht verändert! Schau dir diese geniale schauspielerische Darbietung aus der Ferne voller Stolz an.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'Die falsche Farbe – eine Katastrophe 🔴', 'Ein Weltuntergang, nur weil du das Wasser nicht im blauen, sondern im roten Becher serviert hast? Das ist keine Marotte – dein Kind testet nur deine Grenzen und ob es seine Welt kontrollieren kann. Tausche den Becher aus, ohne einen Machtkampf daraus zu machen, und schone deine Energie.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'Lass deine Gefühle raus 📝', 'Sieht niemand, wie erschöpft du zu Hause bist? Ein Stimmungstagebuch ist dein stillster Vertrauter. Schreibe heute all die Kleinigkeiten hinein, die dich wahnsinnig gemacht haben, und spüre, wie dein Kopf leichter wird.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'Künstliche Intelligenz, echte Lösung 🤖', 'Dein Kind hat eine seltsame Angewohnheit entwickelt, zum Beispiel Haarezwirbeln, und die Artikel im Internet haben dir Angst gemacht? Stopp. Frage Anacan AI nach der tatsächlichen, kinderärztlich bestätigten Ursache und erspare dir unnötige Panik.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'Die Logik beim Versteckspiel 🙈', 'Dein Kind steht mitten im Zimmer, hält sich die Augen zu und wartet darauf, dass du es findest! Die Logik mit 3 Jahren: Wenn ich dich nicht sehe, kannst du mich auch nicht sehen. Tu so, als würdest du dich von dieser unschuldigen Illusion täuschen lassen, und suche es geräuschvoll im Zimmer.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin, das Schlafhormon, wird besonders in einer dunklen und technikfreien Umgebung rasch ausgeschüttet.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'Digitales Gedächtnis 🛒', 'Vergisst du beim Einkaufen immer irgendetwas? Die Einkaufsliste in der App wartet auf dich. Trage dort sofort ein, was ihr braucht, damit dein Partner auf dem Heimweg von der Arbeit gezielt alles besorgen kann – und entlaste deinen Kopf.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', 'Das „Ich mache das selbst!“-Gesetz 👟', 'Dein Kind möchte seine Schnürsenkel selbst binden, und ihr seid schon 10 Minuten zu spät dran. Dränge es nicht. Für seine Entwicklung ist ein gesundes Selbstwertgefühl wichtiger als ein perfekter Zeitplan.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'Die magische Kraft des Flüsterns 🤫', 'Dein Kind ist im Bett so aktiv, dass es einfach nicht einschläft. Anstatt lauter zu werden, senke plötzlich deine Stimme und sprich flüsternd. Wenn dein Kind sich konzentriert, um dich zu hören, schaltet sein Gehirn automatisch in den Schlafmodus.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'Selektives Hörsyndrom 🙉', 'Wenn du sagst, dass dein Kind seine Spielsachen aufräumen soll, hört es nichts – aber das Rascheln einer Schokoladenverpackung im Nebenzimmer nimmt es sofort wahr? Mit seinem Gehör ist alles in Ordnung, es hört einfach nur das, was ihm gerade passt. Versuch, die Regeln zu flüstern – das weckt seine Neugier.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'Schätze aus der Hosentasche 🪨', 'Beim Waschen der Hose findest du in der Tasche 2 Steine, ein vertrocknetes Blatt und ein abgebrochenes Stöckchen? Was für dich wie Müll aussieht, ist für dein Kind eine wertvolle Sammlung, mit der es die Welt entdeckt. Wirf diese Dinge nicht weg, sondern sammle sie in einer kleinen Schatzkiste.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'Brokkoli-Tarnung 🥦', 'Sortiert dein Kind das grüne Gemüse mit chirurgischer Präzision aus der Suppe? Die Phase des wählerischen Essens ist auf ihrem Höhepunkt. Es ist Zeit, im Ernährungsplan besondere, raffinierte Rezepte zu entdecken, die Gemüse unsichtbar machen oder in bunte Bratlinge verwandeln.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'Dein Kind führt Regie beim Märchen 🪄', 'Ihr habt beide genug von den klassischen Kinderbüchern. Öffnet die interaktiven Märchen und lass dein Kind heute Abend die Handlung bestimmen. Frag: „Wohin soll das fliegende Auto jetzt fliegen?“ – und lass es mit seinem selbst erfundenen, verrückten Ende einschlafen.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'Papas Flugmodus ✈️', 'Dein Kind konnte zu Hause seine Energie nicht loswerden und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind hochhebt und mit ihm Flugzeug spielt, erfüllt lautes Lachen das Zimmer und die angestaute körperliche Anspannung löst sich innerhalb von Sekunden.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'In der Gemeinschaft aufatmen 💬', 'Du bist völlig erschöpft und fühlst dich wie die ungeduldigste Mutter der Welt? Öffne sofort die Anacan Community. Zu lesen, dass andere Mütter genau dieselben absurden Krisen erleben, kann eine enorme seelische Unterstützung sein.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'Die endlose Warum?-Schleife 🌪️', '„Warum fliegen Vögel?“, „Warum macht Wasser nass?“, „Warum heißt warum eigentlich warum?“ ... Ein ganzer Zug voller Fragen rast auf dich zu. Auch wenn du müde bist, gib deinem Kind kurze, verständliche Antworten. Es entdeckt die Geheimnisse des Universums durch deine Stimme.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'Flucht in die Natur ⛅', 'Die eigenen vier Wände machen euch beide gereizt. Du hast genug vom Chaos zu Hause. Prüfe mit dem Wetter- und Kleidungstool, was ihr braucht, und macht euch sofort auf den Weg in den Park. Draußen frei herumzutoben beendet selbst die heftigsten Kleinkindkrisen oft wie auf Knopfdruck.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'Kleine Wäschehilfe 🧺', 'Du faltest mühsam die Wäsche, und dein Kind verteilt alles wieder im Zimmer – angeblich, um zu helfen. Statt dich zu ärgern, mach ein Spiel daraus: Mal sehen, wer diese Socken schneller in den Korb werfen kann?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'Avantgardistischer Modegeschmack 👗', 'Dein Kind trägt Sommershorts über dem Winterpullover und will sie nicht ausziehen? Das ist kein Problem. Ein Kind, das sich in einem ungewöhnlichen Outfit unter Menschen traut, steht in Wahrheit mutig zu seiner eigenen Entscheidung. Brich seinen Willen nicht.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'Nächtlichen Nachtschreck erkennen 😭', 'Dein Kind schreckt mitten in der Nacht mit geschlossenen Augen weinend hoch und reagiert auf niemanden. Prüfe es mit der Weinanalyse. Wenn es sich um einen Nachtschreck handelt, versuche nicht, dein Kind zu wecken. Bleib einfach bei ihm und vermittle ihm still ein Gefühl von Sicherheit.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'Wetterwarnung ⛅', 'Lass dich vor einem Spaziergang nicht vom Blick aus dem Fenster täuschen. Mit dem Wetter- und Kleidungsassistenten findest du das passende Outfit für die tatsächliche Temperatur und den Wind draußen – so kannst du entspannt und gut vorbereitet losgehen.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'Vertraute Gemeinschaft 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären. Öffne einfach die Anacan-Community und lies nur mit. Zu sehen, dass andere Mütter ähnlich erschöpft sind, schenkt dir das Gefühl „Ich bin nicht allein“ – und kann die beste Therapie sein.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'Livekonzert und Nachbarn 🎤', 'Dein Kind nimmt einen Löffel in die Hand, stellt sich mitten ins Zimmer und singt aus voller Kehle. Mach dir keine Gedanken darüber, was die Nachbarn denken könnten. In deinem Zuhause wächst ein Star heran – du musst nur applaudieren.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'Mit Musik sanft zur Ruhe kommen 🎶', 'Versuche, die scheinbar grundlosen Stürme am späten Nachmittag mit sanfter klassischer Musik zu beruhigen. Oft wirkt dieser einfache, aber wirkungsvolle Trick zu Hause wahre Wunder und bringt spürbar Ruhe ins Zimmer.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'Schuldgefühle wegen der Bildschirmzeit 📺', 'Du hast dein Kind heute wegen all deiner Aufgaben länger Zeichentrickfilme schauen lassen und hast nun ein schlechtes Gewissen? Mach dir keine Vorwürfe. Manchmal ist der digitale Babysitter die einzige Möglichkeit, die dich vor einem emotionalen Zusammenbruch bewahrt.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'Die Handy-Versteckaktion 📱', 'Du findest dein Handy nicht mehr – und wenig später taucht es in der Spielzeugkiste auf. Dein Baby möchte deine Aufmerksamkeit nicht mit dem Handy teilen. Leg das Gerät beiseite und schenke ihm 15 Minuten lang deine ungeteilte Aufmerksamkeit.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'Stille in Dezibel 🤫', 'Endlich ist dein Baby eingeschlafen! Du kannst die Stille, die sich im Haus ausbreitet, kaum glauben. Aktiviere den Schallpegelmesser und beobachte die 0-10 Dezibel auf dem Display – so kannst du förmlich sehen, wie dein Kopf langsam zur Ruhe kommt.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'Mein Spielzeug gebe ich nicht her! 🧸', 'Auf der Rutsche oder im Sand möchte dein Kind niemandem Platz machen und hält seine Spielsachen ganz fest. Das ist kein Egoismus, sondern das Abstecken eigener Grenzen. Zwing es nicht zum Teilen, sondern bring ihm spielerisch bei, sich abzuwechseln.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'Einladung in die Dunkelheit 🌙', 'Wird dein Baby unruhig, wenn im Schlafzimmer das Licht ausgeht? Stell in einer Ecke des Zimmers ein kleines Nachtlicht mit warmem Licht auf. Der Rest des Raumes sollte für einen tiefen Schlaf vollständig dunkel bleiben.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'Wenn Mama müde ist 🛑', 'Du bist kein Roboter. Wenn du heute keine Kraft zum Kochen hast, bestell etwas oder koche einfach Nudeln. Eine perfekte Mama zu sein bedeutet nicht, alles allein machen zu müssen. Erlaube dir, es dir leichter zu machen.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'Überraschung auf der Liste 🛒', 'Du öffnest vor dem Einkaufen deine Einkaufsliste – und plötzlich kommt dein Kind von hinten, tippt auf den Bildschirm und kritzelt etwas hinein. Ja, es ahmt auch dein digitales Leben nach!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'Ein Geständnis im Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Statt dich durch das Leben anderer in den sozialen Medien zu scrollen, öffne dein Stimmungstagebuch und halte den lustigsten Moment fest, den du heute mit deinem Kind erlebt hast. Digitale Therapie wirkt.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'Verhandeln wie ein Anwalt 🗣️', '„Nur noch 5 Minuten spielen, dann ziehe ich mich an“, sagt dein Kind? Es versucht bereits, professionell mit dir zu verhandeln. Seine Sprachentwicklung ist großartig, aber vergiss nicht, deine Grenzen und Regeln liebevoll zu wahren.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'Zeit für Ruhe 🥱', 'Dein Kind möchte keinen Mittagsschlaf machen und weint? Zwinge es nicht. Dimme das Licht im Zimmer und erkläre eine stille Bilderbuchzeit. So schafft ihr eine neue Routine, bei der ihr beide zur Ruhe kommt.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'Das esse ich heute nicht 🥣', 'Die Suppe, die dein Kind gestern noch genüsslich gegessen hat, will es heute nicht einmal probieren. Wenn keine Zahnprobleme dahinterstecken, testet es wahrscheinlich nur seine Grenzen aus. Schau dir im Ernährungsplan alternative Rezepte an, die die gleichen Vitamine liefern.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'Papas lustige Geräusche 🤡', 'Wenn deine Tricks nicht mehr funktionieren, retten Papas lustige Geräusche und Grimassen oft sofort die Situation. Überlass ihm bei abendlichen Krisen das Ruder, lehn dich zurück und schau entspannt zu.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'Rätselspaß in der Natur 🍁', 'Die langweilige Stimmung zu Hause schlägt euch beiden aufs Gemüt. Geht in den Park und macht euch auf die Suche nach dem Stein mit der ungewöhnlichsten Form. Die Natur ist das größte Forschungslabor für dein Kind und lässt den ganzen Stress verfliegen.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'Fantasiegäste am Tisch ☕', 'Dein Kind reicht dir eine leere Tasse, sagt „Trink Tee“ und unterhält sich mit einem unsichtbaren Freund? Das ist Fantasieentwicklung in ihrer schönsten Form. Unterbrich dieses kleine Schauspiel in der Zimmerecke nicht – trink den Tee einfach mit.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'Ich im magischen Märchen 🪄', 'Ihr kennt die klassischen Bücher schon auswendig. Öffne die interaktiven Märchen, mache dein Kind zur Hauptfigur und sein Zimmer zu dem Ort, den es erobern soll. So wird das Einschlafritual zu einem ganz besonderen Abenteuer.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'Frieden im Badezimmer 🛀', 'Das Spielen mit Wasser macht so viel Spaß, dass dein Kind selbst mit schrumpeligen Fingern nicht aus der Badewanne kommen möchte. Kündige das Ende 5 Minuten vorher an und stelle einen Timer. Die Regel „Wenn es klingelt, steigen wir aus“ funktioniert oft sehr gut.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', '„Nicht meine Hand halten!“ – Freiheit 🚶‍♂️', 'Dein Kind weigert sich draußen entschieden, deine Hand zu halten, und möchte frei herumlaufen. Gib ihm diese Freiheit an sicheren Orten. Behalte es gut im Blick und lass es die Welt mit seinen eigenen Schritten erobern.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'Abendliche Ruhe 🛁', 'Nach einem Tag voller Herumrennen seid ihr beide völlig erschöpft. Lass während des warmen Bads im Hintergrund beruhigende Naturgeräusche laufen. Das harmonische Plätschern des Wassers bereitet selbst das hartnäckigste Kind auf einen tiefen Schlaf vor.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'Berührungsmüdigkeit 🔋', 'Den ganzen Tag klettert dein Kind an dir hoch, möchte auf den Arm und spielt mit deinen Haaren. Du hingegen wünschst dir einfach etwas körperlichen Freiraum. Berührungsmüdigkeit (touched out) ist real. Du hast das Recht, dich wenigstens für 15 Minuten allein in ein Zimmer zurückzuziehen.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'Angst vor dem Badewannenabfluss 🛀', 'Dein Kind wollte früher gar nicht aus dem Wasser und weint nun plötzlich aus Angst vor dem Badewannenabfluss? Mit der wachsenden Fantasie können unbegründete Ängste entstehen. Decke den Abfluss mit einem Plastikspielzeug ab und gib deinem Kind Sicherheit.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'Auszeit als Paar 🥂', 'Das Kind schläft. Lass jetzt die Hausarbeit liegen. Sprich mindestens 20 Minuten mit deinem Partner über etwas anderes als das Kind, Probleme oder Ausgaben. Bevor ihr Eltern seid, seid ihr ein Paar!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'Gespräche mit leblosen Gegenständen 🗣️', 'Dein Kind spricht im Park ganz ernst mit einem Stein oder zu Hause mit einem Stuhl und schimpft sogar mit ihnen. Durch symbolisches Spielen verarbeitet es die Welt. Halte diese besonderen Spielszenarien unbedingt im Entwicklungs-Tracker fest.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'Papas Massage-Session 💆‍♂️', 'Du warst heute viel auf den Beinen, und vom ständigen Hinterherlaufen tut dir der Rücken weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind schläft. Du bist die tragende Säule der Familie – und auch Säulen müssen sich erholen.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'Taktik zum Hinauszögern des Schlafengehens ⏱️', 'Bekommt dein Kind zur Schlafenszeit plötzlich Durst, muss auf die Toilette oder verabschiedet sich sogar von der Wand? Stell einen Timer. Führe die Regel „Wenn es klingelt, gehen alle schlafen“ ein und beende dieses endlose Abschiedsritual mit Geduld.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'Mamas Nährstoffreserven 🥗', 'Du hast dir verschiedene Gerichte ausgedacht, damit dein Kind satt wird – aber bist du selbst wieder hungrig geblieben? Wähle aus den gesunden Rezepten ein eisen- und kalziumreiches Mittagessen, das in 10 Minuten zubereitet ist, und zeige dir damit, dass auch du wichtig bist.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'Künstliche Intelligenz, echte Antworten 🤖', 'Was sind die wissenschaftlich und kinderärztlich belegten Ursachen der Trotzphase mit 3 Jahren? Statt beängstigende Kommentare im Internet zu lesen, kannst du Anacan AI sofort um eine präzise und professionelle Einschätzung der kindlichen Psyche bitten.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'Reizüberflutung 🔋', 'Dein Kind ist den ganzen Tag an dir hochgeklettert, hat an deinen Haaren gezogen und Lärm gemacht. Dein Nervensystem schlägt Alarm. Berührungsmüdigkeit ist absolut real. Übergib dein Kind deinem Partner oder deiner Partnerin und zieh dich für eine Weile in ein Zimmer zurück.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'Eigenwillige Aussprache 🗣️', 'Dein Kind spricht manche Wörter so eigenwillig und mit so ungewöhnlicher Betonung aus, dass du dir das Lachen kaum verkneifen kannst. Korrigiere es nicht lachend. Höre stattdessen aufmerksam zu und antworte, indem du den Satz einfach richtig wiederholst.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'Vergesslich im Supermarkt 🛒', 'Du hast dich auf dein Gedächtnis verlassen, bist einkaufen gegangen und ohne Windeln zurückgekommen? Das kann passieren. Gewöhne dir an, alles, was du brauchst, sofort in die Einkaufsliste einzutragen – lass dich von deinem digitalen Gedächtnis retten.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'Bring deine Gefühle zu Papier 📝', 'Niemand sieht, wie erschöpft du bist? Dein Stimmungstagebuch ist da, um dir zuzuhören. Schreib heute all die Kleinigkeiten hinein, die dich in den Wahnsinn getrieben haben, und mach den Kopf frei.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'Die richtigen Bedingungen für das Schlafhormon 🌙', 'Schalte eine Stunde vor dem Schlafengehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus, damit dein Kind schneller einschläft. Das Schlafhormon wird vor allem in einer dunklen, technikfreien Umgebung ausgeschüttet.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'Freiheit im Park 🌳', 'Vier Wände machen dein Kind gereizt. Nutze den Wetter- und Kleidungsassistenten, um das passende Outfit für den Wind draußen auszuwählen, und geht in den Park. Lass dein Kind im Sand herumtoben, rennen und auch mal hinfallen. Freiheit ist die beste Unterstützung für seine Entwicklung.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'Eine unerwartete Umarmung 💖', 'Mitten im Spielen schaut dein Kind dich plötzlich an, läuft auf dich zu und fällt dir um den Hals. Dafür haben sich all die schlaflosen Nächte und die Erschöpfung gelohnt! Genieße den tiefen, einzigartigen Frieden, den dieser Moment dir schenkt.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'Ein Zeitgefühl entsteht ⏱️', 'Benutzt dein Kind Wörter wie morgen, gestern und später häufig, aber manchmal an der falschen Stelle? Sein Zeitgefühl entwickelt sich! Höre dir diese Versuche mit einem Lächeln an.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'Eine Pause für Mama ☕', 'Wenn dein Kind allein spielt, stürze dich nicht sofort auf die Hausarbeit. Das Chaos im Zimmer läuft nicht weg, aber deine Energie kann zur Neige gehen. Setz dich hin und genieße deinen heißen Kaffee.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'Fluchtplan aus dem Bett 🛌', 'Versucht dein Kind, aus seinem Gitterbett zu klettern? Überprüfe das Zimmer noch einmal auf mögliche Gefahren. Bald ist es Zeit für den Wechsel in ein Kinderbett.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'Fantasievolle Szenarien 🧸', 'Füttert dein Kind seine Spielsachen oder verarztet sie? Symbolische Spiele bilden die Grundlage für Empathie. Halte diesen kognitiven Entwicklungssprung voller Stolz im Entwicklungs-Tracker fest.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'Eine zauberhafte Abendkulisse 🪄', 'Fällt deinem Kind das Einschlafen schwer? Erzähle neue Gewohnheiten als Geschichte, indem du in den smarten Märchen ein Abenteuer über einen heldenhaften kleinen Bären erstellst, der sich die Zähne putzt.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'Miteinander im Park 🌳', 'Spielt dein Kind lieber neben anderen Kindern als gemeinsam mit ihnen? Paralleles Spielen ist in diesem Alter völlig normal. Unterstütze seine soziale Entwicklung, ohne es unter Druck zu setzen.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'Brokkoli-Detektiv 🥦', 'Entdeckt dein Kind selbst das eine grüne Gemüsestück in der Suppe und weigert sich dann, weiterzuessen? Entdecke im Ernährungsplan die leckersten Möglichkeiten, Gemüse unter bunte Nudeln zu mischen, die Aufmerksamkeit abzulenken und gesunde Lebensmittel geschickt zu verstecken.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'Gefühle eingestehen 📝', 'Fühlst du dich schlecht, weil du den ganzen Tag zu allem Nein sagen musstest? Öffne dein Stimmungstagebuch. Schreibe heute ungefiltert deinen dunkelsten Gedanken auf: „Ich wünschte, ich wäre allein.“ Mach dir keine Vorwürfe – jede Mutter ist manchmal erschöpft und möchte einfach nur davonlaufen.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'Spuren der Entwicklung 📈', 'Mit 3 Jahren entwickeln sich die Motorik, der Wortschatz und die emotionale Intelligenz deines Kindes rasant weiter. Halte seine kleinen Entdeckungen regelmäßig im Entwicklungs-Tracker fest und archiviere sie, damit du sie nicht vergisst.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'Sich entschuldigen und es wieder tun 🧸', 'Entschuldigt sich dein Kind aufrichtig dafür, dass es jemanden gehauen oder etwas kaputt gemacht hat, und tut 5 Minuten später genau dasselbe? Es kann seine Impulse noch nicht kontrollieren. Erkläre ihm die Regel geduldig immer wieder.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'Das Bedürfnis, sich auszusprechen 💬', 'Stehst du vor einer schwierigen Entscheidung? (Kita, Töpfchen, Schlaf). Die Ratschläge erfahrener Mütter in der Anacan-Community bieten lebensnahe Lösungen, die in keinem Buch stehen.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'Lass dein Kind das Ende der Geschichte bestimmen 🪄', 'Ihr seid beide müde von den klassischen Büchern. Lass dein Kind diesmal in den interaktiven Märchen selbst entscheiden, wie die Geschichte endet. Frage: „Was denkst du, wer hat dem Helden geholfen?“ So kann es seiner Fantasie vor dem Einschlafen freien Lauf lassen.'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'Gesunde Mama, gesundes Kind 🥑', 'Iss dein Mittagessen in der täglichen Hektik nicht im Stehen. Setz dich hin und genieße einen abwechslungsreichen Salat, der reich an Eisen und Kalzium ist. Deine Energie ist der Motor dieses Zuhauses – achte gut auf sie.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'Die wohltuende Stille 🤫', 'Wenn dein Kind nach einem turbulenten Tag eingeschlafen ist, miss mit einem Schallpegelmesser, wie still es im Zimmer ist. Schon der Anblick der Werte, die sich null nähern, wirkt auf das Gehirn einer Mutter wie die beste visuelle Massage.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'Tatkräftige Hilfe beim Kochen 🧑‍🍳', 'Während du den Teig ausrollst, stellt dein Kind bestimmt einen Stuhl neben dich und mischt sich in die Zubereitung ein. Gib ihm eine eigene Plastikschüssel, die es mit Mehl bestäuben darf. Die Küche wird danach zwar chaotisch aussehen, aber sein ernster, geschäftiger Gesichtsausdruck ist das Aufräumen allemal wert.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'Einander Danke sagen 🥂', 'Ihr habt einen anstrengenden Tag hinter euch. Wenn das Kind eingeschlafen ist, trink mit deinem Partner eine Tasse Tee und bedanke dich mit den Worten: „An diesem turbulenten Tag hast du mir sehr geholfen.“ So entsteht echter Teamgeist.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'Das war nicht meine Schuld! 🤷‍♂️', 'Dein Kind hat das Wasser absichtlich auf den Boden geschüttet, gibt aber dem Tisch die Schuld und sagt: „Der Tisch ist ausgerutscht.“ Das ist keine Lüge, sondern der instinktive Versuch des kindlichen Gehirns, Verantwortung zu vermeiden und sich selbst zu schützen. Lass dich nicht auf einen Machtkampf ein. Sag stattdessen: „Komm, wir helfen dem Tisch und wischen es gemeinsam auf.“ So vermittelst du Verantwortung, ohne dein Kind zu verletzen.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'Der Vier-Wände-Koller ⛅', 'Dir fällt zu Hause die Decke auf den Kopf und dein Kind wird zunehmend aggressiv. Prüfe das Wetter, wähle die passende Kleidung und dann nichts wie raus in den Park. Frische Luft und Bewegungsfreiheit sind der beste Detox – sowohl für das Gehirn deines Kindes als auch für deine strapazierten Nerven.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'Mission Wäschefalten 🧺', 'Du faltest mühsam die saubere Wäsche, und dein Kind stürzt sich hinein und bringt in 2 Sekunden alles durcheinander. Plötzlich herrscht große Stille im Raum ... Liegen deine Nerven blank? Atme tief durch. Wirf dich einfach auf den Wäscheberg und gib dich diesem Chaos lachend geschlagen.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'Regie beim Fantasiemärchen 🪄', 'Ihr beide habt genug von den Figuren aus den klassischen Kinderbüchern. Öffnet die Fantasiemärchen und lass dein Kind heute Abend die Handlung erfinden. Frag: „Wohin soll der fliegende Dinosaurier jetzt reisen?“ So kann es in seiner selbst erfundenen Fantasiewelt einschlafen.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'Papas Flugmodus ✈️', 'Dein Kind konnte zu Hause seine Energie nicht loswerden und erfindet tausend Ausreden, um nicht ins Bett zu müssen. Ruf Papa dazu. Wenn er das Kind hochhebt und Flugzeug mit ihm spielt, erfüllt schallendes Lachen das Zimmer und die angestaute körperliche Anspannung löst sich mit jeder Menge Bewegung und Schweiß.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', 'Der Schlag: „Du bist eine schlechte Mama!“ 💔', 'Du hast das gewünschte Spielzeug nicht gekauft, und dein Kind schaut dich an und sagt: „Du bist gemein“? Lass dir das nicht zu Herzen gehen. Es kann seine Gefühle noch nicht mit den richtigen Worten ausdrücken. Eigentlich möchte es sagen: „Ich bin sehr wütend und enttäuscht.“ Nimm Blickkontakt auf und zeig ihm einfach, dass du sein Gefühl wahrnimmst.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', '„Ich will schieben!“ im Supermarkt 🛒', 'Dein Kind will den Einkaufswagen selbst schieben, stößt dabei gegen die Regale und zieht alle Blicke auf sich. Jedes Mal, wenn du eingreifst, fängt es an zu weinen. Schiebt den Wagen einfach gemeinsam. Und damit du nichts vergisst, halte die Einkaufsliste in der App stets aktuell – so wird dein Kopf weniger belastet.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'Die Stille des Schallmessers 🤫', 'Endlich ist dein Kind eingeschlafen! Die Stille, die sich über das Zuhause legt, ist so tief, dass sie fast in den Ohren schmerzt. Aktiviere den Schallmesser und sieh dir die Anzeige von 0-10 Dezibel auf dem Bildschirm an. Spüre dabei förmlich, wie sich dein Gehirn langsam erholt.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'Die Community als Vertraute 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären. Öffne einfach die Anacan Community und lies still mit. Zu sehen, dass andere Mütter ähnlich erschöpft sind und ebenfalls komische kindliche Wutanfälle erleben, vermittelt dir das Gefühl, nicht allein zu sein – und das kann unglaublich beruhigend wirken.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'Der kleine Küchenchef 🧑‍🍳', 'Während du den Teig ausrollst, stellt dein Kind bestimmt einen Stuhl neben dich und möchte unbedingt mitmachen. Gib ihm eine eigene Plastikschüssel, in die es etwas Mehl geben darf. Die Küche wird danach zwar chaotisch aussehen, aber sein ernster, geschäftiger Gesichtsausdruck und das Gefühl „Ich kann das auch!“ sind das Aufräumen allemal wert.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'Stolz auf verkehrt herum angezogene Sachen 🧦', 'Die Ferse der Socke sitzt oben auf dem Fuß, aber dein Kind läuft stolz damit herum, weil es sie selbst angezogen hat. Greif auf keinen Fall ein. Das Gefühl „Ich habe es geschafft!“ ist als psychologische Grundlage millionenfach wertvoller als ein schönes Aussehen oder richtig angezogene Kleidung. Lass es den Tag ruhig so verbringen.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'Offline-Minuten für Mama ☕', 'Dein Kind beschäftigt sich allein mit einem Puzzle und ist schon seit 10 Minuten still. Du möchtest diesen Moment nutzen, um die Wohnung aufzuräumen. Nein! Leg dich aufs Sofa. Auch dein Akku muss aufgeladen werden, damit du dieses Tempo bis zum Abend durchhältst.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'Sich mit der Dunkelheit anfreunden 🐰', 'Dein Kind möchte nicht einschlafen und sagt, dass es Angst vor den Schatten im Zimmer hat? Verdunkle den Raum vollständig und formt mit euren Händen Vogel- und Hundeschatten an der Wand. Indem ihr die Angst in ein Spiel verwandelt, hilfst du deinem Kind, sich mit der Dunkelheit anzufreunden und seine Fantasie bewusst zu lenken.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'Künstliche Intelligenz und Sorgen 🤖', 'Du machst dir Sorgen, weil dein Kind manche Laute noch nicht richtig aussprechen kann? Schließe die beängstigenden Internetforen. Frage Anacan AI nach den Meilensteinen der Sprachentwicklung im Alter von etwa 38 Monaten und erhalte eine wissenschaftlich fundierte und realistische Antwort.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'Du bist das Kind, ich bin die Mama 👩‍👧', 'Das Rollentausch-Spiel beginnt! Dein Kind gibt dir Anweisungen wie: „Komm her, iss dein Essen, weine nicht.“ Lass dich mit Freude auf diese erste Führungserfahrung ein und spiele widerspruchslos sein Kind. Das ist eine der wichtigsten Grundlagen für die Entwicklung von Empathie.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin wird besonders gut in einer dunklen, technikfreien Umgebung ausgeschüttet.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'Theater vor dem Spiegel 🎭', 'Schon früh am Morgen stellt sich dein Kind vor den Spiegel und übt verschiedene Gesichtsausdrücke beim Weinen, Lachen und Staunen. So entdeckt es, wie es seine Gefühle ausdrücken kann und wie sich dabei sein Gesicht verändert. Beobachte diese geniale schauspielerische Darbietung lächelnd aus der Ferne.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'Papas magische Arme 🫂', 'Vom vielen Tragen tun dir schon die Arme weh, doch dein Kind möchte immer noch auf den Arm. Ruf Papa! In Papas Armen zu fliegen, schenkt deinem Kind die gewünschte Aufmerksamkeit und deinen Armen die dringend benötigte Erholung.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'Kein Müll, sondern Kunst 🎨', 'Mitten im Zimmer hat dein Kind aus kleinen Papierschnipseln und abgeschnittenen Fäden ein großes Kunstwerk geschaffen – und du darfst es auf keinen Fall wegwerfen. Lass deinen Perfektionismus beim Aufräumen kurz beiseite. Respektiere das kreative Chaos – aufräumen kannst du auch morgen noch.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', 'Die „Ich kann das allein!“-Phase 🛑', 'Dein Kind möchte seine Schnürsenkel selbst binden, obwohl ihr schon 10 Minuten zu spät dran seid. Dränge es nicht. Für seine Entwicklung ist ein unversehrtes Selbstvertrauen wichtiger als ein durcheinandergeratener Zeitplan. Lass es versuchen.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'Geflüsterte Geschichten 🌙', 'Du hast heute schon so viel geredet, dass deine Stimme und deine Lunge müde sind. Schalte das Licht aus, leg dich neben dein Kind und flüstere ihm ins Ohr, was ihr im Laufe des Tages erlebt habt. Das Flüstern bündelt seine Aufmerksamkeit und stimmt sein Gehirn auf beinahe hypnotische Weise auf einen tiefen Schlaf ein.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'Der Mythos von der perfekten Mutter 🛑', 'Die Kinder in den sozialen Medien können Farben und Zahlen schon auf Englisch aufsagen, aber dein Kind möchte das nicht? Hör sofort auf, zu vergleichen! Jedes Kind hat sein ganz eigenes Entwicklungstempo. Dein Kind ist genau richtig, so wie es sich in seinem eigenen Tempo entwickelt.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'Ist der Mittagsschlaf vorbei? ⏱️', 'Dauert das Einschlafen am Abend länger als 1 Stunde? Wirf einen Blick auf den Schlafrhythmus. In der turbulenten Phase um den 3. Geburtstag kann es an der Zeit sein, den Mittagsschlaf ganz wegzulassen und die Schlafenszeit am Abend vorzuverlegen.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'Die endlosen Warum-Fragen 🌪️', 'Warum können Fische nicht laufen? Wo ist die Sonne hin? Schon früh am Morgen sucht das Gehirn deines Kindes mit 100 Fragen pro Stunde nach Antworten auf die großen Rätsel des Lebens. Auch wenn du müde wirst, antworte kurz und verständlich. Dein Kind entdeckt die Geheimnisse des Universums durch deine Worte und deinen Tonfall.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'Heute darf’s richtig dreckig werden 🏖️', 'Dein Baby möchte mit Matsch und Sand spielen? Dann lass es ruhig schmutzig werden! Entdecke unter den empfohlenen Produkten leicht zu reinigendes Zubehör für diese Aktivitäten, die die sensorische Entwicklung fördern, und lass dein Baby nach Herzenslust spielen.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'Kampf gegen den Schatten 👻', 'Dein Baby fürchtet sich vor seinem Schatten an der Wand und versteckt sich hinter dir? Seine Fantasie kennt keine Grenzen. Verdunkle das Zimmer und zaubere mit einer Taschenlampe und deinen Händen lustige Schattenspiele an die Wand.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'Mit Musik sanft in den Schlaf 🎶', 'Versuche, scheinbar grundlose Wutanfälle am Abend mit sanfter klassischer Musik zu beruhigen. Dieser einfache, aber wirkungsvolle Trick wirkt zu Hause oft Wunder und bringt eine wohltuende Ruhe ins Zimmer.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'Der Hilferuf deines Körpers 🩸', 'Lass dich nicht von scheinbar grundloser Gereiztheit und Müdigkeit überwältigen. Wirf einen Blick in den Periodentracker – dein Körper sendet dir Signale. Statt dir Vorwürfe zu machen, gönn dir Ruhe und einen magnesiumreichen Snack.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'Wörter absichtlich verdrehen 🗣️', 'Dein Kind verdreht hartnäckig ein Wort und wartet darauf, dass du darüber lachst? Es entdeckt gerade seinen Sinn für Humor. Lach ruhig mit, aber sprich das Wort jedes Mal auch sanft und richtig aus, damit sich die korrekte Aussprache ebenfalls im Gehirn einprägt.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'Mama, vergiss dich selbst nicht 🥗', 'Du hast Eier auf 4 verschiedene Arten zubereitet, damit dein Baby etwas isst – aber was hast du gegessen? Belohne dich mit einem besonderen, eisen- und kalziumreichen Gericht aus unseren gesunden Rezepten, das in nur 5 Minuten fertig ist, und bewahre deine Energie.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'Taktiken zum Hinauszögern der Schlafenszeit ⏱️', 'Bekommt dein Kind zur Schlafenszeit plötzlich Durst, muss auf die Toilette oder möchte sich sogar von der Wand verabschieden? Stell einen Timer. Führt die Regel „Wenn der Wecker klingelt, gehen alle schlafen“ ein und beendet dieses endlose Abschiedsritual geduldig und gelassen.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'Besprechung mit den Spielsachen 🧸', 'Dein Kind stellt all seine Teddys und Autos in einer Reihe auf und erklärt ihnen mit erhobenem Zeigefinger sehr ernst etwas? Dabei entwickeln sich Führungsqualitäten und Konzentrationsfähigkeit. Stell dich an den Rand des Zimmers und beobachte diese Fantasiebesprechung still, ohne zu stören.'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'Papas seltsame Geräusche 🤡', 'Wenn deine Tricks nicht mehr funktionieren, retten Papas seltsame Tiergeräusche und lustige Grimassen sofort die Situation. Überlass ihm bei abendlichen Krisen das Feld und genieße das fröhliche Lachen aus der Ferne.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'Aufstand gegen den Mittagsschlaf 🥱', 'Dein Kind will nicht ins Bett und weint? Zwinge es nicht. Dimme das Licht im Zimmer und führe eine ruhige Bücherstunde ein. So entsteht eine neue Routine, bei der ihr beide zur Ruhe kommen könnt.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'Gedanken über die Kita 🏫', 'Hast du das Gefühl, dass dein Kind inzwischen mehr soziale Kontakte braucht? Ist jetzt der richtige Zeitpunkt für die Kita? Tritt der Anacan-Community bei und lies die echten Eingewöhnungserfahrungen anderer Mütter, um dir die Entscheidung zu erleichtern.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'Plötzlicher Wutanfall 💥', 'Ist dein Kind beim Spielen plötzlich wütend geworden und hat seine Spielsachen herumgeworfen? Es kann seine Gefühle noch nicht selbst regulieren. Statt zu schimpfen, zeige Einfühlungsvermögen, bleib in seiner Nähe und sage: „Ich sehe, dass du wütend bist. Komm, wir atmen gemeinsam tief durch.“'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'Wird dein Kind unruhig, wenn im Schlafzimmer das Licht ausgeht? 🌙', 'Stelle in eine Ecke des Zimmers ein kleines Nachtlicht mit warmem Licht. Der restliche Raum sollte für einen tiefen Schlaf jedoch vollständig dunkel bleiben.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'Gespräche mit leblosen Gegenständen 🗣️', 'Dein Kind erzählt einem Stein im Park oder einem Stuhl zu Hause völlig ernst etwas und schimpft sogar mit ihm. Durch symbolisches Spielen verarbeitet es die Welt. Halte diese besonderen Spielszenarien unbedingt im Entwicklungstracker fest.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'Das Wunder des warmen Wassers 🛀', 'Manchmal hilft einfach nichts und dein Kind weint wegen allem. Setze es in eine Badewanne mit lauwarmem Wasser und gib etwas Badeschaum hinzu. Die fast magische, entspannende Kraft des Wassers kann sofort Ruhe in den ganzen Raum und sein Nervensystem bringen.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'Wetterhinweis ⛅', 'Lass dich vor einem Spaziergang nicht vom Blick aus dem Fenster täuschen. Nutze den Wetter- und Kleidungsassistenten, um ein passendes Outfit für die tatsächliche Temperatur und den Wind draußen auszuwählen. So könnt ihr entspannt und gut vorbereitet das Haus verlassen und dein Kind kann sich an der frischen Luft austoben.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'Kleine Zeichentrickkritikerin, kleiner Zeichentrickkritiker 📺', 'Dein Kind erzählt dir in seiner eigenen Sprache von dem Zeichentrickfilm, den es gesehen hat, und erklärt ganz ernst, wer wohin gegangen ist. Höre aufmerksam und mit sichtbarem Staunen zu. Lass dein Kind sich wie der klügste Mensch der Welt fühlen.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'Perfektion gibt es nicht 🛑', 'Heute ist nichts nach Plan gelaufen? Mach dir keine Vorwürfe. Du bist eine echte Mutter und keine gefilterte Illusion aus den sozialen Medien. Dein Kind braucht einfach nur dein Lächeln und deine Umarmung.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'Nächtlichen Schrecken entschlüsseln 😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert auf niemanden. Überprüfe es mithilfe der Schreianalyse. Wenn es sich um Nachtschreck handelt, versuche nicht, dein Kind zu wecken. Bleib einfach bei ihm und vermittle ihm still ein Gefühl von Sicherheit.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'Einfach nur kuscheln 🫂', 'Du brauchst weder ein Spiel noch ein Buch oder eine Geschichte. Drück dein Kind heute Abend einfach an deine Brust, atme seinen wunderbaren Duft ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'Verbotene Wörter 🤐', 'Dein Kind wiederholt lachend ein Schimpfwort, das es irgendwo gehört hat, und wartet auf deine Reaktion? Deine stärkste Waffe ist, gar nicht darauf zu reagieren. Lache nicht, werde nicht wütend, sondern ignoriere es einfach. Dein Kind wird das Wort bald wieder vergessen.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'Erlaubnis für ein unordentliches Zuhause 🌪️', 'Bist du es leid, jeden Tag dieselben Spielsachen aufzuräumen? Dann räum heute einfach nicht auf! Dein Zuhause ist kein Museum, sondern ein Ort voller Leben. Konzentriere dich nicht auf die Unordnung, sondern auf die Freude deines Kindes am freien Entdecken – und gönn dir eine Pause.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'Schau nach unten: Was entdeckt dein Kind? 👣', 'Dein Kind genießt es, barfuß zu laufen und den Teppich oder die Bodenfliesen im Zimmer zu spüren. Die Stimulation der Nerven in den Fußsohlen ist für sein Gleichgewicht und seine motorische Entwicklung sehr wichtig. Lass dein Kind deshalb ruhig ohne Socken laufen.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661'::uuid, 'Zeit für euch als Paar 🥂', 'Das Kind schläft. Lass jetzt die Hausarbeit liegen. Sprich mindestens 20 Minuten mit deinem Partner oder deiner Partnerin über etwas anderes als das Kind und die Ausgaben. Ihr seid schließlich auch ein Paar!'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'Dein Einkaufsretter 🛒', 'Vergisst du beim Einkaufen ausgerechnet immer das Wichtigste? Die Einkaufsliste in der App wartet schon auf dich. Trag dort alles ein, was ihr braucht, damit dein Partner es auf dem Heimweg von der Arbeit gezielt besorgen kann – und du dir nicht den Kopf zerbrechen musst.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'Dampf ablassen im Tagebuch 📝', 'Hat dir jemand gesagt: „Du bist doch zu Hause, wovon bist du denn müde?“ Öffne sofort das Stimmungstagebuch und tippe dir deinen ganzen Ärger von der Seele. Deine wahren Gefühle aufzuschreiben, ist heilsamer, als ein Lächeln vorzutäuschen.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'Ich erklär''s dir! ☝️', 'Dein Kind erklärt dir mit ernster Miene und ganz wichtig etwas, das du längst weißt. So testet es sein Wissen. Auch wenn du dich zusammenreißen musst, um nicht zu lachen: Hör aufmerksam und ganz ernst zu und bestätige seine Gedanken.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'Stille digital gemessen 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich im Haus ausbreitet, kaum glauben. Aktiviere den Schallpegelmesser und spüre beim Anblick der 0-10 Dezibel auf dem Display, wie dein Kopf langsam zur Ruhe kommt.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'Wettercheck ⛅', 'Du bist dir nicht sicher, wie das Wetter draußen ist? Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und empfiehlt das passende Outfit.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'Zieht die eigenen Schuhe aus 👟', 'Ist das Anziehen inzwischen zu einem Ringkampf geworden? Dein Kind zieht seine Socken und Schuhe schon selbst aus. Staune über seine motorischen Fähigkeiten!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'Unterstützung vom Papa 🫂', 'Wechselt euch beim nächtlichen Aufstehen ab: einmal du, einmal dein Partner. Teilt euch die Belastung als Team genau zur Hälfte.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'Der Schlafverzögerungs-Toilettengang 🚽', 'Kurz bevor dein Kind einschläft, heißt es plötzlich: „Ich muss aufs Klo!“ Du gehst mit – doch es kommt nichts. Das ist eine der raffiniertesten Taktiken, um das Schlafengehen hinauszuzögern. Schimpf nicht, sondern setze eine klare Grenze: „Wir gehen jetzt ein letztes Mal und danach direkt zurück ins Bett.“'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'Bei wählerischem Essen gibt es keine Logik. 🥦', 'Bis gestern hat dein Kind diese Suppe noch genüsslich gegessen, und heute rührt es sie nicht einmal an? Schau dir die gesunden Rezepte an und entdecke, wie du püriertes Gemüse in bunten Pastasoßen verstecken kannst. Meistere die Kunst des Tarnens.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'Unterwasserreich 🛀', 'Baden dient jetzt nicht mehr nur der Sauberkeit, sondern ist eine U-Boot-Mission. Lass das Wasser ruhig in alle Richtungen spritzen. Die magische Wirkung des Wassers spült all die hartnäckige, negative Energie, die sich im Laufe des Tages angestaut hat, einfach in den Abfluss.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'Genialer Erfinder 👟', 'Dein Kind hält sich einen Schuh ans Ohr und führt ganz ernst ein Gespräch mit einem Hallo. Es erfindet neue Funktionen für Gegenstände! Lass dir diesen absurden und genialen Moment nicht entgehen. Halte den kleinen, lustigen Erfinder bei einem Baby-Fotoshooting fest und gib dem Bild einen Ehrenplatz in deinem Fotoarchiv.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'Digitale Stille-Therapie 🤫', 'Endlich herrscht im Zimmer vollkommene Stille. Beeil dich nicht, die Spülmaschine einzuräumen. Aktiviere den Schallpegelmesser, beobachte, wie die Anzeige auf 0 Dezibel sinkt, und spüre, wie dein müdes Gehirn zur Ruhe kommt.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'Künstlerisches Konfetti-Chaos ✂️', 'Dein Kind zerreißt jedes Blatt Papier, das ihm in die Hände fällt, in tausend kleine Stücke und verteilt sie im ganzen Zimmer? Dabei trainiert es seine Feinmotorik! Werde nicht wütend und greif nicht gleich zum Besen. Sammelt die Schnipsel in einer Schachtel und lasst es anschließend schneien.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'Der Rivale im Spiegel 🪞', 'Dein Kind steht vor dem Spiegel, zieht die Augenbrauen zusammen und macht wütende und seltsame Grimassen. Es testet, wie verschiedene Gefühle im Gesicht aussehen. Beobachte ganz still und fasziniert die Probe dieses kleinen Theaterschauspielers.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'Sehnsucht nach dem Alleinsein 🚪', 'Du bist erschöpft von deinem Kind, das den ganzen Tag an dir hochklettert und an dir klebt. Du gehst zur Toilette, schließt die Tür und bist 5 Minuten lang allein. Öffne sofort das Stimmungstagebuch, lass all deine angestauten Gefühle auf den Bildschirm fließen und atme erleichtert auf.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'Regisseur der Geschichte 🪄', 'Heute Abend ist deine Stimme müde. Öffne die intelligenten Märchen. Sag deinem Kind: Heute bist du der Held, und im Hintergrund regnet es. Erschaffe so eine besondere, beruhigende und personalisierte Klangwelt und begleite dein Kind sanft in den Schlaf.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'Bettwanderer 🛏️', 'Dein Baby beginnt die Nacht im eigenen Bett und wacht morgens in eurem Bett auf – natürlich quer ausgestreckt und mit den Füßen in deinem Gesicht. Nimm diese Eroberung eures Bettes mit Humor. Dein vertrauter, warmer Geruch ist seine größte Geborgenheitszone.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'Der Zauber des Kartons 📦', 'Es hat das teure, lärmende Spielzeug, das du gekauft hast, beiseitegelegt und spielt seit 1 Stunde mit der Verpackung? Das kindliche Gehirn liebt keine fertigen Spielideen, sondern leere Gegenstände, die es mit Fantasie füllen kann. Für dein Kind ist der Karton ein Raumschiff – lass ihn einfach stehen.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'Sommerrebellion im Winter ❄️', 'Draußen weht ein kalter Wind, aber dein Kind besteht darauf, seine Sommershorts anzuziehen. Lange Erklärungen bringen jetzt nichts. Öffne das Wetter- und Kleidungs-Tool und zeige ihm das dick angezogene Kindersymbol auf dem Bildschirm. Der Trick „Schau, sogar das Handy sagt, dass wir heute eine lange Hose anziehen müssen“ funktioniert wunderbar.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'Der Biss ins Unsichtbare 🍏', 'Dein Kind hat nichts in der Hand, kommt aber zu dir und reicht dir mit den Worten „Hier, beiß ab“ einen imaginären Apfel. Rollenspiele sind für die Persönlichkeitsentwicklung besonders wichtig. Beiß mit großem Appetit und einem lauten „Knack“ in die Luft und bestätige, dass dies der leckerste Apfel der Welt ist.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'Das Monster am Fenster 👻', 'Der Schatten eines Baumes, der sich draußen im Wind wiegt, fällt ins Zimmer, und dein Kind bekommt Angst und versteckt sich hinter dir. Schalte nicht gleich das Zimmerlicht ein. Nimm eine Taschenlampe, leuchte auf den Schatten und sage: „Schau, das ist nur der Baum, der tanzt.“ So verwandelst du die Angst in Magie.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', 'Der „Schau mich an!“-Marathon 👀', 'Hat dein Kind gleich nach dem Aufwachen ganze 40 Mal „Mama, schau mich an!“ gesagt? Es hüpft und dreht sich und möchte deine Bestätigung. Lege das Handy weg, schenke ihm einfach 3 Minuten lang deine ungeteilte Aufmerksamkeit und sage: „Du bist großartig!“ Diese ununterbrochene Aufmerksamkeit wird ausreichen, um sein Bedürfnis nach Nähe zu stillen.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'Mamas Recht auf Faulheit 🍕', 'Könntest du heute wegen allem losschreien? Herrscht zu Hause das reinste Chaos? Lass das Putzen sein und bleib der Küche fern. Bestell eine Pizza oder etwas anderes Einfaches. Verabschiede dich von der Illusion der perfekten Mutter – deine seelische Gesundheit ist viel wertvoller als eine selbst gekochte Mahlzeit.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'Paar-Koma 📺', 'Das Kind schläft! Endlich sitzt ihr gemeinsam auf dem Sofa und wollt einen Film schauen, doch nach 10 Minuten seid ihr beide eingeschlafen. So sieht eure Realität aus. Dieses erschöpfte, aber wunderschöne Bild, wie ihr aneinandergelehnt schlaft, ist Liebe in ihrer reinsten Form.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'Der erste unsinnige Witz 🤡', '„Der Hund stieg ins Auto und explodierte!“, sagt dein Kind und lacht sich darüber kaputt. Das ergibt zwar keinen Sinn, aber es entdeckt gerade erst seinen Sinn für Humor. Suche nicht nach Logik, sondern stimme einfach laut in dieses unschuldige, fröhliche Lachen ein.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'Politik auf der Rutsche 🛝', 'Dein Kind steht oben auf der Rutsche und lässt die anderen Kinder nicht rutschen. Zieh es nicht aus Scham grob herunter. Lass dich von den Blicken der anderen nicht beirren und erinnere es mit sanfter Stimme daran, dass alle der Reihe nach dran sind. So verteidigt es sein Gefühl von Besitz.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'Es ist kein Baby mehr! 🌟', 'Dein Kind ist jetzt ein eigenständiger Mensch mit eigenen Entscheidungen, seltsamen Fragen und einem riesengroßen Herzen. Danke dir selbst dafür, dass du seinen starken Charakter nicht brichst, sondern es liebevoll begleitest und ihm Orientierung gibst. Du machst das großartig.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'Ein Sieg ohne Champagner 🥂', 'Schenkt euch nach einem anstrengenden Tag einfach warmen Tee in die Gläser. Setzt euch auf dem Sofa einander gegenüber, stoßt an und sagt: „Auch dieses Chaos haben wir heute überlebt.“ Ihr seid sowohl die Befehlshaber als auch das Team eures Zuhauses.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'Die Kraft der Gemeinschaft 💬', 'Der Gedanke „Warum ist mein Kind nur so stur?“ lässt dir keine Ruhe. Schau in der Anacan-Community vorbei. Wenn du von ähnlich absurden Wutanfällen bei anderen Müttern zu Hause liest, wirst du erkennen, dass du nicht allein und auf einem völlig normalen Weg bist.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'Der Rhythmus des Lichts 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. In einer dunklen, technikfreien Umgebung wird Melatonin schneller ausgeschüttet und erleichtert so das Einschlafen.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'Das Frühstück des Dinosauriers 🦖', 'Beim Frühstück möchte dein Kind wie ein Dinosaurier essen: ohne die Hände zu benutzen und mit dem Mund direkt zum Teller. Jetzt ist nicht der Moment für eine Lektion in Tischmanieren! Lass es 5 Minuten lang ein Dinosaurier sein. Bald wird ihm das Spiel langweilig, und es greift ganz von selbst zum Löffel.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', '„Ich mache das selbst“-Tempo 🐢', 'Ihr müsst aus dem Haus, aber dein Kind will seine Schuhe unbedingt selbst anziehen – und das dauert im Schneckentempo 15 Minuten. Wenn du eingreifst, dauert der anschließende Wutanfall 30 Minuten. Konzentriere dich nicht auf die verlorene Zeit, sondern auf sein unversehrtes Selbstwertgefühl, und warte geduldig.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'Die verschwundenen Schlüssel 🔑', 'Du findest deine Hausschlüssel nicht? Schau im Kühlschrank oder im Schuhschrank nach. Dein Kind versteckt Dinge, um zu testen, ob sie weiterexistieren, auch wenn es sie nicht sieht. Entscheide dich bei dieser lustigen Schatzsuche fürs Lachen statt fürs Ärgern.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'Die Hypnose des Flüsterns 🤫', 'Dein Kind liegt im Bett, streckt die Beine in die Luft und will nicht einschlafen. Statt laut zu werden, senke plötzlich deine Stimme und sprich nur noch flüsternd mit ihm. Sobald es sich konzentriert, um dich zu verstehen, schaltet sein Gehirn wie von selbst in den Schlafmodus.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'Eine Pause für deine Arme 🫂', 'Dein Körper schmerzt, weil dein Kind den ganzen Tag an dir hochklettert und auf den Arm möchte. Übergib am Abend den Staffelstab an Papa. Wenn er das Kind auf den Rücken nimmt und mit ihm Pferdchen spielt, bekommt es die gewünschte Aufmerksamkeit und deine Arme ihre wohlverdiente Pause.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'Das Morgenkonzert 🎤', 'Die Sonne ist noch nicht ganz aufgegangen, aber dein Kind hüpft schon im Bett herum und singt laut in einer Sprache, die du nicht verstehst. Ja, du bist noch müde, doch diese Lebensfreude, die durchs Zimmer wirbelt, wird auch dich aus dem Bett holen. Lächle einfach, wenn du seine Stimme hörst.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'Künstliche Intelligenz als Retterin 🤖', '„Mama, wo geht die Sonne schlafen?“ Hat dich diese Frage sprachlos gemacht? Mach die Erklärung nicht unnötig kompliziert. Stelle Anacan AI diese Frage, gib das Alter deines Kindes an und erzähle ihm anschließend die wunderbare, wie eine Geschichte formulierte Antwort, die ein dreijähriges Kind leicht verstehen kann.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'Stille Tränen 💖', 'Dein Kind hat dich den ganzen Tag in den Wahnsinn getrieben. Doch jetzt schläft es so unschuldig in seinem Bett, dass dir beim Anblick die Tränen kommen, oder? Genau das ist das größte Paradox des Mutterseins. Diese eine Träne ist Ausdruck deiner Dankbarkeit dafür, dass es dein Kind gibt.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'Geheime Lebensmittelmission 🥣', 'Bis gestern hat dein Kind Eier geliebt, heute bekommst du keinen einzigen Bissen in seinen Mund. Kämpfe nicht gegen seinen Willen an. Probiere raffinierte, gesunde Snackrezepte aus, in denen proteinreiche Zutaten anders, bunt und spannend präsentiert werden – und geh als Gewinnerin aus der Situation hervor.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'Wenn die Logik versagt 🛑', 'Dein Kind schreit, weil es sein Wasser im roten Becher haben möchte. Du füllst es in den roten Becher, und nun weint es, weil du es ausgerechnet dort hineingegossen hast. Hier gibt es keine Logik. Es ist einfach müde und muss seinen Gefühlen freien Lauf lassen. Warte ruhig ab – der Sturm wird sich von selbst legen.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'Eine plötzliche Liebeserklärung 🥰', 'Mitten im Spielen wirft dein Kind sein Spielzeug hin, läuft zu dir, schlingt die Arme um deinen Hals und sagt: „Ich liebe dich.“ Genau das ist der Zauber, der all die Erschöpfung und den Schlafmangel vergessen lässt. Drück dein Kind fest an deine Brust und atme seinen Duft tief ein.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'Papas seltsames Märchen 📖', 'Heute Abend ist deine Stimme müde. Überlass Papa das Vorlesen. Er wird sich zu den Bildern im Buch eine völlig andere, fantasievolle und lustige Geschichte ausdenken und euer Kind zum Lachen bringen. Und du kannst das Ganze gemütlich mit einer Tasse Tee von der Seite genießen.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'Wirbel um den Einkaufswagen 🛒', 'Obwohl der große Einkaufswagen größer ist als dein Kind, will es ihn unbedingt selbst schieben. Bevor es mitten im Supermarkt Tränen gibt, lass seine Hände am Wagen und lenke ihn unauffällig in die richtige Richtung.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'Freiheit im verkehrt angezogenen Outfit 👗', 'Dein Kind hat die Hose verkehrt herum angezogen und verkündet ganz entschlossen: „Das habe ich selbst gemacht!“ Vergiss die Optik. Sein wachsendes Selbstvertrauen und das Gefühl von Selbstständigkeit sind viel wichtiger als der richtige Sitz der Kleidung. Sei stolz auf deinen kleinen Rebellen.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'Kaffee mitten im Chaos ☕', 'Mitten im Zimmer hat dein Kind all seine Spielsachen verteilt und baut daraus eine Burg. Sobald du das Chaos aufräumst, wird alles wieder auseinandergerissen. Gib den Kampf also auf, setz dich mit deinem noch heißen Kaffee in eine Ecke des Zimmers und betrachte das Chaos ganz entspannt aus der Ferne.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'Schatten im Kinderzimmer 🐰', 'Hat dein Kind angefangen, sich vor der Dunkelheit zu fürchten? Verdunkle das Zimmer vollständig und zaubere mit einer kleinen Taschenlampe Lichtspiele und Tierschatten an die Decke. So wird die gefürchtete Dunkelheit zu einem kleinen Abenteuer vor dem Schlafengehen, bei dem ihr gemeinsam lachen könnt.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'Hoffnung auf eine ungestörte Nacht 🤞', 'Dein Kind schläft und im Haus ist tiefe Stille eingekehrt. Dein größter Wunsch ist, dass es heute Nacht nicht aufwacht. Spiele das sanfte Waldrauschen als Hintergrundgeräusch des Geräuschmessers leise ab, damit dein Kind möglichst lange in der Tiefschlafphase bleibt.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'Das Naturlabor 🍂', 'Dir fällt zu Hause die Decke auf den Kopf und dein Kind ist unruhig. Prüfe das Wetter, zieht euch passend an und geht unbedingt nach draußen. Macht es euch zur Aufgabe, trockene Zweige und Blätter zu sammeln. So kann dein Kind seine Energie loswerden und du kommst aus den eigenen vier Wänden heraus und kannst wieder durchatmen.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'Mama der Kuscheltiere 🧸', 'Aus dem Zimmer sind Geräusche zu hören. Du lauschst genauer – und dein Kind schimpft mit seinem Teddybären, genau in deinem Tonfall und mit deinen Sätzen! Es ist deine beste Kopie. Eine perfekte Gelegenheit, dein eigenes Verhalten einmal von außen zu betrachten.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'Das unteilbare Frühstück 🍳', 'Von seinem eigenen Teller gibt dein Kind dir auf keinen Fall etwas ab, besteht aber darauf, von dem Ei auf deinem Teller zu essen. Kinder vertrauen der Wahl ihrer Eltern einfach mehr. Kämpfe nicht dagegen an – überlasse diesem kleinen Egoisten deinen Bissen mit viel Liebe.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'Katastrophe ohne Einkaufsliste 🛒', 'Du hast dich auf dein Gedächtnis verlassen, kommst nach Hause und stellst fest, dass du ausgerechnet die für dein Kind so wichtige Milch vergessen hast. Dein Kopf ist ohnehin schon voll genug. Gewöhne dir an, Dinge sofort in die Einkaufsliste der App einzutragen, sobald du merkst, dass du sie brauchst – so ersparst du dir unnötigen Stress.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'Der Ozean in der Badewanne 🌊', 'Beim Baden geht es längst nicht mehr ums Sauberwerden, sondern darum, Wellen zu schlagen. Lass das Wasser ruhig herumspritzen. Seine magnetische Wirkung spült die hartnäckige negative Energie fort, die sich im Laufe des Tages in deinem Kind angestaut hat, und lässt es tiefer schlafen.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'Du bist perfekt 🛑', 'Machst du dir Vorwürfe, wenn du in sozialen Netzwerken Mütter siehst, die jeden Tag mit ihren Kindern Kunstwerke erschaffen und deren Zuhause immer makellos glänzt? Glaub diesen Filtern nicht. Dein chaotisches, lautes und echtes Zuhause ist für dein Kind das wärmste und vollkommenste Nest voller Liebe.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'Das Argument des kleinen Anwalts 🗣️', '„Ich darf Schokolade essen, weil ich schon groß bin.“ Dein Kind erkennt bereits Ursache und Wirkung und versucht, mit dir zu verhandeln! Seine Sprachentwicklung macht tolle Fortschritte. Lobe es dafür, aber halte zugleich liebevoll an deinen Grenzen und Regeln fest.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'Stille als Therapie 🤫', 'Endlich ist dein Kind eingeschlafen! Aktiviere den Schallpegelmesser und beobachte, wie die Anzeige auf dem Bildschirm bis auf 0 Dezibel sinkt. Spüre dabei, wie dein müdes Gehirn zur Ruhe kommt und diese sichtbare Stille dich sanft entspannt.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'Küchenchaos 🧑‍🍳', 'Während du den Teig ausrollst, kommt dein Kind dazu, greift mitten ins Mehl und verteilt es überall. Ja, die Küche ist verwüstet und du hast noch mehr Arbeit. Aber halte seinen ernsten, geschäftigen Gesichtsausdruck sofort mit dem Baby-Fotoshooting fest. Das Chaos verschwindet, diese Erinnerung bleibt.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'Sei stolz auf dich 🚀', 'Wenn du zurückblickst, siehst du, was für eine starke Persönlichkeit dein Kind geworden ist. Nimm dir heute Zeit, es ganz in Ruhe anzusehen, und sei stolz auf dich, weil du einen so wunderbaren Menschen großgezogen hast.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'Ein Dankeschön ans Team 🥂', 'Ihr habt einen weiteren schwierigen und turbulenten Tag gemeistert. Wenn euer Kind eingeschlafen ist, setzt euch bei einer Tasse Tee zusammen und sagt zueinander: „Du hast mir heute sehr geholfen, danke.“ Elternsein wird schöner, wenn man es nicht allein, sondern als starkes Team meistert.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'Erste Zeichen von Empathie 🧸', 'Streichelt dein Kind sein Spielzeug, wenn es herunterfällt, und sagt: „Nicht weinen“? Dann entwickelt es gerade Empathie! Halte diese süße Phase unbedingt im Entwicklungs-Tracker fest.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'Kleidung verkehrt herum 👗', 'Will dein Kind das Oberteil in seiner Hand unbedingt verkehrt herum anziehen? Kämpfe nicht dagegen an. Lass es ruhig einen Tag lang so zu Hause herumlaufen, statt seinen Willen zu brechen.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'Wir sind ein Team! 💖', 'Setzt euch nach einem schwierigen Tag zusammen und redet offen über das, was euch belastet. Wenn ihr füreinander da seid, fühlt sich die Last gleich nur noch halb so schwer an.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'Bettdecken-Ingenieurskunst 🛏️', 'Dein Kind ist kurz davor einzuschlafen und fängt plötzlich an zu weinen: Die Ecke der Bettdecke ist umgeknickt! Für dein Kind ist es lebenswichtig, dass die Decke millimetergenau liegt. Atme tief durch, streiche die Decke glatt, als wäre sie frisch gebügelt, und lächle einfach über diesen amüsanten Perfektionismus.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'Verdächtige Stille 🤫', 'Plötzlich herrscht im Haus tiefe Stille. Das Schallmessgerät zeigt 0 Dezibel an. Wenn dein Kind still ist, findet irgendwo bestimmt gerade eine große Entdeckungsreise statt. Mach dich innerlich auf bemalte Wände oder zerschnittenes Papier gefasst, bevor du das Zimmer betrittst.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'Lass dich nicht auf eine Diskussion ein. 💼', '„Ich esse diesen Brei nicht, weil er gelb ist!“ Dein Kind argumentiert mit einer so überzeugenden, in sich schlüssigen absurden Logik, dass du dich beinahe schuldig fühlst. Lass dich nicht auf eine Diskussion ein. Überzeuge den kleinen Anwalt lieber mit den Worten: „Du hast recht, er ist gelb. Aber wie wäre es, wenn wir rote Beeren hineingeben?“'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', 'Die „Mama, schau mal!“-Phase 👀', 'Dein Kind springt vom Sofa und ruft jedes Mal, während es genau 50 Mal dieselbe Bewegung wiederholt: „Mama, schau mich an!“ Leg dein Handy beiseite. Es springt nicht wegen der Bewegung selbst, sondern wegen dieses bestätigenden Funkelns in deinen Augen. Schenk ihm 5 Minuten lang deine ungeteilte Aufmerksamkeit, damit es dieses Bedürfnis stillen kann.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'Musikalische Hypnose 🎶', 'Am späten Nachmittag beginnen scheinbar grundlose Gefühlsstürme und Weinanfälle. Schalte den Fernseher aus, dimme das Licht und lass ganz leise klassische Musik im Raum erklingen. Die tiefen Klänge der Musik können die Atmosphäre wie von Zauberhand verändern und Ruhe in den Raum bringen.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'Drehbuchautor für Zeichentrickfilme 📺', 'Dein Kind erzählt dir die Handlung des Zeichentrickfilms, den es gesehen hat, so anders und zugleich so überzeugend, dass du ihm beinahe glaubst. Seine Fantasie entwickelt sich gerade prächtig.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'Mamas Reset-Knopf 🚪', 'Der Lärm dröhnt in deinem Kopf und du möchtest bei jeder Kleinigkeit losschreien. Öffne dein Stimmungstagebuch. Schreib dort ganz frei all deine Erschöpfung hinein. Diese kurze digitale Auszeit hilft dir, dich neu zu sammeln.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'Tanz mit der Dunkelheit 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin (das Schlafhormon) wird bei Dunkelheit und ohne störendes Bildschirmlicht verstärkt ausgeschüttet und erleichtert so das Einschlafen.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'Der Schatz von der Straße 🍁', 'Dein Kind zeigt dir voller Freude einen schmutzigen Flaschendeckel oder einen ungewöhnlich gefärbten Stein, den es auf dem Boden gefunden hat – als hätte es Gold entdeckt. Statt zu sagen: „Wirf das weg, es ist schmutzig“, würdige seine Entdeckerfreude mit den Worten: „Was für eine ungewöhnliche Farbe! Komm, wir waschen es zu Hause ab.“'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'Die Philosophiestunde ist zurück 🤔', 'Warum weht der Wind? Warum fallen die Blätter? Schon am frühen Morgen bringen dich tiefgründige philosophische Fragen ins Grübeln. Mach deine Erklärung nicht unnötig kompliziert, sondern erzähl deinem Kind von der Natur in einer märchenhaften Sprache, die es verstehen kann. Der Klang deiner Stimme ist für dein Kind der sicherste Weg, das Universum zu begreifen.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'Konzert in der Küche 🥄', 'Dein Kind holt Töpfe und Holzlöffel hervor und veranstaltet mitten in der Küche ein Konzert. Auch wenn du davon Kopfschmerzen bekommst, entwickelt es dabei sein Rhythmusgefühl und seine Kreativität. Greif nicht sofort ein, sondern lass diese wilde Energie einige Minuten lang in Schallwellen durch den Raum strömen.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'Trost in der Community 💬', 'Der Gedanke „Warum ist mein Kind nur so stur?“ lässt dich innerlich nicht los. Schau in der Anacan Community vorbei. Wenn du von ähnlich absurden Wutanfällen bei anderen Müttern zu Hause liest, wirst du merken, dass du nicht allein bist und ein völlig normales, gesundes Kind großziehst.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'Sein warmer Atem 💖', 'Den ganzen Tag hat dein Baby dich in den Wahnsinn getrieben und wegen allem geweint. Doch jetzt liegt es im Bett eng an deine Brust gekuschelt und sein gleichmäßiger, warmer Atem erfüllt den Raum. Genau das ist die schönste Belohnung des Mutterseins. Drück dein Baby fest an dich und spüre, wie all die Müdigkeit mit jedem Atemzug verfliegt.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'Der Lohn der Teamarbeit 🥂', 'Ein weiterer schwieriger, turbulenter Tag liegt hinter euch. Wenn euer Kind eingeschlafen ist, schenkt euch gemeinsam eine Tasse Tee ein und sagt einander: „Auch dieses Chaos haben wir heute überstanden – wir sind ein großartiges Team.“ Elternsein wird nicht im Alleingang schön, sondern durch gegenseitige Unterstützung.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'Schuhe verkehrt herum 👟', 'Dein Kind hat die Schuhe vertauscht angezogen und läuft so stolz herum, als hätte es die Welt erobert. Wenn du eingreifst und sie richtig anziehen willst, ist die ganze Freude dahin. Selbstvertrauen und Selbstständigkeit sind wichtiger als ein perfektes Aussehen. Lass den kleinen Rebellen stolz weitermarschieren.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'Chaos in der Küche 🧑‍🍳', 'Während du den Teig ausrollst, greift dein Kind in das Mehl und verteilt es überall – plötzlich ist alles weiß. Ja, die Küche sieht chaotisch aus. Aber halte seinen ernsten, geschäftigen Gesichtsausdruck sofort mit dem Baby-Fotoshooting fest. Das Chaos lässt sich beseitigen, doch dieser lustige Schnappschuss bleibt für immer.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'Ein lebendiger Spiegel 🦜', 'Dein Kind schimpft mit seinem Spielzeug und ahmt dabei genau den Gesichtsausdruck nach, den du machst, wenn du dich ärgerst. So siehst du dich plötzlich von außen! Es ahmt nach, was es beobachtet. Dieser lustige, aber nachdenklich stimmende Anblick ist ein wunderbarer Spiegel, der dich daran erinnert, bewusster auf dein Verhalten zu achten.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'Ich im personalisierten Märchen 🪄', 'Du kennst die klassischen Kinderbücher schon auswendig und bist es leid, sie immer wieder vorzulesen. Öffne die personalisierten Märchen. Mach dein Kind zur Hauptfigur, wähle beruhigende Waldgeräusche als Hintergrund und erschaffe so ganz mühelos ein außergewöhnliches Einschlafritual.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'Frische Luft ⛅', 'Prüfe das Wetter, wähle die passende Kleidung und geh mit deinem Kind unbedingt nach draußen. Gebt euch einfach die Aufgabe, trockene Zweige und Steine zu sammeln. So kann dein Kind seine Energie loswerden, während du den eigenen vier Wänden entkommst und tief durchatmest.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'Papas Wasserschlacht 🛁', 'Heute Abend ist Papa ganz allein für das Baderitual zuständig. Lass die beiden nach Herzenslust mit Wasser spritzen, während du hinter der Tür die völlige Ruhe genießt.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'Kleiderrevolte 🥽', 'Dein Kind möchte zu Hause mit Schwimmbrille und Wintermütze herumlaufen. Es besteht darauf und will sie nicht abnehmen. Vergiss gesellschaftliche Konventionen. Lass es den Tag in dieser ungewöhnlichen, lustigen Kombination verbringen, damit du seine Kreativität und Entscheidungsfreiheit nicht einschränkst.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'Überraschung im Einkaufswagen 🛒', 'An der Kasse entdeckst du im Einkaufswagen 3 verschiedene Tafeln Schokolade und 1 seltsam geformte Seife, die du nicht ausgesucht hast. Lege die Sachen mit einem schnellen Handgriff zurück. Behalte außerdem immer deine Einkaufsliste im Blick, damit du nichts vergisst und nicht von deinem Plan abweichst.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'Hörgerät ausgeschaltet 🙉', 'Du sagst: „Räum die Spielsachen auf“ oder „Komm, wasch dir die Hände“, doch die Reaktion ist gleich null. So zu tun, als würde man nichts hören, gehört mit 3 Jahren zu den liebsten Hobbys. Statt zu schreien, geh zu deinem Kind und flüstere ihm ganz leise ins Ohr. Der plötzliche Wechsel deiner Stimmlage wird sofort seine Aufmerksamkeit wecken.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'Erpressung im Badezimmer 🛀', 'Beim Einsteigen hat dein Kind geweint, jetzt schreit es, weil es nicht mehr aus dem Wasser möchte. Die magnetische Wirkung des Wassers scheint es verzaubert zu haben. Kündige das Ende 3 Minuten vorher an und stelle einen Timer. Rituale wie „Wenn es klingelt, ist das Spiel vorbei“ funktionieren fast immer.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'Lebensmitteldesigner 🥦', 'Dein Kind sortiert das Essen auf dem Teller nach Farben und Formen und schiebt alles Grüne an den Tischrand. Werde bei der Essensplanung kreativ. Finde heraus, wie du das Gemüse zu einem unsichtbaren Püree verarbeiten und in Frikadellen oder Soßen verstecken kannst – so gewinnst du dieses Spiel.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'Chefarzt des Hauses 🩺', 'Dein Kind nimmt sein Spielzeugstethoskop, legt es auf deine Brust, zieht die Augenbrauen zusammen und sagt: „Nicht atmen.“ Du bist der folgsame Patient. Nutze dieses Rollenspiel als Gelegenheit: Schließe die Augen, lege dich während der 3-minütigen Untersuchung einfach auf den Boden und gönne deinem Rücken eine Pause.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'Papas Stimmbänder 📖', 'Heute ist deine Stimme müde und dein Hals trocken. Überlass Papa die Gutenachtgeschichte. Er wird anhand der Bilder im Buch eine völlig andere, lustige und frei erfundene Geschichte erzählen und euer Kind zum Lachen bringen. Du kannst diese schöne Szene währenddessen mit einer Tasse heißen Tee aus der Ferne genießen.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'Wanderung durchs Bett 🛏️', 'Abends schläft dein Kind in der richtigen Position ein und wacht morgens mit den Füßen auf dem Kissen und dem Kopf in der gegenüberliegenden Ecke des Bettes auf. Selbst im Schlaf erkundet es die Welt! Genieße diese lustige Wanderung durchs Bett, bevor du es weckst.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'Philosophische Einschlafverzögerung 🦉', 'Kaum liegt dein Kind im Bett, stellt es tiefgründige Fragen wie: „Mama, warum fallen die Sterne nicht herunter?“ Dabei geht es nicht darum, etwas über die Welt zu lernen, sondern das Einschlafen hinauszuzögern. Gib kurze, fantasievolle und liebevolle Antworten und lass dann mit den schlauen Gute-Nacht-Geschichten Ruhe im Kinderzimmer einkehren.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'Kleiner Held im Kostüm 🦸‍♂️', 'Dein Kind will zu Hause unbedingt Winterstiefel oder eine Superheldenmaske tragen? Vergiss gesellschaftliche Normen und ästhetische Ansprüche. So entdeckt es seine Persönlichkeit. Lass es mit seinen Stiefeln durchs Zimmer laufen und sich wie ein echter Held fühlen.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'Die Zähne des Dinosauriers 🦖', 'Dein Kind weigert sich vehement, seine Zähne zu putzen, und wirft die Zahnbürste weg. Mach ein Spiel daraus! Gib ihm eine zweite Zahnbürste und sage: „Komm, wir putzen zuerst die Zähne deines Spielzeug-Dinosauriers.“ Während dein Kind den Dinosaurier putzt, kannst du ihm ganz geschickt die Zähne putzen.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'Kleckern für die Selbstständigkeit 🥣', 'Dein Kind will seinen Joghurt unbedingt mit der Gabel essen und kleckert alles voll. Greif nicht ein und nimm ihm die Gabel nicht aus der Hand. Verschüttetes Essen lässt sich wegwischen, aber sein stolzes „Ich kann das allein“-Gefühl lässt sich nur schwer wiederherstellen. Zieh ihm ein Silikonlätzchen an und beobachte das Ganze geduldig.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', '10 Minuten für Mama 🚪', 'Der Lärm hat deinen Kopf völlig betäubt. Öffne dein Stimmungstagebuch und schreibe dir alles frei von der Seele, was dich heute wahnsinnig gemacht hat. So drückst du deinen inneren Reset-Knopf.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'Die Faszination der Mülltonne 📦', 'Obwohl es so viele teure, leuchtende Spielsachen gibt, beschäftigt sich dein Kind stundenlang mit einer leeren Plastikwasserflasche oder einem Karton. Die kindliche Fantasie liebt keine vorgefertigten Szenarien, sondern einfache Gegenstände, die Raum für Kreativität lassen. Schau zu und lerne davon.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'Revolution im Traumland ☁️', 'Kaum ist dein Kind morgens aufgewacht, runzelt es die Stirn und ist beleidigt auf dich. Der Grund? In seinem Traum hast du ihm nicht das gewünschte Spielzeug gegeben! Das kindliche Gehirn kann Träume und Wirklichkeit noch nicht vollständig voneinander unterscheiden. Entschuldige dich ganz ernst und schmunzle innerlich über diese absurde Situation.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'Stiller Blickwechsel 🥂', 'Das Kind ist endlich eingeschlafen. Du und dein Partner sitzt nebeneinander auf dem Sofa und habt nicht einmal mehr die Kraft zu reden. Ihr schaut euch einfach schweigend an und lächelt. Ja, dieser stille Blickwechsel ist die schönste Art zu sagen: Wir meistern dieses Chaos.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'Schattentheater an der Wand 🐰', 'Mit der Ausrede, dass es Angst im Dunkeln hat, flüchtet dein Kind aus dem Bett. Schaltet alle Lichter im Zimmer aus, nehmt eine Taschenlampe und formt mit euren Händen Vogel- und Hundeschatten an der Wand. So wird die Dunkelheit, vor der es sich fürchtet, innerhalb von Sekunden zum sichersten Theater der Welt.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'Taktik für den Abschied vom Park 🌳', 'Es ist Zeit, den Park zu verlassen, und schon beginnt der Weinanfall. Versuche nicht, dein Kind einfach mitzuschleifen. Mach einen Wettbewerb daraus und frage: „Mal sehen, wer schneller beim Auto ist?“ Kinder sagen zu einem Wettrennen und der Aussicht aufs Gewinnen fast nie Nein.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'Der unsichtbare Gast 👻', 'Beim Frühstück verlangt dein Kind, dass du auch für seinen imaginären Freund einen Teller auf den Tisch stellst. Das ist kein Zeichen einer seelischen Leere, sondern ein Entwicklungssprung seiner Fantasie und Intelligenz. Stell den Teller hin, schenke eurem Gast imaginären Tee ein und werde Teil dieses wunderbaren Theaters.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'Neue Wörter entdecken 🗣️', 'Dein Kind erfindet für Gegenstände völlig neue Namen, die es in keiner Sprache gibt. Und es besteht darauf, dass auch du diese Wörter verwendest! Öffne den Entwicklungstracker und halte diese lustigen Wortschöpfungen unbedingt fest, damit ihr sie später lesen und gemeinsam darüber lachen könnt.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'Die geheimen Schätze des Hauses 🔑', 'Du findest den Haus- oder Autoschlüssel oder die Fernbedienung nicht? Dann schau im Spielzeugofen oder unter dem Bett deines Kindes nach. Indem es Dinge versteckt, testet es, wie die Welt funktioniert. Entscheide dich bei dieser lustigen Schatzsuche fürs Lachen und tiefe Durchatmen statt fürs Ärgern.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'Das Badeparadox 🛀', 'Gerade hat dein Kind noch geweint, weil es nicht in die Badewanne wollte, und jetzt schreit es, weil es nicht mehr herauskommen möchte! Die magische, beruhigende Wirkung des Wassers hat es wie hypnotisiert. Damit das Ende des Bades nicht zum Drama wird, nenne das Handtuch eine „warme Umarmung“, wickle dein Kind darin ein und hole es aus der Wanne.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'Der „Meins!“-Trotz 🧸', 'Dein Kind umklammert irgendeinen beliebigen Gegenstand im Haus, ruft „Das gehört mir!“ und gibt ihn niemandem. Es entdeckt gerade die Grenzen von Besitz. Wirf ihm keinen Egoismus vor, sondern überlasse ihm den Gegenstand einfach für diesen Moment.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'Die Klangfarbe deiner Stimme 🌙', 'Dein Kind hört nicht auf die Handlung des Märchens im Buch, sondern auf deinen Tonfall. Vergiss heute Abend die Handlung. Zieh die Geschichte in die Länge und lies sie mit sanfter, leiser Stimme wie eine ruhige Melodie vor. So sendest du seinem Nervensystem ein direktes Schlafsignal.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'Die Social-Media-Illusion 📱', 'Du siehst im Internet all die perfekten Mütter und machst dir wegen der Unordnung bei dir zu Hause Vorwürfe? Stopp. Lass dich von diesen 15 Sekunden langen, gefilterten Videos nicht täuschen.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'Die Dezibel der Stille 🤫', 'Endlich ist dein Kind eingeschlafen! Lauf jetzt nicht los, um das Zimmer aufzuräumen. Aktiviere den Schallpegelmesser und schau dir die Anzeige von 0-10 Dezibel auf dem Bildschirm an. Diese sichtbare Bestätigung der vollkommenen Stille zu Hause wird sich für dein müdes Gehirn wie die schönste Massage anfühlen.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'Professor für Philosophie 🧐', 'Dein Kind fragt nicht: „Mama, warum ist die Sonne dort?“, sondern einfach: „Warum ist die Sonne?“ Seine Fragen werden immer abstrakter. Streng dein Gehirn nicht mit stundenlangen wissenschaftlichen Erklärungen an. Eine kurze, märchenhafte und liebevolle Antwort wie „Weil sie uns so gern wärmt“ wird ihm völlig genügen.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'Die Beine machen Urlaub 🚶‍♂️', 'Mitten auf der Straße setzt sich dein Kind plötzlich auf den Boden und sagt: „Meine Beine sind kaputt, nimm mich auf den Arm.“ Nein, es ist nicht müde, sondern testet dich nur. Gib der Erpressung nicht nach. Bezieh es stattdessen in ein Spiel ein und sag: „Mal sehen, wie wir wie Pinguine bis zum Auto watscheln können!“'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'Eine farbenfrohe Ernährung 🥕', 'Heute hat dein Kind beschlossen, nur orangefarbene Lebensmittel zu essen, und lehnt alles andere ab. Die Kinderlogik ist wieder am Werk! Entdecke, wie du Gemüse in gesunden Rezepten geschickt verstecken kannst. Mit abwechslungsreichen Rezepten aus Kürbis- und Karottenpüree kannst du diese Trotzphase meistern.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'Der Morgensolist 🎤', 'Schon in aller Frühe, während du kaum die Augen aufbekommst, gibt dein Kind mitten im Zimmer mit seinem Spielzeug ein Konzert. Versuch nicht, es zum Schweigen zu bringen. Diese wilde, unerschöpfliche Lebensenergie von Kindern bringt Wärme und Freude ins Zuhause. Schau dein Kind lächelnd an.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'Eine heilsame Berührung 💆‍♂️', 'Dein Kind kommt im Bett einfach nicht zur Ruhe. Lass Märchen und Musik beiseite. Massiere seine kleinen Füße oder seinen Rücken ganz sanft mit streichelnden Bewegungen. Körperkontakt senkt sowohl bei deinem Kind als auch bei dir sofort den Cortisolspiegel (das Stresshormon) und macht schläfrig.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'Nachtschreck 😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert auf niemanden. Überprüfe es mithilfe der Weinanalyse. Wenn es sich um einen Nachtschreck handelt, schüttle dein Kind nicht und versuche nicht, es zu wecken. Bleib einfach ruhig bei ihm und vermittle ihm Sicherheit – es geht vorüber.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'Eiskalte Logik 🥶', 'Dein Kind öffnet den Kühlschrank, verlangt nach der Eiswürfelform und will sie trotz eiskalter Hände nicht loslassen. So erkundet es mit seinem Körper den Unterschied zwischen warm und kalt. Fülle eine Schüssel mit lauwarmem und eine andere mit Eiswasser und verwandle diese Entdeckung in ein kleines wissenschaftliches Experiment – dann ist die Trotzphase im Nu vorbei.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'Raus in die Natur ⛅', 'Zwischen vier Wänden verwandelt sich seine überschüssige Energie in Aggression, und jeder Satz beginnt mit einem Nein. Geh mit deinem Kind unbedingt nach draußen – unabhängig von Wetter und Kleidung, aber natürlich gut ausgerüstet. Der Kontakt mit der Erde hilft seinem Nervensystem, sich sofort zu regulieren.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'Nachtlicht 🌙', 'Wird dein Kind unruhig, sobald im Schlafzimmer das Licht ausgeht? Stelle ein kleines Nachtlicht mit warmem Licht – orange oder rot – in eine Ecke des Zimmers. Der Rest des Raumes sollte für die Melatoninausschüttung und einen tiefen Schlaf vollständig dunkel bleiben.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'Die digitale Einkaufsliste als Retterin 🛒', 'Du stehst mitten im Supermarkt und fragst dich: Was wollte ich hier noch mal kaufen? Im Mama-Alltag sind die Gedanken ohnehin ständig an tausend Orten zugleich. Gewöhne dir an, alles sofort in die Einkaufsliste der App einzutragen, sobald dir etwas einfällt – so machst du dir das Leben leichter.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', 'Die „Ich helfe dir!“-Falle 🧽', 'Will dein Kind beim Abwaschen unbedingt einen Stuhl neben dich stellen und mit dem Wasser spielen? Eigentlich möchte es nicht helfen, sondern mitten im Geschehen sein. Gib ihm eine kleine Plastikschüssel und einen Schwamm. Die Küche wird zwar unter Wasser stehen, aber sein Selbstbewusstsein wird riesig sein.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'Die magische Frequenz der Musik 🎶', 'Versuche, grundlose Wutanfälle und lautes Schreien am späten Nachmittag mit sanfter klassischer Musik zu unterbrechen. Dieser einfache, aber wirkungsvolle Trick kann die angespannte Stimmung im Raum oft wie durch Zauberhand verändern und dein Kind zur Ruhe bringen.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'Kleine Modeexpertin 👗', 'Heute möchte dein Kind mit zwei unterschiedlichen Socken und einem verkehrt herum angezogenen Oberteil nach draußen gehen. Vergiss die gesellschaftlichen Vorstellungen davon, was zusammenpasst. Die Freiheit, eine eigene Entscheidung zu treffen und dazu zu stehen, ist eine viel wichtigere Lektion fürs Leben als farblich abgestimmte Kleidung. Lass es zu.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'KI und Gelassenheit 🤖', 'Verunsichern dich die starken Gefühlsschwankungen deines Kindes mit etwa dreieinhalb Jahren? Schließe die beängstigenden und belastenden Internetforen. Lass dir von Anacan AI wissenschaftlich und psychologisch fundierte, beruhigende Antworten zu den Entwicklungskrisen in diesem Alter geben.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'Lass dein Kind die Geschichte bestimmen 🪄', 'Ihr habt beide genug von den klassischen Büchern und im Kinderzimmer herrscht gelangweilte Stimmung. Öffne die interaktiven Märchen und lass dein Kind heute Abend die Handlung lenken. Frag: „Wohin soll das fliegende Auto jetzt fahren?“ So kann es in seiner Fantasie auf Abenteuerreise gehen und dabei einschlafen.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'Die hypnotische Kraft des Flüsterns 🤫', 'Dein Kind liegt im Bett, streckt die Beine in die Luft und will partout nicht einschlafen. Statt laut zu werden, senke plötzlich deine Stimme und sprich nur noch flüsternd. Wenn dein Kind ganz aufmerksam wird, um dich zu verstehen, schaltet sein Gehirn wie von selbst in den Ruhe- und Schlafmodus.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Eine Offline-Auszeit für Mama 🛋️', 'Sobald dein Kind einen Zeichentrickfilm schaut oder sich in sein Spiel vertieft, springst du auf, um die Spülmaschine auszuräumen oder Wäsche aufzuhängen? Stopp! Nutze diese 10 Minuten, um einfach auf dem Sofa zu liegen, an die Decke zu schauen und an nichts zu denken. Du bist kein Roboter.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'Vervollständige angefangene Sätze 🗣️', 'Wenn deinem Kind ein Wort nicht einfällt, gestikuliert es, runzelt die Stirn und wartet darauf, dass du es errätst. Sein Wortschatz wächst – nur arbeitet sein Gehirn schneller, als es sprechen kann. Vervollständige den Satz geduldig und beobachte die Erleichterung in seinem Gesicht: „Jaaa, genau das wollte ich sagen!“'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'Kleine Food-Designer 🥦', 'Dein Kind sortiert das Essen auf dem Teller nach Farben und Formen und schiebt alles Grüne an den Rand. Schau dir die gesunden Rezepte an. Entdecke, wie du Gemüse zu einem unsichtbaren Püree verarbeitest und in leckeren Soßen versteckst – und gewinne dieses Spiel ganz heimlich.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'Reiten auf Papas Rücken 🐴', 'Dein Kind konnte seine Energie noch nicht vollständig abbauen und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind auf seinem Rücken reiten lässt, erfüllt lautes Lachen das Zimmer – und angestaute körperliche Anspannung sowie die scheinbar endlose Energie lösen sich innerhalb weniger Augenblicke unter ordentlich Schweiß in Luft auf.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'Verbotene Wörter 🤐', 'Dein Kind wiederholt lachend ein Schimpfwort, das es auf der Straße oder im Fernsehen gehört hat, und wartet gespannt auf deine Reaktion. Deine stärkste Waffe ist, gar nicht darauf zu reagieren. Lache nicht, ärgere dich nicht, sondern ignoriere es einfach. Schon bald wird dein Kind das Wort wieder vergessen.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'Unsichtbare Krümel 🧹', 'Mit einem ernsten Gesichtsausdruck fegt dein Kind mit seinem kleinen Besen unsichtbaren Staub vom Teppich. Es ahmt dich einfach nur nach. Halte diesen pflichtbewussten Moment beim Baby-Fotoshooting fest – die kleinste und süßeste Haushaltshilfe ist im Einsatz.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'Schallpegelmesser-Therapie 🤫', 'Der kleine Wirbelwind zu Hause hat sich endlich dem Schlaf ergeben. Im Zimmer ist außer dem Geräusch des Geschirrspülers nichts zu hören. Öffne die Schallpegelmesser-App, betrachte die niedrigen Dezibelwerte auf dem Bildschirm und schließe die Augen. Diese sichtbare Stille ist die beste Massage für dein Gehirn.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'Aufwachen wie eine Katze 🐾', 'Heute Morgen ist dein Kind kein Mensch. Es läuft auf allen vieren, schmiegt sich an dein Bein und verständigt sich nur durch Miauen. Das ist Fantasie in ihrer süßesten und schönsten Form. Statt Regeln aufzustellen, reiche ihm ebenfalls ein imaginäres Schälchen Milch und genieße dieses Spiel.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'Ein Geständnis in der Community 💬', 'Du hast heute wegen allem geschimpft und fühlst dich wie die ungeduldigste Mutter der Welt? Bitte denk daran, dass du nicht allein bist. Schau in der Anacan-Community vorbei und beruhige dein schlechtes Gewissen, indem du liest, dass auch andere Mütter heute genauso erschöpft sind.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'Papas verrücktes Märchen 📖', 'Heute Abend übernimmst nicht du das Erzählen. Gib Papa das Märchenbuch und lass ihn die Geschichte absichtlich verdreht, komisch und völlig absurd erzählen. Lehn dich zurück und beobachte, wie viel Spaß dein Kind daran hat, ihn zu korrigieren und herzlich über Papa zu lachen.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'Avantgardistischer Architekt 🥞', 'Dein Kind stapelt beim Frühstück die Pfannkuchen zu einem Turm, bohrt ein Loch in die Mitte und steckt den Finger hindurch. Mit Essen zu spielen ist für dein Kind ein neues Bauprojekt. Sieh über den schmutzigen Tisch hinweg – so entdeckt es auch die Beschaffenheit verschiedener Lebensmittel.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'Der Fantasieladen 🍅', 'In einer Ecke des Zimmers sammelt dein Kind seine Spielsachen und verkauft dir für imaginäres Geld eine imaginäre Tomate. Nimm dieses Verkaufsspiel ganz ernst. Kaufe die Fantasietomate und tu so, als würdest du sie genüsslich essen. Rollenspiele sind eine wichtige Grundlage für seine soziale Intelligenz und sein mathematisches Denken.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'Mamas geheime Schokolade 🍫', 'Liebe Mama, wenn du heimlich hinter dem Küchenschrank ein Stück Schokolade isst, steht dir dieser Glukoseschub absolut zu. Du musst schließlich auch deine Akkus aufladen, um den ganzen Tag genug Energie für all die endlosen „Warums?“ zu haben. Atme tief durch und genieße jeden Bissen.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'Der Zauber der Märchen 🪄', 'Vergiss das klassische Vorlesen und erwecke Märchen zum Leben. Erzeuge mit dem Mund das Rauschen des Windes, das Knarren einer Tür oder die Schritte der Figuren und verwandle das Zimmer in ein kleines Hörtheater. Dein Baby wird von dieser Vorstellung begeistert sein.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'Taktik gegen das Hinauszögern der Schlafenszeit ⏱️', 'Bekommt dein Kind plötzlich Durst, muss noch einmal zur Toilette oder verabschiedet sich sogar von der Wand, sobald es Zeit zum Schlafen ist? Stelle einen Timer und führt die Regel ein: Wenn es klingelt, gehen alle schlafen. So kannst du dieses endlose Abschiedsritual und die meisterhaften Verzögerungstricks geduldig beenden.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'Mama der Kuscheltiere 🧸', 'Aus dem Kinderzimmer sind Stimmen zu hören. Du hörst genauer hin und stellst fest, dass dein Kind seinen Teddy mit genau deinem Tonfall und deinen typischen Sätzen schimpft! Es ist dein perfektes Abbild. Eine wunderbare Gelegenheit, dein eigenes Verhalten einmal von außen zu betrachten.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'Wettercheck ⛅', 'Das Wetter draußen ist unbeständig – die Sonne scheint, aber es ist auch windig? Lass dir vom Wetter- und Kleidungshelfer sofort die Windgeschwindigkeit anzeigen, die du vom Fenster aus nicht erkennen kannst, und erhalte einen passenden Outfitvorschlag. So könnt ihr ohne langes Zögern an der Haustür zum Spaziergang aufbrechen.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'Papas Geheimtaktik 👨‍🍼', 'Die Erschöpfung und der Lärm des Tages waren genug für dich. Überlass am Abend Papa mit seiner spielerischen Art die Vorbereitung aufs Schlafengehen und das Zähneputzen. Zieh dich währenddessen in ein anderes Zimmer zurück und gönn dir unbedingt etwas Ruhe in völliger Stille.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'Mamas Energieriegel 🥑', 'Du hast vier verschiedene Mahlzeiten zusammengestellt, um dein Kind zum Essen zu bewegen – aber was hast du selbst gegessen? Wähle aus den gesunden Rezepten einen kalziumreichen Snack, der in 5 Minuten fertig ist, und genieße ihn notfalls im Stehen. Du bist der Motor dieser Familie.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'Das Frühstück, das keiner teilen will 🍳', 'Von seinem eigenen Teller möchte dein Kind dir auf keinen Fall etwas abgeben, aber von deinem Ei oder Käse will es unbedingt probieren. Kinder vertrauen der Auswahl ihrer Eltern vollkommen. Kämpfe nicht dagegen an, sondern überlass ihm deinen Bissen mit Liebe.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'Massage im Team 💆‍♂️', 'Wenn das Kind schläft, könnt ihr euch gegenseitig die Schultern massieren, um den körperlichen und seelischen Stress des Tages loszulassen. Ihr seid nicht nur Eltern, die unter demselben Dach leben, sondern ein unerschütterliches Team, das sich gegenseitig unterstützt.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'Das Meer in der Badewanne 🌊', 'Beim Baden geht es längst nicht mehr nur ums Sauberwerden, sondern darum, Wellen zu machen. Lass das Wasser ruhig in alle Richtungen spritzen und das Bad nass werden. Die magnetische Wirkung des Wassers spült all die hartnäckige, negative Energie, die sich im Laufe des Tages in deinem Kind angestaut hat, einfach in den Abfluss.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'Geheimnisse hinter verschlossener Tür 🚪', 'Geht dein Kind in sein Zimmer, schließt die Tür hinter sich und möchte allein sein? Es entwickelt ein Gefühl für Privatsphäre und seine eigene Persönlichkeit. Sorge für die nötige Sicherheit und gestehe ihm dieses kleine Recht auf Privatsphäre zu. Dein Kind wird groß.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'Ein Eintrag im Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Statt durch die scheinbar perfekten Leben anderer in den sozialen Medien zu scrollen, öffne das Stimmungstagebuch und halte für später fest, was dein Kind heute besonders Komisches gemacht und dich am meisten zum Lachen gebracht hat. Es aufzuschreiben ist Balsam für die Seele.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'Ein Toast auf euch als Paar 🥂', 'Das Kind schläft. Auch wenn ihr keinen Champagner habt, gießt euch warmen Tee in die Gläser und stoßt mit deinem Partner an: „Auch diesen turbulenten Tag haben wir heil überstanden.“ Ihr seid zugleich die Anführer und das unschlagbare Team eures Zuhauses.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'Tränen ohne erkennbaren Grund 🐶', 'Dein Kind weint herzzerreißend, weil der Hund auf der Straße es nicht angesehen hat oder weil ein Blatt zu Boden gefallen ist? Such darin keine Logik. Für dein Kind ist das wirklich ein tiefer Kummer. Bestätige einfach sein Gefühl und sage: „Ich weiß, du wolltest, dass der Hund dich ansieht.“'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'Diplomatie auf dem Spielplatz 🤝', 'Schubst dein Kind auf der Rutsche ein anderes Kind weg, weil es selbst rutschen möchte? Teilen ist für dein Kind noch ein schwieriges Konzept, das es nicht vollständig verinnerlicht hat. Statt es zu beschämen oder zu bestrafen, erinnere es einfach an die Regel und sage: „Jetzt ist das andere Kind an der Reihe.“'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'Der Hilferuf deines Körpers 🩸', 'Gib dich scheinbar grundloser Gereiztheit und Müdigkeit nicht einfach hin. Schau in den Perioden-Tracker – dein Körper sendet dir Signale. Statt dir Vorwürfe zu machen, gönn dir Ruhe und einen magnesiumreichen Snack.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'Kampf mit dem Schatten 👻', 'Hat dein Kind Angst vor seinem Schatten an der Wand und versteckt sich hinter dir? Rund um das 3. Lebensjahr kennt die Fantasie keine Grenzen. Verdunkle den Raum und lass mit deinen Händen und einer Taschenlampe Schattenspiele an der Wand entstehen. Verwandle die Dunkelheit, vor der es sich fürchtet, in ein großes Vergnügen.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'Das war nicht meine Schuld! 🤷‍♂️', 'Dein Kind hat das Wasser absichtlich auf den Boden geschüttet, gibt aber dem Tisch die Schuld und sagt: „Der Tisch ist verrutscht.“ Das ist keine Lüge, sondern ein instinktiver Versuch, sich zu verteidigen. Lass dich nicht auf einen Machtkampf ein. Sage stattdessen: „Komm, wir helfen dem Tisch und wischen es gemeinsam auf.“ So vermittelst du Verantwortung, ohne dein Kind zu verletzen.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'Unterstützung aus der Community 💬', 'Überkommt dich manchmal plötzlich der beklemmende Gedanke: „Ich werde nie wieder die unbeschwerte Person sein, die ich früher war“? Teile dieses vorübergehende, aber sehr belastende und tiefgehende Gefühl mit den Müttern in der Anacan Community. Bei ihnen findest du Trost und Unterstützung, denn sie haben Ähnliches erlebt.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'Einfach nur kuscheln 🫂', 'Du brauchst kein Spiel, kein lautes Bilderbuch und keine Geschichte. Drück dein Kind heute Abend einfach an deine Brust, atme seinen unverwechselbaren Duft tief ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist und wie sehr du es liebst.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', '„Ich will schieben!“ im Supermarkt 🛒', 'Dein Kind möchte den Einkaufswagen selbst schieben und sorgt für Chaos, weil es gegen die Regale fährt. Bevor es in aller Öffentlichkeit zu Tränen kommt, lass seine Hände am Einkaufswagen und lenke ihn unauffällig mit. Was dir noch fehlt, kannst du auf deiner Einkaufsliste nachsehen.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'Spielzeugchaos 🌪️', 'Bist du es leid, jeden Tag dieselben Spielsachen aufzuräumen? Dann lass es heute einfach sein! Euer Zuhause ist kein Museum, sondern ein warmer, lebendiger Ort, an dem ein kleiner Entdecker heranwächst. Konzentriere dich nicht auf die Unordnung, sondern auf die Freude deines Kindes am freien Entdecken – und gönn dir eine Pause.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'Schau nach unten: Was entdeckt dein Kind? 👣', 'Dein Kind genießt es, barfuß zu laufen und den Teppich, die Steine im Raum oder die kalten Fliesen zu spüren. Die Stimulation der Nerven in den Fußsohlen ist für sein Gleichgewicht und seine neurologische Entwicklung sehr wichtig. Halte es daher keinesfalls davon ab, ohne Socken zu laufen.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'Künstliche Intelligenz, echte Lösung 🤖', 'Hat es dich beunruhigt, dass dein Kind auf alles sehr heftig reagiert? Vergiss die beängstigenden Artikel im Internet. Frage Anacan AI, ob es sich möglicherweise nur um eine vorübergehende Stressreaktion handelt, und beruhige dich mit einer wissenschaftlich fundierten, von Kinderärzten geprüften Antwort.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'Die digitale Messung der Stille 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich im Haus ausbreitet, kaum glauben. Aktiviere den Schallpegelmesser und betrachte die 0-10 Dezibel auf dem Bildschirm. Spüre dabei förmlich, wie sich dein Gehirn langsam erholt und zur Ruhe kommt.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'Licht aus, Schlaf an 🌙', 'Damit dein Kind schneller einschläft, schalte eine Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin (das Schlafhormon) wird in einer dunklen, technikfreien Umgebung schneller ausgeschüttet und erleichtert so das Einschlafen.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'Inspiration aus den Blogs 📱', 'Welche Entwicklungssprünge stehen um den 40. Monat an? Was sollte dein Kind bereits können? Wirf einen Blick auf die Entwicklungsblogs in der App und freue dich darüber, wie große Fortschritte dein Kind beim Verstehen und logischen Denken macht.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'Unvollendete Sätze ergänzen 🗣️', 'Wenn dein Kind ein Wort vergessen hat, gestikuliert es, runzelt die Stirn und wartet darauf, dass du es errätst. Ergänze den Satz geduldig und beobachte die Erleichterung in seinem Gesicht: „Jaaa, genau das wollte ich sagen!“ Du bist sein ganz persönlicher Übersetzer.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'Das plötzliche Hungersyndrom 🥱', 'Kaum liegt dein Kind im Bett, sagt es: „Mama, ich habe Hunger!“, und will in die Küche laufen. Ein genialer Trick, um das Schlafengehen hinauszuzögern! Plane für den Abend einen kleinen, schlaffördernden Snack ein – so nimmst du ihm diese Ausrede schon im Voraus.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', 'Die „Meine Beine sind müde“-Masche 🚶‍♂️', 'Dein Kind setzt sich unterwegs plötzlich auf den Boden und sagt: „Meine Beine sind kaputt, trag mich!“? Dahinter steckt nicht unbedingt körperliche Müdigkeit, sondern vielleicht der Versuch, Mama umzustimmen. Mach ein Spiel daraus: Wer kann bis nach Hause schneller wie ein Hase hüpfen?'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'Mamas Reset-Knopf 🚪', 'Der Lärm zerrt an deinen Nerven und du möchtest am liebsten wegen allem losschreien. Öffne dein Stimmungstagebuch und schreibe dir ganz ungehindert deinen ganzen Frust und deine Erschöpfung von der Seele. Diese kurze digitale Auszeit hilft dir, wieder neue Kraft zu schöpfen.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'Papas Gute-Nacht-Geschichte 📖', 'Heute Abend ist deine Stimme müde. Überlass Papa das Vorlesen. Er wird anhand der Bilder im Buch eine völlig neue, frei erfundene und lustige Geschichte erzählen und euer Kind zum Lachen bringen. Und du kannst das Ganze ganz entspannt mit einer Tasse Tee genießen.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'Kleine Hilfe beim Wäschefalten 🧺', 'Du faltest mühsam die Wäsche zusammen, während dein Kind „Ich helfe!“ sagt und alles wieder im Zimmer verteilt. Statt dich zu ärgern, mach ein Spiel daraus: Wer kann diese Socken schneller und zielsicherer in den Korb werfen?'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'Unbedingt raus in die Natur ⛅', 'Hinter vier Wänden verwandelt sich die überschüssige Energie deines Kindes in Aggression, und jeder Satz beginnt mit „Nein“. Unabhängig von Wetter und Kleidung: Zieh dein Kind passend an und geh unbedingt mit ihm nach draußen. Der Kontakt mit der Erde hilft seinem Nervensystem, sich sofort wieder zu regulieren.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'Wenn jede Logik versagt 🔴', 'Dein Kind schreit, weil es sein Wasser im roten Becher haben möchte. Du füllst es um, und nun weint es, weil du es ausgerechnet in diesen Becher gegossen hast. Hier geht es nicht um Logik. Dein Kind ist einfach müde und muss seine Gefühle in einem Wutanfall herauslassen. Warte ruhig ab – der Sturm wird von selbst vorüberziehen.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'Schätze aus der Hosentasche 🪨', 'Beim Waschen der Hose hast du 2 Steine, ein vertrocknetes Blatt und ein halbes Stöckchen in der Tasche gefunden? Was für dich wie Müll aussieht, ist für dein Kind eine wertvolle Sammlung von Entdeckungen aus seiner Welt. Statt alles wegzuwerfen, könnt ihr die Fundstücke in einer kleinen Schatzkiste sammeln.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'Ich im smarten Märchen 🪄', 'Die klassischen Kinderbücher kennst du inzwischen auswendig. Öffne die smarten Märchen, mach dein Kind zur Hauptfigur und sein Zimmer zum Ort, den es zu erobern gilt. So entsteht ganz ohne Aufwand eine außergewöhnliche Einschlafgeschichte zum Anhören.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'Kein Müll, sondern Kunst 🎨', 'Mitten im Zimmer hat dein Kind aus kleinen Papierschnipseln und abgeschnittenen Fäden ein großes Kunstwerk geschaffen und lässt dich nichts davon wegwerfen. Stell deinen Ordnungsdrang für einen Moment zurück. Respektiere das kreative Chaos deines Kindes – aufräumen könnt ihr auch morgen noch.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'Unterstützung durch die Schreianalyse😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert auf niemanden. Nutze die Schreianalyse zur Einschätzung: Wenn es sich um Nachtschreck handelt, versuche nicht, dein Kind zu wecken. Bleib einfach still bei ihm – nach wenigen Minuten wird es von selbst wieder einschlafen.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'Gespräche mit leblosen Gegenständen 🗣️', 'Dein Kind führt im Park mit einem Stein oder zu Hause mit einem Stuhl völlig ernsthafte Gespräche und schimpft sogar mit ihnen. Durch symbolisches Spielen verarbeitet es die Welt und ihre Regeln. Halte diese besonderen Spielszenarien unbedingt im Entwicklungstracker fest.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'Spielspaß in der Badewanne 🌊', 'Baden bedeutet inzwischen nicht mehr nur sauber zu werden, sondern Wellen zu machen und zu spielen. Lass das Wasser ruhig herumspritzen und das Bad nass werden. Die geradezu magnetische Wirkung des Wassers hilft dabei, die angestaute Trotzenergie und negative Anspannung des Tages einfach in den Abfluss zu spülen.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'Gezieltes Zerstören 🧱', 'Mit großer Mühe baut dein Kind einen Turm und bringt ihn dann lachend mit einem einzigen Schlag zum Einsturz. Dabei lernt es etwas über Physik und das Prinzip von Ursache und Wirkung. Ärgere dich nicht – die einstürzenden Türme schaffen neue neuronale Verbindungen in seinem Gehirn. Hilf ihm, den Turm wieder aufzubauen.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'Weltuntergang beim Mittagsschlaf 🥱', 'Dein Kind will nicht ins Bett und weint? Zwinge es nicht. Dimme das Licht im Zimmer und erkläre die ruhige Bilderbuchzeit. So entsteht eine neue Routine, bei der ihr beide auf unterschiedliche Weise zur Ruhe kommen könnt.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'Der Fantasieladen 🍅', 'Dein Kind sammelt in einer Ecke des Zimmers Spielzeug und verkauft dir für Fantasiegeld eine imaginäre Tomate. Nimm dieses Verkaufsspiel ganz ernst. Kaufe die Fantasietomate und tue so, als würdest du sie genüsslich essen. Rollenspiele bilden eine der wichtigsten Grundlagen seiner sozialen Intelligenz.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'Musikalische Hypnose 🎶', 'Am späten Nachmittag ziehen scheinbar grundlose Stürme auf und die Weinanfälle beginnen. Schalte den Fernseher aus, dimme das Licht und lass ganz leise klassische Musik im Zimmer laufen. Die tiefen Klänge der Musik können die Atmosphäre wie durch Zauberhand verändern.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'Perfektion gibt es nicht 🛑', 'War deine Geduld heute am Ende? Fühle dich deswegen nicht schlecht. Löse dich von den Illusionen der perfekten Mutter im Internet. Du bist eine echte Mama und darfst deine Gefühle und deine Erschöpfung zulassen.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'Der Einkaufsretter 🛒', 'Vergisst du beim Einkaufen immer ausgerechnet das Wichtigste? Die Einkaufsliste in der App wartet auf dich. Trage dort ein, was ihr braucht, damit dein Partner auf dem Heimweg von der Arbeit alles gezielt besorgen kann – und du deinen Kopf nicht damit belasten musst.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', 'Die „Mama, schau mal!“-Phase 👀', 'Dein Kind springt vom Sofa und ruft bei derselben Bewegung ganze 50 Mal: „Mama, schau mal!“ Lege dein Handy weg und sieh hin. Es springt, um dieses bestätigende Leuchten in deinen Augen zu sehen. Schenke ihm 5 Minuten ungeteilte Aufmerksamkeit, damit sein Bedürfnis danach gestillt wird.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'Geflüsterte Geschichten 🌙', 'Heute hast du deine Stimme oft erheben müssen und bist ganz außer Atem. Schalte das Licht aus, lege dich neben dein Kind und flüstere ihm einfach ins Ohr, was ihr im Laufe des Tages erlebt habt. Das Flüstern bündelt seine Aufmerksamkeit und bereitet sein Gehirn auf fast hypnotische Weise auf einen tiefen Schlaf vor.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'Wetter-Check ⛅', 'Draußen ist das Wetter nicht ganz eindeutig – die Sonne scheint, aber es weht auch Wind? Das Wetter- und Kleidungstool zeigt dir sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und empfiehlt das passende Outfit. So musst du nicht lange an der Tür überlegen und kannst direkt losgehen.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'Team-Massage 💆‍♂️', 'Wenn euer Kind eingeschlafen ist, könnt ihr euch gegenseitig die Schultern massieren, um den Stress des Tages abzuschütteln. Ihr seid nicht nur Eltern, die unter einem Dach leben, sondern ein unschlagbares Team, das sich gegenseitig unterstützt.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'Plötzliche Gefühlsschwankungen 🤖', 'Verunsichern dich die heftigen Gefühlsschwankungen deines Kindes mit etwa dreieinhalb Jahren? Schließe die beängstigenden und belastenden Onlineforen. Bei Anacan AI erhältst du wissenschaftlich und psychologisch fundierte, beruhigende Antworten zu den Krisen in diesem Alter.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'Das Wunder des warmen Wassers 🛀', 'Manchmal hilft einfach nichts und dein Kind weint wegen allem. Setze es in eine Badewanne mit lauwarmem Wasser und gib etwas Badeschaum hinein. Die fast magische, entspannende Kraft des Wassers kann augenblicklich Ruhe in den ganzen Raum und sein Nervensystem bringen.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'Kleine Modeexpertin, kleiner Modeexperte 👗', 'Heute möchte dein Kind mit zwei unterschiedlichen Socken und einem verkehrt herum angezogenen Oberteil nach draußen. Lass die gesellschaftlichen Vorstellungen davon, was zusammenpasst, einfach beiseite. Die Freiheit, selbst zu entscheiden und dazu zu stehen, ist eine viel wichtigere Lektion fürs Leben als farblich abgestimmte Kleidung. Erlaube es ihm.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'Lebendiges Diktiergerät 🎙️', 'Heute Morgen sagt dein Kind zu seinem Spielzeug ein beiläufiges und vielleicht sogar unpassendes Wort, das du gestern im Gespräch mit deinem Partner benutzt hast! Es ist dein lebendiger Spiegel. Achte besonders auf die Emotionen, die du in seiner Gegenwart ausdrückst – es ahmt alles genau nach.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'Papas lustige Geschichte 📖', 'Heute Abend bist nicht du die Erzählerin. Gib Papa das Märchenbuch und lass ihn die Geschichte absichtlich verdreht, komisch und völlig absurd erzählen. Lehne dich zurück und beobachte, wie viel Spaß dein Kind daran hat, ihn zu korrigieren und herzlich über Papa zu lachen.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'Die Kraft der Community 💬', 'Der Gedanke „Warum ist mein Kind nur so stur?“ lässt dir keine Ruhe. Schau in der Anacan Community vorbei. Wenn du von den ähnlich absurden Krisen bei anderen Müttern zu Hause liest, wirst du erkennen, dass du nicht allein bist und dich auf einem völlig normalen Weg befindest.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'Der Morgendiktator ist im Einsatz 👑', 'Setz dich nicht dorthin, da soll mein Teddy sitzen! Beim Frühstück bestimmt dein Kind über den ganzen Tisch. Brich seinen Willen nicht abrupt, sondern wahre die Balance und den Frieden im Raum, indem du sagst: „Gut, dein Teddy sitzt dort und ich hier.“'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'Tee bei Kerzenschein 🕯️', 'Dein Kind schläft. Schalte das Licht aus und zünde eine Kerze auf dem Tisch an. Nicht für die Romantik, sondern einfach, um deine den ganzen Tag über strapazierten Nerven und deine von Bildschirmen und Lärm müden Augen zu beruhigen.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'Berührungsmüdigkeit 🔋', 'Den ganzen Tag klettert dein Kind auf dir herum, will kuscheln und spielt mit deinen Haaren. Berührungsmüdigkeit (touched out) ist real. Du hast das Recht, dich wenigstens 15 Minuten lang allein in ein Zimmer zurückzuziehen und deinen Körper ganz für dich zu haben.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'Reiten auf Papas Rücken 🐴', 'Dein Kind konnte seine Energie noch nicht ganz loswerden und weigert sich, ins Bett zu gehen. Bitte Papa um Hilfe. Wenn er das Kind auf seinem Rücken reiten lässt, erfüllt schallendes Lachen den Raum – und all die angestaute körperliche Anspannung und die scheinbar endlose Energie lösen sich innerhalb von Sekunden unter Schweiß auf.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'Ein Geständnis in der Community 💬', 'Du hast heute wegen allem geschrien und fühlst dich wie die ungeduldigste Mutter der Welt? Bitte denk daran, dass du nicht allein bist. Schau in der Anacan-Community vorbei und lies, dass andere Mütter heute genauso erschöpft sind – das kann unglaublich entlastend sein.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'Der Rivale im Spiegel 🪞', 'Dein Kind steht vor dem Spiegel, zieht die Augenbrauen zusammen und macht wütende und seltsame Grimassen. Es testet, wie verschiedene Emotionen im Gesicht aussehen. Beobachte still und interessiert, wie dieser kleine Theaterschauspieler probt.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'Geheime Lebensmittelmission 🥣', 'Bis gestern hat dein Kind Eier geliebt, heute bekommst du keinen einzigen Bissen in seinen Mund. Kämpfe nicht gegen seinen Willen an. Nutze raffinierte Rezepte für gesunde Snacks, in denen du Eiweißquellen anders, bunt und spannend präsentierst – und gehe so als Gewinnerin hervor.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'Die Bestätigung der Stille 🤫', 'Miss nach einem lauten Tag, wenn dein Kind eingeschlafen ist, mit einem Schallpegelmesser die Stille im Zimmer. Zu sehen, wie sich die Zahlen null nähern, wirkt mit dieser sichtbaren Ruhe wie die wohltuendste Massage für das Gehirn einer Mutter.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'Ein plötzliches „Ich liebe dich“ 💖', 'Mitten im Spielen schaut dein Kind dich plötzlich an, läuft auf dich zu und fällt dir um den Hals. Dafür lohnen sich all die schlaflosen Nächte und die Erschöpfung! Genieße den tiefen, einzigartigen Frieden, den dieser Moment mit sich bringt.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'Licht aus, Schlafenszeit 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme im Zimmer aus. Melatonin, das Schlafhormon, wird in einer dunklen, technikfreien Umgebung besonders gut ausgeschüttet.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'Ballaststoffbedarf 💩', 'Dein Kind ist ständig in Bewegung, vergisst aber, Wasser zu trinken. Achte beim Töpfchengang auf den Stuhlgang. Besteht Verstopfungsgefahr, vermerke es in der App und ergänze den Speiseplan über das Ernährungskontroll-Tool direkt um Haferflocken und Pflaumen.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'Verbotene Wörter 🤐', 'Dein Kind wiederholt lachend ein Schimpfwort, das es auf der Straße oder im Fernsehen gehört hat, und wartet gespannt auf deine Reaktion. Deine stärkste Waffe ist, nicht darauf zu reagieren. Lache nicht, werde nicht wütend – ignoriere es einfach. Schon bald wird dein Kind das Wort wieder vergessen.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'Dein Kind bestimmt das Ende der Geschichte 🪄', 'Ihr habt beide genug von den klassischen Büchern. Lass dein Kind bei den interaktiven Märchen diesmal selbst das Ende der Geschichte bestimmen. Frage zum Beispiel: „Was meinst du, wer hat der Hauptfigur geholfen?“ So kann dein Kind seiner Fantasie vor dem Einschlafen freien Lauf lassen.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'Eiskalte Logik 🥶', 'Dein Kind öffnet den Kühlschrank, verlangt nach der Eiswürfelform und lässt sie trotz kalter Hände nicht mehr los. So erkundet es Wärme und Kälte mit dem eigenen Körper. Fülle eine Schüssel mit lauwarmem und eine weitere mit Eiswasser und verwandle diese Entdeckung in ein kleines wissenschaftliches Experiment.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'Mit Papa im Park auspowern 👨‍👧', 'Muttersein sollte keine Schicht sein, die 24/7 andauert. Aktiviere den Partner-Modus! Heute darf dein Kind seine scheinbar endlose Energie mit Papa im Park auspowern, während du zu Hause die absolute Ruhe genießt.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'Küchenkonzert 🥄', 'Dein Kind holt Töpfe und Holzlöffel heraus und gibt mitten in der Küche ein Konzert. Auch wenn dir dabei der Kopf dröhnt, fördert es so sein Rhythmusgefühl und seine Kreativität. Greife nicht sofort ein, sondern lass diese wilde Energie ein paar Minuten lang in Schallwellen durch den Raum strömen.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'Die Stille im Schrank 🚪', 'Plötzlich wird es zu Hause ganz still und du findest dein Kind im Schrank, wo es sich versteckt und allein spielt. Es sucht nach einem persönlichen Rückzugsort. Hol es nicht sofort heraus. Auch dein Kind möchte dem Lärm entkommen, allein sein und seinem Kopf eine Pause gönnen.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'Stiller Ärger 😤', 'Wenn es nicht bekommt, was es möchte, weint es nicht, sondern verschränkt die Arme, schaut zur Wand und schmollt. Das ist eine neue und sehr wichtige Stufe der Emotionsregulation. Bedränge dein Kind nicht – 3 Minuten später kommt es lachend zurück, als wäre nichts gewesen.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'Das Maß der goldenen Stille 🤫', 'Der Lärm zu Hause lässt dir die Ohren klingeln. Sobald dein Kind endlich eingeschlafen ist, aktiviere den Schallpegelmesser. Diese Zahlen nahe null auf dem Bildschirm zu beobachten – diese digitale Stille – ist die schönste visuelle Massage für das Gehirn einer müden Mutter.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'Eine neue Sprache entdecken 🗣️', 'Dein Kind erfindet ungewöhnliche zusammengesetzte Wörter wie Flieg-und-renn oder Heiß-kalt. Sein Wortschatz wächst unglaublich schnell. Halte diese lustigen Wortschöpfungen unbedingt im Entwicklungs-Tracker fest – als unvergessliche Erinnerung für später.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'Ein ungewöhnlicher Wegbegleiter 🥄', 'Auf dem Weg zum Park besteht dein Kind darauf, statt seiner Spielzeugautos eine Schöpfkelle aus der Küche mitzunehmen. Halte es nicht davon ab! Diese Schöpfkelle wird heute im Park sein ungewöhnlichstes, aber praktischstes Spielzeug zum Buddeln im Sand sein.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'Katzen haben Angst vor Wasser 🐈', 'Um nicht in die Badewanne zu müssen, sagt dein Kind: Ich bin eine Katze, und Katzen baden nicht. Geh auf seine Rolle ein und spiele weiter: Möchte diese Katze vielleicht mit Seifenblasen spielen? So kannst du dein Kind mit Fantasie fürs Baden begeistern und Widerstände spielerisch überwinden.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'Professionelles Verhandeln 🛒', 'Statt im Supermarkt wegen Süßigkeiten zu weinen, verhandelt dein Kind: Wenn wir das kaufen, esse ich meine Suppe. Herzlichen Glückwunsch, dein kleiner Anwalt wird groß! Lass die Einkaufsliste geöffnet, damit du nichts vergisst und dich beim Diskutieren nicht ablenken lässt.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', 'Die Schau-mich-an!-Phase 👀', 'Dein Kind springt vom Sofa und wiederholt jedes Mal genau 50 Mal dieselbe Bewegung, während es auf deine Bestätigung wartet. Schau von deinem Handy auf. Es springt nicht wegen der Bewegung, sondern nur wegen dieses liebevollen Funkelns der Anerkennung in deinen Augen.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'Kleiner Geschäftsmann 🍅', 'In einer Ecke des Zimmers sammelt dein Kind seine Spielsachen und verkauft dir für imaginäres Geld imaginäre Tomaten. Nimm dieses Verkaufsspiel ganz ernst. Kaufe die imaginäre Tomate und tu so, als würdest du sie genüsslich essen. Rollenspiele bilden eine wichtige Grundlage für seine soziale Intelligenz und sein mathematisches Denken.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'Kalzium-Schutzschild 🦴', 'Für schnell wachsende Knochen ist Kalzium unverzichtbar. Dein Kind trinkt keine Milch? Nutze die Ernährungskontrolle und erfasse heute unbedingt, wie viel Käse, Joghurt oder Brokkoli es gegessen hat.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'Flucht aus dem Bett 🏃‍♂️', '„Gib mir Wasser“, „Such mein Spielzeug“ ... Mit 3 Jahren gehen die Ausreden, um nicht einschlafen zu müssen, nie aus. Stelle den Schlaf-Timer ein und halte konsequent an den Grenzen fest.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'Riesige Last 🎒', 'Dein Kind will deine schweren Taschen oder den großen Regenschirm unbedingt selbst tragen. Es schleppt sie hinter sich her, lehnt aber jede Hilfe entschieden ab. Lass es seine Kraft ausprobieren. Es möchte sich wie der stärkste Held im Haus fühlen – bremse seine Selbstständigkeit nicht aus.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'Eine neue Identität 🕷️', 'Dein Kind wacht morgens auf und erklärt dir mit ernster Miene: „Ich bin kein Kind, ich bin eine Spinne.“ Um den 40. Monat herum kennt die Fantasie kaum noch Grenzen. Diskutiere nicht, sondern gib ihm die Rolle der frühstückenden Spinne und spiel bei diesem absurden Theater einfach mit.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'Endlose Ausreden 🦶', 'Gerade als dein Kind einschläft, will es mit der Ausrede „Mein Zeh juckt“ wieder aus dem Bett. Im Hinauszögern des Schlafengehens ist es inzwischen ein Meister. Bleib ernst, tu so, als würdest du seinen Fuß kratzen, und schalte konsequent das Licht aus – du setzt die Grenzen.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'Papa nur mit Mütze 🧢', 'Dein Kind verlangt, dass Papa unbedingt eine Wintermütze trägt, bevor es ins Bett geht. Lass Papa die Mütze aufsetzen und lustige Geräusche machen. Diese herrlich absurde Abendeinlage bringt euch vor dem Schlafengehen zum Lachen und löst den Widerstand deines Kindes im Nu auf.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'Trotz, der der Physik widerspricht 💧', 'Dein Kind schluchzt, weil es sein Wasser trocken haben möchte? Indem das kindliche Gehirn Unmögliches fordert, testet es in Wirklichkeit deine Entschlossenheit. Suche in diesem Moment nicht nach Logik, sondern lenke seine Aufmerksamkeit sofort mit einem andersfarbigen Gegenstand ab.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'Stille Vertraute 📝', 'Du hast das Gefühl, dass dich niemand versteht und du zu Hause völlig erschöpft bist? Schluss mit dem aufgesetzten Lächeln. Schreib heute in dein Stimmungstagebuch, wie ausgebrannt du dich wirklich fühlst. Jedes Wort, das du auf den Bildschirm bringst, nimmt dir eine schwere Last von den Schultern.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'Nickerchen auf dem Boden 🥱', 'Dein Kind hat sich hartnäckig gegen den Mittagsschlaf gewehrt, ist dann aber zusammengerollt zwischen seinen Spielsachen auf dem Teppich eingeschlafen. Trag es nicht ins Bett und riskiere nicht, es aufzuwecken. Lass es mitten im Zimmer friedlich schlummern – und gönn dir selbst 1 Stunde Ruhe.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'Wettercheck ⛅', 'Die Sonne scheint, aber dein Kind möchte unbedingt die Winterjacke anziehen. Diskutiere nicht. Öffne das Wetter- und Kleidungstool und zeig ihm das Symbol mit dem leicht angezogenen Kind auf dem Bildschirm. Der Trick „Schau, das Handy sagt, dass es heute warm ist“ funktioniert fast immer hervorragend.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'Es bestimmt die Handlung 🪄', 'Klassische Märchen wecken nicht mehr die Aufmerksamkeit deines Kindes? Öffne die interaktiven Märchen und frag: „Wohin soll dieser magische Zug jetzt fahren?“ Lass dein Kind in seine selbst erfundene, herrlich verrückte und völlig absurde Geschichte eintauchen und dabei einschlafen.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'Termin beim Zahnarzt 🦷', 'Dein Kind nimmt die Zahnbürste in die Hand und möchte deine Zähne ganz ernsthaft untersuchen. Öffne den Mund und folge den Anweisungen dieses drolligen kleinen Zahnarztes. Rollenspiele gehören zu den wirksamsten und unterhaltsamsten Möglichkeiten, die Persönlichkeit zu fördern und Ängste zu überwinden.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'Kein Müll, sondern ein Schatz 🍬', 'Die Welt geht unter, weil du das alte Schokoladenpapier weggeworfen hast, das dein Kind seit Tagen aufbewahrt, aber nie benutzt hat? Was für dich Müll ist, kann für dein Kind ein wertvolles Sammlerstück sein. Um die Tränen zu stoppen, lenke seine Aufmerksamkeit sofort auf einen interessanteren Gegenstand.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'Ein Sieg ohne Champagner 🥂', 'Das Kind schläft. Auch wenn kein Champagner da ist, gießt euch heißen Tee in die Gläser, stoßt miteinander an und sagt: „Wir haben dieses stürmische Chaos auch heute wieder gemeistert.“ Ihr seid ein unerschütterliches und unermüdliches Team.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'Brokkoli-Detektiv 🥦', 'Dein Kind hat das eine grüne Gemüsestück in der Suppe entdeckt und weigert sich nun zu essen? Nutze im Ernährungsplan clevere Tricks: Misch das Gemüse unter bunte Nudeln, um davon abzulenken, oder püriere es, um es unauffällig im Essen zu verstecken.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'Die Liste in deiner Tasche 🛒', 'Ist im täglichen Chaos das Shampoo oder sind die Feuchttücher ausgegangen? Versuch nicht, dir alles zu merken: Schreib es sofort auf die Einkaufsliste und synchronisiere sie mit deinem Partner.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'Bedürfnis nach Ruhe 🤫', 'Die erste halbe Stunde nach dem Einschlafen ist die empfindlichste Phase. Überprüfe den Dezibelpegel der Umgebung mit einem Schallpegelmesser und drehe den Fernseher im Nebenzimmer leiser.'),
  ('602f2986-8e86-421e-ab71-94038d048ccf', 'Redet wie ein Anwalt 🗣️', 'Versucht dein Kind schon, mit Worten mit dir zu verhandeln? Sagt es: „Ich spiele noch ein bisschen, dann gehe ich schlafen“? Seine Sprachentwicklung macht tolle Fortschritte – vergiss aber nicht, konsequent bei deinen Grenzen zu bleiben.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'Puzzle und Logik 🧩', 'Versucht dein Kind, Puzzle mit 5-6 Teilen zusammenzusetzen? Dabei lernt es räumliches Denken und Logik. Unterbrich es nicht bei diesen wiederholten, aber lehrreichen Beschäftigungen.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'Papas Unterstützung 🫂', 'Wechselt euch beim nächtlichen Aufwachen unbedingt ab. Manchmal beruhigen Papas rhythmisches Streicheln und sein vertrauter Geruch das Kind im Dunkeln sofort.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'Die Forderung nach einem blauen Apfel 🍏', 'Kaum hat dein Kind die Augen geöffnet, verlangt es lautstark einen blauen Apfel von dir. Erkläre ihm jetzt nicht in einer Physik- oder Biologiestunde, dass es so etwas in der Natur nicht gibt. Antworte auf seine absurde Logik ebenso absurd, aber wirkungsvoll: „Die blauen Äpfel schlafen noch. Komm, wir wecken den roten auf.“'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'Der Decken-Tick 🛏️', 'Dein Kind ist gerade dabei einzuschlafen und fängt plötzlich an zu weinen: „Die Decke berührt meinen linken Fuß!“ Schmunzle innerlich über diese neue Marotte, die sich dein dreieinhalbjähriges Kind ausgedacht hat, um das Einschlafen hinauszuzögern. Richte wortlos die Decke, bleib konsequent und schalte das Licht im Zimmer vollständig aus.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'Der Preis verdächtiger Stille 💄', 'Das Ergebnis von 10 Minuten plötzlicher Stille zu Hause: Du betrittst das Zimmer und siehst, dass dein Kind mit deinem Lieblingslippenstift sowohl sein Gesicht als auch den Spiegel bemalt hat. Zum Ärgern ist es jetzt zu spät.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'Empathie auf höchstem Niveau 🩹', 'Klebt dein Kind seinem Teddy ein Pflaster auf den Arm und küsst ihn, weil er wehtut? Freu dich über dieses große, mitfühlende Herz. Halte dieses tiefe Mitgefühl voller Stolz als besonders schöne Charaktereigenschaft im Entwicklungs-Tracker fest.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'Papa übernimmt 👨‍👧', 'Deine Geduld ist am Ende? Schließ die Zimmertür und lass dein Kind mit seinem Papa allein. Heute Abend darf er bei den Spielen zu Hause das Kommando übernehmen, während du dich ausruhst.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'Schau mal, was ich kann! 🤸‍♂️', 'Versucht dein Kind, auf einem Bein zu stehen oder zu hüpfen, um deine Aufmerksamkeit zu bekommen? Es wünscht sich Anerkennung. Halte dieses körperliche Gleichgewicht im Entwicklungs-Tracker fest und applaudiere ihm.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'Gemüsekämpfe 🥦', 'Schiebt dein Kind das grüne Gemüse auf dem Teller beiseite? Mach keinen Kampf daraus. Entdecke unter den gesunden Rezepten clevere Möglichkeiten, Gemüse in Muffins oder Bratlingen zu verstecken.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'Angst vor der Dunkelheit? 👻', 'Gegen 3.5 Jahre tritt die Angst vor der Dunkelheit häufig auf. Stell ein kleines Nachtlicht ins Zimmer und erfinde in den Smarten Märchen Geschichten über mutige Heldinnen und Helden.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'Gespräche unter Müttern 💬', 'Belastet dich der Gedanke: „Warum ist mein Kind noch immer nicht vollständig ans Töpfchen gewöhnt?“ Tritt der Anacan-Community bei – dort wirst du sehen, dass jedes Kind sein eigenes Tempo hat.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'Verdreht dein Kind Wörter? 🗣️', 'Vertauscht dein Kind absichtlich einige Laute, macht lustige Geräusche und lacht darüber? Es entdeckt, wie flexibel Sprache ist. Mach mit und spielt gemeinsam Wortspiele.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'Erste Freundschaften 👫', 'Versucht dein Kind im Park schon, gemeinsam mit anderen Kindern zu spielen – also interaktiv statt nur nebeneinander? Jetzt beginnt die soziale Entwicklung so richtig! Beobachte diesen Moment aus sicherer Entfernung und sei bei Bedarf zur Stelle.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'Kunst auf dem Körper 🖍️', 'Plötzlich ist es verdächtig still – und du entdeckst dein Kind dabei, wie es mit Filzstiften Kunstwerke auf seine Arme malt. Ärgere dich nicht. Es trainiert gerade seine Feinmotorik, und die Farbe lässt sich ohnehin mit Wasser von der Haut abwaschen. Atme tief durch und halte diesen lustigen Moment fest.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf'::uuid, 'Die hypnotische Kraft des Flüsterns 🤫', 'Im Bett ist dein Kind so aktiv, dass es einfach nicht einschläft. Statt lauter zu werden, senke deine Stimme plötzlich. Sprich nur noch flüsternd mit ihm. Sobald es sich konzentriert, um dich zu verstehen, schaltet sein Gehirn automatisch in den Schlafmodus.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'Die Kraft der Mütter-Community 💬', 'Der Gedanke „Dieses Kind wird sich niemals beruhigen“ erschöpft dich? Schau in der Anacan Community vorbei. Wenn du dort ähnliche und sogar noch lustigere Geschichten über kleine Dickköpfe liest, wirst du merken, dass du nicht allein bist, und erleichtert aufatmen.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'Professor der Philosophie 🤔', '„Warum kann man den Wind nicht sehen?“, „Warum fallen Blätter herunter?“ Schon früh am Morgen bringen dich tiefgründige Fragen ins Grübeln. Versuche nicht, stundenlang wissenschaftliche Erklärungen zu liefern. Fantasievolle, liebevolle Antworten wie „Weil die Bäume ihre Kleidung wechseln“ reichen deinem Kind in diesem Alter vollkommen aus.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'Tanz mit den Schatten 🐰', 'Dein Kind sagt, es habe Angst im Dunkeln, und flüchtet deshalb aus dem Bett. Schalte alle Lichter im Zimmer aus, nimm eine Taschenlampe und forme mit deinen Händen Vogel- oder Hundeschatten an der Wand. So verwandelt sich die gefürchtete Dunkelheit innerhalb weniger Sekunden in ein Theater.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'KI als Retterin 🤖', 'Du findest keine Antwort auf die Fragen oder das ungewöhnliche Verhalten deines Kindes? Frag Anacan AI. Sie erklärt dir kurz, verständlich und beruhigend aus kinderärztlicher Sicht, wie das Gehirn von Kindern ab 3 Jahren funktioniert.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'Die Wärme seines Atems 💖', 'Den ganzen Tag hat dein Kind dich in den Wahnsinn getrieben und sich bei allem quergestellt. Doch jetzt liegt es im Bett eng an deine Brust gekuschelt, und sein gleichmäßiger Atem erfüllt den Raum. Genau das ist die schönste Belohnung des Mutterseins. Drück es fest an dich und vergiss für einen Moment all die Erschöpfung.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'Stolz trotz vertauschter Schuhe 👟', 'Dein Kind hat die Schuhe vertauscht angezogen, läuft aber so stolz herum, als hätte es die Welt erobert. Greif nicht ein und versuche nicht, sie richtig anzuziehen. Sein Selbstvertrauen und seine Selbstständigkeit sind millionenfach wichtiger als ein perfektes Aussehen.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'Papas magische Arme ✈️', 'Vom ganzen Herumtragen fallen dir schon fast die Arme ab, aber dein Kind ist immer noch voller Energie und wehrt sich gegen das Zubettgehen. Ruf Papa zu Hilfe. Wenn er das Kind in die Luft hebt und Flugzeug mit ihm spielt, erfüllt lautes Lachen den Raum – und die ganze aufgestaute, scheinbar endlose Energie ist innerhalb von Sekunden verbraucht.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'Die Bordstein-Challenge 🧱', 'Auf dem Weg zum Park möchte dein Kind partout nicht auf dem normalen Gehweg laufen, sondern wie ein Seiltänzer auf der schmalsten und höchsten Bordsteinkante balancieren. Dabei entwickeln sich Grobmotorik und Gleichgewichtssinn! Halte es zur Sicherheit an der Hand und lass es diesen kleinen, für dein Kind aber so wichtigen Gipfel erobern.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'Spaziergang mit dem unsichtbaren Hund 🐕', 'Mitten im Zimmer streckt dein Kind die Hand nach unten, streichelt einen unsichtbaren Hund und spricht mit ihm. Das ist die unschuldigste Phase der Fantasie. Frag: „Wie heißt der Hund?“ Stell in einer Zimmerecke einen imaginären Wassernapf auf und übernimm eine Nebenrolle in diesem großartigen Theaterstück.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'Die Kleiderschrank-Rebellion 🕶️', 'Dein Kind kommt mit Sonnenbrille und Wintermütze zum Frühstück und weigert sich vehement, sie auszuziehen. Vergiss Ästhetik und die Meinung anderer. Die Freiheit, eigene Entscheidungen zu treffen und dafür einzustehen, ist eine viel wichtigere psychologische Grundlage als ein perfekt abgestimmtes Outfit.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'Stille in Zahlen 🤫', 'Der Lärm zu Hause lässt dir die Ohren klingeln. Sobald dein Kind endlich eingeschlafen ist, aktiviere den Schallpegelmesser. Zu beobachten, wie der Wert auf dem Bildschirm auf 0-10 Dezibel sinkt, ist für das Gehirn einer müden Mutter die schönste sichtbare Entspannungsmassage.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'Der Ameisenretter 🐜', 'Hat sich dein Kind im Park weinend vor eine Ameise gestellt, um sie davor zu bewahren, zertreten zu werden? Bewundere dieses riesige, mitfühlende Herz.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'Ich in einer interaktiven Geschichte 🪄', 'Vom Vorlesen klassischer Bücher sind deine Stimmbänder schon müde. Öffne die interaktiven Geschichten. Mach dein Kind zur Hauptfigur, wähle beruhigende Waldgeräusche als Hintergrund und erschaffe so ganz mühelos ein außergewöhnliches, hypnotisches Einschlafritual.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'Der stille Trost der Community 💬', 'Überkommt dich plötzlich der Gedanke: „Ich werde nie wieder die unabhängige, unbeschwerte Person sein, die ich früher war“? Besuche die Anacan-Community. Dort kannst du lesen, dass auch andere Mütter diese belastenden, aber ganz natürlichen Gefühle erleben und dass sie zu einer Phase des Mutterseins gehören. Das kann Trost spenden.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', 'Der „Schau mich an!“-Trotz 👀', 'Kommt dein Kind zu dir und dreht dein Gesicht zu sich, wenn du aufs Handy schaust oder mit etwas anderem beschäftigt bist? Es möchte deine ungeteilte Aufmerksamkeit. Halte Blickkontakt und zeige ihm, dass du ihm zuhörst.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'Papa ist dran 👨‍🍼', 'Du musst die nächtlichen Wachphasen nicht ganz allein bewältigen. Wecke auch deinen Partner – ein Team zu sein bedeutet, die Verantwortung gleichmäßig zu teilen.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'Was soll ich nur kochen? 🍲', 'Dir gehen die Ideen für den Beikost-Speiseplan aus? Verlier dich nicht im Internet, sondern entdecke im Bereich „Gesunde Rezepte“ neue Köstlichkeiten.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'Ein ganz persönliches Märchen 🪄', 'Erstelle in „Smarte Märchen“ eine besondere Geschichte, in der dein eigenes Kind die Hauptrolle spielt: ein mutiges Kleines, das mit einer Zauberschere die Welt bunt macht.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'Ich helfe dir! 🧹', 'Versucht dein Kind, dir die Wäsche aus der Hand zu nehmen, während du sie zusammenlegst? Es fühlt sich schon richtig groß. Gib ihm ein kleines Handtuch und lass es mithelfen.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'Ich verrate dir ein Geheimnis 🤫', 'Kaum liegt dein Kind im Bett und seine Augen fallen fast zu, sagt es plötzlich: „Mama, ich verrate dir ein Geheimnis“, um den Schlaf hinauszuzögern. Im Aufschieben der Schlafenszeit könnten Kinder glatt promovieren. Lächle, sag: „Du kannst mir dein Geheimnis im Traum erzählen“, und mach entschlossen das Licht aus.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'Nur die Creme vom Keks 🍪', 'Hat dein Kind die Creme aus der Mitte der runden Kekse geleckt und die trockenen Hälften am Tischrand aufgereiht? Herzlichen Glückwunsch, du bist jetzt offiziell mit der Ernährungsphilosophie eines 3.5-jährigen Kindes vertraut. Entdecke unter „Gesunde Rezepte“ sinnvollere, aber dennoch lustige Snacks, die seine Aufmerksamkeit wecken.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'Du darfst nicht mitsingen! 🛑', 'Du hast bei dem Kinderlied im Hintergrund mitgesummt, und sofort kam der empörte Ruf: „Du darfst nicht mitsingen!“ Dein Kind ist der einzige Solist im Raum, und deine Gesangsversuche machen ihm die Bühne streitig. Nimm es nicht persönlich und überlass diesem kleinen Egoisten die Bühne.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'Wort-Remix 🗣️', 'Dein Kind verbindet Wörter wie Wasser und Milch zu völlig neuen Fantasiewörtern wie Milchwasser und lacht darüber. Es mixt seinen Wortschatz neu! Lach bei diesen Sprachspielen mit – genau durch solche Experimente lernt sein Gehirn die Grenzen der Sprache kennen.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'Plötzlicher Liebesausbruch 🫂', 'Morgens sagt dein Kind noch, du sollst weggehen, und beim Zubettgehen schlingt es fest die Arme um deinen Hals und sagt: „Ich liebe dich mehr als alles auf der Welt.“ Genau das ist das Paradox des Mutterseins! Genieß seinen warmen Atem und lass die ganze Erschöpfung des Tages verfliegen.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'Mama, geh weg! 💔', 'Wenn ein Wunsch nicht erfüllt wird, schaut dein Kind dich an und sagt: „Ich will dich nicht, geh weg!“ Lass dir davon nicht das Herz brechen. Es weiß noch nicht, wie es mit seiner Wut umgehen soll. Nimm es nicht persönlich. Sag: „Ich bin da. Wenn du dich beruhigt hast, reden wir“, und gib ihm Raum, seine Gefühle zuzulassen.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'Kleiner Anwalt im Supermarkt 🛒', 'Statt sich wegen einer Süßigkeit auf den Boden zu werfen, verhandelt dein Kind: „Wenn wir das kaufen, esse ich zu Hause meine Suppe.“ Herzlichen Glückwunsch, dein kleiner Anwalt wird groß! Damit du nichts vergisst, behalte die Einkaufsliste im Blick – so verlierst du beim Diskutieren mit ihm nicht dein eigentliches Ziel aus den Augen.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'Tsunami in der Badewanne 🌊', 'Baden dient nicht mehr nur der Sauberkeit, sondern ist jetzt ein Spiel, bei dem ein kleiner Tsunami entsteht. Lass das Wasser ruhig in alle Richtungen spritzen. Die fast magische, beruhigende Wirkung des Wassers spült all die hartnäckige negative Energie, die sich im Laufe des Tages angesammelt hat, einfach in den Abfluss.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'Mamas Recht auf Faulheit 🍕', 'Du könntest heute wegen allem losschreien? Zu Hause herrscht Chaos? Lass das Putzen sein und den Herd aus. Bestell Pizza oder einfach das, was am unkompliziertesten ist. Verabschiede dich von der Illusion der perfekten Mutter – deine psychische Gesundheit ist viel wertvoller als eine selbst gekochte Mahlzeit.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'Unbedingt selbst einschenken 💧', 'Dein Kind will das Wasser unbedingt selbst aus dem großen Krug in das kleine Glas gießen. Das Wasser landet auf dem Tisch und von dort auf dem Boden. Doch schau dir diese kleinen Hände an, die nach dem Lappen greifen und alles sauber machen wollen. Durch Fehler lernt dein Kind, Verantwortung zu übernehmen – dieses Chaos ist Entwicklung pur.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'Die erste Begegnung mit einer kleinen Schere ✂️', 'Versucht dein Kind, mit einer kindersicheren Plastikschere Papier zu schneiden? Das ist eine großartige Übung für die Feinmotorik! Halte diesen Moment unbedingt im Entwicklungstracker fest.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'Verschiedene Stimmen beim Märchenerzählen 🪄', 'Öffnet heute Abend die schlauen Märchen, aber lies den Text mit unterschiedlichen Stimmen vor. Sprich mit tiefer Stimme wie der Bär und mit hoher Stimme wie der Vogel – so entsteht im Zimmer ein kleines Theater. Das bringt Abwechslung, zieht dein Kind sofort mitten in die Geschichte und lässt es anschließend sanft einschlafen.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'Geflüsterte Entdeckungen im Dunkeln 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und flüstere ihm ganz leise ins Ohr, was ihr tagsüber erlebt habt oder welche Eigenschaft du besonders an ihm liebst. Flüstern ist eine fast magische Methode, die Geräusche rundherum vergessen lässt und das Gehirn auf den Schlaf vorbereitet.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'Ein Regenschirm im Haus ☂️', 'Draußen scheint die Sonne, aber dein Kind möchte mit aufgespanntem Regenschirm durchs Haus laufen. Seine Fantasie hält sich nicht an die Regeln der realen Umgebung. Wenn zu Hause genug Platz ist, lass es sich unter dem Regenschirm ein kleines Lager bauen. Schränke die kindliche Logik nicht durch gesellschaftliche Normen ein.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'Die Nein-Probe im Supermarkt 🛒', 'Mitten im Supermarkt wollte dein Kind Süßigkeiten, du hast Nein gesagt und es fing an zu weinen. Trotz der missbilligenden Blicke der selbst ernannten Erziehungsexperten ringsum bist du bei deiner Entscheidung geblieben. Du bist eine großartige Mama! Behalte außerdem deine Einkaufsliste im Blick, damit du nichts vergisst und schnell wieder rauskommst.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'Das grundlose „Warum hast du meinen Namen gesagt?“ 😤', 'Du hast nur „Komm, das Essen ist fertig“ gesagt, doch dein Kind wurde wütend und fing mit der Frage „Warum hast du meinen Namen gesagt?“ an zu weinen. In diesem Alter sind die Gefühle so durcheinander, dass Kinder manchmal scheinbar aus dem Nichts beleidigt sind. Versuch gar nicht erst, etwas zu erklären – 2 Minuten später wird es von selbst zum Essen gerannt kommen.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'Künstliche Intelligenz und seltsame Phobien 🤖', 'Hat dein Kind plötzlich Angst vor dem roten Auto, mit dem es sonst immer gespielt hat? Wenn dich unerklärliche Ängste beunruhigen, schließe die traumatisierenden Internetforen. Lass dir von Anacan AI wissenschaftlich fundiert und beruhigend erklären, welche merkwürdigen Züge die Fantasie mit 3.5 Jahren annehmen kann.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'Als Paar einen Film schauen ... 🎬', 'Das Kind schläft! Endlich setzt ihr euch gemeinsam aufs Sofa, um einen Film anzusehen, doch nach 10 Minuten seid ihr beide tief eingeschlafen. So sieht eure Realität aus. Dieses erschöpfte Bild, wie ihr aneinandergelehnt schlaft, ist der schönste Ausdruck echter Teamarbeit.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'Krümel im Bett 🍞', 'Du wachst morgens auf und das ganze Bett ist voller Crackerkrümel. Offenbar hat dein Kind sich früh am Morgen selbst ein Frühstück organisiert. Statt zu schimpfen, halte diese selbstständige Problemlösung im Entwicklungs-Tracker als lustige Erinnerung fest.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'Schultermassage von Papa 💆‍♂️', 'Heute warst du lange auf den Beinen. Vom Hinterherlaufen und Spielzeugaufsammeln tut dir der Rücken weh. Sobald das Kind eingeschlafen ist, bitte deinen Partner um eine zehnminütige Schultermassage. Du bist die tragende Säule der Familie – und auch Säulen brauchen unbedingt Ruhe und Erholung.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'Ich mache das selbst! 🛑', 'Dein Kind will seine Schnürsenkel unbedingt selbst binden, schafft es nicht, wird wütend und weist deine Hilfe energisch zurück. Atme tief durch. Ein unversehrtes Selbstwertgefühl ist für seine Zukunft wichtiger als ein durcheinandergeratener Zeitplan. Warte geduldig ab.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', 'Das „Es hat mich angeschaut!“-Drama 👀', 'Dein Kind hat im Park bitterlich geweint, nur weil ein anderes Kind es angeschaut hat? Für ein Kind, das seine sozialen Grenzen gerade erst entdeckt, kann selbst der Blick eines anderen wie ein Eindringen wirken. Nimm es in den Arm und lenke es mit den Worten ab: „Es hat sich nur dein schönes T-Shirt angesehen.“'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'Mit fantasievollen Geschichten zur Ruhe kommen 🪄', 'Dein Kind rennt im Zimmer herum und weigert sich, ins Bett zu gehen. Dimme das Licht. Denk dir eine spannende Geschichte aus und lies sie ihm vor.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'Spielzeug in Reih und Glied 🚗', 'Dein Kind hat alle seine Autos mit millimetergenauer Präzision quer durch das Zimmer aufgereiht und erlaubt nicht, dass auch nur eines davon verschoben wird. Dahinter steckt das Bedürfnis nach visueller Ordnung. Beobachte die Arbeit dieses kleinen Architekten still aus der Ferne und bringe nichts durcheinander.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'Stille Mitleserin in der Community 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären oder dein Herz ausschütten. Besuche einfach die Anacan-Community und lies nur mit. Zu sehen, wie andere Mütter mit denselben absurden Krisen umgehen, kann die beste stille Therapie sein.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'Die Krise wegen der falschen Löffelgröße 🥄', 'Fast wäre eine Revolution ausgebrochen, weil du die Suppe mit dem großen Löffel serviert hast. „Ich wollte den kleinen Löffel!“ Obwohl das Essen dasselbe ist, verändert die Größe des Löffels in der Vorstellung deines Kindes sogar dessen Geschmack. Diskutiere nicht, sondern tausche einfach den Löffel aus und spare deine Energie.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', 'Der „Deck mich zu!“-Tick 🛏️', 'Dein Kind ist fast eingeschlafen, doch dann verrutscht eine Ecke der Bettdecke und es ruft: „Deck mich zu!“ Dass die Ränder der Decke ganz gerade liegen, ist für dein Kind von größter Bedeutung. Zieh die Decke glatt, als wäre sie frisch gebügelt, und lächle innerlich über diese drolligen Einschlafrituale.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'Mamas Blickduell mit der Wand 🛋️', 'Im Zimmer ist es laut, dein Kind schlägt seine Spielsachen gegeneinander und du starrst einfach ins Leere auf die Wand, völlig weggetreten (zoned out). Das ist ein Schutzmechanismus deines Gehirns. Gönn dir diese 5 Minuten, in denen du wie eingefroren bist – du brauchst sie, um danach wieder ins Leben zurückzufinden.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'Schockierende Fragen in der Öffentlichkeit 😳', 'Hat dein Kind im Bus oder im Supermarkt laut gefragt: „Warum hat diese Frau so eine große Nase?“ Dieser Moment, in dem du am liebsten im Erdboden versinken würdest! Statt dein Kind zum Schweigen zu bringen und zu beschämen, lenke seine Aufmerksamkeit sofort auf einen bunten Gegenstand und rette dich diplomatisch aus der Situation.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'Papas unlogische Herausforderungen 🎲', 'Abends rennt dein Kind durchs Haus, weil es keinen Schlafanzug anziehen will. Da macht Papa daraus ein absurdes Spiel: „Mal sehen, ob du diesen Schlafanzug mit geschlossenen Augen anziehen kannst!“ Und bumm! Schon ist das Kind angezogen, ohne es überhaupt zu merken. Für diese unlogischen, aber wirksamen Spiele der Papas kann man einfach nur applaudieren.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', 'Die „Ich bin ein Baby!“-Nostalgie 🍼', 'Dein Kind krabbelt plötzlich wie ein Baby, weint und sagt: „Ich bin ein Baby, nimm mich in den Arm“? Das Großwerden macht manchmal auch Kindern Angst, sodass sie sich nach den vertrauten und sicheren Tagen ihrer Babyzeit sehnen. Nimm dein Kind für ein paar Minuten wie damals in den Arm und streichle es liebevoll.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'Suppe aus Matsch 🍲', 'Im Park mischt dein Kind Wasser und Erde, hält dir den Matsch hin und sagt: „Mama, ich habe dir Suppe gekocht.“ Jetzt bloß nicht angeekelt reagieren! Tu so, als würdest du diese Suppe wie das köstlichste Essen der Welt genießen.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'Der digitale Genuss der Stille 🤫', 'Das Chaos zu Hause ist endlich vorbei und dein Kind ist eingeschlafen. Öffne den Schallpegelmesser und beobachte auf dem Bildschirm, wie leise es im Zimmer ist (0-10 Dezibel). Diese Zahlen nahe null wirken auf das Gehirn einer erschöpften Mutter wie die teuerste Wellnessbehandlung der Welt.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'Der Kratzer auf der Banane 🍌', 'Nach dem Schälen entdeckt dein Kind einen winzigen, nur millimetergroßen Kratzer auf der Banane und ruft: „Die ist schlecht!“ Das Streben von Kindern nach optischer Perfektion kann wahnsinnige Ausmaße annehmen. Schneide die Stelle mit einem Messer ab, sage: „Ich habe sie gerettet!“ und beende damit dieses kleine Drama.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'Mission: Türen abschließen 🚪', 'Dein Kind hat besonderen Spaß daran, sich in allen Zimmern einzuschließen und dich draußen stehen zu lassen. Sein Verständnis von Privatsphäre nimmt gerade revolutionäre Formen an. Sorge dafür, dass keine Finger eingeklemmt werden, aber verdirb ihm nicht gleich das ganze Spiel, mit dem es sein eigenes Revier markiert.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'Die Waschmaschine entdecken 🧺', 'Dein Kind sitzt vor der Waschmaschine und schaut so gebannt auf die kreisende Wäsche, als würde es einen Zeichentrickfilm sehen. Diese Beschäftigung ist völlig kostenlos und wirkt beruhigend. Stör es nicht dabei – nutze auch du die Gelegenheit, um dich auszuruhen.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'Fluchtversuche beim Vorlesen 🏃‍♂️', 'Beim Vorlesen springt dein Kind bei jeder Gelegenheit aus dem Bett und läuft los, um noch ein Spielzeug zu holen. Es will sich dem Schlaf einfach nicht geschlagen geben. Senke deine Stimme plötzlich und lies flüsternd weiter. Um dich hören zu können, wird es ins Bett zurückkehren, aufmerksam lauschen und schließlich einschlafen.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'Ich bin schon groß und trinke Kaffee! ☕', 'Dein Kind greift nach deiner Tasse und verkündet entschlossen: „Ich bin schon groß, ich will auch Kaffee trinken!“ Es möchte einfach an deiner Welt teilhaben. Gib etwas Milch und Kakao in seine kleine Tasse, sag: „Schau, das ist dein Kinderkaffee“, und stoßt gemeinsam an.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'Wetter und Zwiebellook ⛅', 'Im Frühling ist das Wetter wechselhaft: morgens kalt, mittags warm. Das Wetter- und Kleidungstool erinnert dich an den Zwiebellook, bei dem mehrere Schichten übereinander getragen werden. Sobald deinem Kind im Park wärmer wird, kannst du eine Schicht ausziehen. So verhinderst du, dass es schwitzt – und ersparst dir selbst unnötigen Stress.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'Das Spiel mit der geklauten Nase 👃', 'Du sagst: „Ich habe deine Nase!“ und zeigst deinen Daumen – doch dein Kind glaubt es wirklich und fängt an zu weinen! Mit 3.5 Jahren kann es Fantasie und Wirklichkeit manchmal noch nicht klar voneinander unterscheiden. Sag sofort: „Aha, ich habe sie wieder eingesetzt“, und gib ihm einen Kuss auf die Nase. So verwandelst du diesen kleinen Schreck wieder in ein Lächeln.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'Ein stiller Blickwechsel mit deinem Partner 🥂', 'Das Kind ist endlich eingeschlafen. Du und dein Partner sitzt nebeneinander auf dem Sofa und habt nicht einmal mehr die Kraft zum Reden. Ihr schaut euch einfach schweigend an und lächelt. Dieser stille Blick ist die schönste Art, einander zu sagen: „Wir meistern dieses Chaos großartig.“'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'KI und plötzliche Trotzreaktionen 🤖', 'Dein Kind war bis gestern noch ruhig und reagiert heute auf alles aggressiv? Suche im Internet nicht nach beängstigenden Ursachen. Frage Anacan AI nach den psychologischen Gründen für diesen Entwicklungssprung (mental leap) und lass dich durch eine kinderärztlich geprüfte Antwort beruhigen.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', 'Ich habe das gefunden – besitzergreifende Kleinkinder 🔑', 'Dein Kind hebt die Fernbedienung oder Papas Schlüssel vom Boden auf und behauptet: „Ich habe das gefunden, also gehört es mir!“ Für dein Kind bedeutet Finden zugleich Besitzen. Nimm ihm den Gegenstand nicht mit Gewalt weg. Sag stattdessen: „Danke, dass du das für mich gefunden hast“, lenke seine Aufmerksamkeit auf ein anderes Spielzeug und nimm ihn dann zurück.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'Pflasterliebe 🩹', 'Dein Kind hat eine unsichtbare Wunde an seinem Körper entdeckt und besteht darauf, dass du dort ein Pflaster aufklebst. Es geht nicht um körperliche Schmerzen, sondern einfach um das Bedürfnis nach Mamas Aufmerksamkeit und Zuwendung. Kleb das kleine Pflaster auf und gib ihm einen Kuss – glaub uns, das rettet euch den Tag.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'Der visuelle Genuss der Stille 🤫', 'Das Chaos zu Hause ist endlich vorbei und dein Kind ist eingeschlafen. Lauf jetzt nicht gleich zum Abwasch! Öffne den Schallpegelmesser und betrachte 15 Minuten lang die vollkommene Stille im Zimmer (0-10 Dezibel). Spüre, wie dein Kopf zur Ruhe kommt und wie heilsam diese sichtbare Stille sein kann.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'Sandarchitektur 🏰', 'Im Sandkasten im Park gräbt dein Kind so tief, als würde es nach einem Schatz suchen. Von oben bis unten ist es voller Matsch. Aber unterbrich diesen Entdeckungsmoment nicht. Wenn du das Wetter im Blick behältst und vorher Kleidung auswählst, die schmutzig werden darf, kannst du dieses Schauspiel ganz entspannt genießen.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'Abendsport – auf Papa herumhüpfen 🤸‍♂️', 'Dein Kind ist seine Energie noch nicht losgeworden und will nicht ins Bett. Lass Papa sich aufs Sofa legen und dein Kind auf ihm herumhüpfen. Papas lustige Geräusche werden alle zum Lachen bringen und die überschüssige Energie ist innerhalb von Sekunden aufgebraucht.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'Selbstfürsorge für Mama 🥗', 'Du hast dir 3 verschiedene Menüs ausgedacht, damit dein Kind satt wird – und bist selbst schon wieder hungrig geblieben? Wähle im Bereich Ernährungsplan ein energiereiches, eisen- und kalziumreiches Mittagessen aus, das in 10 Minuten fertig ist. Denn nicht nur dein Kind, sondern auch du verdienst eine gute Mahlzeit.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'Das „Wer bist du?“-Spiel 🎭', 'Am Morgen schaut dein Kind dich mit todernster Miene an und fragt: „Wer bist du? Wo ist meine Mama?“ Die Fantasie ist auf ihrem Höhepunkt! Spiel einfach mit: Sag mit verstellter Stimme „Ich bin die Nachbarin, deine Mama kommt gleich“ und führt dieses großartige Theaterstück gemeinsam fort.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'Kunst aus Toilettenpapier 🧻', 'Ein paar Minuten Stille ... Und als du das Zimmer betrittst, stellst du fest, dass das gesamte Toilettenpapier abgerollt und im ganzen Haus verteilt wurde! Statt dich zu ärgern, sammelt die Papierbahnen gemeinsam ein und bastelt daraus einen Schneemann oder einen Ball. Besiege das Chaos nicht mit Schimpfen, sondern mit Kreativität.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'Ins Ohr geflüsterte Liebesworte 💖', 'Dein Kind hat dich den ganzen Tag in den Wahnsinn getrieben und sich bei allem quergestellt. Aber jetzt liegt es so unschuldig im Bett und schläft ... Leg dich zu ihm und flüstere ihm ins Ohr, wie sehr du es liebst und was es heute alles gut gemacht hat. Kinder spüren Mamas liebevolle Stimme sogar im Schlaf.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'Mini-Spa im Badezimmer 🛀', 'Heute Abend gönnst du nicht nur deinem Kind ein Bad, sondern auch dir selbst. Wenn dein Kind eingeschlafen ist, lass warmes Wasser ein, gib etwas Badeschaum dazu und zünde im Badezimmer eine einzelne Kerze an. Schließ die Tür ab und leg deine Mutterrolle für nur 15 Minuten ab, um wieder ganz du selbst zu sein.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'Der Friseurversuch ✂️', 'Du kommst ins Zimmer und siehst, wie dein Kind mit einer Schere in der Hand versucht, seiner Puppe die Haare zu schneiden. Ein solcher Anblick ist der Albtraum jeder Mutter. Nimm ihm ruhig die Schere ab und halte diesen Friseurversuch bei einem Baby-Fotoshooting als lustige Erinnerung fest.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'Spiel das Lied noch mal! 🎶', 'Dein Kind möchte das Lied, das gerade im Radio lief und schon zu Ende ist, noch einmal hören. Du erklärst ihm, dass es eine Liveübertragung war und das Lied vorbei ist. Doch es weint und ruft: Spiel es noch mal! Ein Kindergehirn kann die Logik einer Liveübertragung noch nicht verstehen. Lenke dein Kind ab, indem du das Lied selbst mit einer lustigen, verstellten Stimme singst.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'Überflüssiges auf der Einkaufsliste 🛒', 'Bevor du zum Supermarkt gehst, öffnest du deine Einkaufsliste. Plötzlich kommt dein Kind von hinten, tippt auf den Bildschirm und fügt nacheinander unverständliche Buchstaben und Schokolade hinzu. Ja, Kinder entdecken die digitale Welt wirklich blitzschnell!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'Eine Tasse Tee in aller Ruhe ☕', 'Dein Kind hat mitten im Zimmer seine Spielsachen in einer Reihe aufgestellt und spielt ganz allein. Bitte nutze diesen Moment nicht zum Staubsaugen! Setz dich aufs Sofa, trink deinen Kaffee oder Tee, solange er noch heiß ist, und genieße einfach 10 Minuten lang die Ruhe, ohne an irgendetwas zu denken.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'Der Timer-Trick fürs Schlafengehen ⏱️', 'Bekommt dein Kind plötzlich Durst, muss zur Toilette oder verabschiedet sich sogar von der Wand, sobald es Zeit fürs Bett ist? Stell einen Timer. Führt die Regel ein: Wenn der Timer klingelt, gehen alle schlafen. So beendest du diese endlose Abschiedszeremonie und geschickte Verzögerungstaktik ganz ohne Diskussionen.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'Echte Künstler wählen die Wand 🖍️', 'Ein paar Sekunden Stille haben nichts Gutes bedeutet. Du kommst ins Zimmer und siehst, dass dein Kind mit Filzstiften ein Kunstwerk an die Wand gemalt hat. Atme tief durch. Seine Feinmotorik entwickelt sich, und die Wand lässt sich schließlich wieder sauber machen. Fotografiere dieses Meisterwerk unbedingt, damit ihr später darüber lachen könnt.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'Die Kraft der Anacan-Community 💬', 'Der Gedanke „Warum ist mein Kind nur so stur?“ lässt dich nicht los. Schau in der Anacan-Community vorbei. Wenn du von ähnlich absurden Wutanfällen bei anderen Müttern zu Hause liest, wirst du merken, dass du nicht allein bist und dich auf einem völlig normalen Weg befindest.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'Tänze vor dem Spiegel 🪞', 'Dein Kind stellt sich vor den Spiegel, singt und probiert verschiedene Tanzbewegungen aus. Es erkundet dabei seinen eigenen Rhythmus und beobachtet, wie es aussieht! Halte dieses Körperbewusstsein und Rhythmusgefühl voller Freude im Entwicklungstracker fest.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'Geflüstertes Schlafduett 🌙', 'Im Bett ist dein Kind so aktiv, dass es einfach nicht einschläft. Statt lauter zu werden, senke deine Stimme plötzlich und beginne, sein Lieblingslied zu flüstern. Sobald es sich konzentriert, um dich hören zu können, wird sein Gehirn automatisch beruhigt und stellt sich auf den Schlafmodus ein.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'Haarekämmen ist der Feind 🪮', 'Sobald dein Kind den Kamm sieht, läuft es schreiend aus dem Zimmer. Beende den Machtkampf. Gib ihm zunächst den Kamm und lass es deine Haare oder die Haare seiner Puppe kämmen. Wenn es das Gefühl hat, die Kontrolle zu haben, wird es dir anschließend eher erlauben, seine Haare zu kämmen.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'Unterstützung in der Anacan-Community 💬', 'Überkommt dich manchmal plötzlich der bedrückende Gedanke, dass du nie wieder dein früheres, unbeschwertes Ich sein wirst? Teile dieses vorübergehende, aber sehr belastende und tief gehende Gefühl mit den Müttern in der Anacan-Community. Dort findest du Trost und Unterstützung von Frauen, die Ähnliches erlebt haben.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'Wassertherapie 🌊', 'Manchmal hilft einfach nichts und dein Kind weint wegen allem. Setze es in eine Wanne mit lauwarmem Wasser und gib etwas Badeschaum dazu. Die beruhigende, spannungslösende Wirkung des Wassers kann im ganzen Raum und im Nervensystem deines Kindes augenblicklich für Ruhe sorgen.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'Papas Massagestunde 💆‍♂️', 'Heute warst du lange auf den Beinen, bist deinem Kind hinterhergelaufen und hast Spielzeug vom Boden aufgesammelt – dein Rücken tut schon weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind eingeschlafen ist. Du bist eine tragende Säule eures Zuhauses, und auch Säulen müssen sich unbedingt ausruhen und neue Kraft schöpfen.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'Der Stolz auf das verkehrt herum angezogene Shirt 👕', 'Dein Kind hat sein Shirt verkehrt herum angezogen und präsentiert es so stolz, als hätte es gerade die Welt erobert. Ein Kind, das mit verkehrt herum angezogener Kleidung nach draußen geht, steht zu seiner eigenen Entscheidung. Greif kein bisschen ein, sondern bewundere dieses Selbstvertrauen.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'Grenzen testen im Supermarkt 🛒', 'An der Kasse tauchen im Einkaufswagen plötzlich 3 verschiedene Schokoladensorten auf, die du nicht ausgesucht hast. Dein Kind testet deine Grenzen. Lege die Sachen mit einem schnellen Handgriff zurück. Und damit du selbst nichts vergisst, behalte stets die Einkaufsliste in der App im Blick.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'Mit intelligenten Märchen sanft einschlafen 🪄', 'Die klassischen Bücher kannst du schon auswendig. Öffne die intelligenten Märchen, mache dein Kind zur Hauptfigur und sein Zimmer zum Ort, den es zu erobern gilt. So entsteht ganz mühelos ein außergewöhnliches Einschlaferlebnis zum Anhören – und auch du kannst dich entspannen.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'Schattentheater im dunklen Zimmer 🐰', 'Dein Kind sagt, es habe Angst im Dunkeln, und flüchtet aus dem Bett. Schalte alle Lichter im Zimmer aus, nimm eine Taschenlampe und forme mit deinen Händen Vögel oder Hunde an der Wand. So verwandelt sich die gefürchtete Dunkelheit innerhalb von Sekunden in ein Theater.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'Mit dem Schallpegelmesser die Ruhe bewahren 🤫', 'Der Lärm zu Hause lässt dir die Ohren klingeln. Wenn dein Kind endlich eingeschlafen ist, aktiviere den Schallpegelmesser. Diese Zahlen nahe null auf dem Bildschirm zu beobachten – diese digitale Stille – ist die schönste visuelle Massage für das müde Mutterhirn.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', 'Die „Du darfst nicht sitzen!“-Diktatur 🪑', 'Du möchtest dich aufs Sofa setzen, doch dein Kind rennt herbei und sagt: „Da sitzt mein Teddybär, steh auf!“ Es versucht, zu Hause das Kommando zu übernehmen. Brich seinen Willen nicht mit aller Härte, sondern bewahre das Gleichgewicht und den Frieden im Zimmer, indem du sagst: „Der Teddybär sitzt hier, und ich setze mich neben ihn.“'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: Warum lügen Kinder? 🤥', '„Ich habe das Wasser nicht verschüttet, das Spielzeug war es“, sagt dein Kind. Lügt es oder spielt nur seine Fantasie? Suche im Internet nicht nach beängstigenden Antworten. Erfahre von Anacan AI, dass solche Fantasievorstellungen bei einem 3.5-jährigen Kind eine völlig normale Entwicklungsstufe sind, und sei beruhigt.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'Lachanfall mit deinem Partner 🥂', 'Das Kind ist endlich eingeschlafen. Während du deinem Partner von diesem absurden Vorfall erzählst, der dich tagsüber in den Wahnsinn getrieben hat, brecht ihr plötzlich beide in schallendes Gelächter aus. Ja, dieses Lachen ist eine der schönsten Belohnungen des Elternseins.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'Spielzeug mit in die Badewanne nehmen 🛀', 'Dein Kind möchte nicht baden, willigt aber ein, sobald all seine Autos und Plastikbären in der Badewanne liegen. Halte es nicht davon ab. Diese Spielsachen sind die besten Helfer, damit es sich der beruhigenden Wirkung des Wassers hingibt.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'Die Liebe zu Nudeln 🍝', 'Das Fleisch, das dein Kind gestern noch mochte, lehnt es heute ab und möchte den ganzen Tag nur Nudeln essen. Kämpfe nicht gegen seinen Willen an. Lerne, wie du Proteine und Gemüse in gesunden Nudelrezepten als unsichtbare Soße verstecken kannst – und gewinne so die Mahlzeitenschlacht.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'Versteckspiel am frühen Morgen 🙈', 'Ihr kommt zu spät zur Arbeit oder in die Kita, doch dein Kind versteckt sich hinter dem Vorhang und ruft: „Finde mich!“ Auch wenn deine Nerven blank liegen, würde Schimpfen alles nur noch länger hinauszögern. Mach für 2 Minuten mit und frage: „Wo ist denn mein süßer Schatz?“ Dann findest du dein Kind und holst es aus seinem Versteck.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'Essen nach Farben sortieren 🍅', 'Dein Kind sortiert das Essen auf dem Teller nach Farben und Formen und schiebt alles Grüne zur Seite. Schau in den Ernährungsplan. Dort erfährst du, wie du Gemüse so fein pürierst, dass es unsichtbar wird, und in leckeren Soßen versteckst – so gewinnst du dieses Spiel ganz unbemerkt.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'Papas erfundene Geschichten 📖', 'Heute Abend musst nicht du erzählen. Gib Papa das Märchenbuch und lass ihn die Geschichte absichtlich verdreht, lustig und völlig absurd erzählen. Lehne dich zurück und beobachte, wie viel Freude dein Kind daran hat, ihn zu verbessern und gemeinsam mit Papa herzlich zu lachen.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'Die Wut im Stimmungstagebuch loswerden 📝', 'Sieht denn niemand, wie erschöpft du zu Hause bist? Das Stimmungstagebuch ist dein stillster Vertrauter. Schreib dort heute jedes Detail auf, das dich auf die Palme gebracht hat, und spüre beim Blick auf den Bildschirm, wie dein Kopf leichter wird und deine Sorgen davonfliegen.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'Mit einer Mütze durchs Haus laufen 🧢', 'Dein Kind möchte die Wintermütze im Haus tragen. Es besteht darauf und zieht sie nicht aus. Vergiss gesellschaftliche Konventionen. Solange die Raumtemperatur angenehm ist, darf dein Kind den Tag in diesem ungewöhnlichen, lustigen Look verbringen. So bewahrst du seine Kreativität und die Freiheit, eigene Entscheidungen zu treffen.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', '„Du hörst mir nicht zu!“ 😠', 'Während du aufs Handy schaust oder im Essen rührst, kommt dein Kind zu dir, dreht dein Gesicht zu sich und sagt: „Schau mich an!“ Es hat recht. Es möchte nicht nur, dass du körperlich anwesend bist, sondern deine ungeteilte Aufmerksamkeit. Unterbrich deine Tätigkeit und höre ihm nur 3 Minuten lang mit vollem Blickkontakt zu.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'Erste Kontaktversuche im Park 🤝', 'Dein Kind geht im Park auf ein unbekanntes Kind zu und stellt sich mit „Ich heiße ...“ vor. Seine sozialen Fähigkeiten entwickeln sich in erstaunlichem Tempo. Halte diese mutigen Kontaktversuche im Entwicklungstracker als einen Moment fest, auf den ihr bei seiner Persönlichkeitsentwicklung stolz sein könnt.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'Die hartnäckige Nein-Phase 🛑', '„Möchtest du Wasser?“ – „Nein!“ Doch nur 5 Sekunden später weint dein Kind nach Wasser. In dieser Phase testet es die Folgen seiner Entscheidungen. Es sagt sogar zu Dingen Nein, die es eigentlich möchte. Stell das Wasser auf den Tisch und übe keinen Druck aus. Sobald dein Kind seinen inneren Konflikt überwunden hat, wird es trinken.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'Unlogische Tränen ☀️', 'Hat dein Kind schluchzend geweint, weil die Sonne ihm in die Augen scheint? Suche in diesem Moment nicht nach Logik. Für dein Kind ist das wirklich ein tiefer Kummer – es ärgert sich darüber, dass es die Welt nicht kontrollieren kann. Bestätige einfach sein Gefühl, indem du sagst: „Ich habe den Vorhang zugezogen und die Sonne versteckt.“'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'Sehnsucht nach dem Alleinsein 🚪', 'Der Lärm dröhnt in deinem Kopf und du möchtest nur noch herumschreien. Bring dein Kind an einen sicheren Ort, geh ins Badezimmer und schließ die Tür. Schau einfach 5 Minuten lang an die Wand und tu nichts. Diese kurze Pause hilft dir, neue Kraft für deine Rolle als Mutter zu sammeln.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'Die Barfußregel 👣', 'Dein Kind liebt es, barfuß zu laufen und mit den Füßen den Teppich, Steine im Zimmer oder kalte Fliesen zu berühren. Die Stimulation der Nerven in den Fußsohlen ist für sein Gleichgewicht und seine neurologische Entwicklung sehr wichtig. Solange ihm nicht kalt ist, solltest du es ruhig ohne Socken laufen lassen.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'Papas seltsame Geräusche 🤡', 'Wenn deine Tricks nicht mehr funktionieren, retten Papas seltsame Tierlaute und lustige Grimassen sofort die Situation. Überlass ihm bei abendlichen Krisen direkt das Feld, lehn dich zurück und schau entspannt zu.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'Heute koche ich 🧑‍🍳', 'Stellt dein Kind unbedingt einen Stuhl neben dich und mischt sich ein, während du den Teig ausrollst? Eigentlich möchte es nicht helfen, sondern mitten im Geschehen sein. Gib ihm ein kleines Stück Teig. Die Küche wird danach chaotisch aussehen, aber sein Selbstvertrauen und seine Kreativität werden wachsen.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'Neue Wörter festhalten 📈', 'Dein Kind gibt Gegenständen völlig frei erfundene Namen, die es in keiner Sprache gibt. Und es besteht darauf, dass auch du diese Wörter verwendest! Öffne den Entwicklungstracker und archiviere diese lustigen Wortschöpfungen unbedingt, damit ihr sie später lesen und gemeinsam darüber lachen könnt.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'Mit der Dunkelheit anfreunden 🌙', 'Damit dein Kind schneller einschläft, solltest du 1 Stunde vor dem Zubettgehen alle zusätzlichen Lichtquellen und Tablet-Bildschirme ausschalten. In einer dunklen, technikfreien Umgebung wird Melatonin schneller ausgeschüttet und erleichtert so das Einschlafen.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'Licht aus und der Stille lauschen 🤫', 'Endlich ist dein Kind eingeschlafen. Jetzt stört dich selbst das kleinste Geräusch im Haus. Dimme das Licht, schalte den Fernseher aus und genieße mitten in der Dunkelheit diese seltene, herrliche Stille. So fällt selbst die Erschöpfung des ganzen Tages von dir ab.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'Die Realität des kalten Kaffees ☕', 'Den Kaffee einzuschenken und ihn 3 Stunden später eiskalt zu trinken, ist ein ungeschriebenes Gesetz des Mutterseins. Aber heute machst du es anders! Lass dein Kind seinen Lieblingscartoon anschauen und trink deinen Kaffee, solange er noch heiß ist. Du bist kein Roboter und hast ein Recht auf Erholung.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'Die digitale Stille des Geräuschmessers 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich im Haus ausbreitet, kaum glauben. Aktiviere den Geräuschmesser, schau auf die 0-10 Dezibel auf dem Bildschirm und spüre förmlich, wie sich dein Gehirn langsam erholt.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'Ich bin deine Mama! 👩‍👧', 'Der Rollentausch beginnt! Dein Kind gibt dir Anweisungen: Komm her, geh ins Bett, weine nicht. Lass dich mit Freude auf diese erste Führungserfahrung ein, widersprich nicht und spiele die Rolle seines Kindes. So entwickelt sich Empathie.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'Operation „Versteckte Vitamine“ 🥣', 'Was dein Kind gestern noch geliebt hat, will es heute nicht einmal probieren. Kämpfe nicht gegen seinen Willen an. Probiere gesunde Snackrezepte aus, die proteinreiche Zutaten in unterschiedliche, farbenfrohe und spannende Formen verwandeln – und gewinne so auf clevere Weise.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'Mein Kuscheltier ist krank 🩺', 'Dein Kind nimmt sein Spielzeugstethoskop, untersucht den Teddybären ganz ernst und klebt ihm ein Pflaster auf. Durch symbolische Spiele entwickelt es Mitgefühl und verarbeitet seine Erlebnisse. Mach mit und übernimm die Rolle einer Patientin im Krankenhaus.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'Traumwelten mit smarten Märchen 🪄', 'Die klassischen Bücher kennst du inzwischen auswendig. Öffne die smarten Märchen, mach dein Kind zur Hauptfigur und sein Zimmer zum Ort, den es zu erobern gilt. So entsteht ganz ohne Aufwand ein außergewöhnliches Hörerlebnis zum Einschlafen.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'Geständnisse im Stimmungstagebuch 📝', 'Sieht niemand, wie erschöpft du zu Hause bist? Das Stimmungstagebuch ist dein stillster Vertrauter. Schreib heute alle Kleinigkeiten hinein, die dich verrückt gemacht haben, und sieh auf dem Bildschirm, wie dein Kopf leichter wird und deine Sorgen davonfliegen.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'Wetter und plötzliche Umschwünge ⛅', 'Draußen ist das Wetter unbeständig – die Sonne scheint, aber gleichzeitig weht der Wind? Lass dir vom Wetter- und Kleidungs-Tool sofort die Windgeschwindigkeit, die du vom Fenster aus nicht erkennen kannst, und das passende Outfit anzeigen. So kannst du ohne langes Überlegen an der Tür direkt zu eurem Spaziergang aufbrechen.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'Ich will selbst einschenken 💧', 'Das Wasser aus dem großen Krug ins kleine Glas einzuschenken, will dein Kind unbedingt selbst übernehmen. Dabei landet das Wasser erst auf dem Tisch und dann auf dem Boden. Aber schau dir diese kleinen Hände an, die nach einem Tuch greifen und alles sauber machen wollen. Dein Kind lernt durch Fehler, Verantwortung zu übernehmen – werde nicht böse.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'Der Ozean in der Badewanne 🌊', 'Baden bedeutet längst nicht mehr nur, sauber zu werden – jetzt geht es darum, Wellen zu machen. Lass das Wasser ruhig herumspritzen. Seine fast magnetische Wirkung spült all die angestaute trotzige, negative Energie des Tages einfach in den Abfluss.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'Einkaufsliste – nie wieder etwas vergessen 🛒', 'Vergisst du beim Einkaufen ausgerechnet immer das Wichtigste? Die Einkaufsliste wartet in der App auf dich. Trage dort alles ein, was ihr braucht, damit dein Partner es auf dem Heimweg von der Arbeit gezielt besorgen kann und du deinen Kopf nicht unnötig belasten musst.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'Baukunst im Park 🏰', 'Im Sandkasten gräbt dein Kind so tief, als würde es nach einem Schatz suchen. Von oben bis unten ist alles voller Matsch. Aber unterbrich diesen Entdeckungsmoment nicht. Wenn du im Voraus wettergerechte Kleidung auswählst, die schmutzig werden darf, kannst du das Ganze ganz entspannt beobachten.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'Seltsame Freundschaften mit Gegenständen 🗣️', 'Im Park erzählt dein Kind einem Stein oder zu Hause einem Stuhl mit ernster Miene etwas und schimpft sogar mit ihnen. Durch symbolisches Spielen verarbeitet es die Welt. Halte diese besonderen Spielszenarien unbedingt im Entwicklungs-Tracker fest.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'Ich im interaktiven Märchen 🪄', 'Gib der Hauptfigur im interaktiven Märchen heute Abend einfach den Namen deines Kindes. Erzähle, wie die Figur im Märchen ihr Zimmer aufräumt und danach entspannt einschläft. So vermittelst du deinem Kind Regeln auf indirekte Weise, statt es anzuschreien.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'Stimmungstagebuch – Zeit zum Loslassen 📝', 'Nimm dein Handy zur Hand. Anstatt durch das Leben anderer in den sozialen Medien zu scrollen, öffne das Stimmungstagebuch und halte den lustigsten Moment deines Kindes von heute für die Zukunft fest. Diese digitale Auszeit wird auch dir guttun.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'Reiten auf Papas Rücken 🐴', 'Dein Kind konnte seine Energie noch nicht vollständig loswerden und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind auf seinem Rücken reiten lässt, erfüllt lautes Lachen das Zimmer. Die angestaute körperliche Anspannung und die scheinbar endlose Energie lösen sich innerhalb weniger Sekunden mit ordentlich Bewegung in Luft auf.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'Papas geheime Bestechung 🤫', 'Dein Kind will sich nicht die Zähne putzen. Papa schleicht sich zu ihm und sagt: „Wenn du dir die Zähne putzt, zeige ich dir den Zauberstein in meiner Tasche.“ Manchmal dürfen die Regeln des Mama-Alltags durch solche raffinierten, ungewöhnlichen Spiele der Väter gebrochen werden – vor allem, wenn sie sofort funktionieren.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'Vom Balkon aus die Welt beobachten 👀', 'Dein Kind geht auf den Balkon, winkt allen Vorbeigehenden laut rufend zu und ist gekränkt, wenn niemand reagiert. Sein Bedürfnis nach sozialem Kontakt ist gerade besonders groß. Zieh es nicht einfach nach drinnen. Sag lieber: „Sie sind sehr weit weg und haben dich vielleicht nicht gehört.“ So schützt du seine Empathie, ohne seine Gefühle zu verletzen.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'Stille Bilderbuchzeit 📖', 'Heute Abend spricht niemand. Öffnet die Gute-Nacht-Geschichten und betrachtet die Bilder gemeinsam in aller Ruhe, statt den Text laut vorzulesen – begleitet von sanften Naturgeräuschen aus dem Gerät. Die vielen visuellen Eindrücke machen dein Kind müde und lassen es ganz von selbst einschlafen.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'Das Ei wurde falsch serviert 🍳', 'Ein großer Wutanfall bricht aus, weil du das gekochte Ei halbiert hast. „Ich wollte es ganz!“ Die Form des Essens ist für Kinder ein besonders sensibles Thema. Sieh dir gesunde Rezepte an und lerne, wie du Lebensmittel in der richtigen Form und mit lustigen Schnitten ansprechend servieren kannst.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'Kleiner Naturdetektiv 🔍', 'Dein Kind saß im Park 20 Minuten lang regungslos da, nur um einen Ameisenhaufen zu beobachten. Dräng es nicht zur Eile. Wenn du es mithilfe des Wetter- und Kleidungsassistenten passend zum Wetter und mit Kleidung mit dickem, warmem Boden ausgestattet hast, darf dieser kleine Biologe in Ruhe die Welt entdecken.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'Das Mini-Labor in der Badewanne 🛀', 'Dein Kind mischt verschiedenfarbige Seifen ins Wasser und braut daraus einen Zaubertrank. Ja, das Badezimmer wird dabei nass und unordentlich. Doch es lernt etwas über Lösungsmittel und darüber, wie sich Stoffe vermischen. Dieses wissenschaftliche Experiment vertreibt die Müdigkeit des Abends und ist eine wunderbare Möglichkeit, dein Kind auf einen ruhigen Schlaf vorzubereiten.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'Rückzug in den Kleiderschrank 🚪', 'Mitten im Haus ist es plötzlich still geworden. Du findest dein Kind allein im dunklen Kleiderschrank spielend. Das ist keine Depression, sondern einfach ein Moment, in dem es sich emotional neu sortiert. Schließ die Tür sanft und gönn ihm den Luxus dieses persönlichen Rückzugsortes.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'Die Berührungs-Rebellion 🔋', 'Du bist körperlich völlig erschöpft von deinem Kind, das den ganzen Tag an dir hochklettert und an deinen Haaren zieht. Bring es an einen sicheren Ort und geh kurz in ein anderes Zimmer. Schreib „Mein Körper gehört nicht mir“ in dein Stimmungstagebuch und lass so die seelische Belastung dieses Touched-out-Syndroms los.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', 'Die Schau-mal!-Phase 👀', 'Dein Kind springt vom Sofa und ruft: Mama, schau mal!, während es genau dieselbe Bewegung 50-mal wiederholt. Nimm den Blick vom Handy. Es springt nicht wegen der Bewegung selbst, sondern wegen dieses bestätigenden Leuchtens in deinen Augen. Schenke ihm 5 Minuten lang deine ungeteilte Aufmerksamkeit, damit es dieses Bedürfnis stillen kann.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', '0 Dezibel auf dem Schallpegelmesser 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich über das Haus gelegt hat, kaum glauben. Aktiviere den Schallpegelmesser, betrachte die Anzeige von 0-10 Dezibel und spüre, wie dein Kopf langsam zur Ruhe kommt und diese sichtbare Stille dich wie eine sanfte Massage entspannt.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'Freies Tanzen 🎶', 'Sobald dein Kind irgendeinen Rhythmus hört – ob in einem Werbespot oder in einer Autohupe –, beginnt es zu tanzen. Sieh das Leben genauso fröhlich wie dein Kind! Mach mit und tanzt ein paar Minuten lang ausgelassen durchs Zimmer – dein ganzer Stress wird wie weggeblasen sein.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'Entwicklungs-Tracker – Stolz auf die Fortschritte 📈', 'Dein Kind ist kein Baby mehr! Es ist ein eigenständiger Mensch mit eigenen Entscheidungen, ungewöhnlichen Fragen und einem riesengroßen Herzen. Du machst das großartig!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'Grenzlinien auf dem Teppich 🗺️', 'Dein Kind hat die Regel aufgestellt, dass man vom Zimmer in die Küche nur gehen darf, wenn man dabei auf die roten Linien des Teppichs tritt. Dabei arbeiten Grobmotorik und Konzentration zusammen. Brich diese unsinnige Regel nicht – tanze gemeinsam mit deinem Kind über die Linien und mach daraus eure Morgengymnastik.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'Theater unter dem Kissen 🎪', 'Dein Kind liegt im Bett, hat aber den Kopf unter das Kissen gesteckt und spricht mit sich selbst. Verdunkle das Zimmer vollständig. Lass es in seinem dunklen, geborgenen Versteck eigene Geschichten erfinden und langsam ins Reich der Träume hinübergleiten, ohne es zu stören.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'Die Nudelprobe in der Hosentasche 🍝', 'Du hast in der Hosentasche, die gerade in die Waschmaschine sollte, eine vertrocknete Nudel gefunden? Für dich ist sie Müll, für dein Kind vielleicht ein Vorrat für den Fall, dass es unterwegs Hunger bekommt. Schimpfe nicht, sondern halte diesen ersten Funken von Planungstalent als lustige Erinnerung im Entwicklungs-Tracker fest.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', 'Die Forderung: Trockne das Wasser! 💧', 'Anstatt das Wasser im Glas zu trinken, ruft dein Kind: Das ist viel zu nass, trockne es! Willkommen in der absurden Welt eines 3.5-jährigen Kindes. Wenn du versuchst, es zu erklären, kostet dich das nur Energie. Sag einfach: Gut, ich hole dir anderes trockenes Wasser, und gib ihm dasselbe Wasser in einem andersfarbigen Glas.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'Schmollen ohne Grund 😤', 'Du hast nur gesagt: „Komm, das Essen ist fertig“, doch dein Kind verschränkt die Arme, starrt die Wand an und schmollt. In diesem Alter ist die Gefühlswelt so chaotisch, dass Kinder manchmal scheinbar grundlos beleidigt sind. Versuch nicht, etwas zu erklären – 2 Minuten später wird dein Kind von selbst zum Essen gerannt kommen.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: Ängste bei Kindern 🤖', 'Hat dein Kind plötzlich Angst vor dem roten Auto, mit dem es sonst immer gespielt hat? Wenn dich unerklärliche Ängste beunruhigen, schließe die verstörenden Internetforen. Bei Anacan AI erhältst du eine wissenschaftlich fundierte und beruhigende Antwort auf die Besonderheiten der Fantasie im Alter von 3.5 Jahren.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'Die hypnotische Kraft des Flüsterns 🌙', 'Dein Kind liegt im Bett, streckt die Beine in die Luft und will auf keinen Fall einschlafen. Statt zu schimpfen, senke plötzlich deine Stimme und sprich nur noch flüsternd. Wenn dein Kind sich konzentriert, um dich zu verstehen, stellt sich sein Gehirn ganz automatisch auf Ruhe und Schlaf ein.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'Entspannung in der Anacan-Community 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären. Öffne einfach die Anacan-Community und lies nur mit. Zu sehen, dass andere Mütter ähnlich erschöpft sind, vermittelt dir das Gefühl „Ich bin nicht allein“ – und kann die beste Therapie sein.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'Das Fragenfeuerwerk: Warum? 🌪️', '„Warum können Fische nicht laufen?“, „Wo ist die Sonne hin?“ Schon früh am Morgen sucht das Gehirn deines Kindes mit 100 Fragen pro Stunde nach Antworten auf die großen Fragen des Lebens. Auch wenn du müde bist, gib kurze Antworten. Dein Kind entdeckt die Geheimnisse des Universums durch den Klang deiner Stimme.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'Das gehört mir! – Alles besitzen wollen 🧸', 'Dein Kind nimmt irgendeinen Gegenstand aus dem Haushalt in den Arm, ruft „Das gehört mir!“ und will ihn niemandem geben. Es entdeckt gerade die Grenzen von Besitz und Eigentum. Wirf ihm keinen Egoismus vor, sondern lenke seine Aufmerksamkeit auf ein anderes Spiel und nimm den Gegenstand dann zurück.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'Mamas eigene Portion 🥗', 'Du hast dir 3 verschiedene Gerichte überlegt, damit dein Kind satt wird – und bist selbst wieder hungrig geblieben? Wähle im Bereich Ernährungsplan ein energiespendendes, in 10 Minuten zubereitetes und eisen- sowie kalziumreiches Mittagessen, das nicht nur für Kinder, sondern auch für Mütter gedacht ist. Denn auch du bist wichtig.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'Champagner für Eltern 🥂', 'Gießt euch nach einem anstrengenden Tag einfach warmen Tee in eure Gläser. Setzt euch auf dem Sofa einander gegenüber, stoßt an und sagt: „Auch dieses Chaos haben wir heute überlebt.“ Ihr seid zugleich die Anführer und das Team eurer Familie.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'Innere Ruhe mit dem Schallpegelmesser 🤫', 'Endlich ist dein Baby eingeschlafen. Doch das Klingeln in deinen Ohren hört nicht auf. Öffne den Schallpegelmesser in der App. Beobachte die Anzeige von 0 Dezibel auf dem Bildschirm und spüre, wie die Stille im Raum in dein Gehirn dringt und dich zur Ruhe kommen lässt.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'Der Handydieb 📱', 'Als du dir gerade Tee einschenkst, bemerkst du, dass dein Handy verschwunden ist – und hinter dem Sofa genauso wie du „Hallo“ sagt. Dein Kind erkundet deine digitalen Gewohnheiten. Hol dir das Gerät spielerisch zurück, indem du sagst: „Mein Handy möchte auch mit dir sprechen.“'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'Die „Zieh dich selbst an!“-Strategie 👖', 'Dein Kind streckt die Beine in die Luft und sagt: „Ich bin ein Baby, du musst mich anziehen.“ Kinder schwanken zwischen Selbstständigkeit und Abhängigkeit. Zieh es nicht mit Gewalt an. Lege die Kleidung daneben und locke es mit den Worten: „Diese Superheldenhose wartet auf ihren Besitzer.“'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'Die geheimnisvolle Kraft des Flüsterns 🌙', 'Dein Kind erfindet immer neue Ausreden, um nicht ins Bett zu müssen. Sprich ganz leise und nur noch im Flüsterton. Um dich zu verstehen, muss es seine Aufmerksamkeit bewusst auf dich richten. Diese Konzentration beruhigt sein Gehirn und hilft ihm, einzuschlafen.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'Trost in der Anacan-Community 💬', 'Überwältigt dich das Gefühl: „Ich werde nie perfekt sein“? Verabschiede dich von der Illusion der Instagram-Mütter. Schau in der Anacan-Community vorbei, lies die ehrlichen Geständnisse von Müttern, deren Zuhause im Chaos versinkt und deren Kinder die Wände bemalen, und sage dir: „Ich bin völlig normal.“'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'Dinosaurierlogik 🦖', 'Am Morgen beantwortet dein Kind keine einzige Frage, sondern brüllt nur. Heute ist es ein T-Rex. Passe dich seiner Fantasiewelt an und frage: „Essen T-Rexe eigentlich Brei?“ So könnt ihr das Morgenritual ganz ohne Tränen meistern.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'Papas erfundene Helden 🦸‍♂️', 'Vergesst heute Abend die Geschichten aus dem Buch. Papa soll eine fantasievolle, abenteuerliche Geschichte erzählen, in der das Kind selbst die Hauptrolle spielt. Sätze wie „Und dann zog es sein Schwert und ... putzte sich die Zähne!“ bringen das Kind zum Lachen und stimmen es auf das Schlafengehen ein.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'Das eigene Bild kritisieren 🖍️', 'Dein Kind zeigt dir sein schwarzes Gekritzel, sagt: „Das warst du, aber es ist nicht gut geworden“, und zerreißt es. Es entwickelt gerade die Fähigkeit zur Selbstkritik! Spiele seine Gefühle nicht herunter. Unterstütze seine Entwicklung, indem du fragst: „Möchtest du beim nächsten Bild vielleicht auch Rot ausprobieren?“'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', '„Du bist eine schlechte Mama!“, hat es gesagt? 💔', 'Diesen Satz hat dein Kind gesagt, weil du ihm das gewünschte Auto nicht gekauft hast. Das hat dir einen Stich versetzt. Aber denk daran: Es kann seine Gefühle noch nicht richtig ausdrücken und möchte eigentlich sagen: „Ich bin enttäuscht.“ Nimm es einfach in den Arm und erkenne sein Gefühl an.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'Ein Gespür für Mode 👗', 'Dein Kind möchte in Sommersandalen über dicken Wintersocken in den Park gehen. Es besteht darauf und zieht sie nicht aus. Vergiss gesellschaftliche Konventionen. Lass es den Tag in diesem ungewöhnlichen, lustigen Outfit verbringen, damit du seine Kreativität nicht ausbremst – es lernt gerade, sich frei auszudrücken.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'Der Rivale im Spiegel 🪞', 'Dein Kind steht vor dem Spiegel, zieht die Augenbrauen zusammen und macht wütende und seltsame Grimassen. Es probiert aus, wie verschiedene Gefühle im Gesicht aussehen. Beobachte still und mit Freude, wie dieser kleine Schauspieler für seinen großen Auftritt übt.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'Eine Auszeit für Mama 🚪', 'Der Lärm dröhnt in deinem Kopf und du möchtest einfach nur losschreien. Bring dein Kind an einen sicheren Ort, geh ins Bad und schließe die Tür. Öffne dein Stimmungstagebuch und schreib dir deine ganze Erschöpfung frei von der Seele. Diese kurze therapeutische Pause hilft dir, wieder zur Ruhe zu kommen.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'Sich mit der Dunkelheit anfreunden 🐰', 'Dein Kind läuft aus dem Bett und sagt, es habe Angst im Dunkeln. Schalte alle Lichter im Zimmer aus, nimm eine Taschenlampe und forme mit deinen Händen Vogel- und Hundeschatten an der Wand. So verwandelt sich die gefürchtete Dunkelheit innerhalb von Sekunden in eine Theaterbühne.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'Taktik für den Wettercheck ⛅', 'Draußen scheint die Sonne, aber es weht auch Wind. Lass dich nicht vom Blick aus dem Fenster täuschen. Das Wetter- und Kleidungs-Tool zeigt dir sofort die gefühlte Temperatur und die passende Kleidung im Zwiebellook. So verschwendest du an der Haustür keine Zeit mit Grübeln und ihr könnt gut vorbereitet zum Spaziergang aufbrechen.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'Das war nicht meine Schuld! 🤷‍♂️', 'Dein Kind hat das Wasser absichtlich auf den Boden geschüttet, schiebt aber seinem Spielzeug die Schuld zu und sagt: „Es hat mich geschubst.“ Das ist keine Lüge, sondern ein Schutzmechanismus des kindlichen Gehirns. Diskutiere nicht dagegen, sondern sag: „Komm, wir zeigen dem Spielzeug, wie man das sauber macht.“ So umgehst du den Widerstand geschickt.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'Der Ozeansturm in der Badewanne 🌊', 'Beim Baden geht es längst nicht mehr nur ums Sauberwerden, sondern darum, einen kleinen Tsunami zu veranstalten. Lass das Wasser ruhig herumspritzen. Die fast magische, befreiende Wirkung des Wassers spült all die hartnäckige, negative Energie fort, die sich im Laufe des Tages in deinem Kind angesammelt hat.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'Der Hilferuf deines Körpers 🩸', 'Lass dich nicht von grundloser Gereiztheit und Müdigkeit überwältigen. Wirf einen Blick in den Perioden-Tracker – dein Körper sendet dir Signale. Statt dir Vorwürfe zu machen, gönn dir eine Pause mit einem magnesiumreichen Snack aus den gesunden Rezepten.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'Philosophie am frühen Morgen 🤔', 'Warum fallen Vögel nicht herunter? Warum ist der Baum grün geworden? Die wissenschaftliche Konferenz am frühen Morgen ist hiermit eröffnet. Wenn du es leid bist, präzise Erklärungen zu liefern, gib die Frage mit „Was glaubst du, warum?“ zurück und lausche diesen wunderbaren Fantasieantworten.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'Die Timer-Vereinbarung fürs Schlafengehen ⏱️', 'Sobald es Zeit zum Schlafengehen ist, bekommt dein Kind plötzlich Durst, muss auf die Toilette oder möchte sich von der Wand verabschieden. Stell einen Timer. Führt die Regel ein: Wenn es klingelt, machen alle das Licht aus. So kannst du diesem endlosen Abschiedsritual und der meisterhaften Hinhaltetaktik geduldig ein Ende setzen.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'Der „Ich will das!“-Anfall im Supermarkt 🛒', 'Dein Kind schreit an der Kasse nach Süßigkeiten? Lass dich von den missbilligenden „Was für ein ungezogenes Kind“-Blicken der anderen keinesfalls verunsichern. Stell ruhig Blickkontakt her, erkläre die Regel und bleib konsequent. Was nicht auf der Liste steht, wird nicht gekauft.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'Das „Wer bist du?“-Spiel 🎭', 'Dein Kind schaut dich mit todernster Miene an und fragt: „Wer bist du? Wo ist meine Mama?“ Es spielt mit dir Theater! Sag mit verstellter Stimme: „Ich bin die Nachbarin, deine Mama kommt gleich“, und führt dieses großartige Schauspiel weiter.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', 'Ein plötzliches „Ich liebe dich“ 💖', 'Mitten im Spielen schaut dein Kind dich plötzlich an, rennt zu dir und fällt dir um den Hals. Dafür haben sich all die schlaflosen Nächte und die ganze Erschöpfung gelohnt! Genieße den tiefen, einzigartigen Frieden dieses Augenblicks – das ganze Chaos ist sofort vergessen.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'Kein Müll, sondern Kunst 🎨', 'Mitten im Zimmer hat dein Kind aus kleinen Papierschnipseln und abgeschnittenen Fäden ein großes Kunstwerk geschaffen und erlaubt dir nicht, es wegzuwerfen. Leg deinen Putzfimmel beiseite. Respektiere das kreative Chaos – aufräumen könnt ihr auch morgen noch.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'Die Ruhe der Stille 🤫', 'Dein Kind ist endlich eingeschlafen! Du kannst die Stille, die sich über das Haus gelegt hat, kaum fassen. Aktiviere den Schallpegelmesser und betrachte die 0-10 Dezibel auf dem Bildschirm. Spüre, wie dein Kopf langsam zur Ruhe kommt und diese sichtbare Stille wie eine Massage auf dich wirkt.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', 'Du darfst nicht mitsingen! 🛑', 'Du hast bei einem Kinderlied im Hintergrund mitgesummt, und sofort kam der Protest: Du darfst nicht mitsingen! Dein Kind ist der einzige Star im Raum – deine Gesangseinlage stiehlt ihm nur die Show. Nimm es nicht persönlich und überlass diesem kleinen Egoisten die Bühne.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'Ich im schlauen Märchen 🪄', 'Gib der Hauptfigur in den schlauen Märchen heute Abend einfach den Namen deines Kindes. Erzähle, wie die Figur im Märchen ihr Zimmer aufgeräumt hat und danach friedlich eingeschlafen ist. So vermittelst du Regeln ganz nebenbei, statt sie laut einzufordern.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'Gerät der Rhythmus durcheinander? ⏱️', 'Dauert das Einschlafen am Abend sehr lange? Sieh dir den Zeitplan im Schlaf-Timer an. Vielleicht ist es wirklich an der Zeit, den Mittagsschlaf ganz wegzulassen und die Schlafenszeit am Abend vorzuziehen.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'Kleiner Zeichentrickkritiker 📺', 'Dein Kind erzählt dir mit seiner ganz eigenen Grammatik von dem Zeichentrickfilm, den es gesehen hat, und erklärt ernsthaft, wer wohin gegangen ist. Hör aufmerksam und mit staunendem Blick zu. So kann seine Fantasie Flügel bekommen und es fühlt sich wie der klügste Mensch der Welt.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'Stille Unterstützung aus der Community 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären oder dein Herz ausschütten. Öffne einfach die Anacan Community und lies nur mit. Zu sehen, wie andere Mütter mit denselben absurden Krisen umgehen, kann der stärkste stille Trost sein.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'Flucht aus dem Bett 🏃‍♂️', 'Gib mir Wasser, such mein Spielzeug ... Die Ausreden eines dreijährigen Kindes, um nicht einschlafen zu müssen, nehmen kein Ende. Schalte den Schlaf-Timer ein, halte konsequent an den Grenzen fest und bring mit Weißen Geräuschen Ruhe ins Zimmer.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'Kleiner Geschichtenerzähler 🗣️', 'Verbindet dein Kind schon Wörter miteinander und erfindet fantasievolle Geschichten und fantastische Szenarien? Halte diesen wunderbaren Sprachschub sofort als Sprachaufnahme fest und verewige ihn im Babyalbum.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'Kalzium-Schutzschild 🦴', 'Für schnell wachsende Knochen ist Kalzium unverzichtbar. Dein Kind trinkt keine Milch? Erfasse heute unbedingt mit dem Ernährungstracker, wie viel Käse, Joghurt oder Brokkoli es gegessen hat.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', 'Das habe ich im Supermarkt gefunden 🛒', 'Kurz vor der Kasse taucht im Einkaufswagen plötzlich eine Packung Kekse auf, die du nicht hineingelegt hast. Dein Kind war heimlich auf Entdeckungstour. Öffne die Einkaufsliste und sage: „Schau, das steht nicht auf unserer Liste. Beim nächsten Mal schreiben wir es auf.“ So überträgst du die Regel einer digitalen Autorität.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'Teezeit zu zweit 🥂', 'Schenke nach einem anstrengenden Tag einfach heißen Tee in zwei Gläser. Setzt euch auf dem Sofa einander gegenüber, stoßt an und sagt: „Auch dieses Chaos haben wir heute überstanden – wir sind ein tolles Team.“ Ihr seid das unerschütterliche Fundament eures Zuhauses.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'Mission verstecktes Gemüse 🥦', 'Dein Kind entdeckt das eine Reiskorn oder Stück Karotte in der Suppe und sagt: „Das esse ich nicht.“ Öffne den Ernährungsplan. Finde heraus, wie du Proteine und Gemüse in bunte Küchlein verwandeln und so deinen kleinen, eigensinnigen Feinschmecker überlisten kannst.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'Kletterolympiade auf den Möbeln 🧗‍♂️', 'Dein Kind klettert über die Sofakante in Richtung Fenster. Für dich ist die Wohnung voller Gefahren, für dein Kind ist sie ein Fitnessstudio. Statt mit „Pass auf, du fällst!“ Panik zu verbreiten, sage lieber: „Setz deine Hand dorthin“, und lenke sein Bewegungsbedürfnis in sichere Bahnen.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'Künstliche Intelligenz und Gelassenheit 🤖', 'Hat dich das plötzlich auftretende Stottern oder ein Wutanfall deines Kindes dazu gebracht, im Internet nach schlimmen Krankheiten zu suchen? Stopp! Frage Anacan AI, ob dahinter ein Entwicklungsschub mit 3 Jahren stecken könnte, und erhalte eine beruhigende, kinderärztlich geprüfte Antwort.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'Geräuschkulisse im Kinderzimmer 🪄', 'Öffne die smarten Märchen. Lass beim Vorlesen einfach eine Tür knarren, den Wind rauschen oder ein Flüstern erklingen und verwandle das Zimmer in ein kleines Hörtheater. Diese ungewöhnliche Klangwelt zieht dein Kind sofort mitten in die Geschichte hinein – und von dort in einen tiefen Schlaf.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'Flucht vor dem Schatten 👻', 'Beim Spazierengehen erschrickt dein Kind plötzlich vor seinem eigenen Schatten und versteckt sich hinter dir. Suche nicht nach Logik – so funktioniert die Fantasie mit 3.5 Jahren. Sage: „Komm, wir springen auf den Schatten!“, und verwandle das, wovor es Angst hat, sofort in ein Bewegungsspiel.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'Eine Schultermassage vom Papa 💆‍♂️', 'Du warst heute lange auf den Beinen. Vom Hinterherlaufen und Aufheben der Spielsachen tut dir der Rücken weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind schläft. Du bist der Motor eures Zuhauses – und auch ein Motor braucht unbedingt Ruhe und Erholung.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'Vervollständige angefangene Sätze 🗣️', 'Wenn ihm ein Wort nicht einfällt, gestikuliert es, zieht die Augenbrauen zusammen und wartet darauf, dass du es errätst. Sein Wortschatz wächst – nur arbeitet sein Gehirn schneller als seine Zunge. Vervollständige geduldig seinen Satz und beobachte die Erleichterung in seinem Gesicht: Ja, genau das wollte ich sagen.'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'Reiterspiel auf Papas Rücken 🐴', 'Es konnte seine Energie noch nicht ganz loswerden und wehrt sich gegen das Zubettgehen. Ruf Papa zu Hilfe. Wenn er das Kind auf seinen Rücken nimmt und wie ein Pferd durch das Zimmer galoppiert, erfüllt lautes Lachen den Raum. Der angestaute körperliche Stress und die scheinbar endlose Energie lösen sich innerhalb von Sekunden unter viel Bewegung und Schweiß auf.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'Mamas Energieriegel 🥑', 'Du hast 4 verschiedene Menüs zusammengestellt, um dein Kind zum Essen zu bewegen – aber was hast du gegessen? Wähle aus den gesunden Rezepten einen besonderen, kalziumreichen Snack, der in 5 Minuten fertig ist, und genieße ihn, selbst wenn es nur im Stehen geht. Du bist der Motor dieses Zuhauses und musst deine Akkus aufladen.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'Aufwachen wie eine Katze 🐾', 'Heute Morgen ist dein Kind kein Mensch. Es läuft auf allen vieren, schmiegt sich an deine Beine und verständigt sich nur mit einem „Miau“. Das ist Fantasie in ihrer süßesten Form. Statt Regeln aufzustellen, reich ihm ebenfalls ein imaginäres Schälchen Milch und genieße dieses Spiel.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'Musikalische Hypnose 🎶', 'Am späten Nachmittag brechen scheinbar grundlose Stürme los und die Weinanfälle beginnen. Schalte den Fernseher aus, dimme das Licht und lass ganz leise klassische Musik im Zimmer laufen. Die tiefen Klänge der Musik werden die Atmosphäre wie von Zauberhand verändern und Ruhe in den Raum bringen.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'Frühstück, das man nicht teilen möchte 🍳', 'Von seinem eigenen Teller will dein Kind dir absolut nichts abgeben, besteht aber darauf, von dem Ei auf deinem Teller zu essen. Kinder vertrauen der Auswahl ihrer Eltern vollkommen. Kämpfe nicht dagegen an, gib ihm liebevoll einen Bissen ab und lächle.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'Gespräche mit leblosen Gegenständen 🗣️', 'Dein Kind erzählt einem Stein im Park oder einem Stuhl zu Hause mit völlig ernstem Gesicht etwas und schimpft sogar mit ihm. Durch symbolisches Spielen verarbeitet es die Welt. Halte diese besonderen Szenarien unbedingt im Entwicklungs-Tracker fest – sie sind ein Zeichen großer Kreativität!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'Ein Geständnis im Stimmungstagebuch 📝', 'Nimm dein Handy zur Hand. Statt in den sozialen Medien durch das scheinbar perfekte Leben anderer zu scrollen, öffne das Stimmungstagebuch und halte für später den lustigsten Moment des Tages fest, mit dem dein Kind dich am meisten zum Lachen gebracht hat. Dort hineinzuschreiben ist die reinste Therapie.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'Die „Das gehört mir!“-Phase 🧸', 'Will dein Kind sein Spielzeug mit niemandem teilen? Das ist kein Egoismus, sondern ein normaler Entwicklungsschritt. Lies in den Blogs, warum es zunächst nicht ums Teilen, sondern ums Abwechseln geht, und probiere die Tipps im Alltag aus.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'Revolution am Morgen 🛑', 'Lehnt dein Kind heute voller Abscheu ab, was es gestern noch so gern gegessen hat? Das ist keine Appetitlosigkeit, sondern einfach ein Versuch, selbst zu bestimmen. Sprich mit Anacan AI darüber, wie du bei solchen Krisen gelassen bleibst, atme tief durch und beginne am Esstisch niemals einen Machtkampf.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'Papa ist dran 👨‍👧', 'Muttersein ist keine Schicht, die 24/7 dauert. Jetzt ist dein Partner gefragt! Lass Papa heute mit dem Kind im Park die scheinbar endlose Energie austoben, während du zu Hause die absolute Ruhe genießt.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'Mamas Auszeit ☕', 'Ununterbrochen mit dem Kind zu sprechen und Fragen zu beantworten, ist anstrengend. Finde unter den mama-freundlichen Orten ein Café mit Spielecke, genieße deinen heißen Kaffee, tausche dich mit anderen Müttern aus und atme ein wenig durch.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'Papa ist mit der Gutenachtgeschichte dran 📚', 'Heute Abend übernimmt Papa das Einschlafritual komplett. Er liest die Geschichte vor, während du hinter der Tür die absolute Ruhe genießt.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'Ich mach das selbst! 🛑', 'Will dein Kind alles selbst machen und dauert das Anziehen dadurch 3-mal so lange? Achte nicht auf das entstandene Chaos, sondern auf das wachsende Selbstvertrauen. Wenn dir langsam der Geduldsfaden reißt, lies in den Blogs, wie du solche Krisen spielerisch lösen kannst, und atme tief durch.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'Heißer Tee und Ruhe 🍵', 'Der Timer ist abgelaufen, das Kind schläft. Vergiss den Haushalt – alles kann warten. Bereite dir mithilfe der gesunden Rezepte ein besonderes Getränk zu und genieße die Zeit für dich.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'Versteckspiel am frühen Morgen 🙈', 'Du kommst zu spät zur Arbeit oder in die Kita, während dein Kind sich hinter dem Vorhang versteckt und „Such mich!“ ruft. Auch wenn deine Nerven blank liegen: Schimpfen würde alles nur noch länger dauern lassen. Spiel 2 Minuten lang mit und frage: „Wo ist denn mein süßer Schatz?“, finde dein Kind und locke es so aus seinem Versteck.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'Essen nach Farben sortieren 🍅', 'Dein Kind sortiert das Essen auf dem Teller nach Farben und Formen und schiebt alles Grüne beiseite. Schau in den Ernährungsplan. Entdecke, wie du Gemüse zu einem unsichtbaren Püree verarbeiten und in leckeren Soßen verstecken kannst – und gewinne dieses Spiel ganz heimlich.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'Das Bedürfnis nach Ruhe 🤫', 'Endlich ist dein Kind eingeschlafen! Du kannst die Stille, die sich über das Zuhause gelegt hat, kaum fassen. Aktiviere den Schallpegelmesser, schau auf die 0-10 Dezibel auf dem Bildschirm und spüre, wie dein Kopf langsam zur Ruhe kommt und diese sichtbare Stille dich sanft entspannt.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'Schätze aus der Hosentasche 🪨', 'Beim Waschen der Hose hast du 2 Steine, ein vertrocknetes Blatt und ein halbes Stöckchen in der Tasche gefunden? Was für dich Abfall ist, gehört für dein Kind zu einer wertvollen Sammlung, mit der es die Welt entdeckt. Wirf diese Dinge nicht weg, sondern sammle sie in einer kleinen Schatzkiste.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'Mission: Türen abschließen 🚪', 'Dein Kind hat besonderen Spaß daran, die Türen aller Zimmer von innen abzuschließen und dich draußen stehen zu lassen. Das Verständnis von Privatsphäre erreicht eine ganz neue Stufe. Sorge dafür, dass keine Finger eingeklemmt werden, aber störe dieses Spiel, bei dem es sein eigenes Revier absteckt, nicht unnötig.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'Kunst mit Toilettenpapier 🧻', 'Ein paar Minuten Stille ... Und als du ins Zimmer kommst, siehst du, dass die ganze Toilettenpapierrolle abgerollt und im Haus verteilt wurde! Statt dich zu ärgern, sammelt das Papier gemeinsam ein und bastelt daraus einen Schneemann oder einen Ball. Begegne dem Chaos nicht mit Schimpfen, sondern mit Kreativität.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'Die Waschmaschine entdecken 🧺', 'Dein Kind sitzt vor der Waschmaschine und verfolgt die sich drehende Wäsche so konzentriert, als würde es einen Zeichentrickfilm schauen. Diese Unterhaltung ist völlig kostenlos und wirkt beruhigend. Störe es nicht, sondern nutze die Gelegenheit, um dich ebenfalls auszuruhen – das Chaos macht gerade eine kurze Pause.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'Liebe Worte ins Ohr flüstern 💖', 'Den ganzen Tag hat dein Kind dich in den Wahnsinn getrieben und sich bei allem quergestellt. Doch jetzt liegt es so unschuldig schlafend im Bett ... Leg dich zu ihm und flüstere ihm ins Ohr, wie sehr du es liebst und was es heute alles gut gemacht hat. Kinder spüren die liebevolle Stimme ihrer Mama sogar im Schlaf.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', 'Der „Du hörst mir nicht zu!“-Moment 😠', 'Während du auf dein Handy schaust oder im Essen rührst, kommt dein Kind zu dir und dreht dein Gesicht zu sich: Schau mich an! Es hat recht. Es möchte nicht nur deine körperliche Anwesenheit, sondern deine ungeteilte Aufmerksamkeit. Unterbrich deine Tätigkeit und höre ihm nur 3 Minuten lang mit vollem Blickkontakt zu.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'Fluchtversuche beim Vorlesen 🏃‍♂️', 'Beim Vorlesen springt dein Kind bei jeder Gelegenheit aus dem Bett und läuft los, um noch ein Spielzeug zu holen. Es will sich dem Schlaf einfach nicht ergeben. Senke plötzlich deine Stimme und lies flüsternd weiter. Um dich hören zu können, wird es ins Bett zurückkehren und dir aufmerksam zuhören.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'Wetter und Zwiebellook-Taktik ⛅', 'Zum Frühling hin ist das Wetter wechselhaft: morgens kalt, mittags warm. Das Wetter- und Kleidungstool erinnert dich an den praktischen Zwiebellook. Wenn deinem Kind im Park wärmer wird, kannst du einfach eine Schicht ausziehen. So verhinderst du, dass es schwitzt, und ersparst dir selbst unnötigen Stress.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'KI und plötzliche Trotzreaktionen 🤖', 'Dein Kind war bis gestern noch ruhig und reagiert heute auf alles aggressiv? Suche im Internet nicht nach beängstigenden Ursachen. Frage Anacan AI nach den psychologischen Gründen für diesen Entwicklungssprung (Mental Leap) und beruhige dich mit einer kinderärztlich geprüften Antwort.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'Das Spiel mit der geklauten Nase 👃', 'Du sagst: „Ich habe deine Nase!“, zeigst deinen Daumen – und dein Kind glaubt es wirklich und fängt an zu weinen! Mit 3.5 Jahren kann es aufgrund seiner lebhaften Fantasie Realität und Illusion manchmal noch nicht unterscheiden. Sage sofort: „Ah, ich habe sie wieder eingesetzt!“, und küsse seine Nase. So verwandelst du diesen kleinen Schreck schnell wieder in ein Lächeln.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'Stiller Blickkontakt mit deinem Partner 🥂', 'Das Kind schläft endlich. Du und dein Partner sitzt nebeneinander auf dem Sofa und habt nicht einmal mehr die Kraft zum Reden. Ihr schaut euch einfach schweigend an und lächelt. Dieser stille Blick ist die schönste Art zu sagen: „Wir meistern dieses Chaos großartig.“'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', '„Ich habe das gefunden“ – das besitzergreifende Kleinkind 🔑', 'Dein Kind hebt die Fernbedienung oder Papas Schlüssel vom Boden auf und verkündet: „Ich habe das gefunden, das gehört mir!“ Für dein Kind bedeutet Finden zugleich Besitzen. Nimm es ihm nicht mit Gewalt weg. Sage stattdessen: „Danke, dass du das für mich gefunden hast“, lenke seine Aufmerksamkeit auf ein anderes Spielzeug und nimm den Gegenstand dann zurück.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'Konzert in der Küche 🥄', 'Dein Kind holt Töpfe und Holzlöffel heraus und veranstaltet mitten in der Küche ein Konzert. Auch wenn du davon Kopfschmerzen bekommst, fördert es damit sein Rhythmusgefühl und seine Kreativität. Greife nicht sofort ein, sondern lass diese wilde Energie ein paar Minuten lang in Form von Schallwellen durch den Raum strömen.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'Mini-Spa im Badezimmer 🛀', 'Heute Abend ist die Badewanne nicht nur für dein Kind da, sondern auch für dich. Wenn dein Kind eingeschlafen ist, gönne dir warmes Wasser, etwas Schaum und eine einzelne brennende Kerze im Badezimmer. Schließe die Tür ab und lege deine Mutterrolle für nur 15 Minuten ab. Sei wieder ganz du selbst – du hast es verdient.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'Ein Geständnis im Stimmungstagebuch', 'Nimm dein Handy zur Hand. Statt in den sozialen Medien durch das Leben anderer zu scrollen, öffne das Stimmungstagebuch und halte den lustigsten Moment deines Kindes von heute für später fest. Diese digitale Therapie wird auch dich entspannen – schau auf den Bildschirm und spüre, wie deine Sorgen verfliegen.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'Spiel das Lied noch mal! 🎶', 'Dein Kind möchte das Lied, das gerade im Radio lief und schon vorbei ist, noch einmal hören. Du erklärst, dass es eine Liveübertragung war und das Lied zu Ende ist. Doch es weint und ruft: „Spiel es noch mal!“ Das kindliche Gehirn versteht die Logik einer Liveübertragung noch nicht. Um dein Kind abzulenken, sing das Lied einfach selbst mit einer lustigen, verstellten Stimme.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'Tee in aller Ruhe ☕', 'Mitten im Zimmer reiht dein Kind seine Spielsachen auf und spielt ganz allein. Um Himmels willen, nutze diesen Moment nicht zum Staubsaugen! Setz dich aufs Sofa, trink deinen Kaffee oder Tee, solange er noch heiß ist, und genieße einfach 10 Minuten lang die Stille, ohne an irgendetwas zu denken.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'Der Timer-Trick fürs Zubettgehen ⏱️', 'Bekommt dein Kind plötzlich Durst, muss noch einmal zur Toilette oder verabschiedet sich sogar von der Wand, sobald es Zeit zum Schlafen ist? Stell einen Timer. Führt die Regel „Wenn der Wecker klingelt, gehen alle schlafen“ ein – so entkommst du diesem endlosen Abschiedsritual und der meisterhaften Verzögerungstaktik ganz ohne Diskussion.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'Die Stärke der Anacan-Community 💬', 'Der Gedanke „Warum ist mein Kind nur so stur?“ lässt dir keine Ruhe. Schau in der Anacan-Community vorbei. Wenn du von den ähnlich absurden Wutanfällen bei anderen Müttern zu Hause liest, wirst du merken, dass du nicht allein bist und dass bei euch alles völlig normal läuft.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'Ein echter Künstler wählt die Wand 🖍️', 'Ein paar Sekunden Stille endeten in einer kleinen Katastrophe: Du kommst ins Zimmer und siehst, dass dein Kind mit Filzstiften ein Kunstwerk an die Wand gemalt hat. Atme tief durch. Seine Feinmotorik entwickelt sich, und die Wand lässt sich schließlich wieder reinigen. Fotografiere dieses Meisterwerk unbedingt, damit ihr später darüber lachen könnt.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'Einladung in die Dunkelheit 🌙', 'Wird dein Kind unruhig, wenn im Schlafzimmer das Licht ausgeht? Stell in eine Ecke des Zimmers ein kleines Nachtlicht mit warmem Licht (orange oder rot). Der restliche Raum sollte für die Melatoninausschüttung und einen tiefen Schlaf vollständig dunkel bleiben.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'Der Friseurversuch ✂️', 'Du kommst ins Zimmer und siehst, wie dein Kind mit einer Schere in der Hand versucht, seiner Puppe die Haare zu schneiden. Ein solcher Moment ist der Albtraum jeder Mutter. Nimm ihm ruhig die Schere ab und halte diesen Friseurversuch beim Baby-Fotoshooting als lustige Erinnerung für später fest.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'Raus in die Natur ⛅', 'Hinter vier Wänden verwandelt sich die überschüssige Energie in Aggression, und jeder Satz beginnt mit einem Nein. Unabhängig von Wetter und Kleidung: Zieh dein Kind passend an und geh unbedingt mit ihm nach draußen. Der Kontakt mit der Erde hilft seinem Nervensystem, sich sofort zu regulieren.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'Das gehört mir! – Alles für sich beanspruchen 🧸', 'Dein Kind schnappt sich irgendeinen Gegenstand im Haus, umklammert ihn, ruft „Das gehört mir!“ und gibt ihn niemandem. Es entdeckt gerade die Grenzen von Besitz. Wirf ihm keinen Egoismus vor, sondern lenke seine Aufmerksamkeit auf ein anderes Spiel und nimm den Gegenstand dann zurück.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'Kein Müll, sondern Kunst 🎨', 'Mitten im Zimmer hat dein Kind aus kleinen Papierschnipseln und abgeschnittenen Fäden ein großes Kunstwerk geschaffen und lässt nicht zu, dass du es wegwirfst. Lass deinen Putzfimmel für einen Moment beiseite. Respektiere das kreative Chaos – aufräumen kannst du auch morgen noch.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'Reiten auf Papas Rücken 🐴', 'Dein Kind konnte seine Energie noch nicht vollständig loswerden und weigert sich, ins Bett zu gehen. Ruf Papa zu Hilfe. Wenn er das Kind auf seinem Rücken reiten lässt, erfüllt lautes Lachen den Raum, und der angestaute körperliche Stress und die scheinbar endlose Energie lösen sich innerhalb weniger Sekunden unter Schweiß und Bewegung auf.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'Die Welt der Märchen 🪄', 'Lass die klassischen Märchen beiseite. Öffne die intelligenten Märchen. Erstelle ein individuelles Märchen.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'Unterstützung aus der Community 💬', 'Du bist völlig erschöpft und möchtest niemandem etwas erklären oder dich aussprechen. Tritt der Anacan-Community bei und lies einfach nur mit. Zu sehen, wie andere Mütter mit denselben absurden Krisen umgehen, kann der stärkste stille Trost sein.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'Der morgendliche Diktator ist im Einsatz 👑', '„Setz dich nicht dorthin, da sitzt mein Teddybär!“ Beim Frühstück bestimmt dein Kind über den ganzen Tisch. Brich seinen Willen nicht abrupt, sondern bewahre das Gleichgewicht und den Frieden im Raum, indem du sagst: „Okay, dein Teddybär sitzt dort und ich sitze hier.“'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'Aufstand gegen den Mittagsschlaf 🥱', 'Dein Kind will nicht ins Bett und weint? Zwing es nicht. Dimme das Licht im Zimmer und rufe eine stille Bilderbuchzeit aus. So schaffst du eine neue Routine, die euch beiden guttut und bei der ihr euch auf unterschiedliche Weise erholen könnt.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'Lass dein Kind die Geschichte schreiben 🪄', 'Ihr habt beide genug von den klassischen Büchern und im Zimmer herrscht eine langweilige Stimmung. Öffne die smarten Märchen und lass dein Kind heute Abend bestimmen, wie die Geschichte weitergeht. Frag: „Wohin soll das fliegende Auto jetzt fahren?“ So kann es im Traum neue Welten erobern.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'Der Rivale im Spiegel 🪞', 'Dein Kind steht vor dem Spiegel, runzelt die Stirn und probiert wütende und seltsame Gesichtsausdrücke aus. Es testet, wie verschiedene Gefühle im Gesicht aussehen. Beobachte ganz leise und mit Freude, wie dieser kleine Theaterstar probt.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'Flüstergespräch mit der Wand 🤫', 'Dein Kind liegt im Bett, hat sich zur Wand gedreht und flüstert jemandem seine Sorgen zu? Wie süß! Schalte das Licht aus, lausche, wie das Flüstern langsam in den Schlaf übergeht, und entspann dich.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'Streit wegen des falschen Bechers? 🥤', 'Im Zimmer ist die Hölle los, weil du das Wasser im gelben Becher serviert hast? Nimm es nicht zu ernst – dein Kind testet heute Morgen einfach seine Grenzen aus. Gieß das Wasser schnell in den blauen Becher, stell den Frieden wieder her und spar dir deine Energie für den Rest des Tages.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'Feindschaft mit dem Staubsauger 🌪️', 'Dein Kind stellt sich dir weinend in den Weg und ruft: „Saug meinen Staub nicht weg!“, während du putzt? Das Besitzgefühl hat absurde Ausmaße erreicht. Schalte den Staubsauger aus und veranstaltet 5 Minuten lang eine Abschiedszeremonie für den Staub. Glaub mir, so ist dieses Chaos schneller vorbei.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'Schon wieder das falsche Outfit 🧥', 'Ihr wollt raus, aber dein Kind möchte Gummistiefel und ein kurzärmeliges Oberteil tragen? Diskutiere nicht. Öffne „Wetter und Kleidung“ und zeig ihm, dass das Handy dieses Outfit nicht erlaubt. Überlass dem Bildschirm die Regel, halte dich heraus – und dein Kind wird sein Oberteil ganz ruhig anziehen.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'Der Traum von einer Tasse Tee ☕', 'Du bist so müde, dass du dich heimlich in die Küche geschlichen und die Tür geschlossen hast, während dein Kind spielt? Verständlich. Öffne dein Stimmungstagebuch und schreib nur zwei Worte: Heute überlebt. Manchmal braucht eine Mama einfach diese 5 Minuten Auszeit.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'Halt die Wolke fest, damit sie nicht wegfliegt! ☁️', 'Dein Kind schaut aus dem Fenster und weint, weil die Wolke weiterzieht? Verschwende keine Zeit mit einer wissenschaftlichen Erklärung des Windes. Sag einfach: „Sie ist losgezogen, um anderen Kindern Hallo zu sagen.“ Begegne dieser ungewöhnlichen Kinderlogik mit Humor und kleinen Fantasiegeschichten – und rette so den Tag.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'Sofaraufen mit Papa 🤼‍♂️', 'Ist dein Kind weggerannt und hat sich versteckt, um nicht ins Bett zu müssen? Dann ist Papa dran. Lass die beiden zum Spaß auf dem Sofa raufen. Dieses laute, schweißtreibende Spiel mit Papa wird auch noch die letzte hartnäckige Energie deines Kindes aufbrauchen, sodass es sich schließlich dem Schlaf ergibt.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'Genug von den perfekten Internet-Mamas? 📵', 'Lass dich nicht entmutigen, wenn du Instagram öffnest und überall nur vermeintlich perfekte Kinder siehst! Schließ die App und geh in die Anacan-Community. Wenn du siehst, dass es bei anderen zu Hause genauso chaotisch und laut zugeht wie bei dir, kannst du tief durchatmen: Du bist nicht allein!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'Das koche ich selbst! 🍳', 'Dein Kind wollte das Ei unbedingt selbst verquirlen und die Hälfte landete auf dem Tisch? Lass es seinen stolzen Küchenchef-Blick genießen. Die Küche muss sowieso geputzt werden – aber seinen wachsenden Selbstwert und seine Selbstständigkeit solltest du nicht bremsen.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c'::uuid, 'Der geheime Nudelvorrat 🍝', 'Beim Waschen der Hose hast du eine vertrocknete Nudel in der Tasche gefunden? Das ist keine Gier, sondern kindliche Vorratsplanung. Wirf sie mit ernster Miene in den Müll, aber lächle innerlich über dein kleines Entdecker- und Sammlerkind. Sie werden so schnell groß!'),
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc', 'Die Zahl der Stille auf dem Display 🤫', 'Endlich schläft dein Kind. Ist es im Haus so still geworden, dass dir die Ohren klingeln? Öffne den Schallpegelmesser in der App. Der Anblick der Anzeige mit 0 Dezibel wird für dein müdes, vom Lärm überreiztes Gehirn die beste visuelle Massage der Welt sein.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'Das Etikett im Shirt piekst! 🏷️', 'Dein Kind will das Shirt nicht anziehen, weil das kleine Etikett hinten wie eine Nadel piekst? Die sensorische Empfindlichkeit mit 3.5 Jahren kann einen wahnsinnig machen. Diskutiere gar nicht erst: Nimm die Schere, schneide das Etikett direkt am Ansatz ab und beende diese Minikrise in Sekundenschnelle.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'Das war mein Stein! 🪨', 'Dein Kind schreit verzweifelt, weil du den schmutzigen Stein weggeworfen hast, den es aus dem Park mitgebracht hatte? Offenbar war er sein bester Freund. Such sofort einen anderen glänzenden Gegenstand und rette die Situation geschickt mit einer erfundenen Geschichte: „Schau, der Stein hat dir das als Erinnerung geschickt!“'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'Meine Geschichte, meine Regeln 📖', 'Du hast beim Vorlesen ein Wort falsch gesagt und wurdest sofort korrigiert? Dann kennt dein Kind die Geschichte wohl auswendig! Klapp das Buch zu und sag: „Dann liest du mir heute Abend vor.“ Lass seine Fantasie arbeiten, während du dich einfach hinlegst und seiner Stimme lauschst.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'Überschwemmung in der Badewanne 🌊', 'Baden ist nur ein Vorwand – in Wirklichkeit erschafft dein Kind in der Wanne einen Ozean und spielt mit den Wellen? Lass es spielen. Das Plätschern und Spritzen wird seine unerschöpfliche, unbändige Energie fortspülen. Abends wird es sich ohne Widerstand ins Bett legen.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'KI-Antworten auf ungewöhnliche Fragen 🤖', 'Mama, wo geht mein Schatten nachts hin? Hat dich diese Frage sprachlos gemacht? Denk dir nichts aus. Öffne die Anacan AI und lass dir die märchenhafteste, liebevoll erklärte wissenschaftliche Antwort für ein 3,5-jähriges Kind geben, um sie ihm vorzulesen. So fühlst du dich wie eine große Philosophin und eine Mama, die alles weiß.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'Stolz auf links getragen 👕', 'Dein Kind hat sein Shirt auf links angezogen und lässt dich partout nichts daran ändern? Seine Sache! Das Selbstvertrauen in seinem „Ich hab’s geschafft!“-Blick ist wichtiger, als das Shirt richtig herum zu tragen. Lass es den ganzen Tag stolz so herumlaufen – es ist seine Entscheidung.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'Mit Flüstern in den Schlaf 🤫', 'Dein Kind steht immer wieder auf, rennt im Zimmer herum und will nicht schlafen? Schimpf nicht. Fang plötzlich an, ganz leise zu flüstern. Um dich zu verstehen, muss es sich so stark konzentrieren, dass sein Gehirn müde wird und automatisch in den Schlafmodus wechselt. Probier es aus!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'Ein Moment vollkommener Ruhe 🛋️', 'Dein Kind ist so in sein Puzzle vertieft, dass es im Haus plötzlich still geworden ist? Werde nicht misstrauisch, sondern schenk dir sofort einen Kaffee ein. Nutze diese seltenen, kostbaren Minuten nicht zum Putzen oder Wäschemachen, sondern um zur Ruhe zu kommen. Du bist kein Roboter.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'Mini-Labor in der Badewanne 🛀', 'Dein Kind mischt verschiedenfarbige Seifen ins Wasser und braut einen Zaubertrank. Ja, das Bad wird dabei nass und chaotisch. Aber es lernt etwas über Lösungsmittel und darüber, wie sich Stoffe vermischen. Diese wissenschaftliche Entdeckungsreise vertreibt die Müdigkeit des Abends und bereitet es wunderbar auf einen ruhigen Schlaf vor.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'Rebellion gegen Berührungen 🔋', 'Du bist körperlich völlig erschöpft, weil dein Kind den ganzen Tag an dir hochgeklettert ist und an deinen Haaren gezogen hat. Bring es an einen sicheren Ort und geh kurz in ein anderes Zimmer. Schreib „Mein Körper gehört nicht mir“ in dein Stimmungstagebuch und lass so die psychische Belastung des Touched-out-Syndroms los.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'Sozialer Rückzug im Kleiderschrank 🚪', 'Mitten im Alltag ist es im Haus plötzlich still geworden. Du findest dein Kind allein im dunklen Kleiderschrank spielend. Das ist keine Depression, sondern einfach ein Moment, in dem es sich emotional neu sortiert. Schließ die Tür sanft und gönn ihm den Luxus dieses privaten Rückzugsortes.'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'Die Suppendetektivin im Einsatz 🥕', 'Hat dein Kind den Löffel in die Suppe gesteckt, zielgenau ein einziges Stück Zwiebel gefunden und beiseitegelegt? Das ist die Präzision eines Juweliers! Schau gleich bei den gesunden Rezepten vorbei und erfahre, wie du ab morgen Gemüse pürieren und in Soßen verstecken kannst – und so heimlich gewinnst.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'Gemeinsam schweigen als Paar 🥂', 'Das Kind schläft, die Wohnung ist aufgeräumt. Setz dich neben deinen Partner aufs Sofa und schaltet nicht einmal den Fernseher ein. Werft euch einfach diesen Blick zu, der sagt: „Auch das haben wir geschafft, wir haben überlebt.“ Glaub mir, genau das ist einer der romantischsten und ehrlichsten Momente des Elternseins.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', 'Das gefürchtete „Ich will das!“ im Supermarkt 🛒', 'Dein Kind schreit direkt vor der Kasse nach Schokolade? Gib trotz der Blicke der anderen nicht nach. Öffne die Einkaufsliste und sag: „Das steht hier nicht drauf, die Kasse wird es nicht akzeptieren.“ Eine äußere Autorität wirkt auf Kinder oft überzeugender.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'Warum hast du mit mir gesprochen? 😤', 'Dein Kind ist wütend geworden, nur weil du „Guten Morgen“ gesagt hast? Die Phase des grundlosen Schmollens läuft weiterhin auf Hochtouren. Dräng es nicht, sondern schenk dir in Ruhe einen Tee ein. Du kannst sicher sein: Zwei Minuten später kommt es und klammert sich an deine Beine. Seine Gefühle sind einfach völlig durcheinander!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'Das Kind auf allen vieren 🐾', 'Ist dein Kind heute Morgen nicht wie ein Kind, sondern wie ein Hund auf allen vieren aus dem Bett gekrochen? Reg dich nicht mit Regeln auf. Sag einfach: „Brav, mein schlaues Hündchen“, und gib ihm sein Frühstück. Bei Rollenspielen mitzumachen spart viel mehr Energie, als sich auf einen Machtkampf einzulassen.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'Plötzliches Schreien mitten in der Nacht 😭', 'Ist dein Kind nachts weinend aufgeschreckt, hat die Augen geschlossen und reagiert nicht auf dich? Prüfe es mit der Schreianalyse: Das ist ein Nachtschreck. Versuch nicht, es aufzuwecken. Bleib einfach bei ihm, halte seine Hand und streichle es. Es wird sich von selbst beruhigen und wieder tief einschlafen.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'Mein Körper gehört nicht mir 🔋', 'Klammert sich dein Kind den ganzen Tag an deine Beine und will ständig auf den Arm? Du bist körperlich erschöpft. Du leidest unter Berührungsüberlastung (touched out). Lass es mit seinen Spielsachen im Zimmer und zieh dich für fünf Minuten ins Bad zurück, um einfach kurz allein zu sein. Das ist dein gutes Recht.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'Ich mache die Tür auf! 🚪', 'Hat dein Kind beim Hinausgehen geweint und dich gezwungen, die Tür wieder zu schließen, nur weil du sie geöffnet hast? Das Gefühl von Kontrolle ist in diesem Alter eines der wichtigsten psychischen Bedürfnisse. Lass es dich eine Minute kosten – dafür verhinderst du draußen einen 30-minütigen Wutanfall und stärkst gleichzeitig sein Selbstvertrauen.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'Handydieb 📱', 'Als du dir gerade Tee einschenkst, stellst du fest, dass dein Handy verschwunden ist – und hinter dem Sofa genau wie du „Hallo“ sagt. Dein Baby scannt gerade deine digitalen Gewohnheiten.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', 'Die „Zieh dich selbst an!“-Politik 👖', 'Dein Baby streckt die Beine in die Luft und sagt: „Ich bin ein Baby, du musst mich anziehen!“ Kinder schwanken zwischen Selbstständigkeit und Abhängigkeit. Zieh es nicht mit Gewalt an. Lege die Kleidung daneben und trickse es mit den Worten aus: „Diese Superheldenhose wartet auf ihren Besitzer.“'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'Innere Ruhe dank Schallpegelmesser 🤫', 'Endlich schläft dein Baby. Doch das Klingeln in deinen Ohren hört nicht auf. Öffne den Schallpegelmesser in der App. Beobachte die Anzeige „0 Dezibel“ auf dem Bildschirm und sieh, wie die Stille im Raum in dein Gehirn eindringt und dich erholt.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'Trost in der Anacan-Community 💬', 'Erdrückt dich das Gefühl, niemals perfekt sein zu können? Verabschiede dich von der Illusion der Instagram-Mamas. Schau in der Anacan-Community vorbei, lies die ehrlichen Geständnisse von Müttern, deren Zuhause im Chaos versinkt und deren Kind die Wände bemalt, und sage dir: „Ich bin völlig normal.“'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'Die mystische Kraft des Flüsterns 🌙', 'Dein Kind erfindet Ausreden, um nicht ins Bett zu müssen. Senke deine Stimme ganz ab und sprich nur noch flüsternd. Um dich zu verstehen, muss es sich bewusst konzentrieren – und diese Fokussierung wird sein Gehirn beinahe hypnotisieren und es einschlafen lassen.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'Dinosaurierlogik 🦖', 'Am Morgen beantwortet dein Kind keine einzige Frage, sondern brüllt nur. Heute ist es ein T-Rex. „Essen T-Rexe eigentlich Brei?“ Spiele bei dieser erfundenen Rolle mit und bringe das Morgenritual ganz ohne Tränen hinter euch.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'Papas erfundene Helden 🦸‍♂️', 'Vergesst heute Abend die Märchen aus den Büchern. Papa soll eine fantasievolle, fantastische Geschichte erzählen, in der das Kind selbst die Hauptfigur ist. Sätze wie „Und dann zog es sein Schwert und ... putzte sich die Zähne!“ bringen das Kind zum Lachen und stimmen es aufs Schlafengehen ein.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'Kritik am eigenen Bild 🖍️', 'Dein Kind zeigt dir sein schwarzes Gekritzel, sagt: „Das warst du, aber es ist schlecht geworden“, und zerreißt es. Es entwickelt gerade die Fähigkeit zur Selbstkritik! Spiele seine Gefühle nicht herunter, sondern unterstütze seine Entwicklung mit einem Vorschlag wie: „Vielleicht probierst du beim nächsten Bild auch mal Rot aus?“'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', 'Das habe ich im Supermarkt gefunden 🛒', 'Kurz vor der Kasse taucht im Einkaufswagen plötzlich eine Packung Kekse auf, die du nicht hineingelegt hast. Dein Kind war heimlich auf Entdeckungstour. Öffne die Einkaufsliste und überlasse die Entscheidung einer digitalen Autorität: „Schau, das steht nicht auf unserer Liste. Beim nächsten Mal schreiben wir es auf.“'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'Die Möbelkletter-Olympiade 🧗‍♂️', 'Dein Kind klettert über die Sofakante in Richtung Fenster. Für dich steckt die Wohnung voller Gefahren, für dein Kind ist sie ein Fitnessstudio. Statt mit „Vorsicht, du fällst!“ Panik zu verbreiten, lenke seinen Bewegungsdrang mit einer konkreten Anweisung wie „Setz deine Hand dorthin“ in sichere Bahnen.'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'Operation verstecktes Gemüse 🥦', 'Dein Kind findet selbst das eine Reiskorn oder Stückchen Karotte in der Suppe und sagt: „Das esse ich nicht.“ Öffne den Ernährungsplan. Dort erfährst du, wie du Proteine und Gemüse in bunte Küchlein verwandelst und so das Köpfchen dieses eigensinnigen kleinen Feinschmeckers überlistest.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'Teezeit zu zweit 🥂', 'Gießt euch nach einem anstrengenden Tag einfach heißen Tee in die Gläser. Setzt euch auf dem Sofa einander gegenüber, stoßt an und sagt: „Auch dieses Chaos haben wir heute überstanden. Wir sind ein großartiges Team!“ Ihr seid das unerschütterliche Fundament eures Zuhauses.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'Angst vor dem eigenen Schatten 👻', 'Beim Spazierengehen erschrickt dein Kind plötzlich vor seinem eigenen Schatten und versteckt sich hinter dir. Suche nicht nach Logik – so funktioniert die Fantasie mit 3.5 Jahren. Sag: „Komm, wir springen auf den Schatten!“ So verwandelst du das, wovor es sich fürchtet, sofort in ein Bewegungsspiel.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'Künstliche Intelligenz und Gelassenheit 🤖', 'Das plötzlich auftretende Stottern oder die Wutanfälle deines Kindes haben dich dazu gebracht, im Internet nach schlimmen Krankheiten zu suchen? Stopp! Frage Anacan AI, ob es sich um einen Entwicklungsschub im Alter von 3 Jahren handeln könnte, und erhalte eine beruhigende, kinderärztlich geprüfte Antwort.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'Geräuscheffekte im Kinderzimmer 🪄', 'Öffne die smarten Märchen. Lass beim Vorlesen einfach eine Tür knarren, den Wind rauschen oder ein leises Flüstern erklingen und verwandle das Zimmer so in ein kleines Hörtheater. Diese ungewöhnliche Klangwelt zieht dein Kind sofort mitten in die Geschichte hinein – und von dort aus in einen tiefen Schlaf.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'Die Mitte des Brotes gehört mir! 🍞', 'Isst dein Kind nur die weiche Mitte einer Brotscheibe und reicht dir die Rinde? Diskutiere nicht über die Ränder. Stich das Brot ab morgen mit Ausstechformen aus Metall aus, zum Beispiel in Tierform. Ein schönes Design löst dieses kleine Ernährungsproblem im Handumdrehen.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'Atme einfach seinen Duft ein 🫂', 'Hat dein Kind dich heute wirklich in den Wahnsinn getrieben und dir die ganze Energie geraubt? Aber wie unschuldig es jetzt im Bett schläft ... Mach das Licht aus und lies heute keine Geschichte vor. Leg dich zu ihm, atme diesen unverwechselbaren Kinderduft ganz tief ein und sei auch für diesen Tag dankbar.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'Ich will nicht raus! ⛅', 'Dir fällt zu Hause die Decke auf den Kopf, aber dein Kind liegt weinend auf dem Sofa und will nicht nach draußen? Öffne „Wetter und Kleidung“, wähle das passende Outfit aus und nimm es mit in den Park – notfalls auch gegen seinen Willen. Sobald es die frische Luft im Gesicht spürt, ist die ganze schlechte Laune wie weggeblasen. Du schaffst das!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'Das Gesetz der getrennten Lebensmittel 🚫', 'Beim Frühstück gibt es einen Aufstand, weil die Tomate die Gurke berührt hat? Willkommen in der offiziellen Ernährungsphilosophie mit 3.5 Jahren. Such nicht nach Logik: Entdecke unter „Gesunde Rezepte“, wie du den Teller in lustige, streng getrennte Bereiche aufteilen und diese absurde Krise friedlich lösen kannst.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'Diplomatische Verhandlungen zur Schlafenszeit 🤝', 'Um nicht ins Bett gehen zu müssen, verhandelt dein Kind ganz offiziell mit dir: noch zwei Schlucke Wasser, noch eine Umarmung, dann schlafe ich. Schmunzle über diese geschickte Manipulation. Akzeptiere die Bedingungen, mach entschlossen das Licht aus und besiegle den Vertrag auf der Stelle.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'Der Boden ist Lava 🌋', 'Der Boden ist Lava, schnell aufs Sofa! Die Fantasie hat euer Zuhause in einen Dschungel verwandelt. Lass deine Aufgaben kurz liegen und tauche in die Welt deines Kindes ein, indem du wenigstens 2 Minuten lang mit ihm vor der Lava flüchtest. Manchmal ist es der beste Stressabbau, nach den Regeln des Kindes zu spielen.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'Geheimnisse aus dem Mülleimer 🗑️', 'Dein Kind spielt den ganzen Tag nicht mit dem gekauften Spielzeug, sondern mit der Luftpolsterfolie, in die es eingewickelt war? Das kindliche Gehirn liebt keine fertigen Spielideen, sondern Freiheit. Halte diese ungewöhnlich kreativen Momente stolz im Entwicklungstracker fest.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'Entspannte Momente am Abend 🛀', 'Nach all den Warum-Fragen des Tages brummt dir der Kopf. Setz dein Kind in eine Wanne mit warmem Wasser und gib etwas Badeschaum hinein. Setz dich daneben und konzentriere dich einfach auf das Plätschern des Wassers. Seine magische Wirkung spült nicht nur die Trotzreaktionen deines Kindes weg, sondern beruhigt auch deine Nerven.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'Du hörst mir nicht zu! 😤', '„Hör mir zu!“, sagt dein Kind und dreht dein Gesicht mit seinen Händen zu sich. Es will nicht nur, dass du körperlich anwesend bist, sondern deine 100%ige Aufmerksamkeit. Leg dein Handy oder deine Arbeit für nur 3 Minuten beiseite, sieh ihm in die Augen und hör aufmerksam zu. So kannst du stundenlangem Quengeln vorbeugen.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'Gespräche mit leblosen Dingen 🗣️', 'Dein Kind erzählt einem Stein im Park oder einem Stuhl zu Hause mit völligem Ernst etwas und schimpft sogar mit ihnen. Durch symbolisches Spielen verarbeitet es die Welt.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'Versteckspiel am frühen Morgen 🙈', 'Ihr seid spät dran für die Arbeit oder den Kindergarten, aber dein Kind versteckt sich hinter dem Vorhang und ruft: „Such mich!“ Auch wenn deine Nerven blank liegen, würde Schimpfen alles nur noch länger hinauszögern. Spiel einfach zwei Minuten mit und frag: „Wo ist denn mein süßer Schatz?“ Dann findest du dein Kind und holst es aus seinem Versteck.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'Diplomatie auf dem Spielplatz 🤝', 'Dein Kind schubst an der Rutsche ein anderes Kind weg, weil es selbst rutschen möchte? Teilen und Abwechseln sind für es noch schwierige Konzepte, die es erst lernen muss. Statt es zu beschämen oder zu bestrafen, erinnere es einfach an die Regel: „Jetzt ist das andere Kind dran.“'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'Warum schaut mich die Sonne an?! ☀️', 'Dein Kind öffnet morgens die Augen und weint bitterlich: „Warum schaut mir die Sonne direkt in die Augen?“ Versuch nicht, nach Logik zu suchen oder Naturphänomene zu erklären. Es ist einfach wütend, weil es die Welt nicht kontrollieren kann. Zieh den Vorhang zu und sag: „Ich habe die Sonne für dich versteckt.“ So löst du dieses absurde Problem in Sekundenschnelle.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'Mein Auto schläft noch nicht! 🚗', 'Dein Kind weigert sich, ins Bett zu gehen, und behauptet: „Mein Auto ist noch nicht müde“? Kinder übertragen ihre eigene Müdigkeit und ihren Widerstand oft auf ihre Spielsachen. Diskutiere nicht, sondern öffne die schlauen Märchen und erfinde eine Geschichte über Autos. Sobald das Auto eingeschlafen ist, wird auch dein Kind ganz von selbst die Augen schließen. Probier es aus!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'Die Brotrinde muss ab! 🍞', 'Dein Kind isst nur den weichen Teil des Toasts und lehnt die Ränder entschieden ab? In diesem Alter spielt die Optik eine ganz besondere Rolle. Schneide das Brot in niedliche Tierformen. Das kreative Design wird diesen Streit im Handumdrehen beenden.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'Der Genuss stiller Blicke 🥂', 'Das Kind schläft, die Wohnung ist aufgeräumt. Setzt euch nebeneinander aufs Sofa und lasst sogar den Fernseher aus. Werft euch einfach diesen „Wir haben auch diesen Tag überlebt“-Blick zu. Glaub mir: Genau das ist einer der romantischsten und authentischsten Momente im erschöpften Elternalltag.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'Das Drama um den unsichtbaren Fleck 👕', 'Dein Kind hat auf seinem Oberteil einen Fleck entdeckt, den man nur unter dem Mikroskop sehen könnte, und weigert sich nun, es anzuziehen? Tu so, als würdest du den Fleck mit einem Feuchttuch wegwischen, und sag: „Ich habe ihn weggezaubert.“ Kinder glauben immer an Mamas Zauberkraft – probier es aus.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'Schattentheater im dunklen Zimmer 🐰', 'Hat dein Kind Angst vor der Dunkelheit und will nicht ins Bett? Schalte das Licht im Zimmer ganz aus und eine kleine Taschenlampe ein. Forme mit deinen Händen Hunde- und Vogelschatten an der Wand. Verwandle die beängstigende Dunkelheit in einen Spielplatz – dann ist das Einschlafen nur noch eine Frage der Zeit.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'Dinosaurier essen keinen Brei! 🦖', 'Beantwortet dein Kind morgens keine einzige Frage, sondern brüllt nur? Heute ist es ein T-Rex. Frag: Essen T-Rexe eigentlich Frühstück? Lass dich auf diese erfundene Rolle ein – so setzt es sich ganz ohne Tränen an den Tisch.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'Heute bin ich am Ende 🛑', 'Alles kam auf einmal und du bist laut geworden. Jetzt hast du ein schlechtes Gewissen. Du bist kein Roboter. Öffne dein Stimmungstagebuch und schreibe: Heute war ich wirklich erschöpft. Dieses Eingeständnis wird dir mehr helfen, als dich zu einem falschen Lächeln zu zwingen.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'Das „Wer bist du?“-Spiel 🎭', 'Hat dein Kind dich heute Morgen wie eine Fremde angesehen und gefragt: Wer bist du? Wo ist meine Mama? Das ist ein neues Rollenspiel. Sag: Ich bin die Nachbarin, deine Mama kommt gleich. Lass das Zimmer morgens vor Lachen beben – das spart viel mehr Energie als ein Machtkampf.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'Einschlafen ohne Gute-Nacht-Geschichte 🪄', 'Hast du heute Abend keine Kraft mehr, eine Geschichte vorzulesen? Öffne die smarten Märchen. Lass im Hintergrund nur die Geräusche des flüsternden Waldes und des Windes laufen. Hört euch in der Dunkelheit gemeinsam die Naturklänge an und erholt euch vom Lärm. Auch deine Augen können sich dabei sofort entspannen.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'Der vergessene Schatz in der Waschmaschine 🍝', 'Hast du beim Waschen der Hose trockene Nudeln oder einen Stein in der Tasche gefunden? Das ist keine Gier, sondern kindlicher Entdeckergeist. Wirf den Fund mit ernster Miene in den Müll, aber lächle innerlich über dein kleines Vorratskind. Halte es im Entwicklungstracker als lustigen Moment fest.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'Gib das Wasser in einem anderen Becher! 🥤', 'Im Zimmer ist die Hölle los, weil du das Wasser im gelben Becher serviert hast? Mach kein großes Thema daraus – dein Kind testet gerade nur seine Grenzen aus. Gieß das Wasser einfach sofort in den gewünschten Becher. So kehrt Frieden ein und du sparst deine Energie für den Rest des Tages.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'Der Wettkampftrick für den Abschied vom Park 🌳', 'Es ist Zeit, den Park zu verlassen, und schon beginnt der Tränenausbruch. Dein Kind wegzuzerren, wird nicht helfen. Frag: Wer schafft es schneller, wie ein Pinguin zum Auto zu watscheln? So lenkst du seine Aufmerksamkeit sofort auf einen lustigen Wettkampf. Es wird unbedingt gewinnen wollen.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'Mitternachtsphilosophie 🦉', 'Kaum liegt dein Kind im Bett, stellt es tiefgründige Fragen wie: „Mami, warum fallen die Wolken nicht herunter?“ Dabei geht es nicht darum, etwas über Wissenschaft zu lernen, sondern mit dir zu reden und das Einschlafen hinauszuzögern. Gib eine kurze, erfundene Antwort wie „Weil sie dort oben schlafen“, schalte die sanfte Melodie aus den Schlauen Märchen ein und sorge entschlossen für Ruhe zur Schlafenszeit.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'Diese schockierende Frage im Supermarkt 😳', 'Hat dein Kind mitten in der Kassenschlange laut gefragt: „Warum sehen die Haare dieser Frau so aus?“ Beschäme es nicht und zwinge es nicht zum Schweigen. Lenke seine Aufmerksamkeit sofort auf die Einkaufsliste in der App: „Lass uns nachsehen, ob wir die Äpfel schon eingepackt haben.“ So kannst du dich diplomatisch aus der Situation retten.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'Warum wurde ausgerechnet dieses T-Shirt gewaschen?! 👕', 'Bei euch zu Hause herrscht Trauerstimmung, weil du das geliebte, längst verwaschene T-Shirt in die Waschmaschine gesteckt hast? Die Bindung von Kindern an Gegenstände ist manchmal stärker als jede Logik. Diskutiere nicht, sondern öffne sofort das Baby-Fotoshooting und fotografiere dein Kind mit seinem wütenden Gesicht. Mit dem Trick „Komm, wir schauen mal, wie wütend du auf dem Bildschirm aussiehst“ wird aus dem Ärger schnell ein Lachen und dein Kind ist sofort abgelenkt. Probier es aus!'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'Licht aus, Schattentheater an 🐰', 'Dein Kind hat Angst im Dunkeln und möchte nicht allein auf den Flur gehen? Schalte das Licht im Zimmer ganz aus und knipse eine kleine Taschenlampe an. Forme mit deinen Händen Hunde und Vögel als Schatten an der Wand und verwandle die Dunkelheit von einem unheimlichen Ort in einen Spielplatz. Dann schläft dein Kind bestimmt im Nu ein.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'Auch du musst mal offline sein ☕', 'Dein Kind ist so sehr ins Spielen mit seinen Spielsachen vertieft, dass es zu Hause plötzlich ganz still ist? Bitte verschwende diesen Moment nicht mit Staubsaugen oder Wäschefalten! Leg dich aufs Sofa, schreibe einfach „5 Minuten Frieden“ ins Stimmungstagebuch und trink deinen Kaffee, solange er heiß ist. Auch du bist ein Mensch in diesem Zuhause.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'Ich war das nicht, das war mein Teddy! 🧸', 'Dein Kind hat absichtlich Wasser auf den Boden geschüttet und gibt nun seinem Kuscheltier die Schuld? Es lügt nicht, sondern hat gerade den Schutzmechanismus eines 3.5-jährigen Kindes entdeckt. Lass dich nicht auf einen Machtkampf ein. Sag stattdessen: „Dann zeigen wir deinem Teddy mal, wie man das sauber macht“, und gib deinem Kind ein Handtuch. So lernt es, Verantwortung zu übernehmen, ohne dass sein Selbstwertgefühl verletzt wird.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'Trotz, der die Gesetze der Physik herausfordert 💧', 'Dein Kind hat Wasser auf dem Tisch verschüttet und verlangt nun weinend von dir, es wieder ins Glas zu füllen! Ja, hier hat Logik gerade keinen Platz – dein Kind ist einfach nur enttäuscht über einen Fehler, der sich nicht rückgängig machen lässt. Versuche nicht, es zu erklären. Gib ihm ein Handtuch, sag: „Komm, wir lassen das Wasser verschwinden“, und mach ein Spiel daraus.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'Ein Offline-Rückzugsort für Mama 🚪', 'Der Lärm lässt deine Ohren klingeln. Bring dein Kind an einen sicheren Ort oder lass es kurz bei seinem Papa, geh ins Bad und schließe die Tür. Schau einfach 5 Minuten lang die Wand an und tu nichts – nimm nicht einmal dein Handy in die Hand. Diese kurze Ruhepause ist deine stärkste Geheimwaffe, um neue Kraft für deine Rolle als Mama zu schöpfen.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'Papa im Flugmodus ✈️', 'Zu Hause konnte dein Kind seine Energie nicht loswerden und will nicht ins Bett. Ruf Papa aufs Sofa. Wenn er das Kind in die Luft hebt und mit ihm Flugzeug spielt, lässt das schallende Lachen die ganze angestaute körperliche Anspannung innerhalb von Sekunden verschwinden. Jetzt ist Papa am Zug.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'Eine neue Sprache entsteht 🗣️', 'Dein Kind erfindet völlig neue, poetische Sätze wie „Mein Spielzeug ist traurig“ oder „Der Himmel hat geweint“ und überträgt dabei Gefühle auf Gegenstände. Sein Wortschatz und seine emotionale Intelligenz entwickeln sich rasant. Halte diese süßen philosophischen Gedanken gleich im Videomodus des Baby-Fotoshootings fest.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'Der Küchenchef bei der Arbeit 🧑‍🍳', 'Wenn du Muffins backst, will dein Kind unbedingt auf einem Stuhl neben dir stehen und das Mehl selbst hineinschütten. Wenn du es lässt, wird die Küche im Chaos versinken. Gib ihm eine leere Schüssel, Wasser und etwas Mehl und sag: „Knete du den Teig für deinen eigenen Muffin.“ Es wird chaotisch, aber sein Stolz wird grenzenlos sein.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', 'Die „Iss doch selbst!“-Rebellion 🥣', 'Obwohl dein Kind selbst essen kann, besteht es hartnäckig darauf, von dir gefüttert zu werden – nur um dann den Löffel wegzuschieben und zu weinen. Das ist eine Phase voller Widersprüche. Versuch weder, es unbedingt zu füttern, noch hab Angst, dass es hungrig bleibt. Stell den Teller vor dein Kind, sag: „Du kannst essen, wenn du Hunger hast“, und steh vom Tisch auf. Es wird selbst essen.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'Mamas Energiereserven 🥗', 'Du hast dir verschiedene Gerichte ausgedacht, damit dein Kind satt wird – aber hast du selbst wieder nur im Stehen etwas Trockenes gegessen? Tu dir etwas Gutes und wähle bei den gesunden Rezepten ein energiespendendes Mittagessen, das reich an Eisen und Kalzium ist, in 10 Minuten zubereitet werden kann und nicht nur Kindern, sondern auch Mamas guttut.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'Das „Mein Spielzeug ist krank“-Spiel 🩺', 'Dein Kind nimmt sein Spielzeugstethoskop, untersucht seinen Teddybären ganz ernst und klebt ihm ein Pflaster auf. Durch Rollenspiele verarbeitet und entwickelt es Mitgefühl und Fürsorge. Leg dich als Patientin im Krankenhaus hin und lass dich 5 Minuten lang in aller Ruhe untersuchen.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'Sanft einschlafen mit cleveren Märchen 🪄', 'Die klassischen Bücher kennst du schon auswendig. Öffne die cleveren Märchen, mach dein Kind zur Hauptfigur und sein Zimmer zu dem Ort, den es zu erobern gilt. So entsteht ganz mühelos ein außergewöhnliches Einschlafritual.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'Einfach nur kuscheln 🫂', 'Heute braucht es weder ein Spiel noch ein Buch oder Märchen. Drück dein Kind heute Abend einfach fest an deine Brust, atme seinen wunderbaren Duft tief ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist und wie sehr du es liebst.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'Sofaraufen mit Papa 🤼‍♂️', 'Ist dein Kind weggerannt und hat sich versteckt, um nicht ins Bett zu müssen? Dann übergib an Papa. Lass die beiden auf dem Sofa spielerisch miteinander raufen. Dieses laute, schweißtreibende Spiel wird auch die letzte überschüssige Energie deines Kindes aufbrauchen, sodass es sich leichter dem Schlaf hingibt.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'Der hypnotische Effekt von Musik 🎶', 'Versuche, grundlose Wutanfälle am späten Nachmittag mit sanfter klassischer Musik zu beruhigen. Schalte den Fernseher aus. Oft übertönt dieser einfache Trick die Reizüberflutung, und wie durch ein Wunder kehrt Ruhe im Zimmer ein.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'Selbst erfundene Sätze 🗣️', 'Dein Kind bildet ungewöhnliche Sätze wie „Der Himmel hat geweint“ oder „Das Auto ist beleidigt“. Sein Wortschatz wächst rasant, und es spielt mit Wörtern. Öffne den Entwicklungstracker und halte diese süßen, poetischen Weisheiten fest – in ein paar Jahren werdet ihr herzlich darüber lachen.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'Kein schlechtes Gewissen wegen der Bildschirmzeit 📺', 'War heute viel los und dein Kind saß deshalb länger vor dem Fernseher? Plagt dich jetzt das schlechte Gewissen? Du kannst nicht jeden Tag perfekt sein. Manchmal sind Bildschirme die harmlosesten Babysitter, die uns vor völligem Chaos bewahren. Sei nicht so streng mit dir.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'Wenn plötzlich seltsame Ängste auftauchen 🤖', 'Hat dein Kind plötzlich Angst vor dem Abfluss in der Badewanne? Suche nicht im Internet nach Krankheiten. Frag Anacan AI und erfahre, dass dies eine völlig normale, vorübergehende Angst ist, die durch die lebhafte Fantasie in diesem Alter entsteht. So kannst du deine Sorgen schnell beruhigen.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'Ich esse selbst! 🥣', 'Obwohl dein Kind selbst essen kann, besteht es darauf, dass du es fütterst. Hältst du ihm aber den Löffel hin, schiebt es ihn weg und weint. Es weiß selbst nicht, was es will. Stell den Teller vor dein Kind, sag „Du kannst essen, wenn du Hunger hast“, und steh vom Tisch auf. Wenn es hungrig ist, wird es selbst essen.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'Nimm dir auch etwas Zeit für dich 💆‍♂️', 'Bitte deinen Partner nach dem Einschlafen des Kindes um eine 10-minütige Schultermassage. Vom ganzen Trubel des Tages ist dein Nacken völlig verspannt. Ihr seid nicht nur Eltern, die im selben Haus leben, sondern auch die engsten emotionalen Stützen füreinander.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'Instagram-Mamas und die Realität 📱', 'Lass dich nicht entmutigen, wenn du auf Instagram sofort die scheinbar perfekten Kinder aller anderen siehst! Schließ die App und besuche die Anacan-Community. Dort wirst du sehen, dass es bei allen zu Hause genauso chaotisch ist wie bei dir und ihre Kinder genauso laut sind. Dann kannst du dir sagen: „Ich bin völlig normal!“'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'Beim Klingeln geht’s ins Bett ⏱️', 'Das Zubettgehen zieht sich immer länger hin. Wasser, Toilette, sich von der Wand verabschieden ... Stell den Timer deines Handys und führt die Regel ein: Sobald es klingelt, machen alle das Licht aus. Wenn dein Kind das Signal hört, wird es ohne Einwände ins Bett gehen.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'Ein Kind auf allen vieren 🐾', 'Ist dein Kind heute Morgen nicht wie ein Kind, sondern wie ein Hund aus dem Bett gekrabbelt? Reg dich nicht auf und halte ihm keine Standpauke. Sag einfach: „Fein gemacht, mein schlaues Hündchen“, und gib ihm Frühstück. Bei Rollenspielen mitzumachen kostet viel weniger Energie als ein Machtkampf.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'Mein Körper gehört nicht mehr mir 🔋', 'Klammert sich dein Kind den ganzen Tag an dein Bein und will ständig auf den Arm? Du bist körperlich erschöpft und leidest unter Berührungsüberlastung. Lass es mit seinen Spielsachen im Zimmer und zieh dich für 5 Minuten ins Bad zurück. Schließ die Tür und genieße einfach das kurze Alleinsein.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'Plötzliches Schreien mitten in der Nacht 😭', 'Ist dein Kind nachts mit geschlossenen Augen weinend aufgeschreckt und reagiert nicht auf dich? Wenn es dabei wie im Schlaf wirkt, kann das ein Nachtschreck sein. Versuch nicht, es zu wecken. Bleib einfach bei ihm, halte seine Hand und streichle es sanft. Es wird sich von selbst beruhigen und wieder tief einschlafen.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'Küchenchaos mit kleiner Hilfe 🧑‍🍳', 'Du rollst Teig aus, da schiebt dein Kind seinen Stuhl heran und will unbedingt selbst das Mehl hineinschütten? Wenn du es nicht lässt, wird es weinen. Gib ihm eine kleine Plastikschüssel und etwas Mehl. Die Küche wird danach zwar chaotisch aussehen, aber dieser ernste Gesichtsausdruck deines kleinen Küchenchefs ist das Aufräumen wert.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'Ich mache die Tür auf! 🚪', 'Hat dein Kind beim Verlassen des Hauses geweint, weil du die Tür geöffnet hast, sie wieder schließen lassen und dann selbst geöffnet? Das Gefühl, selbst bestimmen zu können, ist in diesem Alter eines der größten psychischen Bedürfnisse. Nimm dir dafür 1 Minute mehr Zeit und erspare euch so möglicherweise einen 30-minütigen Wutanfall draußen.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'Mitten im Supermarkt wie eingefroren 🛒', 'Standest du schon einmal mitten im Supermarkt und hast überlegt: „Was wollte ich noch mal kaufen?“ Der Kopf einer Mutter ist tatsächlich randvoll. Öffne einfach die Einkaufsliste in der App und vertrau diesem digitalen Gedächtnis – so findest du leichter aus dem Chaos heraus.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'Überschwemmung in der Badewanne 🌊', 'Ist Baden nur ein Vorwand und dein Kind erschafft in der Wanne eigentlich einen Ozean, um mit den Wellen zu spielen? Lass es spielen. Das Plätschern und Spritzen hilft ihm, seine scheinbar unerschöpfliche Energie abzubauen. Am Abend wird es sich ohne großen Widerstand ins Bett legen.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'Der perfekte Moment der Stille 🛋️', 'Dein Kind spielt so vertieft mit seinen Puzzles, dass es zu Hause plötzlich ganz still ist? Werde nicht misstrauisch, sondern schenk dir sofort einen Kaffee ein. Nutze diese seltenen, kostbaren Minuten nicht zum Putzen oder Wäschewaschen, sondern um zur Ruhe zu kommen und einfach an die Decke zu schauen. Du bist kein Roboter.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'Das Etikett im Shirt kratzt! 🏷️', 'Dein Kind will es nicht anziehen, weil das kleine Etikett am Rücken wie eine Nadel piekst? Die sensorische Empfindlichkeit in diesem Alter kann einen wahnsinnig machen. Diskutiere gar nicht erst, nimm eine Schere, schneide das Etikett ganz ab und beende diese Minikrise in Sekundenschnelle.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'Mit Flüstern in den Schlaf 🤫', 'Dein Kind steht immer wieder aus dem Bett auf, rennt durchs Zimmer und will nicht schlafen? Schrei nicht. Fang plötzlich an, ganz leise zu flüstern. Um dich zu verstehen, muss es sich so sehr konzentrieren, dass sein Gehirn müde wird und automatisch in den Schlafmodus wechselt. Probier es aus!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', 'Die Ausrede „Mein Spielzeug war’s!“ 🤷‍♂️', 'Dein Kind hat das Wasser absichtlich auf den Boden geschüttet, zeigt dann aber auf sein Spielzeugauto und sagt: „Das hat es umgestoßen“? Das ist keine echte Lüge, sondern ein Schutzmechanismus. Sag einfach: „Dann bringen wir dem Auto auch bei, wie man sauber macht“, und lenke sein Gehirn geschickt um.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'Die Zahl der Stille auf dem Display 🤫', 'Endlich ist dein Kind eingeschlafen. Im Haus ist es so still, dass deine Ohren klingeln? Öffne den Schallpegelmesser in der App. Der Anblick von 0 Dezibel ist für dein müdes, vom Lärm überreiztes Gehirn die beste visuelle Massage der Welt.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'Mission unsichtbares Gemüse 🥦', 'Dein Kind hat das eine Möhrenstückchen in der Suppe entdeckt und gesagt: „Das esse ich nicht“? Das kommt dir sicher bekannt vor! Püriere das Gemüse und misch es unter Soßen – mal sehen, ob es das jetzt noch findet! Überliste den kleinen Feinschmecker.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'Stolz auf das verkehrt herum angezogene Shirt 👕', 'Dein Kind hat sein Shirt verkehrt herum angezogen und lässt es sich auf keinen Fall richtig herum anziehen? Seine Sache! Das Selbstvertrauen in seinem „Ich hab’s geschafft!“-Blick ist wichtiger als ein richtig angezogenes Shirt. Lass es den ganzen Tag stolz so herumlaufen – das ist seine freie Entscheidung.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'Wenn deine Stimme nichts mehr bringt, kommt Papa 🤡', 'Dein Kind hört nicht mehr auf dich und bleibt stur? Doch kaum kommt Papa und macht seltsame Tiergeräusche und lustige Grimassen, fängt es sofort an zu lachen? Manchmal rettet dieser unsinnige Männerhumor wirklich die Situation. Lehn dich zurück und schau einfach zu.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'KI-Antworten auf seltsame Fragen 🤖', 'Hat dich die Frage „Mami, wo geht mein Schatten nachts hin?“ sprachlos gemacht? Denk dir nichts aus. Öffne Anacan AI, lass dir eine altersgerechte, märchenhaft schöne und zugleich wissenschaftliche Antwort geben und lies sie deinem Kind vor. Du wirst dich wie eine große Philosophin fühlen.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'Meine Wut aufschreiben 📝', 'Niemand sieht, wie erschöpft du zu Hause bist, und das bringt dich zum Platzen? Öffne dein Stimmungstagebuch. Schreib dort alles auf, was dich heute wütend gemacht hat. Deine Gefühle anzunehmen und aufzuschreiben hilft dir mehr, als ein Lächeln vorzutäuschen.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'Lange Gespräche mit leblosen Dingen 🗣️', 'Erzählt dein Kind im Park einem Stein oder zu Hause einem Stuhl ganz ernst irgendwelche Dinge? Durch das Spielen lernt es die Regeln und die Welt kennen.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'Heute Abend kuscheln wir einfach nur 🫂', 'Ihr braucht kein Spiel und kein lautes Buch. Drück dein Kind heute Abend einfach an deine Brust, atme seinen unverwechselbaren Kinderduft tief ein und flüstere ihm im Dunkeln zu, wie wertvoll es ist. Das wird euch beiden guttun.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'Schätze das Wetter nicht nur durchs Fenster ein ⛅', 'Draußen scheint die Sonne, aber es ist auch windig? Wenn dir das Wetter- und Kleidungstool den Zwiebellook empfiehlt, vertrau darauf. Statt unschlüssig an der Tür zu stehen und dich zu ärgern, wählst du die passende Kleidung aus und ihr geht ganz entspannt nach draußen.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'Vom eigenen Essen gibt es nichts für dich 🍳', 'Dein Kind gibt dir nichts von seinem Teller ab, möchte aber unbedingt von deinem essen? Kinder vertrauen der Auswahl ihrer Eltern vollkommen. Kämpf nicht dagegen an, reich ihm den Bissen liebevoll rüber und lächle einfach über diesen lustigen kleinen Egoismus.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'Meine Geschichte, meine Regeln 📖', 'Du hast beim Vorlesen ein Wort falsch gesagt und dein Kind hat dich sofort verbessert? Dann kennt es die Geschichte schon auswendig! Klapp das Buch zu und sag: „Dann liest du mir heute Abend vor.“ Lass seine Fantasie arbeiten, während du dich einfach zurücklehnst und seiner süßen Stimme lauschst.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'Den Turm bauen und wieder umwerfen 🧱', 'Baut dein Kind mühsam einen Turm aus Bauklötzen und reißt ihn dann lachend mit einem einzigen Schlag wieder ein? Auch wenn dir die ganze Mühe leidtut, lernt es dabei etwas über Physik und Ursache und Wirkung. Durch diese Zerstörungsaktionen entstehen neue Verknüpfungen in seinem Gehirn – ärgere dich also nicht.'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'Die Anziehungskraft des Bodens 🍝', 'Wirft dein Kind absichtlich Essen auf den Boden und schaut ihm hinterher? Schimpf nicht – es will dich nicht provozieren, sondern die Schwerkraft testen. Nimm den Teller ruhig weg, erziehen kannst du später.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'Nenn mich Batman! 🦇', 'Ist dein Kind morgens aufgewacht, lehnt plötzlich seinen eigenen Namen ab und verlangt, anders genannt zu werden? Spiel mit! Verwandle die angespannte Stimmung für 5 Minuten in eine Komödie, indem du sagst: Bitte sehr, Batman, iss deinen Brei.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'Das Drama mit dem Pyjamabund 👖', 'Dein Kind schreit, weil der Pyjama angeblich zu eng ist, obwohl er ihm fast vom Körper rutscht? Seine sensorische Empfindlichkeit spielt gerade verrückt. Sag: Warte, ich spreche einen Zauberspruch, damit er weiter wird, und zieh zum Schein am Pyjama. Es wird dir glauben!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'Wenn ich die Augen schließe, verschwinde ich 👀', 'Versucht dein Kind, nicht zu blinzeln, und hält durch, bis ihm die Augen tränen? Das kindliche Gehirn denkt sich manchmal unerklärliche Ängste aus. Verwandle diese absurde Angst in ein Spiel, indem du sagst: Schau, ich habe meine Augen geschlossen und bin immer noch da.'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'Fass mich nicht an, mir wird heiß 🛑', 'Will dein Kind plötzlich nicht mehr von dir umarmt werden? Nimm es nicht persönlich! Es erprobt seine persönlichen Grenzen und lernt, dass sein Körper nur ihm gehört. Das ist ein Zeichen von Selbstständigkeit – beobachte es stolz aus der Ferne.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'Schlafen unter dem Sessel 🛋️', 'Lehnt dein Kind sein Bett ab und ist zusammengerollt unter dem Sessel eingeschlafen? Zieh es nicht gewaltsam hervor und weck es nicht auf. Lass es genießen, an einem ungewohnten, geschützten Ort zu schlafen, und ruh dich ebenfalls aus.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'Das Kissen liegt nicht gerade! 🛏️', 'Weint dein Kind, weil das Kissen nicht millimetergenau liegt? Es strebt gerade nach Perfektion. Spiel nach seinen Regeln, richte das Kissen aus, als hättest du es mit einem Lineal vermessen, und mach entschlossen das Licht aus.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'Panik bei plötzlicher Stille im Haus 🚪', 'Ist es zu Hause plötzlich verdächtig still geworden? Wenn du dich auf die Suche machst, findest du dein Kind vielleicht verträumt hinter einer Tür. Keine Sorge: Es zieht sich vom Lärm zurück und kommt innerlich zur Ruhe. Gib ihm diese Zeit.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'Drama um den zerbrochenen Cracker 🍪', 'Die Welt geht unter, weil der Cracker in zwei Teile zerbrochen ist? Du kannst ihn nicht wieder zusammenkleben. Sag einfach: „Schau, jetzt sind es zwei – einer für mich und einer für dich.“ So bringst du ganz nebenbei Mathematik und Teilen ins Spiel.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'Das Eis blieb im Traum zurück 🍦', 'Dein Kind hat im Traum Eis gegessen und ist sauer auf dich, weil du es geweckt hast? Traum und Wirklichkeit sind gerade durcheinandergeraten. Nimm dein Kind samt Schmollgesicht in den Arm und lach mit ihm – in 2 Minuten ist es wieder in der Realität angekommen.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'Die Farbe der Trinkflasche 🚰', 'Dein Kind möchte nachts Wasser, aber bloß nicht aus dem roten Becher? Versuch nicht, mitten in der Nacht nach Logik zu suchen und ihm eine Lektion zu erteilen. Tausche den Becher einfach sofort aus und spare deine Energie für den Morgen – und für den Familienfrieden.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', 'Der „Da ist ein Stein in meinem Schuh“-Wahn 👟', 'Dein Kind lässt dich den Schuh 10 Mal ausziehen und nachsehen, obwohl kein Stein darin ist! Kommt dir das bekannt vor? Nimm unauffällig ein kleines schwarzes Krümelchen in die Hand und sag: „Schau, ich habe ihn gefunden, wir sind gerettet!“ Dann könnt ihr euren Spaziergang fortsetzen.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'Warum ist der Brei heiß? 🥣', 'Kalt würde dein Kind ihn nicht essen, aber jetzt weint es, weil er heiß ist? Eine echte Zwickmühle! Gib ganz bewusst einen bunten Eiswürfel hinein – das weckt sofort seine Neugier und beruhigt es.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'Weinen hinter verschlossener Tür 🚪', 'Dein Kind hat die Tür geschlossen, weint allein in seinem Zimmer und möchte dich gerade nicht bei sich haben? Versuch nicht, es gegen seinen Willen zu umarmen. Manchmal möchten auch Kinder ihre Gefühle allein durchleben. Gib ihm Zeit und Raum.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'Wut auf den Wolf im Buch 🐺', 'Dein Kind schlägt auf das Bild des Wolfs im Buch ein und schimpft mit ihm? Was für eine wunderbare Fantasie! Ohne Realität und Fantasie zu vermischen, kannst du sagen: „Du hast mich beschützt, du bist sehr mutig.“ So stärkst du sein Selbstvertrauen.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'Zieh mir nicht die Socken an! 🧦', 'Dein Kind lehnt alles, was du für es tun möchtest, entschieden ab? Wunderbar! Leg die Kleidung aufs Sofa und starte ein Wettrennen: „Wer ist zuerst angezogen?“ Innerhalb weniger Sekunden zieht es sich selbst an.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'Wo bleibt mein Mittagessen? 🥗', 'Du bereitest deinem Kind einen besonderen Gemüseteller zu und knabberst selbst nur an einem Stück Brot? Stopp! Mach dir den einfachen 5-Minuten-Salat aus dem Ernährungsplan für Mütter und vergiss nicht, endlich auch den wichtigsten Motor dieses Zuhauses aufzuladen: dich selbst. Du bist wichtig.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'Licht aus, Schlaf an 🌙', 'Schalte eine Stunde vor dem Schlafengehen alle hellen Lichter und den Fernseher aus. Je dunkler es im Zimmer wird, desto eher beginnt dein Kind ganz von selbst zu gähnen. So aktivierst du unbemerkt und auf natürliche Weise das Melatonin – das Schlafhormon – und machst es dir leichter.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'Ich weiß es – und erkläre es dir auch ☝️', 'Kommt dein Kind zu dir und erklärt dir mit ernster, schlauer Miene etwas, das du längst weißt? So testet es sein eigenes Wissen. Beiß dir auf die Lippe, um nicht zu lachen, hör aber ganz aufmerksam zu und sag ernst: „Wirklich? Vielen Dank!“'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'Wenn Papa die Geschichte falsch erzählt 📖', 'Heute Abend musst nicht du vorlesen. Gib Papa das Märchenbuch. Lass ihn die Geschichte absichtlich verdreht, komisch und völlig absurd erzählen. Lehn dich zurück und genieße, wie viel Spaß dein Kind daran hat, ihn zu verbessern und dabei laut zu lachen.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'Vergiss das Aufräumen – die Spielsachen dürfen bleiben 🎨', 'Dein Kind hat mitten im Zimmer aus lauter Kleinteilen ein großes Kunstwerk geschaffen und lässt dich nicht aufräumen? Lass deinen Putzfimmel für einen Moment los. Rühr das kreative Chaos nicht an – aufräumen kannst du auch morgen noch. Euer Zuhause ist kein Museum.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'Dein Kind erzählt dir den Zeichentrickfilm 📺', 'Erzählt dir dein Kind den Zeichentrickfilm, den es gesehen hat, nach seiner ganz eigenen Logik und erklärt dir ernsthaft, wer wohin gegangen ist? Hör aufmerksam zu, als würdest du jedes Wort glauben. Lass dein Kind sich wie der klügste und stärkste Mensch der Welt fühlen.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'Dieses gefürchtete „Ich will das!“ im Supermarkt 🛒', 'Dein Kind schreit direkt vor der Kasse nach Schokolade? Gib trotz der Blicke der anderen Wartenden nicht nach. Öffne die Einkaufsliste und sag: „Das steht hier nicht drauf, die Kasse wird es nicht akzeptieren.“ Eine äußere Autorität wirkt auf Kinder oft überzeugender.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'Mit Wasser die ganze Anspannung wegspülen 🛀', 'Manchmal hilft einfach nichts und dein Kind weint wegen allem. Setz es in eine Badewanne mit angenehm warmem Wasser. Die beinahe magische, entspannende Kraft des Wassers kann im ganzen Raum und im Nervensystem deines Kindes sofort für tiefe Ruhe sorgen. Probier es aus.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'Philosophie unter dem Tisch 🤔', 'Kriecht dein Kind unter den Tisch und erzählt dir von dort aus erfundene Geschichten? Lass den kleinen Philosophen ruhig in seiner Fantasiewelt – und nutze die Zeit, um dich etwas auszuruhen.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'Die Bettdecke ist zu laut 🛌', 'Dein Kind kann angeblich nicht schlafen, weil die Bettdecke raschelt! Skurrile Ausreden haben gerade Hochsaison. Deck es mit einer leichten Decke zu. Wenn es merkt, dass du für alles eine Lösung findest, wird es schließlich aufgeben.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'Aufstand in der Badewanne 🛀', 'Dein Kind will nicht ins Wasser? Gib verschiedenfarbige Becher oder sogar Küchenutensilien aus Kunststoff hinein. Schon verwandelt sich das Wasser vom unheimlichen Ort in ein wahres Spieleparadies.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'Ich bin Papa 👔', 'Dein Kind zieht morgens Papas große Schuhe an und will zur Arbeit gehen? Nur keine Eile! Begleite es bis zur Tür – sobald es den Aufzug sieht, kommt es lachend wieder zurück.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', 'Liebe zu 0 Dezibel 🤫', 'Endlich schläft dein Kind! Öffne den Schallpegelmesser in der App und genieße die absolute Stille, während die Anzeige ganz nach unten sinkt. Diese sichtbare Ruhe wird dein müdes Gehirn wie ein echter Spa-Besuch verwöhnen.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'Der Baum hat sein Blatt fallen lassen 🍂', 'Dein Kind ist wegen eines Blattes auf dem Boden böse auf den Baum und schimpft mit ihm? Seine Verbindung zur Natur ist einfach so unschuldig und herrlich komisch!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'Mein Schatten läuft vor mir 👻', 'Dein Kind weint auf der Straße, weil sein Schatten vor ihm läuft? Nimm es in den Arm und sage: „Schau, jetzt sind unsere Schatten zusammen.“ Statt ihm die Physik zu erklären, gib ihm einfach ein Gefühl von Sicherheit.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'Papas alberne Witze 🤡', 'Sei nicht böse, wenn Papa dein Kind zur Schlafenszeit zum Lachen bringt und dadurch wieder aufweckt. Das fröhliche Lachen lässt den Stress des ganzen Tages verfliegen – lass die beiden ruhig ein bisschen herumalbern.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'Ich bin im Märchen! 🪄', 'Ersetze in personalisierten Märchen den Namen der Hauptfigur einfach durch den Namen deines Kindes. Wenn die Figur in der Geschichte schnell und artig einschläft, wird dein Kind motiviert sein, es ihr gleichzutun.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'Mitten im Supermarkt wie erstarrt 🛒', 'Du stehst im Supermarkt und hast vergessen, was du kaufen wolltest? Wenn du deine Einkaufsliste nicht digital führst, geht in dem ganzen Chaos alles unter. Verlass dich ruhig auf dein digitales Gedächtnis.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'Nachts Sterne zählen 🌟', 'Dein Kind schaut an die Zimmerdecke und zählt imaginäre Sterne? Lass es ruhig zählen. Noch bevor es bei 10 angekommen ist, wird es bereits eingenickt und tief eingeschlafen sein.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'Meine Hände sind meine Füße 🤸‍♂️', 'Dein Kind versucht, auf den Händen zu laufen, und fällt dabei hin? Seine kreative motorische Entwicklung läuft auf Hochtouren! Bau ihm an einem sicheren Ort zu Hause einen kleinen Parcours auf, damit es sich austoben kann.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'Papas leiser Auftritt 👨‍🍼', 'Gerade als du vom Vorlesen völlig erschöpft bist, kommt Papa leise ins Zimmer, streichelt euer Kind und gibt dir ein Zeichen, dass du dich ausruhen sollst. Das ist einer dieser Momente, in denen Elternsein echte Teamarbeit ist.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'Du hast die Banane falsch geschält 🍌', 'Der König der Ausreden! Die Welt geht unter, nur weil du die Banane geschält hast. Gib deinem Kind eine neue und lass es sie selbst so schälen, wie es möchte – notfalls bricht es sie dafür in der Mitte durch. Hauptsache, seine Selbstständigkeit bleibt gewahrt.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'Aufstand, weil es zu warm ist 🧥', 'Dein Kind zieht mitten auf der Straße seine Jacke aus und wirft sie hin, während du Angst hast, dass es friert? Kämpf nicht dagegen an. Wenn ihm wirklich kalt wird, kommt es von selbst und bittet um die Jacke. Lass es diese Erfahrung selbst machen.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'Ich bin ein Stuhl 🪑', 'Dein Kind gibt sich als Gegenstand aus und steht regungslos da? Stell ihm zum Spaß ein Spielzeug darauf und sag: Was für ein schöner Stuhl! Es wird diese ungewöhnliche Rolle lieben und dabei ganz ruhig bleiben.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'Damit das Ei nicht weint 🍳', 'Dein Kind hat Mitleid mit dem Ei, nachdem es aufgeschlagen wurde, und will es nicht essen? Seine Empathie kennt keine Grenzen. Rette die Situation mit einer süßen Fantasiegeschichte: Das Ei wird jetzt in seinen Muskeln weiterleben.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'Das Flüsterspiel 🤫', 'Dein Kind will nicht schlafen und läuft davon? Senke plötzlich deine Stimme und flüstere ganz leise. Um dich zu verstehen, wird es aufmerksam zuhören – und sein müdes Gehirn wird nach 5 Minuten dem Schlaf nachgeben.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'Der Hilferuf deines Körpers 🩸', 'Lass dich nicht von scheinbar grundloser Gereiztheit und Müdigkeit überwältigen. Schau in den Perioden-Tracker – dein Körper sendet dir ein Signal. Statt dir Vorwürfe zu machen, gönn dir Ruhe und einen magnesiumreichen Snack aus den Gesunden Rezepten.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'Nur rote Lebensmittel 🍅', 'Heute dreht sich alles um Rot! Dein Kind will nur rote Sachen? Schau in den Ernährungsplan und gib ihm heute rote Tomaten und Erdbeeren. Lass diesen ungewöhnlichen Wunsch wahr werden, statt dagegen anzukämpfen.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'Mein Kuscheltier ist krank 🩺', 'Dein Kind hat seinen Teddy ins Krankenhaus eingeliefert? Dann sei du auch krank! Leg dich aufs Sofa und lass dich 10 Minuten lang zum Spaß untersuchen – so kann sich nebenbei auch dein Rücken erholen.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'Schlaf bei mir 🫂', 'Dein Kind besteht darauf, dass du neben ihm schläfst? Brich für einen Tag die Regeln, atme seinen vertrauten Duft tief ein und schlafe bei ihm ein. Das ist eine Liebestherapie für euch beide.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'Künstliche Intelligenz, hilf mir 🤖', 'Die unaufhörlichen philosophischen Fragen deines Kindes haben dich erschöpft? Schreib Anacan AI – es formuliert sofort die wissenschaftlichsten, geduldigsten und liebevollsten Antworten, die ein 4-jähriges Kind verstehen kann.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'Ich habe mich im Spiegel nicht erkannt 🪞', 'Dein Kind betrachtet sich im Spiegel, verändert seine Mimik und wird dabei wütend auf sich selbst? Sein Ich-Bewusstsein und seine Gefühlswelt entwickeln sich gerade. Beobachte diese kleine Schauspielvorstellung still aus der Nähe.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'Meine digitale Therapie 🤫', 'Das ganze Haus schläft, aber in deinem Kopf ist es immer noch laut? Öffne den Schallpegelmesser. Der Anblick der Anzeige „0 Dezibel“ im Zimmer wird dich mehr entspannen als eine Therapiesitzung – probier es aus.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'Die Spielsachen ins Bett bringen 🧸', 'Dein Kind will selbst nicht schlafen, legt aber seine Spielsachen einzeln ins Bett und deckt sie zu? Dieses Rollenspiel bereitet es tatsächlich langsam und auf psychologischer Ebene auf den eigenen Schlaf vor – greif nicht ein.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'Warum hast du die Tür geöffnet? 🚪', 'Dein Kind weint, weil du die Tür geöffnet hast, lässt sie wieder schließen und will sie selbst aufmachen? Lass dir diese 1 Minute ruhig nehmen und verhindere so ganz friedlich einen 20-minütigen Aufstand mit Geschrei zu Hause.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'Nur grüne Sachen! 🥦', 'Sucht dein Kind auf dem Teller nur nach grünen Lebensmitteln? Schau in den Ernährungsplan, lerne, wie du aus Blattgemüse süß geformte grüne Gemüsebällchen zubereitest, und stille diese ungewöhnliche Vorliebe.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'Wo ist der Himmel hin? ☁️', 'Hat dich diese plötzliche philosophische Frage bei nebligem Wetter sprachlos gemacht? Sag einfach, die Wolken hätten den Himmel zugedeckt, damit er nicht friert. Für eine wissenschaftliche Erklärung ist dein Kind noch nicht bereit – es möchte einfach ein Märchen hören.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'Mitten im Supermarkt davonrennen 🛒', 'Rennt dein Kind vor der Kasse plötzlich weg und versteckt sich hinter den Regalen? Führe deine Einkaufsliste digital, damit du in solchen Panikmomenten nicht vergisst, was du noch kaufen wolltest, und am Ende mit leeren Händen nach Hause gehst.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'Das Flüsterspiel 🤫', 'Dein Kind rennt schreiend herum und will nicht schlafen? Mach deine Stimme plötzlich ganz leise. Fang an, mit kaum hörbarer Stimme zu flüstern. Es wird sich konzentrieren, um dich zu verstehen, und dabei müde werden.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'Ich bin keine perfekte Mutter 🛑', 'Heute ist alles drunter und drüber gegangen und du hast geschrien? Mach dich nicht selbst fertig. Schreib einfach in dein Stimmungstagebuch: Heute war ein schlechter Tag, aber ich bin eine gute Mutter und morgen versuche ich es noch einmal.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'Die Freiheit, das Shirt verkehrt herum zu tragen 👕', 'Dein Kind trägt sein Shirt mit der Rückseite nach vorn und läuft stolz damit herum? Korrigiere es nicht! Sein Selbstvertrauen ist so groß – schau einfach zu und sei stolz auf diesen freigeistigen Anführer der Zukunft.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'Ein Blickwechsel voller Stille 🥂', 'Das Kind schläft, und du und dein Partner sitzt auf dem Sofa und schaut euch schweigend an. Ihr sagt kein Wort. Diese Stille ist eigentlich die romantischste Art zu sagen: Auch das haben wir geschafft.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'Der Wind hat mich geschubst 💨', 'Dein Kind ist wütend auf den Wind draußen und will ihn schlagen? Hättest du vorher einen Blick auf das Wetter- und Kleidungs-Tool geworfen, wärt ihr vielleicht gar nicht erst hinausgegangen. Jetzt könnt ihr nur noch über diese Komödie lachen und schnell nach Hause laufen.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'Kunst auf dem Fußboden 🎨', 'Dein Kind hat mitten im Zimmer aus trockenen Nudeln ein Bild gelegt und schaut dich stolz an? Vergiss das Aufräumen und lächle ihm einfach zu.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'Papas einschläfernde Gute-Nacht-Geschichte 📖', 'Deine Stimme ist müde und du möchtest keine Geschichte vorlesen? Gib den Ball an Papa weiter. Seine andere, tiefe Stimme und die absurden Details, die er sich ausdenkt, werden das Kind noch schneller in den Schlaf versetzen.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'Meine Haare tun mir weh 🪮', 'Ist Haarekämmen jedes Mal ein Drama? Befeuchte die Haare leicht mit einer Sprühflasche und lenke dein Kind mit lustigen Grimassen im Spiegel ab. Sobald es abgelenkt ist, kämmst du die Haare schnell zu Ende.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'Mein Körper gehört nicht mehr mir 🔋', 'Ist dein Körper ganz taub davon, dass dein Kind den ganzen Tag auf dir herumklettert? Lass es 5 Minuten allein im Zimmer, schließe einfach die Tür, mach die Augen zu und atme tief durch. Du musst neue Kraft tanken.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'Nenn mich nicht Kind! 😤', 'Sagt dein Kind, es sei schon groß, und stellt im Zimmer Regeln für dich auf? Es versucht jetzt zu beweisen, dass es erwachsen geworden ist. Sprich es mit „Na gut, junge Dame/junger Herr“ wie einen Erwachsenen an und gewinne so seinen Respekt.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'Was sagt die Community dazu? 💬', 'Glaubst du, dass du alles falsch machst? Schau in der Anacan Community vorbei, lies die Geschichten über die wilden Kinder anderer Mütter, atme tief durch und sei dankbar für dein eigenes!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'Mach das Zimmer ganz dunkel 🌙', 'Kann dein Kind wegen des Lichts aus dem Flur nicht schlafen? Es möchte völlige Dunkelheit. Schließ die Tür fest, verdunkle das Zimmer vollständig und lass das Melatonin auf natürliche Weise wirken, damit dein Kind einschläft.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'Das unsichtbare Fleckenproblem 👕', 'Sucht dein Kind nach einem Fleck auf seiner Hose, obwohl dort gar nichts ist? Da sind sie wieder, diese visuellen Fixierungen. Wisch einfach zum Schein mit einem Feuchttuch darüber und sag, der Fleck sei weg. Kinder lassen sich schnell von solchen Illusionen überzeugen.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'Setz dich weiter weg 🛑', 'Verlangt dein Kind, dass du nicht neben seinem Bett, sondern weiter weg an der Tür sitzt? Nimm es nicht persönlich! Das ist ein großer Schritt in Richtung Selbstständigkeit – innerlich darfst du dich darüber freuen.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'Der Vogel am Fenster gehört mir 🐦', 'Möchte dein Kind den Vogel aus dem Hof mit nach Hause nehmen und weint deswegen? Seine Tierliebe kennt keine Grenzen. Erzähl ihm einfach, dass die Vogelmama zu Hause auf ihn wartet – so wird aus der Krise im Handumdrehen wieder Ruhe.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'Die nächtlichen Ängste beginnen 👻', 'Hat dein Kind Angst vor dem Monster unter dem Bett? Füll eine leere Sprühflasche mit Wasser und versprüh es im Zimmer als magisches Monsterspray. Die Angst wird innerhalb von Sekunden verschwinden.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'Ich will meine Zähne mit dem Finger putzen 🪥', 'Lehnt dein Kind die Zahnbürste ab und will seine Zähne unbedingt mit dem Finger putzen? Widersprich nicht: Zur Not geht es auch mit einem sauberen Finger und ein wenig Zahnpasta. Mach kein großes Drama daraus.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'Heimlicher Schokoladengenuss 🍫', 'Isst du heimlich Schokolade in der Küche, während dein Kind fernsieht? Lass es dir schmecken! Um all diese Krisen durchzustehen, ist das dein ganz natürlicher Energieriegel. Mach dir keine Vorwürfe.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'Märchen mit Regengeräuschen 🌧️', 'Deine Stimme ist weg und du hast keine Kraft, ein Märchen vorzulesen? Spiele bei den smarten Märchen einfach Regen- und Waldgeräusche im Hintergrund ab. Diese Ruhe der Natur lässt dein Kind manchmal schneller einschlafen als das schönste Märchen.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'Halt nicht meine Hand! 🚶‍♂️', 'Möchte dein Kind unterwegs deine Hand loslassen und allein gehen? Wenn ihr euch in einem sicheren Bereich befindet, lass es seine Selbstständigkeit ausprobieren und folge ihm einfach stolz mit zwei Schritten Abstand.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'Die Brotrinde ist der Feind 🍞', 'Dein Kind isst nur die Mitte und lässt die Ränder entschlossen liegen? Kämpfe nicht gegen die Brotrinde an. Schneide das Brot mit Ausstechformen in Tierform aus, sodass Formen ohne Rinde entstehen, und lass dein Kind Freude an diesem kreativen Essen haben.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'Es will nicht rausgehen ⛅', 'Die vier Wände fallen euch auf den Kopf, aber dein Kind weint und will nicht nach draußen? Verlass dich auf das Wetter- und Kleidungstool und geh trotzdem mit ihm raus. Sobald es die frische Luft einatmet, ist der ganze Frust von zu Hause innerhalb von Sekunden verflogen.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'Pyjama-Ringen mit Papa 🤼‍♂️', 'Dein Kind will nicht schlafen? Lass Papa beim spielerischen Raufen so tun, als würde er es besiegen. Dabei powert es sich aus, verbraucht seine letzte Energie und flitzt anschließend ins Bett.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'Kraft aus der Gemeinschaft schöpfen 💬', 'Wenn deine Geduld am Ende ist, schau in der Anacan-Community vorbei. Wenn du siehst, dass andere Mütter genau dasselbe Chaos erleben, spürst du große Erleichterung und weißt: Ich bin nicht allein.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'Auch das haben wir geschafft! 🚀', 'Das ganze Haus schläft. Du bist bereit für das neue Chaos des nächsten Monats – du bist inzwischen ein echter Profi. Mach das Licht aus und danke dir selbst für all die kleinen Wunder, die du heute vollbracht hast.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'Dieser Schatten gehört mir 👻', 'Dein Kind hat seinen Schatten für sich entdeckt, spricht mit ihm und gibt ihm Anweisungen? Seine Fantasie kennt keine Grenzen.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'Die Risse im Asphalt sind Gesetz 🛣️', 'Macht dein Kind beim Gehen auf der Straße seltsame Bewegungen, nur um nicht auf die Linien zwischen den Steinen zu treten? Dabei arbeiten Grobmotorik und Aufmerksamkeit gleichzeitig. Hetze es nicht, nimm es an die Hand und spring gemeinsam mit ihm über die Linien.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'Angst vor dem Abfluss 🛁', 'Hat dein Kind Angst vor dem Abfluss, wenn das Badewasser abläuft? Seine Fantasie schlägt gerade wilde Kapriolen. Stell ein Spielzeugschiff aus Plastik darauf und sag: „Schau, das ist ein Beschützer. Er lässt nicht zu, dass irgendetwas hineingezogen wird.“ So wird die Angst im Nu zum Spiel.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'Das Konzert um 6 Uhr morgens 🎤', 'Singt dein Kind gleich nach dem Aufwachen aus voller Kehle ein selbst erfundenes Lied? Bremse diese wilde Energie nicht mit den Worten: „Sei leise, sonst wachen die Nachbarn auf.“ Sing einfach mit. Ein Kind, das den Morgen mit einem Lied beginnt, ist tagsüber meist weniger aggressiv.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'Der 0-Dezibel-Tanz der Stille 🤫', 'Endlich ist das Zimmer dunkel und dein Kind schläft. Im Haus ist es so still, dass dir fast die Ohren zufallen. Öffne den Schallpegelmesser in der App. Zu beobachten, wie die Anzeige auf dem Bildschirm auf 0 Dezibel sinkt, ist eine echte digitale Massage für dein vom Lärm aufgeblähtes Gehirn.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'Mein Kuscheltier ist sauer auf dich 🧸', 'Kommt dein Kind zu dir und sagt: „Mein Bär ist sauer auf dich“, weil du geschrien hast? Es überträgt seine eigenen Gefühle auf Gegenstände, um sie dir mitzuteilen. Entschuldige dich ganz ernsthaft bei dem Bären und umarme ihn. Du wirst sehen, wie erleichtert dein Kind ist.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'Warum dampft der Tee? ☕', 'Betrachtet dein Kind den Dampf, der aus deiner Tasse aufsteigt, und verlangt eine Erklärung oder bekommt sogar Angst? Dir fällt keine kindgerechte wissenschaftliche Antwort ein? Bitte Anacan AI um eine fantasievolle und liebevolle Erklärung für ein 4-jähriges Kind: „Der Dampf fliegt nach oben, um sich den Wolken anzuschließen.“'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'Der heimliche Angriff auf die Liste 🛒', 'Du hast vor dem Einkauf die Einkaufsliste in der App geöffnet und entdeckt, dass dort 5 Tafeln Schokolade stehen? Ja, dein Kind hat längst gelernt, sich in dein Handy einzuschleichen und die digitale Welt nachzuahmen.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'Das Drama um den ganzen Apfel 🍏', 'Im ganzen Zimmer ertönt Geschrei, weil du den Apfel in Stücke geschnitten hast? Dein Kind weint: „Ich wollte ihn ganz!“ Such nicht nach Logik. Setz die Stücke wieder zusammen, sag: „Schau, ich habe ihn repariert“, und entzieh dich diesem absurden Drama auf diplomatische Weise.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'Eine Torte aus Sand 🏖️', 'Hat dein Kind im Park Wasser und Erde gemischt, sich dabei mit Matsch beschmiert und dir eine Torte gebacken? Vergiss die Sauberkeit. Das fördert die Feinmotorik und Kreativität.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'Wer zuerst blinzelt, verliert 👀', 'Dein Kind will nicht schlafen und starrt dich absichtlich mit weit aufgerissenen Augen an? Spielt „Wer zuerst die Augen schließt, verliert“. Die Augen werden tränen, es wird müde und nach 2 Minuten fallen sie ganz von allein zu. Probier es aus!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'Versteckte Spielsachen im Bett 🧸', 'Du legst dich ins Bett und findest darunter 3 harte Spielzeugautos? Dein Kind schläft mit ihnen, um auf sie aufzupassen. Keine Sorge: 10 Minuten nach dem Einschlafen kannst du die drückenden Spielsachen heimlich entfernen, damit es bequem weiterschläft.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'Stiller Trost in der Community 💬', 'Du bist völlig erschöpft und möchtest nicht einmal jemandem dein Herz ausschütten? Schau in der Anacan-Community vorbei und lies einfach nur mit. Zu sehen, wie andere Mütter mit denselben absurden Krisen umgehen, kann dir den stärksten stillen Trost schenken.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'Die Krise wegen des falschen Löffels 🥄', 'Beinahe ist eine Revolution ausgebrochen, nur weil du die Suppe mit dem großen Löffel serviert hast? Im Alter von etwa 4 Jahren kann die Größe des Löffels in der kindlichen Vorstellung sogar den Geschmack verändern – obwohl das Essen dasselbe ist. Diskutiere nicht, tausche den Löffel sofort aus und spare deine Energie.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'Schweigend aufs Sofa sinken 🥂', 'Das Kind schläft, die Wohnung ist aufgeräumt. Setzt euch nebeneinander aufs Sofa und lasst sogar den Fernseher aus. Werft euch einfach diesen Blick zu: „Auch das haben wir geschafft – wir haben überlebt.“ Glaub mir, genau das ist einer der romantischsten und ehrlichsten Momente des Elternseins.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'Die Liebe zur Farbe Grün 🥦', 'Dein Kind sucht auf dem Teller nur nach grünen Lebensmitteln und schiebt alles in anderen Farben weg? Schau dir gesunde Rezepte an und entdecke, wie du aus grünem Gemüse niedlich geformte Gemüsebällchen zubereiten kannst.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'Warum hast du die Tür zugemacht? 🚪', 'Dein Kind hat lautstark protestiert und dich die Tür wieder öffnen lassen, weil du sie beim Verlassen des Hauses zugemacht hast? Das Gefühl von Kontrolle ist eines seiner größten Bedürfnisse. Nimm dir 1 Minute mehr Zeit und lass dein Kind die Tür selbst schließen – so ersparst du euch womöglich einen 30-minütigen Weinanfall draußen.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'Papas erfundener Held 🦸‍♂️', 'Du hast keine Stimme mehr und keine Luft zum Vorlesen? Dann ist Papa dran. Lass ihn eine frei erfundene, herrlich unlogische Geschichte erzählen, in der euer Kind die Hauptrolle spielt. Du legst dich einfach aufs Sofa und lauschst dem Gelächter aus dem Kinderzimmer.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'Der verkehrt herum angezogene Socken 🧦', 'Der Socken sitzt mit der Ferse oben auf dem Fuß und dein Kind lässt dich das auf keinen Fall korrigieren? Dann lass ihn so. Sein stolzes Gefühl, es ganz allein geschafft zu haben, ist eine Million Mal wertvoller als ein richtig angezogener Socken.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'Nur noch ein Schluck Wasser 💧', 'Kaum ist dein Kind eingeschlafen, springt es mit den Worten „Ich habe so großen Durst“ wieder aus dem Bett? Dabei geht es nicht ums Wasser, sondern darum, noch ein bisschen mehr Zeit mit dir zu verbringen. Stell vorsorglich eine auslaufsichere Trinkflasche ans Bett, um diesem beliebten Trick zuvorzukommen.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'Ich bin erschöpft, sage es aber nicht 📝', 'Niemand sieht, wie viel Stress du heute hattest, und du hast das Gefühl, daran zu ersticken, trotzdem alle anlächeln zu müssen? Öffne dein Stimmungstagebuch. Schreib all den Frust und die Wut, die sich in dir angestaut haben, auf den Bildschirm. Dieses digitale Auskotzen wird dir schneller Erleichterung verschaffen als ein Gespräch beim Psychologen.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'Der Jackenkampf 🧥', 'Draußen scheint die Sonne, aber dein Kind will seine Jacke nicht anziehen. Lass dich vom Blick aus dem Fenster nicht täuschen: Zeig ihm im Tool „Wetter und Kleidung“ die tatsächliche Temperatur und das Bild eines Kindes im Zwiebellook. So kommt die Regel vom Handy und nicht von dir.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'Warum hat der Vogel mich nicht angesehen? 🐦', 'Dein Kind schluchzt herzzerreißend, nur weil im Park eine Taube weggeflogen ist? Versuch gar nicht erst, darin Logik zu finden. Für dein Kind ist das wirklich eine große Enttäuschung. Bestätige sein Gefühl liebevoll und sag: „Der Vogel wird dich bestimmt sehr vermissen.“'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'Mein Name soll im Märchen vorkommen 🪄', 'Hat dein Kind genug von den Figuren aus klassischen Kinderbüchern? Ersetze in den „Cleveren Märchen“ den Namen der Hauptfigur durch seinen eigenen. Wenn es hört, wie mutig es selbst einschläft, wird es sich im Kinderzimmer ohne jeden Protest dem Schlaf hingeben.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'Heute bin ich ein Auto 🚗', 'Sagt dein Kind morgens zu dir: „Ich bin kein Kind, ich bin ein Auto“? Besteh nicht auf Regeln. Sag stattdessen: „Dann lass uns deinen Tank mit Benzin – also mit Brei – füllen, damit du schnell fahren kannst.“ Solche lustigen Rollenspiele sind viel einfacher, als laut zu werden.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'Wer ist dieses Kind im Spiegel? 🪞', 'Steht dein Kind vor dem Spiegel, runzelt die Stirn und zieht wütende und seltsame Grimassen? Es entdeckt gerade, wie verschiedene Gefühle im Gesicht aussehen. Beobachte ganz still und genüsslich, wie dieser kleine Theaterschauspieler probt.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'Licht aus, Schatten an 🔦', 'Dein Kind hat Angst im Dunkeln und will nicht ins Bett? Schalte das Licht im Zimmer ganz aus und knipse eine kleine Taschenlampe an. Lass mit deinen Händen Hunde- und Vogelschatten an der Wand entstehen. Verwandle die beängstigende Dunkelheit in ein Theater – dann fällt das Einschlafen leichter.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'Das Meisterwerk an der Wand 🖍️', 'Nach ein paar Sekunden verdächtiger Stille erwischst du dein Kind dabei, wie es mit Filzstiften ein Kunstwerk an die Wand malt? Atme tief durch. Seine Feinmotorik entwickelt sich, und die Wand lässt sich schließlich wieder abwischen. Mach unbedingt ein Foto von diesem Meisterwerk, bevor du es entfernst.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'Reiten auf Papas Rücken 🐴', 'Dein Kind konnte seine Energie noch nicht ganz loswerden und weigert sich, ins Bett zu gehen? Ruf Papa zu Hilfe. Wenn er das Kind auf den Rücken nimmt und durchs Zimmer galoppiert, erfüllt lautes Lachen den Raum – und die angestaute körperliche Anspannung löst sich innerhalb weniger Sekunden beim Herumtoben.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', '5 Minuten Auszeit im Bad 🚪', 'Der Lärm dröhnt dir im Kopf und du möchtest nur noch schreien? Bring dein Kind an einen sicheren Ort, geh ins Bad und schließe die Tür. Schau einfach 5 Minuten lang an die Wand und tu gar nichts. Diese kurze Stille hilft dir, wieder ganz du selbst zu werden.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'Der Brei ist zu rund 🥣', 'Dein Kind ist wütend über die Form seines Essens und weigert sich zu essen? Such nicht nach Logik, sondern rühr den Brei einfach mit dem Löffel um und sag: „Schau, ich habe es repariert.“ Die Kunst der Illusion wirst du als Mama noch oft brauchen.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'Tränen ohne erkennbaren Grund 😭', 'Auf dem Heimweg vom Park bricht die Welt zusammen, weil dein Kind einen Stein nicht treten konnte? Dahinter steckt keine Logik – es ist einfach müde. Diskutiere nicht, nimm es in den Arm, bestätige sein Gefühl und lenke seine Aufmerksamkeit auf etwas anderes.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'Geheimnisse der Flüstergeschichte 🤫', 'Dein Kind erfindet Ausreden, um nicht ins Bett zu müssen? Sprich ganz leise und nur noch im Flüsterton. Um dich zu verstehen, muss es seine Aufmerksamkeit ganz auf dich richten – und sein Gehirn schaltet schon bald in den Schlafmodus.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'Mitten im Supermarkt wie erstarrt 🛒', 'Du bist in den Supermarkt gegangen und hast vergessen, was du kaufen wolltest? Wenn du deine Einkaufsliste nicht digital führst, wirst du in diesem Chaos alles vergessen. Verlass dich jederzeit auf dein digitales Gedächtnis in der App, damit du nicht mit leeren Händen nach Hause kommst.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'Du spielst nicht mit mir! 😤', 'Während du das Essen umrührst, kommt dein Kind zu dir, nimmt dein Gesicht in beide Hände und dreht es zu sich: Schau mich an!? Es hat recht. Es möchte nicht nur deine körperliche Anwesenheit, sondern deine ungeteilte Aufmerksamkeit. Lass deine Arbeit liegen und hör ihm einfach 2 Minuten lang mit vollem Blickkontakt zu.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'Ein Zimmer voller Regengeräusche 🌧️', 'Deine Stimme ist weg und du hast keine Kraft, eine Geschichte vorzulesen? Spiele bei den intelligenten Märchen einfach Regen- und Waldgeräusche im Hintergrund ab. Diese gleichmäßige Ruhe der Natur wirkt manchmal schneller einschläfernd als die beste Geschichte.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'Mit einem selbst erfundenen Namen angesprochen werden 🦇', 'Dein Kind ist aufgewacht, lehnt seinen eigenen Namen ab und verlangt: Nenn mich Batman? Spiel einfach mit! Sag 5 Minuten lang: Bitte sehr, Batman, iss deinen Brei – und verwandle die angespannte Stimmung im Zimmer sofort in eine lustige Situation.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'Genervt von Instagram-Mamas 📱', 'Lass dich nicht entmutigen, wenn du Instagram öffnest und sofort die scheinbar perfekten Kinder aller anderen siehst! Schließ die App und geh in die Anacan-Community. Wenn du siehst, dass es bei allen zu Hause genauso chaotisch aussieht wie bei dir, kannst du tief durchatmen: Du bist nicht allein.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'Den ganzen Stress mit Wasser abwaschen 🛀', 'Manchmal hilft einfach nichts und dein Kind weint wegen allem. Setz es in eine Badewanne mit lauwarmem Wasser. Die beinahe magische, entspannende Wirkung des Wassers bringt sofort tiefe Ruhe in den ganzen Raum und in sein Nervensystem.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'Geh weg, ich will dich nicht 💔', 'Hat dein Kind zu dir gesagt: Du bist eine schlechte Mama, geh weg!, weil du ihm einen Wunsch abgeschlagen hast? Das tut weh. Aber es kann seine Wut noch nicht in die richtigen Worte fassen und meint eigentlich: Ich bin enttäuscht. Nimm es nicht persönlich, sondern umarme dein Kind einfach liebevoll.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'Teestunde mit einem unsichtbaren Freund 🫖', 'Dein Kind schenkt in einer Zimmerecke Tee für jemanden ein, den du nicht sehen kannst, und lacht dabei? Die Phase der Fantasiefreunde beginnt!'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'Warum darf ich nicht singen? 🎶', 'Du hast bei dem Kinderlied im Hintergrund mitgesummt und sofort rief dein Kind: Sing nicht mit! Schließlich ist es der einzige Solist im Raum und deine Gesangsversuche stehlen ihm die Show. Nimm es nicht persönlich und überlass diesem kleinen Egoisten die Bühne.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'Es sucht seine Kleidung selbst aus 👗', 'Rote Hose, Turnschuhe und Wintermütze ... Und dein Kind besteht darauf, genau so in den Park zu gehen. Vergiss, was andere darüber denken könnten. Lass es in seinem selbst gewählten Outfit hinausgehen – diese Freiheit ist für dein Kind wichtiger als Ästhetik.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'Schlafenszeit mit Timer ⏱️', 'Bekommt dein Kind plötzlich Durst oder verabschiedet sich von der Wand, sobald es Zeit fürs Bett ist? Stell einen Timer und legt die Regel fest: Wenn es klingelt, gehen alle schlafen. Einer neutralen Instanz zu folgen, fällt Kindern oft leichter.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'Warum ist der Mond noch da? 🌙', 'Hat dein Kind morgens den Mond am Himmel gesehen und gefragt: Warum ist der Mond noch nicht schlafen gegangen? Überfordere es nicht mit wissenschaftlichen Begriffen. Öffne Anacan AI, lass dir eine süße, altersgerechte Geschichte über den Mond erzählen und stille damit seine Neugier.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'Nur die Brotkruste wird gegessen 🍞', 'Isst dein Kind nur die Kruste und lässt das weiche Innere liegen? Solche eigenwilligen Essgewohnheiten kennst du bestimmt. Kämpfe nicht um jede Kruste. Im Ernährungsplan erfährst du, wie du Brot mit Förmchen ausstechen und so immer neue Krusten zaubern kannst.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'Dunkelheit für Melatonin 🌌', 'Damit dein Kind schneller einschläft, solltest du 1 Stunde vor dem Zubettgehen alle Fernseher und Handybildschirme im Zimmer ausschalten. Melatonin (das Schlafhormon) wird bei Dunkelheit vermehrt ausgeschüttet – vertraue auf diesen natürlichen Prozess.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'Warum schlafen die Spielsachen nicht? 🧸', 'Dein Kind will selbst nicht schlafen, legt aber all seine Spielsachen eines nach dem anderen ins Bett und deckt sie zu? Dieses Rollenspiel bereitet es tatsächlich langsam und ganz von selbst auf den eigenen Schlaf vor. Unterbrich es auf keinen Fall.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'Atme einfach seinen Duft ein 🫂', 'Hat dein Kind dich heute wirklich in den Wahnsinn getrieben und dir all deine Energie geraubt? Und doch schläft es so unschuldig im Bett ... Mach das Licht aus. Leg dich neben dein Kind, atme seinen unverwechselbaren Duft ganz tief ein und flüstere ihm im Dunkeln zu, wie sehr du es liebst.'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'Papas absichtlich falsch vorgelesenes Märchen 📖', 'Gib heute Abend Papa das Märchenbuch. Er soll die Geschichte absichtlich verdreht, komisch und völlig absurd erzählen. Beobachte genüsslich, wie viel Spaß dein Kind daran hat, ihn zu korrigieren, und wie es dabei lauthals lacht.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'Fangen spielen am frühen Morgen 🏃‍♂️', 'Dein Kind rennt morgens um 7 Uhr über die Sofas? Schimpf nicht. Lass deine Aufgaben für 2 Minuten liegen, hüpf mit und mach einfach mit. In die Fantasiewelt deines Kindes einzutauchen, kann auch für dich eine überraschend gute Art sein, Stress abzubauen.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'Panik wegen plötzlichen Stotterns 🤖', 'Hat das plötzlich aufgetretene Stottern deines Kindes dich dazu gebracht, im Internet nach Krankheiten zu suchen? Stopp! Frag Anacan AI und erfahre, ob es mit dem Entwicklungsschub im Alter von 4 Jahren zusammenhängt – so kannst du deine Sorgen beruhigen.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'Die Zahl der Stille auf dem Display 📉', 'Endlich schläft dein Kind. Ist es zu Hause so still, dass dir die Ohren klingeln? Öffne den Schallpegelmesser in der App. Der Anblick der Anzeige 0 Dezibel wird für dein müdes, vom Lärm überreiztes Gehirn die beste visuelle Massage der Welt sein.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'Der Streit um die von dir geschälte Banane 🍌', 'Im Zimmer ist eine Revolution ausgebrochen, weil du die Banane geschält hast? Die goldene Regel in diesem Alter: Dein Kind möchte alles selbst entscheiden. Du kannst die Schale nicht wieder ankleben – gib ihm eine neue Banane und lass es sie selbst so schälen, wie es möchte, damit sein Bedürfnis nach Selbstständigkeit ernst genommen wird.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'Seiltanz auf der Bordsteinkante 🧱', 'Dein Kind möchte auf dem Weg zum Park nicht auf dem normalen Gehweg laufen, sondern unbedingt auf der schmalen Bordsteinkante balancieren? Halte es zur Sicherheit am Arm und lass es diesen kleinen Gipfel erklimmen. So werden Gleichgewichtssinn und Selbstvertrauen gleichzeitig wunderbar gefördert.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'Zeit für dich ist kein Grund für Schuldgefühle 🥗', 'Du hast verschiedene Gerichte zubereitet, um dein Kind satt zu bekommen – aber was hast du gegessen? Bereite dir den einfachen 5-Minuten-Salat für Mütter aus den gesunden Rezepten zu und vergiss nicht, endlich auch deine eigenen Energiereserven aufzuladen.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'Ein stiller Blick zwischen euch 🥂', 'Das Kind schläft. Du und dein Partner sitzt auf dem Sofa und schaut euch schweigend an. Ihr sagt kein Wort. Diese Stille ist eigentlich die romantischste und ehrlichste Art zu sagen: Auch das haben wir geschafft – wir sind ein großartiges Team.'),
  ('9632825c-5c1a-41f6-900b-2b6b7e88d644', 'Die Winterjacke ablehnen 🧥', 'Draußen scheint die Sonne und deshalb will dein Kind die Winterjacke nicht anziehen? Öffne die Wetter- und Kleidungsanzeige und zeig ihm auf dem Handy das Symbol eines winterlich gekleideten Kindes. Überlass die Regel dem Bildschirm und halte dich heraus – dann wird es sich ganz ruhig anziehen.'),
  ('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf', 'Geflüsterte Gespräche im Dunkeln 🌙', 'Schalte das Licht im Zimmer vollständig aus. Leg dich neben dein Kind und flüstere ihm ganz leise ins Ohr, was ihr tagsüber erlebt habt oder welche Eigenschaft du an ihm besonders liebst. Flüstern ist eine der zauberhaftesten Methoden, um das Gehirn auf den Schlaf vorzubereiten.'),
  ('ba2db9df-7097-4890-b7eb-8938c592806f', 'Die Ausrede „Das war nicht ich“ 🤥', 'Dein Kind hat absichtlich Wasser auf den Boden geschüttet, zeigt aber auf sein Spielzeugauto und sagt: „Das hat es umgestoßen“? Das ist keine bewusste Lüge, sondern ein Schutzmechanismus. Sag: „Dann bringen wir dem Auto auch bei, wie man das sauber macht“, und lenke sein Denken geschickt in eine andere Richtung.'),
  ('ce02bfea-edc6-42ad-80fd-37f3c322993b', 'Diplomatie an der Rutsche 🤝', 'Dein Kind hat an der Rutsche ein anderes Kind weggeschubst, weil es selbst rutschen wollte? Schimpf oder schlag es nicht aus Scham. Erinnere es sanft, aber bestimmt an die Regel: „Jetzt ist das andere Kind dran, danach du.“ So lernt es soziale Regeln.'),
  ('2128fd31-18d2-4020-9903-1e4bdb06a192', 'Damit das Ei nicht weint 🍳', 'Dein Kind hat Mitleid mit dem aufgeschlagenen Ei und möchte es deshalb nicht essen? Seine Empathie kennt keine Grenzen. Rette die Situation mit einer liebevollen Fantasiegeschichte wie: „Das Ei wird jetzt in deinen Muskeln wohnen und dich stark machen.“')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_de = v.t, body_de = v.b
FROM (VALUES
  ('2fbf236d-dcf9-462e-911e-87f8e16831b1'::uuid, 'Die genaue Anordnung der Kissen 🛏️', 'Weint dein Kind, weil das Kissen millimetergenau liegen muss? Es hat feste Einschlafrituale entwickelt. Geh darauf ein, richte das Kissen so exakt aus, als hättest du es mit einem Lineal vermessen, und gib ihm Sicherheit, indem du entschlossen das Licht ausschaltest.'),
  ('3b18406f-7fbc-4193-88c1-aa910648f2b5', 'Gib mir meinen Müll zurück! 🗑️', 'Dein Kind macht einen riesigen Aufstand, weil du das alte Schokoladenpapier weggeworfen hast, das es aufbewahrt hatte? Für dich ist es Müll, für dein Kind ein Schatz. Lenke seine Aufmerksamkeit auf ein anderes glänzendes Spielzeug.'),
  ('3d6e1c1c-6a73-4824-ae1e-d09852574023', 'Der kleine Diktator am Tisch 👑', 'Bestimmt dein Kind beim Frühstück, wo alle sitzen sollen, und sagt: „Setz dich nicht dorthin, sondern hierhin“? Bewahre mit einem kleinen Lächeln das Gleichgewicht und den Frieden im Raum, ohne seinen Willen abrupt zu brechen: „Gut, dann machen wir es so, wie du möchtest.“'),
  ('51ca75c5-97b8-4826-b323-ca25f125a567', 'Niemandem etwas erklären müssen 📝', 'Niemand sieht, wie erschöpft du zu Hause bist, und das bringt dich zum Platzen? Öffne dein Stimmungstagebuch. Schreib dort alles auf, was dich heute verrückt gemacht hat. Deine Gefühle anzunehmen und aufzuschreiben, wird dir helfen.'),
  ('989e82d9-dbab-4ad4-8fb4-42a6025e0511', 'Stille Bilderbuchzeit 📖', 'Heute Abend wird nicht vorgelesen. Mach sanfte Hintergrundmusik an und schaut euch nur still die Bilder im Märchenbuch an. So wird sein Gehirn durch die visuellen Eindrücke müde, und es schlummert ein, ohne dass du ein einziges Wort sagen musst.'),
  ('6f490476-47fe-4d7a-adc6-bf02e33e53bc', 'Die Herausforderung an der Supermarktkasse 🛒', 'Schreit dein Kind direkt an der Kasse nach Schokolade? Gib trotz der Blicke der anderen nicht nach. Öffne die Einkaufsliste und sag: „Das steht hier nicht drauf, die Kasse wird es nicht erfassen.“ Wenn du konsequent bleibst, wird auch dein Kind nachgeben.'),
  ('851d1060-8f2e-4d29-b181-eb135eec18ca', 'Mit dem Mund statt mit den Händen essen 🐶', 'Möchte dein Kind wie eine Katze direkt vom Teller essen, ohne die Hände zu benutzen? Verbiete es nicht. Die Küche wird ohnehin schmutzig – lass dein Kind 5 Minuten lang Katze sein. Dieses lustige Rollenspiel ist eine der fröhlichsten Möglichkeiten, mangelnden Appetit zu überwinden.'),
  ('9555c57b-eea5-4d41-a55f-827af2218674', 'Schultermassage vom Papa 💆‍♂️', 'Heute warst du lange auf den Beinen. Vom Hinterherlaufen und Spielzeugaufheben tut dir schon der Rücken weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind schläft. Du bist der Motor der Familie und musst unbedingt neue Kraft tanken.'),
  ('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb', 'Ein völlig dunkles Zimmer 🌌', 'Kann dein Kind wegen des Lichts aus dem Flur nicht schlafen? Es braucht offenbar völlige Dunkelheit. Schließ die Tür fest, verdunkle das Zimmer vollständig und lass das Melatonin auf natürliche Weise wirken, damit dein Kind schneller einschläft.'),
  ('e268e86b-b622-447e-800e-69d444728521', 'Die „Das gehört mir!“-Phase 🧸', 'Umklammert dein Kind die Fernbedienung und ruft: „Die gehört mir!“? Es testet gerade Besitzgrenzen aus. Nenn dein Kind nicht egoistisch. Sag stattdessen: „Danke, dass du sie für mich gefunden hast“, lenk seine Aufmerksamkeit auf ein anderes Spiel und nimm die Fernbedienung zurück.'),
  ('e71d30e6-0cdb-4938-b907-fc93e194b4d5', 'Was unvollständige Sätze bedeuten 🗣️', 'Hat dein Kind ein Wort vergessen, gestikuliert mit den Händen und wartet darauf, dass du es errätst? Vervollständige geduldig den Satz und beobachte die Erleichterung in seinem Gesicht. Genau so entwickelt es mit deiner Unterstützung seinen Wortschatz und sein Selbstvertrauen.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'Die Forderung nach trockenem Wasser 💧', 'Statt das Wasser im Glas zu trinken, ruft dein Kind: „Das ist viel zu nass, mach es trocken!“? Such nicht nach Logik, sondern gieße das Wasser in ein andersfarbiges Glas und sag: „Hier ist dein trockenes Wasser.“ Die Kunst der Illusion ist eine deiner stärksten Geheimwaffen als Mama.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'Unbedingt raus in die Natur ⛅', 'Wird seine Energie zwischen vier Wänden zu Aggression und beginnt jeder Satz mit „Nein“? Vertrau auf wettergerechte Kleidung und geh unbedingt mit ihm nach draußen. Der Kontakt mit der Erde kann sein Nervensystem sofort wieder ins Gleichgewicht bringen.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'Mit dem Klingelton automatisch ins Bett ⏱️', 'Muss dein Kind plötzlich auf die Toilette, sobald es Zeit zum Schlafen ist? Stell einen Timer. Führt die Regel ein: „Wenn es klingelt, machen alle das Licht aus.“ So beendest du dieses endlose Abschiedsritual und die geschickten Verzögerungsmanöver ganz ohne Streit.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'Versteckspiel hinter der Tür 🙈', 'Ihr seid spät dran für die Kita, aber dein Kind versteckt sich hinter dem Vorhang und ruft: „Fang mich!“? Schimpfen würde alles nur noch länger dauern. Sag: „Wo ist denn mein kleiner Schatz?“ und spiel 2 Minuten mit. So kannst du es lachend aus seinem Versteck locken.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'Besondere Geräusche beim Vorlesen 🪄', 'Öffne die smarten Märchen. Lass beim Vorlesen eine Tür knarren, den Wind rauschen oder flüstere und verwandle das Zimmer so in ein kleines Hörtheater. Diese ungewöhnliche Klangwelt zieht dein Kind sofort mitten in die Geschichte hinein.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'Bildschirmpause ohne schlechtes Gewissen 📺', 'Hatte dein Kind heute mehr Bildschirmzeit, weil du so viel zu tun hattest? Plagt dich jetzt das schlechte Gewissen? Du kannst nicht jeden Tag perfekt sein. Manchmal sind Bildschirme die harmlosesten Babysitter, die uns vor dem ganz großen Chaos bewahren. Entspann dich.'),
  ('0c893825-691b-4509-9849-6369336b84d4', 'Der Künstler, der sein eigenes Werk zerreißt 🖍️', 'Gefällt deinem Kind eine gemalte Linie nicht, sodass es „Das ist schlecht geworden“ sagt und das Blatt zerreißt? Jetzt entwickeln sich Selbstkritik und ein Gefühl für Perfektion! Sag: „Komm, nächstes Mal probieren wir eine andere Farbe aus“, und verwandle seine Enttäuschung in Entdeckerfreude.'),
  ('bcac5731-4815-4adc-beb4-861e3ff078b1', 'Sich wie eine Katze anschmiegen 🐾', 'Läuft dein Kind heute Morgen auf allen vieren herum, schmiegt sich an dein Bein und sagt nur „Miau“? Statt aufzustehen und ihm Regeln vorzuhalten, reich ihm einfach einen imaginären Napf mit Milch. Mitspielen ist immer leichter und macht mehr Spaß als Schimpfen.'),
  ('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0', 'Katastrophenhilfe in der Küche 🧑‍🍳', 'Du rollst gerade Teig aus, da schiebt dein Kind einen Stuhl heran und will unbedingt selbst das Mehl hineinschütten? Wenn du es nicht lässt, wird es weinen. Gib ihm eine kleine Plastikschüssel und etwas Mehl. Die Küche wird danach zwar wie ein Schlachtfeld aussehen, aber sein Ego ist zufrieden.'),
  ('776040ef-af05-4430-a752-3b380b194dba', 'Der Mond läuft uns hinterher 🌕', 'Ihr fahrt abends nach Hause, dein Kind schaut aus dem Fenster und sagt, der Mond würde euch folgen? Es denkt, das Universum drehe sich um es. Zerstöre diese schöne Fantasie nicht, sondern mach mit und frage: Wo will der Mond wohl mit uns hin?'),
  ('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14', 'Die Liebe zum schmutzigen T-Shirt 👕', 'Dein Kind trägt seit 3 Tagen dasselbe T-Shirt und lässt dich nicht, es zu waschen? In diesem Alter geben bestimmte Dinge Kindern ein Gefühl von Sicherheit. Diskutiere nicht, sondern erzähle eine kleine Fantasiegeschichte: Ich habe dein T-Shirt auf ein magisches Abenteuer in der Waschmaschine geschickt. Es kommt stärker zurück. So kannst du es ihm abnehmen – es wird dir glauben.'),
  ('b740d6be-007b-4aa6-9c46-6ffbce8b157e', 'Trauerfeier für eine Ameise 🐜', 'Dein Kind hat im Park eine Ameise auf dem Boden entdeckt, will nicht weitergehen und weint, weil sie sich bestimmt verlaufen hat? Seine Empathie kennt keine Grenzen. Sag ihm, dass die Ameisenmama gleich kommt und sie abholt.'),
  ('fcc60573-09e9-4a7c-8399-55df532828cd', 'Weißes Rauschen im Sumpf 🌊', 'Dein Kind hüpft im Zimmer herum, statt zu schlafen? Spiele im Hintergrund ein kräftiges Meeresrauschen oder weißes Rauschen ab. Der gleichmäßige Klang wird die wilde Energie in seinem Kopf fortspülen, und nach 10 Minuten fallen ihm die Augen zu.'),
  ('73abbd29-9b2f-4f48-8461-6482853b741f', 'Katastrophale Hilfe mit dem Besen 🧹', 'Du räumst gerade auf, da kommt dein Kind, ruft Ich mache das! und verteilt den Schmutz noch weiter im Zimmer? Wenn du es nicht lässt, geht die Welt unter. Gib ihm ein feuchtes Tuch und sage: Du bist nur für diese Ecke des Tisches zuständig. So kannst du deine Arbeit erledigen und sein Ego bleibt ebenfalls zufrieden.'),
  ('eacaec53-45d2-4b70-9f52-8b48878bd78c', 'Zeit, die leere Wand anzuschauen 🛋️', 'Dein Kind spielt allein im Zimmer? Bitte verschwende diesen Moment nicht mit Abwaschen! Setz dich aufs Sofa, nimm deinen Tee und schau einfach nur die Wand an. Ja, ohne an irgendetwas zu denken. Trag 5 Minuten Frieden in dein Stimmungstagebuch ein. Du brauchst das.'),
  ('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3', 'Das Drama Mein Haar ist kaputt! 🪮', 'Sobald dein Kind den Kamm sieht, behauptet es, seine Haare täten weh, und läuft davon? Vielleicht macht ihm seine sensorische Empfindlichkeit Angst. Lenke es ab. Gib ihm einen Spiegel und sage: Mal sehen, wer im Spiegel die lustigste Grimasse mit herausgestreckter Zunge macht! Während es beschäftigt ist, kämmst du seine Haare blitzschnell – und fertig.'),
  ('c6026760-e985-429a-b39f-d4d1786df630', 'Das Mini-Labor in der Badewanne 🛀', 'Mischt dein Kind verschiedenfarbige Seifen ins Wasser und braut daraus einen Zaubertrank? Ja, dabei wird das Bad zum Schlachtfeld. Aber dein Kind lernt dabei etwas über Lösungsmittel. Diese wissenschaftliche Entdeckungsreise vertreibt die Müdigkeit des Abends und ist die schönste Art, dein Kind auf einen ruhigen Schlaf vorzubereiten.'),
  ('40e041b4-2484-475f-93b5-25cda3ee362e', 'Das „Wer bist du?“-Theater 🎭', 'Schaut dein Kind dich an, als wärst du eine Fremde, und fragt: „Wer bist du? Wo ist meine Mama?“ Das ist ein neues Rollenspiel. Sag: „Ich bin die Ärztin und möchte dein Herz abhören“, und kitzle dein Kind. Lass das Zimmer am Morgen vor Lachen beben.'),
  ('417e0bcc-cf3b-4a96-95e9-58a2f51764f6', 'Kunst aus Toilettenpapier 🧻', 'Du kommst ins Zimmer und siehst, dass das gesamte Toilettenpapier abgerollt und im Haus verteilt wurde? Statt dich zu ärgern, sammelt das Papier gemeinsam ein und formt daraus einen Ball. Besiege das Chaos nicht mit Schimpfen, sondern mit Kreativität und Lachen.'),
  ('4a1de341-603c-4aae-ab4d-439d7bb05d7c', 'Der Genuss der Stille 🤫', 'Endlich schläft dein Kind. Ist es im Haus so still geworden, dass dir die Ohren klingeln? Öffne den Schallpegelmesser in der App. Der Anblick der Anzeige „0 Dezibel“ ist die beste visuelle Massage der Welt für dein müdes, vom Lärm überreiztes Gehirn.'),
  ('3d9dcc3e-1698-4fca-951e-a58aed0724d2', 'Der Becher hat die falsche Farbe 🥤', 'Ist im Zimmer die Welt untergegangen, weil du das Wasser im gelben Becher serviert hast? Diskutiere nicht darüber – dein Kind testet heute Morgen einfach seine Grenzen aus. Gieß das Wasser sofort in den blauen Becher, stell den Frieden wieder her und spar dir deine Energie.'),
  ('522145b2-4826-4821-80c0-e0e180045415', 'Einfach fest an dich drücken 🫂', 'Hat dein Kind dich heute wirklich in den Wahnsinn getrieben und dir die ganze Energie geraubt? Aber im Bett schläft es so unschuldig ... Mach das Licht aus und lass die Gute-Nacht-Geschichte heute ausfallen. Leg dich zu deinem Kind, atme diesen unverwechselbaren Kinderduft tief ein und sei dankbar.'),
  ('792e3525-032e-4662-ba49-1276a3b3ef78', 'Die Geschichten anderer Mütter 💬', 'Lass dich nicht entmutigen, wenn du Instagram öffnest und sofort die scheinbar perfekten Kinder aller anderen siehst! Schließ die App und besuche die Anacan Community. Atme tief durch, wenn du siehst, dass es bei allen zu Hause genauso chaotisch aussieht wie bei dir.'),
  ('3e4bbd84-ef8f-45a2-b630-5aeadd95390e', 'Die „Halt nicht meine Hand!“-Unabhängigkeit 🚶‍♂️', 'Will dein Kind unterwegs deine Hand loslassen und allein gehen? Wenn ihr euch in einem sicheren Bereich befindet, lass dein Kind seine Selbstständigkeit ausprobieren. Geh einfach zwei Schritte hinter diesem kleinen, freiheitsliebenden Rebellen her und beobachte ihn voller Stolz.'),
  ('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f', 'Die sichtbare Bestätigung der Stille 📉', 'Endlich ist dein Baby eingeschlafen. Hallt das Schreien immer noch in deinen Ohren nach? Öffne den Schallpegelmesser. Zu beobachten, wie die Linie im Zimmer auf 0 desibel sinkt, ist die schönste visuelle Massage der Welt für dein müdes, überreiztes Gehirn.'),
  ('48318bc7-c4f3-4717-9848-18bd10967e29', 'Papas erfundene Geschichte 🦸‍♂️', 'Deine Stimme ist weg und du möchtest kein Buch vorlesen? Überlass die Geschichte Papa. Lass ihn eine frei erfundene, absurde Geschichte erzählen, in der euer Kind die Hauptrolle spielt. Lehn dich entspannt an die Wand und genieße es, wie euer Kind über seinen Papa lacht.'),
  ('4ac93f87-372d-4d1a-a449-a2da763a8227', 'Dieses Essen hat die falsche Form 🥒', 'Dein Kind schiebt den Teller weg, weil du die Gurke länglich statt rund geschnitten hast? Sein Sinn für die Optik von Lebensmitteln entwickelt sich gerade erst. Finde heraus, wie du dasselbe Gemüse als lustige Figuren tarnen kannst. Du wirst dieses Designspiel gewinnen.'),
  ('61167ef0-dce7-4186-9b36-5aa8a00936ff', 'Für einen Moment allein ins Bad flüchten 🛀', 'Dein Kind klammert sich den ganzen Tag an dein Bein und dein Körper kann Berührungen kaum noch ertragen? „Touched out“ zu sein ist real. Lass es im Zimmer, geh für 5 Minuten ins Bad, schließ die Tür und atme einfach durch. Du musst neue Kraft tanken.'),
  ('a897741a-cd22-4371-a712-b1ae3911676e', 'Selbst erfundene Lieder 🎤', 'Die Sonne ist noch nicht aufgegangen, aber dein Kind hüpft schon herum und singt laut irgendwelche Fantasiewörter? Bring es nicht schreiend zum Schweigen. Ein Kind, das den Morgen mit einem Lied beginnt, baut überschüssige Energie und Aggressionen ab. Mach bei dieser wilden Energie 1 Minute lang mit – dann bist du garantiert wach.'),
  ('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e', 'Die perfekten Mütter auf Instagram 📱', 'Du öffnest Instagram, siehst nur aufgeräumte Wohnungen und wohlerzogene Kinder und fühlst dich sofort schlecht? Lösch die App! Komm in die Anacan-Community. Lies die Geschichten echter Mütter, deren Zuhause genauso chaotisch und deren Kinder genauso eigensinnig sind wie deine, und atme auf.'),
  ('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4', 'Mit Flüstern in den Schlaf 🤫', 'Dein Kind springt aus dem Bett und hüpft überall herum? Senke deine Stimme plötzlich ganz ab. Sprich nur noch sehr leise und flüstere. Um dich zu verstehen, muss es sich stark konzentrieren. Nach 5 Minuten wird sein Gehirn müde und schaltet in den Schlafmodus. Probier es aus!'),
  ('1dcf070f-1d18-4228-b248-9ed1c6174aff', 'Ein Spielzeug im Kühlschrank 🧊', 'Du öffnest den Kühlschrank und findest darin ein Spielzeugauto aus Gummi? Das ist ein Spiel, bei dem dein Kind sein Gedächtnis testet und ausprobiert, wie ein Gegenstand an einem ungewöhnlichen Ort wirkt. Ärgere dich nicht – diese Absurdität gehört zu seiner Entwicklung.'),
  ('4c96a8e1-971d-4b98-9e5c-faff2c2726a9', 'Plötzlicher Philosophieschub 🤔', 'Hat dein Kind plötzlich eine wissenschaftliche Frage gestellt wie: „Warum ist es am Meeresgrund dunkel?“ Keine Panik! Öffne die Anacan AI und lass dir eine liebevolle, märchenhafte und von Kinderärzten sowie Psychologen geprüfte Antwort geben, die dein Kind in diesem Alter verstehen kann. Lies sie ihm einfach vor. So bist du immer die Mama, die alles weiß!'),
  ('9f289ae7-fe30-4b1a-8ebd-63874521363d', 'Fangen im dunklen Zimmer 🔦', 'Es ist Schlafenszeit, aber dein Kind steckt noch voller Energie? Schalte alle Lichter im Zimmer aus. Nimm eine kleine Taschenlampe und spielt: „Mal sehen, wen der Lichtstrahl an der Wand fängt!“ Das Spielen im Dunkeln fördert die Melatoninausschüttung und macht dein Kind gleichzeitig müde.'),
  ('d28d5d46-d2a6-4daa-b454-adbdf6be3f63', 'Der Schmerz einer unsichtbaren Wunde 🩹', 'Am Finger ist nichts zu sehen, aber dein Kind weint, weil es sich angeblich verletzt hat, und möchte ein Pflaster? Es geht nicht um körperliche Schmerzen, sondern darum, dass es deine Zuwendung braucht. Kleb das Pflaster auf, gib einen Kuss darauf und sag: „Mit meinem Zauberkuss habe ich es geheilt.“ So ist euer Tag gerettet.'),
  ('19ac1700-7f02-47aa-b9e8-f8064c7e18d0', 'Geschlossene Türen und Privatsphäre 🚪', 'Dein Kind ist in sein Zimmer gegangen, hat die Tür hinter sich geschlossen und gesagt, du sollst nicht hereinkommen? Nimm es nicht persönlich. Es möchte sich einfach kurz von Lärm und Chaos zurückziehen und ausruhen. Solange seine Sicherheit gewährleistet ist, lass es diesen persönlichen Freiraum genießen. Es wird groß!'),
  ('2cb51eab-cbdc-48ba-8569-e245d61ad27e', 'Endlose Ausreden vor dem Schlafengehen 🚰', 'Die Augen fallen schon zu, aber plötzlich springt dein Kind auf und sagt: „Mein Fuß juckt!“ oder „Ich will Wasser!“? Es ist ein Profi darin, das Einschlafen hinauszuzögern. Stell einen Timer und sag: „Wenn das Handy klingelt, gehen auch alle Ausreden schlafen.“ Überlass dem Handy die Autorität und halte dich selbst heraus.'),
  ('9240add5-52c7-45dc-8ae0-15dd7dadfa88', 'Das ist nicht mein Name 📛', 'Sagt dein Kind: „Nenn mich nicht bei meinem Namen, ich bin Spider-Man!“? Es erkundet gerade seine Identität. Mach einfach mit! Serviere das Frühstück mit den Worten: „Bitte sehr, Herr Spider-Man.“ Du hast es in der Hand, die angespannte Stimmung im Zimmer innerhalb von Sekunden in eine lustige Situation zu verwandeln.'),
  ('2127b5f4-7e9a-438e-9094-bd9d7f0d5237', 'Erpressung mit der Einkaufsliste 🛒', 'Verlangt dein Kind direkt an der Kasse plötzlich nach Süßigkeiten? Kümmere dich nicht darum, ob die Umstehenden dich mit einem „Was ist das für eine Mutter?“-Blick ansehen. Öffne die Einkaufsliste, sag: „Das steht nicht auf der Liste, deshalb darf die Kasse es uns nicht verkaufen“, und bleib konsequent.'),
  ('73af2e7a-1bb5-4576-8888-801050bfada3', 'Wenn die Kunst an der Wand landet 🖍️', 'Du kommst ins Zimmer und entdeckst ein neues Wandgemälde? Atme tief durch. Dein Kind hat die Grenzen des Papiers überschritten und probiert seine motorischen Fähigkeiten im Großformat aus. Bevor du das Meisterwerk entfernst, solltest du es unbedingt fotografieren, damit ihr es euch später gemeinsam ansehen und darüber lachen könnt.'),
  ('ba708130-cef9-4b08-8a17-7c16cb66de0a', 'Will nicht aus dem Haus ⛅', 'Zu Hause herrscht Chaos, und dein Kind sitzt weinend auf dem Sofa und sagt, dass es nicht mitkommt? Öffne die Wetter- und Kleidungsübersicht, prüfe die tatsächliche Außentemperatur, zieh ihm ein passendes Outfit an und geh mit ihm in den Park – auch wenn du etwas nachhelfen musst. Sobald es die frische Luft im Gesicht spürt, ist die ganze schlechte Laune wie weggeblasen.'),
  ('c3fe5fd9-dde9-47f5-b95c-98d26881d393', 'Wenn dein Kind zum Märchenhelden wird 🪄', 'Öffne die interaktiven Märchen. Ersetze den Namen der Hauptfigur einfach durch den Namen deines Kindes. Erzähle im Laufe der Geschichte, wie mutig und brav diese Figur einschläft. Wenn dein Kind sich selbst in der Geschichte wiedererkennt, wird es ohne Widerstand die Augen schließen.'),
  ('139226ae-9370-42b4-954a-012623528599', 'Unerklärliches Weinen mitten in der Nacht 😭', 'Dein Kind wacht mitten in der Nacht mit geschlossenen Augen weinend auf und reagiert nicht auf dich? Prüfe es mit der Schreianalyse – höchstwahrscheinlich handelt es sich um einen Nachtschreck. Versuche nicht, dein Kind zu wecken. Bleib einfach bei ihm und halte seine Hand. Es wird sich von selbst beruhigen und wieder einschlafen.'),
  ('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1', 'Mamas geheime Schokoladenpause 🍫', 'Du versteckst dich hinter dem Schrank und isst heimlich Schokolade? Lass sie dir schmecken! Nach all den endlosen Warum-Fragen und dem Geschrei hast du dir diese Glukose redlich verdient, um neue Energie zu tanken. Mach dir deswegen niemals Vorwürfe.'),
  ('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe', 'Fangen spielen mit dem Schatten 🏃‍♂️', 'Dein Kind rennt unterwegs plötzlich los und versucht, seinen eigenen Schatten zu fangen? Seine Fantasie ist gerade stärker als seine Logik. Halt es nicht auf, sondern versuch ebenfalls, deinen Schatten zu fangen, und mach bei diesem verrückten, fröhlichen Spiel mitten auf der Straße mit. Das Leben ist zu kurz, um alles so ernst zu nehmen.'),
  ('4d4b704f-57d5-4f72-9df3-13398bb1f2e3', 'Das Falsch-herum-Schuh-Syndrom 👟', 'Dein Kind hat den rechten Schuh links und den linken Schuh rechts angezogen und lässt dich das nicht korrigieren? Lass es einfach so! Sein Stolz darüber, die Schuhe ganz allein angezogen zu haben, und sein Gefühl von Selbstständigkeit sind millionenfach wertvoller als richtig sitzende Schuhe.'),
  ('95ee8df4-a59a-42f4-b252-bf062304f70b', 'Meinen Frust digital loswerden 📝', 'Niemand sieht, wie erschöpft du heute bist, und selbst das Lächeln fühlt sich erdrückend an? Öffne dein Stimmungstagebuch. Schreib dir all den Frust und die Erschöpfung von der Seele. „Ich kann nicht mehr“ aufzuschreiben, wird dir schneller helfen als der Versuch, falsche Perfektion aufrechtzuerhalten.'),
  ('ec907054-781c-4e3c-be06-6c97119a4864', 'Schultermassage vom Papa 💆‍♂️', 'Du warst heute lange auf den Beinen, bist deinem Kind hinterhergelaufen und hast Spielzeug vom Boden aufgehoben – dein Rücken tut höllisch weh. Bitte deinen Partner um eine 10-minütige Schultermassage, sobald das Kind schläft. Du bist der Motor dieses Zuhauses, und auch ein Motor muss sich unbedingt ausruhen und regenerieren.'),
  ('486ad622-5eff-484f-8ea8-ea64a245ed91', 'Warum hast du die Banane geschält?! 🍌', 'Im Zimmer bricht gerade ein Aufstand aus, weil du die Banane geschält hast? Die goldene Regel in diesem Alter: Dein Kind will alles selbst bestimmen. Du kannst die Schale nicht wieder ankleben – gib ihm sofort eine neue Banane und lass es sie so schälen, wie es möchte. Ein Machtkampf kostet dich nur Zeit.'),
  ('b59a06d3-66eb-4eef-8c37-b58f8b3331ca', 'Gemeinsam als Paar schweigen 🥂', 'Das Kind schläft, die Wohnung ist aufgeräumt. Setz dich neben deinen Partner auf das Sofa und lass sogar den Fernseher aus. Werft euch einfach diesen Blick zu: „Auch das haben wir geschafft – wir haben überlebt.“ Genau das ist einer der romantischsten und ehrlichsten Team-Momente des Elternseins.'),
  ('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b', 'Das kleine Haus unter dem Tisch ⛺', 'Dein Kind hat es sich unter dem Esstisch gemütlich gemacht und möchte dort zu Mittag essen? Sei bei den Regeln etwas flexibel. Reich ihm die Suppe in sein dunkles Versteck. Ein Ortswechsel kann selbst das appetitloseste Kind mit einem Hauch von Abenteuer zum Essen bringen.'),
  ('1f9be131-7868-4433-adc0-efe09d70723d', 'Du spielst nicht mit mir! 😠', 'Während du auf dein Handy geschaut hast, kam dein Kind zu dir, drehte dein Gesicht mit beiden Händen zu sich und forderte: „Schau mich an!“ Es hat recht. Es möchte nicht nur deine körperliche Anwesenheit, sondern deine ungeteilte Aufmerksamkeit. Leg das Handy weg und halte 3 Minuten lang vollen Blickkontakt – dein Kind wird sich sofort beruhigen.'),
  ('86f2c2e9-f758-416c-a78d-b431eb3db53a', 'Seiltanz auf der Bordsteinkante 🧱', 'Auf dem Weg zum Park möchte dein Kind nicht den geraden Weg nehmen, sondern unbedingt auf der schmalsten Bordsteinkante balancieren? Sichere es am Arm ab und lass es diesen kleinen Gipfel bezwingen. So entwickeln sich Gleichgewichtssinn und Selbstvertrauen gleichzeitig – halte es nicht davon ab.'),
  ('963db29c-a2ad-4233-bbc2-364a68692feb', 'Das Klangtheater im Kinderzimmer 🪄', 'Bist du heute Abend zu müde zum Vorlesen? Öffne die Smart-Märchen. Während die Geschichte vorgelesen wird, kannst du mit dem Knarren einer Tür, dem Rauschen des Windes und Flüstern ein kleines Klangtheater im Zimmer erschaffen. Diese ungewöhnliche Geräuschkulisse zieht dein Kind sofort mitten in die Märchenwelt hinein.'),
  ('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6', 'Mit einem Wettrennen aus dem Park 🌳', 'Es ist Zeit, den Park zu verlassen, und schon beginnt der Wutanfall. Dein Kind einfach mitzuzerren, wird nicht funktionieren. Sag: „Mal sehen, wer wie ein Hase schneller bis zum Auto hüpfen kann!“ So lenkst du seine Aufmerksamkeit sofort auf einen lustigen Wettkampf – und es wird garantiert mitmachen.'),
  ('42b47472-82e3-49e8-bb91-8de4938efbde', 'Atme einfach seinen Duft ein 🫂', 'Hat dein Kind dich heute wirklich in den Wahnsinn getrieben und dir die ganze Energie geraubt? Aber wie unschuldig es jetzt im Bett schläft ... Mach das Licht aus. Leg dich zu ihm, atme diesen reinen Kinderduft ganz tief ein und flüstere ihm zu, wie wertvoll es für dich ist.'),
  ('67931668-7ad8-456d-8077-31b1756abd2c', 'Gib das Wasser in einem anderen Becher! 🥤', 'Es gibt einen Riesenaufstand, weil du das Wasser in den gelben Becher gefüllt hast? „Ich wollte den blauen!“, heißt es dann. Mach kein großes Thema daraus – dein Kind testet nur seine Grenzen. Gieß das Wasser einfach in den blauen Becher um, stell den Frieden wieder her und spar dir deine Energie.'),
  ('047715fd-ae66-4d00-8341-50e230c2b688', 'Dinosaurier essen keinen Brei! 🦖', 'Heute Morgen beantwortet dein Kind keine Fragen, sondern brüllt nur? Dann ist es heute eben ein T-Rex. Frag: „Und was essen T-Rexe zum Frühstück?“ Lass dich auf seine Fantasiewelt ein – so sitzt es ganz friedlich und ohne Tränen am Tisch.'),
  ('2da52e9b-b72c-461f-8480-276d6d5e47df', 'Keine Denkblockade mitten im Supermarkt 🛒', 'Du stehst im Supermarkt und hast vergessen, was du kaufen wolltest? Der Mama-Kopf ist einfach wirklich randvoll. Öffne die Einkaufsliste in der App und verlass dich auf dein digitales Gedächtnis – so kommst du garantiert nicht mit leeren Händen nach Hause.'),
  ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4', 'Bildschirme aus, Schlafmodus an 🌙', 'Damit dein Kind schneller einschläft, schalte 1 Stunde vor dem Zubettgehen alle Fernseher und Handybildschirme im Zimmer aus. In einer dunklen Umgebung wird Melatonin schneller ausgeschüttet – lass den natürlichen Prozess für dich arbeiten.'),
  ('020f5f2c-bba3-4441-b9a0-518ce0263ac5', 'Kein Müll, sondern ein Kunstwerk 🎨', 'Dein Kind hat mitten im Zimmer aus trockenen Nudeln und Papierschnipseln ein großes Kunstwerk geschaffen? Leg deinen Ordnungsdrang beiseite. Das ist eine so schöne feinmotorische Leistung, dass sie in den Entwicklungs-Tracker gehört. Dein Zuhause ist schließlich kein Museum.'),
  ('7231bd75-47cb-4255-ae64-144dcd8d314f', 'Die Zahl der Stille auf dem Display 📉', 'Endlich schläft dein Kind. Im Haus ist es so still, dass deine Ohren klingeln? Öffne den Schallpegelmesser in der App. Der Anblick der Anzeige mit 0 Dezibel ist die beste visuelle Massage der Welt für dein müdes, vom Lärm überreiztes Gehirn.'),
  ('d3223299-be6e-4dfc-bfb7-c168e33bb866', 'Vervollständige angefangene Sätze 🗣️', 'Wenn deinem Kind ein Wort nicht einfällt, gestikuliert es und wartet darauf, dass du es errätst? Sein Wortschatz wächst, aber sein Gehirn arbeitet schneller als seine Zunge. Vervollständige den Satz geduldig und beobachte die Erleichterung in seinem Gesicht: „Jaaa, genau das wollte ich sagen!“'),
  ('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e', 'Sofa-Ringen mit Papa 🤼‍♂️', 'Dein Kind ist weggerannt und hat sich versteckt, um nicht ins Bett gehen zu müssen? Übergib an Papa. Lass die beiden auf dem Sofa eine Runde spielerisch ringen. Dieses laute, schweißtreibende Papa-Kind-Spiel verbraucht auch noch den letzten Rest seiner hartnäckigen Energie – danach kann es sich viel leichter dem Schlaf hingeben.'),
  ('76fc525d-97d8-486f-adde-6d0bdc417bbe', 'Das „Das gehört mir!“-Drama 🧸', 'Umklammert dein Kind die Fernbedienung und ruft: „Das gehört mir!“? Es testet gerade Besitzgrenzen aus. Nenne es nicht egoistisch. Sag stattdessen: „Danke, dass du sie für mich gefunden hast“, lenke seine Aufmerksamkeit auf ein anderes Spiel und nimm die Fernbedienung behutsam zurück.'),
  ('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b', 'Wenn es klingelt, gehen wir schlafen ⏱️', 'Das Zubettgehen zieht sich immer länger hin. Noch etwas trinken, zur Toilette gehen, sich von der Wand verabschieden ... Stelle den Timer auf deinem Handy und führe die Regel ein: Sobald es klingelt, machen alle das Licht aus. Einer äußeren Autorität zu folgen, fällt Kindern oft leichter.'),
  ('f24ccc35-5845-4b4b-803c-db7a68218026', 'Du musst dich vor niemandem rechtfertigen 🛑', 'War deine Geduld heute am Ende und du bist laut geworden? Mach dich nicht dafür fertig. Schreib in dein Stimmungstagebuch: „Ich bin eine gute Mutter, ich war heute einfach sehr müde.“ Sei mitfühlend mit dir selbst – niemand erwartet von dir, perfekt zu sein.'),
  ('3fdd99bb-9e81-4b54-a9b9-28997c15bd09', 'Mamas Energieriegel 🥗', 'Du hast dir verschiedene Menüs ausgedacht, damit dein Kind etwas isst – aber was hast du selbst gegessen? Bereite dir den einfachen 5-Minuten-Salat für Mütter aus den gesunden Rezepten zu.'),
  ('8e09c446-7bb4-4213-903b-ca0d9d539235', 'Heißer Tee in aller Stille ☕', 'Dein Kind ist endlich eingeschlafen. Schau auf das Spielzeugchaos mitten im Zimmer und atme tief durch. Räume es jetzt nicht auf! Gieß dir eine heiße Tasse Tee ein, setz dich aufs Sofa und genieße einfach die Ruhe, die dir diese Stille schenkt.'),
  ('b85f6433-c512-4f2e-a5d4-b9023f0eb544', 'Lange Gespräche mit leblosen Gegenständen 🗣️', 'Erzählt dein Kind einem Stein im Park oder einem Stuhl zu Hause mit völligem Ernst etwas? Durch das Spielen lernt es die Regeln und die Welt kennen.'),
  ('039b7451-67d0-43b6-9ed0-d4ec9bf47752', 'Die Jacke wird verweigert 🧥', 'Dein Kind will die Winterjacke nicht anziehen, weil draußen die Sonne scheint? Lass dich vom Blick aus dem Fenster nicht täuschen. Öffne „Wetter und Kleidung“ und zeig ihm auf dem Handy das Symbol eines winterlich angezogenen Kindes. Überlass die Regel dem digitalen Bildschirm und halte dich aus der Diskussion heraus.'),
  ('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c', 'Versteckspiel unter dem Bett 🛏️', 'Dein Kind möchte unbedingt unter dem Bett statt im Bett schlafen? Solche kleinen, geschlossenen Räume vermitteln Kindern ein ähnliches Gefühl von Geborgenheit wie im Mutterleib. Lass es zu und leg dein Kind behutsam ins Bett, sobald es eingeschlafen ist. Schone deine Kräfte.'),
  ('4d053e9f-b091-45c7-9c6a-66e7f1ab590e', 'Die Kunst, Gemüse zu verstecken 🥦', 'Hat dein Kind die eine Karotte in der Suppe entdeckt und gesagt: „Das esse ich nicht“? Püriere das Gemüse und mische es unter Saucen – mal sehen, ob es das jetzt noch findet! So überlistest du seinen kulinarischen Spürsinn ganz geschickt.'),
  ('db42b564-536c-485c-afff-dce099e8c451', 'Ich will fliegen! 🕊️', 'Springt dein Kind vom Sofa, flattert mit den Armen und wird wütend auf dich, weil es nicht fliegen kann? Für die Gesetze der Physik ist es noch etwas zu früh. Sag ihm: „Du kannst noch nicht fliegen, weil deine Flügel erst wachsen müssen“, und lenke es darauf, an einer weichen Stelle zu springen.'),
  ('294ce10a-4fac-4bfb-8007-e2e3fea714ad', 'Das eigene Bild kritisieren 🖍️', 'War dein Kind mit einer gezeichneten Linie unzufrieden, hat „Das ist schlecht geworden“ gesagt und das Papier zerrissen? Jetzt entwickeln sich Selbstkritik und der Wunsch nach Perfektion! Sag: „Lass uns beim nächsten Mal eine andere Farbe ausprobieren“, und verwandle seine Enttäuschung in eine ermutigende Entdeckungsreise.'),
  ('76df67fe-b947-400d-8825-c8fd1637478f', 'Stiller Trost in der Community 💬', 'Bist du so erschöpft, dass du nicht einmal mit jemandem über deine Sorgen sprechen möchtest? Dann besuche die Anacan Community und lies einfach nur mit. Zu sehen, wie andere Mütter mit denselben absurden Krisen umgehen, kann dir den stärksten stillen Trost schenken.'),
  ('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2', 'Meeressturm in der Badewanne 🌊', 'Ist Baden nur ein Vorwand und dein Kind erschafft in der Wanne eigentlich einen Ozean, in dem es mit den Wellen spielt? Lass es ruhig spielen. Das Plätschern und Spritzen des Wassers wird seine schier endlose, unbändige Energie fortspülen. Am Abend legt es sich dann ganz ohne Widerstand ins Bett.'),
  ('3e4c8054-2b97-4968-a10f-267dccb5b8c0', 'Plötzliche Morgenphilosophie 🤔', 'Hat dein Kind plötzlich eine wissenschaftliche Frage gestellt: „Warum kann man den Wind nicht sehen?“ Keine Panik! Öffne die Anacan KI und lass dir eine liebevolle, märchenhafte und von Kinderärzten sowie Psychologen geprüfte Antwort geben, die dein Kind in diesem Alter verstehen kann. Lies sie ihm einfach vor. Du bist die Mama, die immer alles weiß!'),
  ('b7b7faa9-f807-43f1-bf54-6d7f963c5e32', 'Einfach mal ruhig hinlegen 🛋️', 'Beschäftigt sich dein Kind allein mit einem Puzzle und plötzlich ist es still im Haus? Bitte nutze diesen Moment nicht zum Staubsaugen! Leg dich aufs Sofa. Auch dein Akku muss aufgeladen werden, damit du dieses Tempo bis zum Abend durchhältst. Ruh dich unbedingt aus.'),
  ('ccae9470-c321-4925-94c0-7408317b4c14', 'Schätze aus der Hosentasche 🪨', 'Hast du beim Waschen seiner Hose ein getrocknetes Blatt oder einen Stein in der Tasche gefunden? Das ist keine Gier, sondern kindliche Entdeckerlust. Wirf den Fund mit ernster Miene in den Müll, aber lächle innerlich über deinen kleinen Sammler – er entdeckt gerade die Welt.'),
  ('73a43849-8300-493d-9040-f05eaf01e5b6', 'Eiskalte Unlogik 🥶', 'Besteht dein Kind darauf, unbedingt Eiswürfel in den heißen Tee zu geben, statt ihn durch Pusten abzukühlen? Es entdeckt gerade den Gegensatz zwischen heiß und kalt. Gib ihm das Eis und lass es beim Schmelzen zusehen. Auch wenn sich das Frühstück dadurch verzögert, hat es seine eigene wissenschaftliche Entdeckung gemacht.'),
  ('1171703b-c644-4ad0-8298-a24063264467', 'Märchenstunde mit Regengeräuschen 🌧️', 'Deine Stimme versagt und du hast keine Kraft, ein Märchen vorzulesen? Spiele bei den smarten Märchen im Hintergrund einfach nur Regen- und Waldgeräusche ab. Diese gleichmäßige Ruhe der Natur wirkt manchmal schneller einschläfernd als die beste und spannendste Geschichte.'),
  ('43e7fbfe-64bc-4627-85d6-4ddae59c6985', 'Ärger mit dem Spiegelbild 🪞', 'Steht dein Kind vor dem Spiegel, macht unterschiedliche Geräusche und schneidet Grimassen? Das ist ein Zeichen dafür, dass sich sein Selbstbewusstsein entwickelt. Es erkundet seinen Körper und testet, wie seine Gefühle von außen aussehen. Beobachte es einfach still aus der Nähe.'),
  ('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5', 'Berührungs-Overload 🔋', 'Hängt dein Kind den ganzen Tag an deinem Bein und möchte auf den Arm? Du bist körperlich völlig erschöpft und hast gerade einen Berührungs-Overload. Lass es mit seinen Spielsachen im Zimmer und zieh dich für 5 Minuten ins Bad zurück. Schließ die Tür und genieße einfach diesen kurzen Moment für dich allein.'),
  ('2a662eb4-1c17-46f1-ad5d-c566286402e8', 'Streit auf dem Spielplatz 🤝', 'Hat dein Kind ein anderes Kind an der Rutsche weggeschubst, weil es selbst rutschen wollte? Alle schauen dich an. Schlag dein Kind nicht aus Scham. Erinnere es mit sanfter, aber bestimmter Stimme an die Regel: „Jetzt ist das andere Kind dran, danach sind wir an der Reihe.“ So funktioniert das Miteinander.'),
  ('c0dcbfbe-b91a-462c-890d-a8770be19cf3', 'Fangen spielen am frühen Morgen 🏃‍♂️', 'Rennt dein Kind morgens um 7 Uhr über die Sofas? Schimpf nicht. Lass deine Aufgaben für 2 Minuten liegen, spring mit ihm herum und mach einfach mit. In die Fantasiewelt deines Kindes einzutauchen, mag sich ungewohnt anfühlen, ist aber auch für dich eine erstaunlich wirksame Methode, Stress abzubauen.'),
  ('e41be904-7cb3-4dd6-8966-ea3b375783f6', 'Die wissenschaftliche Lösung gegen nächtliche Angst 🔦', 'Hat dein Kind Angst vor den Schatten im Schlafzimmer? Verdunkle das Zimmer nicht vollständig, sondern stelle ein kleines Nachtlicht mit warmem Licht auf. Das stört weder die Melatoninausschüttung noch den Schlaf und gibt ihm zugleich visuelle Sicherheit, sodass die Angst nachlässt.'),
  ('b5588608-ef71-4787-b05e-09f4f4f2492a', 'Ein plötzliches „Ich liebe dich“ 💖', 'Mitten im Spielen schaut dein Kind dich plötzlich an, läuft auf dich zu und fällt dir um den Hals. Dafür haben sich all die schlaflosen Nächte und die Erschöpfung gelohnt! Genieße den tiefen, einzigartigen Frieden dieses Augenblicks und vergiss für einen Moment das ganze Chaos.'),
  ('e2ac4132-1e14-42d5-a828-9c40ffb00179', 'Die magische Kraft des Flüsterns 🤫', 'Springt dein Kind aus dem Bett und hüpft wild herum? Dann werde plötzlich ganz leise. Fang an, mit sehr leiser Stimme zu flüstern. Um dich zu verstehen, muss es sich richtig konzentrieren – und sein Gehirn wird nach 5 Minuten müde und schaltet in den Schlafmodus. Probier es aus!'),
  ('f5be8b0c-0a17-4790-b9b1-73d205d64a76', 'Die Instagram-Mama-Illusion 📱', 'Du öffnest Instagram, siehst überall aufgeräumte Wohnungen und brave Kinder und fühlst dich sofort entmutigt? Lösch die App! Komm in die Anacan-Community. Dort findest du die Geschichten echter Mütter, deren Zuhause genauso chaotisch und deren Kind genauso willensstark ist wie deins.'),
  ('14317db1-b6eb-40d2-8404-59bcea4acdf7', 'Papas Gute-Nacht-Geschichte 📖', 'Deine Stimme ist müde und du hast keine Kraft mehr zum Vorlesen? Dann übergib an Papa. Seine andere, tiefere Stimme und die absurden Details, die er sich ausdenkt, ziehen dein Kind schneller in den Bann und lassen es eher einschlafen als deine vertraute Stimme.'),
  ('5d28c236-3ed8-4900-b875-c6d0d9b2aa20', 'Das „Wer bist du?“-Theater 🎭', 'Dein Kind sieht dich morgens wie eine Fremde an und fragt: „Wer bist du? Wo ist meine Mama?“ Das ist ein neues Rollenspiel. Sag einfach: „Ich bin die Nachbarin, deine Mama kommt gleich.“ Lasst das Zimmer vor Lachen beben – das spart viel mehr Energie, als sich auf einen Machtkampf einzulassen.'),
  ('8758179c-cc13-42d7-b2c1-4900aea35e3a', 'Vom eigenen Essen gibt es dir nichts ab 🍳', 'Dein Kind will dir nichts von seinem Teller abgeben, besteht aber darauf, von deinem zu essen? Kinder vertrauen der Auswahl ihrer Eltern vollkommen. Kämpf nicht dagegen an, gib ihm den Bissen liebevoll ab und lächle einfach über diesen niedlichen Egoismus.'),
  ('12a06ab8-bcee-4772-8e2b-6f509250a594', 'Ich will fliegen! 🕊️', 'Dein Kind springt vom Sofa, schlägt mit den Armen und wird wütend auf dich, weil es nicht fliegen kann? Für die Gesetze der Physik ist es noch zu früh. Sag: „Du kannst noch nicht fliegen, weil deine Flügel noch wachsen“, und lenke es darauf, an eine weiche Stelle zu springen.'),
  ('e80a8c85-c67a-45b2-8209-90553a33fb5f', 'Der Handydieb 📱', 'Du schenkst dir gerade Tee ein und bemerkst, dass dein Handy verschwunden ist – und dann hörst du dein Kind hinter dem Sofa wie du „Hallo?“ sagen? Es ahmt eure digitalen Gewohnheiten nach. Wenn du das Gerät zurücknimmst, sag lachend: „Mein Handy wollte wohl auch mit dir reden.“'),
  ('ebb45c07-d4c6-4504-ac39-3e83655d3e00', 'Gemeinsam schweigen wie ein Paar 🥂', 'Das Kind schläft, die Wohnung ist aufgeräumt. Setzt euch nebeneinander aufs Sofa und lasst sogar den Fernseher aus. Werft euch einfach diesen Blick zu, der sagt: „Auch das haben wir geschafft. Wir haben überlebt.“ Glaub mir: Genau das ist der ehrlichste Teammoment im erschöpften Elternalltag.'),
  ('a86a31ee-9e29-4f41-aa7c-1edc94992d88', 'Plötzliches Schreien mitten in der Nacht 😭', 'Ist dein Baby mit geschlossenen Augen weinend aufgewacht und reagiert nicht auf dich? Lass das Weinen analysieren – es handelt sich um einen Nachtschreck. Versuch nicht, dein Baby zu wecken. Bleib einfach bei ihm, halte seine Hand und streichle es sanft. Es wird sich von selbst beruhigen und wieder in einen tiefen Schlaf fallen.'),
  ('5430bad3-c2db-4b2e-bb46-e51168e8dd91', 'Du hast Post von Anacan 💌', 'In gesunden Rezepten verstecktes Gemüse, Tränen im Stimmungstagebuch und Momente völliger Erschöpfung ... In diesen 4 Jahren bist du zur Meisterin im schwierigsten Beruf der Welt geworden. Du bist jetzt eine Heldin, die keine App mehr braucht und das Chaos mit ihrer eigenen Intuition bewältigt. Wir waren nur dein stiller Wegweiser im Hintergrund – die eigentliche Arbeit hast du geleistet!'),
  ('7c7b74a0-c6ab-409c-babd-0085e345da09', 'Tag 1460: Wir haben es geschafft! 🚀', 'Am Morgen wachst du auf und siehst dein Kind an ... Es ist jetzt tatsächlich 4 Jahre alt! Seit genau 1460 Tagen hast du Schlafmangel, Krisen und Trotzphasen gemeistert und diesen kleinen Menschen großgezogen. In all diesen Jahren hast du nicht nur ein Kind großgezogen, sondern auch eine neue, starke und unbesiegbare Mutter in dir geschaffen. Heute gibt es keine Regeln. Umarme dein Kind einfach und betrachte voller Stolz dieses Wunder, das du geschaffen hast.'),
  ('e37bc161-dfcf-4941-bac0-6c7cfe6f4ba2', 'Die letzte Mitteilung, die letzte Stille 🌌', 'Dein Kind schläft. Mach das Licht aus. Dies ist die letzte Mitteilung, die du von der App erhältst. 1460 Tage lang haben wir versucht, dich zu verstehen und still an deiner Seite zu sein, wenn du müde warst, geweint hast oder nicht mehr weiterwusstest. Leg jetzt dein Handy beiseite. Du bist perfekt, und du bist genug. Die wundervolle Geschichte, die nun folgt, wirst du ganz allein selbst schreiben. Es war uns eine Ehre, dich auf deinem Weg zu begleiten. Bis bald, Mami! ❤️'),
  ('add15a56-d6d1-4819-af57-b57688cec0f4', 'Ohne Vorlesen ins Bett bringen 🪄', 'Du hast heute Abend keine Energie mehr, eine Geschichte vorzulesen? Öffne die smarten Märchen und lass nur die Geräusche des flüsternden Waldes und des Windes im Hintergrund laufen. Hört euch im Dunkeln gemeinsam die Naturklänge an und erholt euch vom Lärm des Tages. So können sich auch eure Augen sofort entspannen.'),
  ('b000be1e-116f-4403-b926-fe4428d04231', 'Meine Wut aufschreiben 📝', 'Niemand sieht, wie erschöpft du zu Hause bist, und das bringt dich zum Platzen? Öffne dein Stimmungstagebuch. Schreib dort alles auf, was dich heute wahnsinnig gemacht hat. Deine Gefühle anzunehmen und aufzuschreiben, hilft dir mehr, als ein Lächeln vorzutäuschen.'),
  ('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8', 'Ich weiß es – ich erklär’s dir ☝️', 'Erklärt dir dein Kind mit ernster, wissender Miene etwas, das du längst weißt? Es testet gerade seine eigenen Fähigkeiten. Beiß dir auf die Lippe, damit du nicht lachst, hör aber ganz aufmerksam zu und sag: „Wirklich? Vielen Dank!“ Das stärkt sein Selbstbewusstsein.'),
  ('5b3e259a-f085-41f9-b9ba-e7ff8789e89c', 'Überschwemmung in der Badewanne 🌊', 'Baden ist nur der Vorwand – in Wirklichkeit verwandelt dein Kind die Badewanne in einen Ozean und spielt mit den Wellen? Lass es spielen. Das Plätschern und Spritzen wird seine unerschöpfliche, eigensinnige Energie einfach wegspülen. Abends wird es sich ohne Widerstand ins Bett legen.'),
  ('7c552cb2-0d81-4027-8eba-e235f8359b1d', 'Dein kleiner Küchenhelfer 🧑‍🍳', 'Während du den Teig ausrollst, stellt dein Kind einen Stuhl neben dich und will unbedingt selbst das Mehl hineinschütten? Wenn du es nicht lässt, wird es weinen. Gib ihm eine kleine Plastikschüssel und etwas Mehl. Die Küche wird danach zwar chaotisch aussehen, aber sein ernster kleiner Kochblick ist das Putzen wert.'),
  ('86e3829d-08da-4b37-867c-0faf0ab2fa1c', 'Mitten im Supermarkt den Faden verlieren 🛒', 'Stehst du mitten im Supermarkt und fragst dich plötzlich: „Was wollte ich noch mal kaufen?“ Dein Mama-Gehirn ist wirklich randvoll. Öffne die Einkaufsliste in der App und vertrau diesem digitalen Gedächtnis – so findest du jederzeit aus dem Chaos heraus.'),
  ('202773be-9378-4cfa-915c-7cbc9e98cdc2', 'Das Etikett im Shirt kratzt! 🏷️', 'Dein Kind will das Shirt nicht anziehen, weil sich das kleine Etikett am Rücken wie eine Nadel anfühlt? Die sensorische Empfindlichkeit in diesem Alter kann einen wirklich verrückt machen. Fang gar nicht erst an zu diskutieren: Nimm die Schere, schneide das Etikett direkt am Ansatz ab und beende diese Minikrise innerhalb von Sekunden.'),
  ('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d', 'Ein Moment vollkommener Ruhe 🛋️', 'Dein Kind ist so tief in sein Puzzle vertieft, dass es im Haus plötzlich still geworden ist? Werde nicht misstrauisch, sondern schenk dir sofort einen Kaffee ein. Verschwende diese seltenen, kostbaren Minuten nicht mit Putzen oder Wäsche. Ruh dich aus und schau einfach an die Decke. Du bist kein Roboter.'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'Ausreden, um aus dem Bett zu kommen 🏃‍♂️', 'Es möchte Wasser trinken, zur Toilette gehen, den Vorhang im Zimmer küssen ... Um nicht einschlafen zu müssen, lässt sich sein Gehirn immer neue Dinge einfallen. Setze klare Grenzen: Nur 1 Glas Wasser, dann ist Schluss. Bleib konsequent.')
) AS v(id, t, b)
WHERE x.id = v.id;

-- Yoxlama: hər ikisi ~0 olmalıdır (boş-mənbə sətirləri istisna olmaqla)
SELECT
  (SELECT count(*) FROM public.pregnancy_day_notifications WHERE title_de IS NULL) AS preg_de_bos,
  (SELECT count(*) FROM public.mommy_day_notifications WHERE title_de IS NULL) AS mommy_de_bos;
